window.HEIBEN_KULINARIK_SEED = {"version": 3, "entries": [{"id": "couscous-royale-mit-lamm-haehnchen-und-merguez", "status": "published", "date": "2026-05-22", "cover": "", "name": "Couscous Royale mit Lamm, Hähnchen und Merguez", "land": "Algerien", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Fleisch", "Geflügel", "Lamm"], "schwierigkeit": "Mittel", "vorbereitungMin": 40, "kochMin": 90, "portionen": 6, "kurzinfo": "Das Festtagsgericht schlechthin: dampfender Grieß, dreierlei Fleisch und ein Gemüsesud, der nach Sonntag bei der Familie schmeckt.", "zutaten": ["600 g Couscous (mittlerer Grieß)", "600 g Lammschulter, in großen Würfeln", "4 Hähnchenkeulen", "6 Merguez (Lamm- oder Rindwurst)", "3 Möhren, in Stücken", "2 Zucchini, in Stücken", "1 Steckrübe oder weißer Rettich, gewürfelt", "1 Dose Kichererbsen (400 g), abgespült", "2 Zwiebeln, gewürfelt", "3 EL Tomatenmark", "2 TL Ras el-Hanout, 1 TL Kreuzkümmel, 1 TL Kurkuma", "Olivenöl, Salz, Pfeffer", "frischer Koriander zum Servieren"], "zubereitung": ["Lamm und Hähnchen in Olivenöl in einem großen Topf rundum anbraten, herausnehmen.", "Zwiebeln glasig dünsten, Tomatenmark und Gewürze kurz mitrösten.", "Fleisch zurückgeben, mit Wasser bedecken, salzen und zugedeckt 45 Minuten sanft köcheln.", "Möhren und Steckrübe zugeben, 15 Minuten garen; dann Zucchini und Kichererbsen weitere 15 Minuten.", "Couscous nach Packung mit etwas Öl und Salz quellen lassen und mit der Gabel auflockern.", "Merguez in einer Pfanne ohne Zugabe von Fett knusprig braten.", "Grieß auf eine große Platte häufen, Fleisch und Gemüse darauf anrichten, mit Sud beträufeln und mit Koriander bestreuen."], "hinweise": "Den Sud lieber etwas reichlicher ansetzen — am nächsten Tag ziehen die Aromen nach und das Gericht schmeckt fast noch besser. Wer es schärfer mag, reicht Harissa separat.", "alternative": "", "geschichte": "Couscous ist in Algerien kein Alltagsessen, sondern Anlass: Es kommt auf den Tisch, wenn Familie zusammenkommt. Traditionell wird der Grieß über dem Gemüsesud gedämpft, damit er dessen Aroma aufnimmt — die schnelle Variante mit Quellgrieß macht das Gericht aber auch unter der Woche möglich.", "persoenlich": "Yakins Großmutter in Boukadir richtete das Couscous immer auf einer einzigen großen Platte an, von der alle gemeinsam aßen. Dieses Bild steht am Anfang von HeiBen Kulinarik.", "servier": "Auf einer großen Platte in der Tischmitte, dazu eingelegtes Gemüse und ein Glas Pfefferminztee.", "tags": ["Festtag", "Familienrezept", "Eintopf", "Maghreb"], "zutatenS": [{"menge": 600.0, "einheit": "g", "item": "Couscous (mittlerer Grieß)", "roh": "600 g Couscous (mittlerer Grieß)"}, {"menge": 600.0, "einheit": "g", "item": "Lammschulter, in großen Würfeln", "roh": "600 g Lammschulter, in großen Würfeln"}, {"menge": 4.0, "einheit": "", "item": "Hähnchenkeulen", "roh": "4 Hähnchenkeulen"}, {"menge": 6.0, "einheit": "", "item": "Merguez (Lamm- oder Rindwurst)", "roh": "6 Merguez (Lamm- oder Rindwurst)"}, {"menge": 3.0, "einheit": "", "item": "Möhren, in Stücken", "roh": "3 Möhren, in Stücken"}, {"menge": 2.0, "einheit": "", "item": "Zucchini, in Stücken", "roh": "2 Zucchini, in Stücken"}, {"menge": 1.0, "einheit": "", "item": "Steckrübe oder weißer Rettich, gewürfelt", "roh": "1 Steckrübe oder weißer Rettich, gewürfelt"}, {"menge": 1.0, "einheit": "Dose", "item": "Kichererbsen (400 g), abgespült", "roh": "1 Dose Kichererbsen (400 g), abgespült"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, gewürfelt", "roh": "2 Zwiebeln, gewürfelt"}, {"menge": 3.0, "einheit": "EL", "item": "Tomatenmark", "roh": "3 EL Tomatenmark"}, {"menge": 2.0, "einheit": "TL", "item": "Ras el-Hanout, 1 TL Kreuzkümmel, 1 TL Kurkuma", "roh": "2 TL Ras el-Hanout, 1 TL Kreuzkümmel, 1 TL Kurkuma"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer", "roh": "Olivenöl, Salz, Pfeffer"}, {"menge": null, "einheit": "", "item": "frischer Koriander zum Servieren", "roh": "frischer Koriander zum Servieren"}], "basisPortionen": 6, "zeitGeschaetzt": false}, {"id": "chorba-frik-algerische-lammsuppe", "status": "published", "date": "2026-05-15", "cover": "", "name": "Chorba Frik — algerische Lammsuppe mit Grünkern", "land": "Algerien", "kontinent": "Afrika", "gang": "Vorspeise", "art": ["Fleisch", "Lamm"], "schwierigkeit": "Einfach", "vorbereitungMin": 20, "kochMin": 60, "portionen": 4, "kurzinfo": "Die wärmende Suppe, die im Ramadan den Tag beschließt: Lamm, Tomate, Grünkern und ein Bündel Kräuter.", "zutaten": ["400 g Lammschulter, klein gewürfelt", "100 g Frik (gerösteter Grünkern), ersatzweise Graupen", "1 Zwiebel, fein gewürfelt", "2 EL Tomatenmark", "400 g passierte Tomaten", "1 TL Kreuzkümmel, 1 TL gemahlener Koriander, ½ TL Zimt", "1 Bund frische Petersilie und Koriander, gehackt", "Olivenöl, Salz, Pfeffer", "Saft einer halben Zitrone"], "zubereitung": ["Lammwürfel in Olivenöl anbraten, Zwiebel zugeben und glasig dünsten.", "Tomatenmark und Gewürze kurz mitrösten, bis es duftet.", "Passierte Tomaten und 1,5 l Wasser angießen, salzen und 40 Minuten köcheln.", "Frik einrühren und weitere 20 Minuten quellen lassen, gelegentlich umrühren.", "Mit Zitronensaft abschmecken, reichlich Kräuter unterrühren."], "hinweise": "Frik gibt der Suppe ihren typisch nussigen Biss. Findet man ihn nicht, funktionieren Graupen gut; die Garzeit dann etwas verlängern.", "alternative": "", "geschichte": "Chorba steht in vielen Haushalten des Maghreb allabendlich während des Ramadan auf dem Tisch. Jede Familie hat ihre eigene Würzung — diese hier ist mild gehalten und lässt sich leicht nachschärfen.", "persoenlich": "", "servier": "Mit einem Spritzer Zitrone und warmem Fladenbrot.", "tags": ["Suppe", "Ramadan", "Maghreb", "Wohlfühlessen"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Lammschulter, klein gewürfelt", "roh": "400 g Lammschulter, klein gewürfelt"}, {"menge": 100.0, "einheit": "g", "item": "Frik (gerösteter Grünkern), ersatzweise Graupen", "roh": "100 g Frik (gerösteter Grünkern), ersatzweise Graupen"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel, fein gewürfelt", "roh": "1 Zwiebel, fein gewürfelt"}, {"menge": 2.0, "einheit": "EL", "item": "Tomatenmark", "roh": "2 EL Tomatenmark"}, {"menge": 400.0, "einheit": "g", "item": "passierte Tomaten", "roh": "400 g passierte Tomaten"}, {"menge": 1.0, "einheit": "TL", "item": "Kreuzkümmel, 1 TL gemahlener Koriander, ½ TL Zimt", "roh": "1 TL Kreuzkümmel, 1 TL gemahlener Koriander, ½ TL Zimt"}, {"menge": 1.0, "einheit": "Bund", "item": "frische Petersilie und Koriander, gehackt", "roh": "1 Bund frische Petersilie und Koriander, gehackt"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer", "roh": "Olivenöl, Salz, Pfeffer"}, {"menge": null, "einheit": "", "item": "Saft einer halben Zitrone", "roh": "Saft einer halben Zitrone"}], "basisPortionen": 4, "zeitGeschaetzt": false}, {"id": "gruenkohl-mit-merguez-statt-pinkel", "status": "published", "date": "2026-05-10", "cover": "", "name": "Grünkohl mit Merguez statt Pinkel", "land": "Deutschland", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "Mittel", "vorbereitungMin": 25, "kochMin": 75, "portionen": 4, "kurzinfo": "Der norddeutsche Winterklassiker — neu gedacht: Wo sonst Pinkel und Kassler liegen, sorgen Merguez und geräuchertes Rind für Rauch und Würze.", "zutaten": ["1,5 kg Grünkohl (TK oder frisch, geputzt)", "8 Merguez (Lamm- oder Rindwurst)", "400 g geräucherte Rinderbrust oder Pastrami am Stück", "2 Zwiebeln, gewürfelt", "2 EL Senf, 1 TL Piment, 1 Lorbeerblatt", "etwas Hafergrütze oder eine Handvoll Haferflocken (zum Binden)", "Gänse- oder Pflanzenschmalz, Salz, Pfeffer", "optional: 1 TL Zucker zum Karamellisieren"], "zubereitung": ["Zwiebeln in Schmalz glasig dünsten, optional mit etwas Zucker leicht karamellisieren.", "Grünkohl zugeben, kurz mitdünsten, mit Wasser oder Brühe knapp bedecken.", "Geräuchertes Rind, Senf, Piment und Lorbeer einlegen und zugedeckt 60 Minuten schmoren.", "Hafergrütze einrühren, damit der Kohl sämig bindet; weitere 10 Minuten köcheln.", "Merguez in der Pfanne knusprig braten und zum Schluss auf dem Kohl anrichten.", "Kräftig mit Salz und Pfeffer abschmecken."], "hinweise": "Grünkohl verträgt eine lange Garzeit — er soll mürbe, nicht knackig sein. Am zweiten Tag aufgewärmt schmeckt er am besten.", "alternative": "Klassisch kommen in den Grünkohl Pinkel (eine Grützwurst vom Schwein) und Kassler. Beides ersetzen wir hier: Merguez bringt dieselbe würzig-fettige Rauchnote wie die Pinkel und sogar mehr Gewürztiefe, geräucherte Rinderbrust übernimmt die Rolle des Kasslers. So bleibt der herzhafte, rauchige Charakter des Originals erhalten — und es verbindet sich ganz nebenbei der Norden mit dem Maghreb.", "geschichte": "Grünkohl ist in Norddeutschland fester Bestandteil des Winters, oft begleitet von „Kohlfahrten“ und einem festlichen Essen am Ziel. Das Gericht lebt von Rauch, Fett und langer Garzeit — Eigenschaften, die sich auch mit anderem Fleisch erreichen lassen.", "persoenlich": "In Katharinas Familie gehörte Grünkohl zu jedem Januar. Als beide Familien zum ersten Mal gemeinsam aßen, entstand aus der Not eine Idee — und dieses Rezept.", "servier": "Mit Salzkartoffeln oder Bratkartoffeln und kräftigem Senf.", "tags": ["Winter", "Norddeutsch", "Klassiker neu interpretiert", "Winterküche"], "zutatenS": [{"menge": 1.5, "einheit": "kg", "item": "Grünkohl (TK oder frisch, geputzt)", "roh": "1,5 kg Grünkohl (TK oder frisch, geputzt)"}, {"menge": 8.0, "einheit": "", "item": "Merguez (Lamm- oder Rindwurst)", "roh": "8 Merguez (Lamm- oder Rindwurst)"}, {"menge": 400.0, "einheit": "g", "item": "geräucherte Rinderbrust oder Pastrami am Stück", "roh": "400 g geräucherte Rinderbrust oder Pastrami am Stück"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, gewürfelt", "roh": "2 Zwiebeln, gewürfelt"}, {"menge": 2.0, "einheit": "EL", "item": "Senf, 1 TL Piment, 1 Lorbeerblatt", "roh": "2 EL Senf, 1 TL Piment, 1 Lorbeerblatt"}, {"menge": null, "einheit": "", "item": "etwas Hafergrütze oder eine Handvoll Haferflocken (zum Binden)", "roh": "etwas Hafergrütze oder eine Handvoll Haferflocken (zum Binden)"}, {"menge": null, "einheit": "", "item": "Gänse- oder Pflanzenschmalz, Salz, Pfeffer", "roh": "Gänse- oder Pflanzenschmalz, Salz, Pfeffer"}, {"menge": null, "einheit": "", "item": "optional: 1 TL Zucker zum Karamellisieren", "roh": "optional: 1 TL Zucker zum Karamellisieren"}], "basisPortionen": 4, "zeitGeschaetzt": false}, {"id": "birnen-bohnen-und-geraeuchertes-rind", "status": "published", "date": "2026-04-28", "cover": "", "name": "Birnen, Bohnen und geräuchertes Rind", "land": "Deutschland", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "Einfach", "vorbereitungMin": 20, "kochMin": 40, "portionen": 4, "kurzinfo": "Das norddeutsche Sommergericht in einer schweinefreien Fassung: grüne Bohnen, feste Kochbirnen und rauchiges Rind statt Speck.", "zutaten": ["800 g grüne Bohnen, geputzt", "4 feste Kochbirnen, geviertelt", "300 g geräucherte Rinderbrust oder luftgetrocknetes Rind, in Scheiben", "2 Zwiebeln, gewürfelt", "1 Zweig Bohnenkraut", "500 ml Gemüse- oder Rinderbrühe", "Butter oder Öl, Salz, Pfeffer", "frische Petersilie"], "zubereitung": ["Zwiebeln in Butter andünsten, geräuchertes Rind kurz mitbraten.", "Bohnen und Bohnenkraut zugeben, mit Brühe angießen und 15 Minuten köcheln.", "Birnenviertel auflegen und weitere 12–15 Minuten garen, bis sie weich, aber nicht zerfallen sind.", "Mit Salz und Pfeffer abschmecken, Bohnenkraut entfernen, mit Petersilie bestreuen."], "hinweise": "Birnen und Bohnen getrennt im Auge behalten — die Birnen sollen ihre Form halten. Süße und Rauch sind hier der ganze Reiz.", "alternative": "Das Original „Birnen, Bohnen und Speck“ wird mit durchwachsenem Schweinespeck gekocht. Geräucherte Rinderbrust liefert dieselbe rauchig-herzhafte Tiefe, ohne Schwein. Wer es kräftiger mag, brät einige Scheiben luftgetrocknetes Rind separat knusprig und streut sie darüber.", "geschichte": "Ein Gericht aus der Erntezeit, wenn Bohnen und Birnen gleichzeitig reif sind. Es lebt vom Kontrast zwischen süßer Frucht, herbem Bohnenkraut und rauchigem Fleisch.", "persoenlich": "", "servier": "Mit jungen Salzkartoffeln.", "tags": ["Sommer", "Norddeutsch", "Klassiker neu interpretiert", "Erntezeit"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "grüne Bohnen, geputzt", "roh": "800 g grüne Bohnen, geputzt"}, {"menge": 4.0, "einheit": "", "item": "feste Kochbirnen, geviertelt", "roh": "4 feste Kochbirnen, geviertelt"}, {"menge": 300.0, "einheit": "g", "item": "geräucherte Rinderbrust oder luftgetrocknetes Rind, in Scheiben", "roh": "300 g geräucherte Rinderbrust oder luftgetrocknetes Rind, in Scheiben"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, gewürfelt", "roh": "2 Zwiebeln, gewürfelt"}, {"menge": 1.0, "einheit": "Zweig", "item": "Bohnenkraut", "roh": "1 Zweig Bohnenkraut"}, {"menge": 500.0, "einheit": "ml", "item": "Gemüse- oder Rinderbrühe", "roh": "500 ml Gemüse- oder Rinderbrühe"}, {"menge": null, "einheit": "", "item": "Butter oder Öl, Salz, Pfeffer", "roh": "Butter oder Öl, Salz, Pfeffer"}, {"menge": null, "einheit": "", "item": "frische Petersilie", "roh": "frische Petersilie"}], "basisPortionen": 4, "zeitGeschaetzt": false}, {"id": "haehnchen-tajine-mit-zitrone-und-oliven", "status": "published", "date": "2026-04-18", "cover": "", "name": "Hähnchen-Tajine mit Salzzitrone und Oliven", "land": "Marokko", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Geflügel"], "schwierigkeit": "Einfach", "vorbereitungMin": 20, "kochMin": 50, "portionen": 4, "kurzinfo": "Zart geschmortes Hähnchen, das Salz-Sauer der eingelegten Zitrone und herbe Oliven — ein Klassiker, der wie von selbst gelingt.", "zutaten": ["8 Hähnchenteile (Keulen und Schenkel)", "1 eingelegte Salzzitrone, in Streifen", "150 g grüne Oliven (entsteint)", "2 Zwiebeln, in Ringen", "3 Knoblauchzehen", "1 TL Kurkuma, 1 TL Ingwer, ½ TL Safranfäden", "1 Bund Koriander und Petersilie", "Olivenöl, Salz, Pfeffer"], "zubereitung": ["Hähnchen mit Kurkuma, Ingwer, Knoblauch und Öl marinieren (gern über Nacht).", "In einer Tajine oder einem schweren Topf Zwiebeln andünsten, Hähnchen darauf legen.", "Safran in etwas warmem Wasser lösen, angießen, salzen und zugedeckt 40 Minuten sanft schmoren.", "Salzzitrone und Oliven zugeben, weitere 10 Minuten garen.", "Mit reichlich Kräutern bestreut servieren."], "hinweise": "Salzzitronen gibt es fertig im Glas — oder man legt sie selbst ein. Sie sind das Herz des Gerichts; bitte nicht weglassen.", "alternative": "", "geschichte": "Die Tajine ist zugleich Topf und Gericht. Ihre Form lässt den Dampf zirkulieren, sodass das Fleisch in seinem eigenen Saft mürbe wird — ein Prinzip, das auch im normalen Schmortopf funktioniert.", "persoenlich": "", "servier": "Mit Fladenbrot oder Couscous, der den Sud aufnimmt.", "tags": ["Schmorgericht", "Maghreb", "Alltagstauglich"], "zutatenS": [{"menge": 8.0, "einheit": "", "item": "Hähnchenteile (Keulen und Schenkel)", "roh": "8 Hähnchenteile (Keulen und Schenkel)"}, {"menge": 1.0, "einheit": "", "item": "eingelegte Salzzitrone, in Streifen", "roh": "1 eingelegte Salzzitrone, in Streifen"}, {"menge": 150.0, "einheit": "g", "item": "grüne Oliven (entsteint)", "roh": "150 g grüne Oliven (entsteint)"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, in Ringen", "roh": "2 Zwiebeln, in Ringen"}, {"menge": 3.0, "einheit": "", "item": "Knoblauchzehen", "roh": "3 Knoblauchzehen"}, {"menge": 1.0, "einheit": "TL", "item": "Kurkuma, 1 TL Ingwer, ½ TL Safranfäden", "roh": "1 TL Kurkuma, 1 TL Ingwer, ½ TL Safranfäden"}, {"menge": 1.0, "einheit": "Bund", "item": "Koriander und Petersilie", "roh": "1 Bund Koriander und Petersilie"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer", "roh": "Olivenöl, Salz, Pfeffer"}], "basisPortionen": 4, "zeitGeschaetzt": false}, {"id": "makroud-griessrauten-mit-datteln", "status": "published", "date": "2026-04-05", "cover": "", "name": "Makroud — Grießrauten mit Datteln", "land": "Algerien", "kontinent": "Afrika", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "Anspruchsvoll", "vorbereitungMin": 45, "kochMin": 25, "portionen": 8, "kurzinfo": "Goldene Grießrauten mit einer Füllung aus Datteln, gebadet in Honig — das Gebäck, das zu jedem Fest gehört.", "zutaten": ["500 g Hartweizengrieß (mittel)", "150 ml mildes Olivenöl", "120 ml Orangenblütenwasser (plus Wasser nach Bedarf)", "400 g entsteinte Datteln", "1 TL Zimt, 1 Prise Muskat", "abgeriebene Schale einer Orange", "300 g Honig", "Öl zum Ausbacken"], "zubereitung": ["Grieß mit Öl verkneten, ruhen lassen, dann mit Orangenblütenwasser zu einem festen Teig verarbeiten.", "Datteln mit Zimt, Muskat und Orangenschale zu einer geschmeidigen Paste mixen.", "Teig zu Bändern ausrollen, Dattelpaste als Strang einlegen, einrollen und in Rauten schneiden.", "Rauten in heißem Öl goldbraun ausbacken und kurz abtropfen lassen.", "Honig leicht erwärmen und die noch warmen Rauten darin wenden.", "Auf einem Gitter abtropfen lassen und vollständig auskühlen."], "hinweise": "Der Teig darf nicht zu nass sein, sonst saugen sich die Rauten beim Frittieren voll. Lieber das Orangenblütenwasser löffelweise zugeben.", "alternative": "", "geschichte": "Makroud reicht von Tunesien bis Algerien und wird zu Festen, Hochzeiten und am Ende des Ramadan gereicht. In manchen Regionen wird es in Honig getaucht, in anderen in Zuckersirup.", "persoenlich": "", "servier": "Zu Pfefferminztee, in kleinen Mengen — sie sind reichhaltig.", "tags": ["Gebäck", "Süßes", "Fest", "Maghreb"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Hartweizengrieß (mittel)", "roh": "500 g Hartweizengrieß (mittel)"}, {"menge": 150.0, "einheit": "ml", "item": "mildes Olivenöl", "roh": "150 ml mildes Olivenöl"}, {"menge": 120.0, "einheit": "ml", "item": "Orangenblütenwasser (plus Wasser nach Bedarf)", "roh": "120 ml Orangenblütenwasser (plus Wasser nach Bedarf)"}, {"menge": 400.0, "einheit": "g", "item": "entsteinte Datteln", "roh": "400 g entsteinte Datteln"}, {"menge": 1.0, "einheit": "TL", "item": "Zimt, 1 Prise Muskat", "roh": "1 TL Zimt, 1 Prise Muskat"}, {"menge": null, "einheit": "", "item": "abgeriebene Schale einer Orange", "roh": "abgeriebene Schale einer Orange"}, {"menge": 300.0, "einheit": "g", "item": "Honig", "roh": "300 g Honig"}, {"menge": null, "einheit": "", "item": "Öl zum Ausbacken", "roh": "Öl zum Ausbacken"}], "basisPortionen": 8, "zeitGeschaetzt": false}, {"id": "tav-kosi", "status": "published", "date": "", "cover": "", "name": "Tavë kosi", "land": "Albanien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Im Ofen gebackenes Lamm unter einer Haube aus Joghurt und Ei, die beim Backen zu einer goldenen, souffléartigen Schicht stockt. Albaniens inoffizielles Nationalgericht, herzhaft und zugleich erstaunlich leicht.", "zutaten": ["800 g Lammschulter oder -keule, in Stücken", "50 g Butter", "2 EL Mehl", "60 g Reis", "500 g Naturjoghurt (vollfett)", "3 Eier", "2 Zehen Knoblauch", "1 TL getrockneter Oregano", "Salz und Pfeffer"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "Lammschulter oder -keule, in Stücken", "roh": "800 g Lammschulter oder -keule, in Stücken"}, {"menge": 50.0, "einheit": "g", "item": "Butter", "roh": "50 g Butter"}, {"menge": 2.0, "einheit": "EL", "item": "Mehl", "roh": "2 EL Mehl"}, {"menge": 60.0, "einheit": "g", "item": "Reis", "roh": "60 g Reis"}, {"menge": 500.0, "einheit": "g", "item": "Naturjoghurt (vollfett)", "roh": "500 g Naturjoghurt (vollfett)"}, {"menge": 3.0, "einheit": "", "item": "Eier", "roh": "3 Eier"}, {"menge": 2.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "2 Zehen Knoblauch"}, {"menge": 1.0, "einheit": "TL", "item": "getrockneter Oregano", "roh": "1 TL getrockneter Oregano"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Lammstücke in etwas Butter rundum anbraten, salzen, pfeffern und mit dem Knoblauch in eine Backform geben.", "Mit wenig Wasser begießen und im Ofen bei 180 °C etwa 30 Minuten vorgaren; den Reis roh untermischen.", "Aus der restlichen Butter und dem Mehl eine helle Mehlschwitze rühren, leicht abkühlen lassen.", "Joghurt mit Eiern und der Mehlschwitze glatt verquirlen, salzen und über das Lamm gießen.", "Bei 180 °C weitere 35–45 Minuten backen, bis die Oberfläche goldgelb gestockt und leicht aufgegangen ist.", "Vor dem Servieren 10 Minuten ruhen lassen, damit sich die Haube setzt."], "hinweise": "Der Joghurt sollte Zimmertemperatur haben, damit er beim Backen nicht gerinnt.\n\nStatt Lamm funktioniert auch Hähnchen; die Garzeit verkürzt sich dann etwas.\n\nEin Spritzer Zitrone im Joghurt verstärkt die typische Säure.", "alternative": "", "geschichte": "Tavë kosi gilt vielen als das Nationalgericht Albaniens und stammt ursprünglich aus der Region um Elbasan, weshalb es auch „Elbasani tavë“ genannt wird. Das Gericht verbindet zwei Einflüsse, die die albanische Küche prägen: die Lammtradition des Balkans und die Joghurt- und Auflauftechniken, die während der osmanischen Zeit verbreitet wurden. Der Name beschreibt das Gericht wörtlich — „tavë“ ist die irdene oder kupferne Backform, „kosi“ der Joghurt. Über Jahrhunderte war es ein Festtagsessen, das man sonntags und zu religiösen Anlässen zubereitete, weil Lamm und Eier kostbar waren. Die joghurtbasierte Haube ist typisch für eine Küche, die Milchprodukte fermentiert haltbar machte. Bis heute steht Tavë kosi in fast jedem traditionellen Lokal des Landes und wird als verbindendes, identitätsstiftendes Gericht verstanden.", "persoenlich": "", "servier": "", "tags": ["Albanien", "Balkan", "Lamm", "Auflauf", "Joghurt", "Ofengericht", "Festtag", "osmanisch geprägt", "Nationalgericht", "Elbasan", "herzhaft", "Sonntagsessen"]}, {"id": "f-rges", "status": "published", "date": "", "cover": "", "name": "Fërgesë", "land": "Albanien", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein warmes Schmorgericht aus Paprika und Tomaten, gebunden mit zerbröseltem Frischkäse (gjizë). In der Hauptstadt als „Fërgesë Tirane“ bekannt, sämig und mild-würzig.", "zutaten": ["4 rote Spitzpaprika", "4 reife Tomaten, gehäutet und gewürfelt", "250 g gjizë (ersatzweise Ricotta oder Quark)", "100 g Feta, zerbröselt", "1 Zwiebel, fein gewürfelt", "2 Zehen Knoblauch", "3 EL Olivenöl", "1 Prise getrocknete Chiliflocken", "Salz und Pfeffer"], "zutatenS": [{"menge": 4.0, "einheit": "", "item": "rote Spitzpaprika", "roh": "4 rote Spitzpaprika"}, {"menge": 4.0, "einheit": "", "item": "reife Tomaten, gehäutet und gewürfelt", "roh": "4 reife Tomaten, gehäutet und gewürfelt"}, {"menge": 250.0, "einheit": "g", "item": "gjizë (ersatzweise Ricotta oder Quark)", "roh": "250 g gjizë (ersatzweise Ricotta oder Quark)"}, {"menge": 100.0, "einheit": "g", "item": "Feta, zerbröselt", "roh": "100 g Feta, zerbröselt"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel, fein gewürfelt", "roh": "1 Zwiebel, fein gewürfelt"}, {"menge": 2.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "2 Zehen Knoblauch"}, {"menge": 3.0, "einheit": "EL", "item": "Olivenöl", "roh": "3 EL Olivenöl"}, {"menge": 1.0, "einheit": "Prise", "item": "getrocknete Chiliflocken", "roh": "1 Prise getrocknete Chiliflocken"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Paprika über offener Flamme oder im Ofen rösten, häuten und in Streifen schneiden.", "Zwiebel und Knoblauch in Olivenöl glasig dünsten.", "Tomaten zugeben und einköcheln, bis eine dicke Sauce entsteht; mit Chili, Salz und Pfeffer würzen.", "Paprikastreifen unterheben und kurz mitschmoren.", "Hitze reduzieren, gjizë und Feta einrühren, nur erwärmen, nicht aufkochen.", "Heiß in der Pfanne servieren, mit Weißbrot zum Tunken."], "hinweise": "Frisch geröstete Paprika schmeckt deutlich besser als eingelegte.\n\nWer es würziger mag, gibt mehr Chili oder eine Prise Paprikapulver dazu.\n\nDie Fërgesë bindet besser, wenn der Käse erst am Ende und bei kleiner Hitze hineinkommt.", "alternative": "", "geschichte": "Fërgesë ist ein Eckpfeiler der zentralalbanischen Küche und besonders eng mit Tirana verbunden, wo die vegetarische Variante als „Fërgesë Tirane“ gilt. Das Gericht entstand aus der bäuerlichen Notwendigkeit, mit wenigen, im Sommer reichlich vorhandenen Zutaten — Paprika, Tomaten, frischem Käse — ein nahrhaftes, warmes Essen zuzubereiten. Der albanische Frischkäse gjizë, ein Molkenkäse ähnlich Ricotta, ist die charakteristische Zutat und gibt der Fërgesë ihre cremige Bindung. Traditionell wurde das Gericht in einer kleinen irdenen Pfanne (ebenfalls „tavë“) am Herdrand fertig geschmort und direkt darin serviert. Es gibt eine zweite, herzhaftere Variante mit Kalbsleber, doch die fleischlose Paprika-Käse-Fassung ist die alltäglichere und in ländlichen Haushalten verbreitete. Fërgesë steht für die mediterran geprägte Seite Albaniens und wird als geteilte Vorspeise mit viel Brot gegessen.", "persoenlich": "", "servier": "", "tags": ["Albanien", "Tirana", "vegetarisch", "Paprika", "Frischkäse", "Schmorgericht", "Vorspeise", "mediterran", "Sommerküche", "gjizë", "geteilte Vorspeise", "bäuerlich"]}, {"id": "byrek-me-spinaq", "status": "published", "date": "", "cover": "", "name": "Byrek me spinaq", "land": "Albanien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine knusprige Blätterteigpastete mit Spinat und Frischkäse, in dünnen, handgezogenen Teigblättern geschichtet. Allgegenwärtiges Alltags- und Straßenessen Albaniens.", "zutaten": ["400 g Filo- oder Yufka-Teigblätter", "500 g frischer Spinat", "200 g Feta oder gjizë, zerbröselt", "2 Frühlingszwiebeln", "2 Eier", "120 ml Olivenöl zum Bestreichen", "Salz und Pfeffer"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Filo- oder Yufka-Teigblätter", "roh": "400 g Filo- oder Yufka-Teigblätter"}, {"menge": 500.0, "einheit": "g", "item": "frischer Spinat", "roh": "500 g frischer Spinat"}, {"menge": 200.0, "einheit": "g", "item": "Feta oder gjizë, zerbröselt", "roh": "200 g Feta oder gjizë, zerbröselt"}, {"menge": 2.0, "einheit": "", "item": "Frühlingszwiebeln", "roh": "2 Frühlingszwiebeln"}, {"menge": 2.0, "einheit": "", "item": "Eier", "roh": "2 Eier"}, {"menge": 120.0, "einheit": "ml", "item": "Olivenöl zum Bestreichen", "roh": "120 ml Olivenöl zum Bestreichen"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Spinat waschen, grob hacken und mit etwas Salz zusammenfallen lassen; gut ausdrücken.", "Spinat mit Käse, gehackten Frühlingszwiebeln und einem Ei vermengen, pfeffern.", "Eine Form mit Öl auspinseln, ein Teigblatt einlegen und mit Öl bestreichen; mehrere Blätter so schichten.", "Die Spinatfüllung gleichmäßig verteilen, mit weiteren geölten Teigblättern abdecken.", "Oberfläche mit verquirltem Ei und Öl bestreichen, in Stücke vorritzen.", "Bei 190 °C 35–40 Minuten goldbraun und knusprig backen; lauwarm servieren."], "hinweise": "Den Teig zwischen den Schichten reichlich ölen — das macht den Byrek knusprig.\n\nSpinat unbedingt gut ausdrücken, sonst weicht der Boden durch.\n\nReste schmecken am nächsten Tag kalt fast noch besser.", "alternative": "", "geschichte": "Der Byrek (im weiteren Balkan „Burek“) gehört zu den verbreitetsten Gebäcken Südosteuropas und kam mit der osmanischen Küche in die Region, wo er auf eine ältere Tradition dünn ausgezogener Teige traf. In Albanien ist Byrek tief im Alltag verankert: Er wird zum Frühstück, als schnelle Mahlzeit unterwegs und zu Feiertagen gebacken. Charakteristisch ist der hauchdünne, von Hand gezogene Teig (petë), den geübte Bäckerinnen über den Handrücken bis zur Durchsichtigkeit dehnen — heute greifen viele Haushalte ersatzweise zu fertigem Filo- oder Yufka-Teig. Die Spinat-Käse-Füllung ist neben der mit Lauch oder der mit Hackfleisch die klassische vegetarische Variante. Regional unterscheidet sich der Byrek in Form (rund in der Pfanne, gerollt oder als Blech) und im verwendeten Käse. Als Sinnbild gastfreundlicher Hausmannskost steht er in jeder Bäckerei des Landes.", "persoenlich": "", "servier": "", "tags": ["Albanien", "Balkan", "vegetarisch", "Blätterteig", "Spinat", "Filo", "Straßenessen", "Frühstück", "osmanisch geprägt", "Pastete", "Snack", "Hausmannskost"]}, {"id": "trinxat", "status": "published", "date": "", "cover": "", "name": "Trinxat", "land": "Andorra", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein deftiges Bergmahl aus zerstampftem Wirsing und Kartoffeln, in der Pfanne knusprig gebraten. Winterküche der Pyrenäen, sättigend und einfach.", "zutaten": ["1 kleiner Wirsing", "600 g mehligkochende Kartoffeln", "3 Zehen Knoblauch", "4 EL Olivenöl", "100 g geräuchertes Rind oder luftgetrocknetes Lamm, gewürfelt", "Salz und Pfeffer"], "zutatenS": [{"menge": 1.0, "einheit": "", "item": "kleiner Wirsing", "roh": "1 kleiner Wirsing"}, {"menge": 600.0, "einheit": "g", "item": "mehligkochende Kartoffeln", "roh": "600 g mehligkochende Kartoffeln"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "3 Zehen Knoblauch"}, {"menge": 4.0, "einheit": "EL", "item": "Olivenöl", "roh": "4 EL Olivenöl"}, {"menge": 100.0, "einheit": "g", "item": "geräuchertes Rind oder luftgetrocknetes Lamm, gewürfelt", "roh": "100 g geräuchertes Rind oder luftgetrocknetes Lamm, gewürfelt"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Wirsing in Streifen schneiden und mit den geschälten, gewürfelten Kartoffeln in Salzwasser weich kochen.", "Abgießen, gut abtropfen lassen und grob zerstampfen, mit Salz und Pfeffer abschmecken.", "Knoblauch in Olivenöl anbraten, das geräucherte Rind kurz mitbraten.", "Die Wirsing-Kartoffel-Masse zugeben und in der Pfanne zu einem flachen Fladen drücken.", "Bei mittlerer Hitze braten, bis sich unten eine knusprige Kruste bildet, dann wenden.", "Heiß servieren, mit dem ausgelassenen Knoblauchöl beträufelt."], "hinweise": "Den Trinxat nicht zu fein stampfen — etwas Struktur gehört dazu.\n\nDie Kruste gelingt am besten in einer gut erhitzten Gusspfanne.\n\nStatt geräuchertem Rind passt auch geröstetes Brot oder Walnuss für eine vegetarische Variante.", "alternative": "Trinxat wird traditionell mit Speck oder Bauch vom Schwein zubereitet. Wir verwenden stattdessen geräuchertes Rind oder luftgetrocknetes Lamm — beides liefert die rauchig-herzhafte Note, ohne Schwein. Für eine rein vegetarische Fassung sorgen geröstete Walnüsse oder knusprige Brotwürfel für Biss.", "geschichte": "Trinxat stammt aus der Hochgebirgsregion der Pyrenäen, die Andorra mit der katalanischen Cerdanya teilt. Der Name leitet sich vom katalanischen „trinxar“ (zerkleinern, zerhacken) ab und beschreibt die Zubereitung: Wirsing und Kartoffeln werden gekocht und zu einer groben Masse zerstampft. Das Gericht ist klassische Winterkost — Wirsing übersteht Frost und wird sogar süßer, weshalb er in den kalten Monaten reichlich verfügbar war, als frisches Gemüse knapp wurde. Trinxat entstand als nahrhaftes Essen der Bergbauern, das aus wenigen lagerfähigen Zutaten satt machte. Traditionell wird es mit Speck zubereitet; in dieser Fassung wählen wir bewusst eine schweinefreie Variante. Bis heute gilt Trinxat als eines der identitätsstiftenden Gerichte Andorras und der angrenzenden Pyrenäentäler und steht im Winter auf vielen Speisekarten.", "persoenlich": "", "servier": "", "tags": ["Andorra", "Pyrenäen", "Cerdanya", "Wirsing", "Kartoffeln", "Winterküche", "Bergküche", "katalanisch geprägt", "vegetarisch möglich", "deftig", "Bauernküche", "Beilage"]}, {"id": "truita-de-riu-a-l-andorrana", "status": "published", "date": "", "cover": "", "name": "Truita de riu a l'andorrana", "land": "Andorra", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Bachforelle aus den Gebirgsbächen, in Mehl gewendet und in Olivenöl mit Knoblauch und Kräutern gebraten. Schlichte Bergküche, die den Fisch in den Mittelpunkt stellt.", "zutaten": ["4 küchenfertige Bachforellen", "4 EL Mehl", "6 EL Olivenöl", "4 Zehen Knoblauch, in Scheiben", "1 Zitrone", "1 Bund glatte Petersilie", "Salz und Pfeffer"], "zutatenS": [{"menge": 4.0, "einheit": "", "item": "küchenfertige Bachforellen", "roh": "4 küchenfertige Bachforellen"}, {"menge": 4.0, "einheit": "EL", "item": "Mehl", "roh": "4 EL Mehl"}, {"menge": 6.0, "einheit": "EL", "item": "Olivenöl", "roh": "6 EL Olivenöl"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch, in Scheiben", "roh": "4 Zehen Knoblauch, in Scheiben"}, {"menge": 1.0, "einheit": "", "item": "Zitrone", "roh": "1 Zitrone"}, {"menge": 1.0, "einheit": "Bund", "item": "glatte Petersilie", "roh": "1 Bund glatte Petersilie"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Forellen innen und außen salzen und pfeffern, in Mehl wenden und überschüssiges Mehl abklopfen.", "Olivenöl in einer großen Pfanne erhitzen und die Knoblauchscheiben goldgelb braten, herausnehmen.", "Forellen im aromatisierten Öl je Seite 4–5 Minuten knusprig braten.", "Den gebratenen Knoblauch zurück in die Pfanne geben.", "Mit Zitronensaft beträufeln und gehackte Petersilie darüberstreuen.", "Sofort servieren, dazu passen Salzkartoffeln oder gedünstetes Gemüse."], "hinweise": "Das Öl muss heiß genug sein, damit die Haut knusprig wird und nicht festklebt.\n\nDie Forelle nur einmal wenden, sonst zerfällt sie.\n\nFrische Kräuter erst zum Schluss zugeben, damit sie ihr Aroma behalten.", "alternative": "", "geschichte": "Die Bäche und Flüsse der andorranischen Hochtäler sind reich an Bachforellen, und der Fisch gehört seit jeher zur Ernährung der Bergbevölkerung. „Truita de riu“ bedeutet schlicht Flussforelle — nicht zu verwechseln mit „truita“ als katalanischem Wort für Omelett. In einer Region, in der frischer Seefisch über Jahrhunderte unerreichbar war, lieferten die heimischen Forellen wertvolles, frisches Eiweiß. Die Zubereitung ist bewusst einfach gehalten und folgt der Logik der Bergküche: Der Fisch wird in Mehl gewendet und in reichlich Olivenöl knusprig gebraten, oft mit viel Knoblauch und etwas Kräutern. Manche Varianten umwickeln die Forelle mit Schinken; in dieser Fassung bleibt der reine Fischgeschmack im Vordergrund. Das Gericht steht für die enge Bindung Andorras an seine Berglandschaft und seine Gewässer und wird häufig mit einfachem Gemüse oder Kartoffeln gereicht.", "persoenlich": "", "servier": "", "tags": ["Andorra", "Pyrenäen", "Forelle", "Fisch", "Bergküche", "Olivenöl", "Knoblauch", "schlicht", "Süßwasserfisch", "katalanisch geprägt", "regional", "Hauptgericht"]}, {"id": "coca", "status": "published", "date": "", "cover": "", "name": "Coca", "land": "Andorra", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein flaches Hefegebäck der katalanischen Pyrenäen, in süßer Form mit Zucker und Pinienkernen bestreut. Festtagsgebäck, das zu Feiern und Jahreswenden gehört.", "zutaten": ["300 g Mehl", "120 ml lauwarme Milch", "15 g frische Hefe", "60 g Zucker (plus etwas zum Bestreuen)", "1 Ei", "50 ml Olivenöl", "40 g Pinienkerne", "1 Prise Anis oder abgeriebene Zitronenschale"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "Mehl", "roh": "300 g Mehl"}, {"menge": 120.0, "einheit": "ml", "item": "lauwarme Milch", "roh": "120 ml lauwarme Milch"}, {"menge": 15.0, "einheit": "g", "item": "frische Hefe", "roh": "15 g frische Hefe"}, {"menge": 60.0, "einheit": "g", "item": "Zucker (plus etwas zum Bestreuen)", "roh": "60 g Zucker (plus etwas zum Bestreuen)"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 50.0, "einheit": "ml", "item": "Olivenöl", "roh": "50 ml Olivenöl"}, {"menge": 40.0, "einheit": "g", "item": "Pinienkerne", "roh": "40 g Pinienkerne"}, {"menge": 1.0, "einheit": "Prise", "item": "Anis oder abgeriebene Zitronenschale", "roh": "1 Prise Anis oder abgeriebene Zitronenschale"}], "zubereitung": ["Hefe in der lauwarmen Milch mit etwas Zucker auflösen und 10 Minuten anspringen lassen.", "Mehl mit Zucker, Ei, Öl, Anis und der Hefemilch zu einem geschmeidigen Teig kneten.", "Zugedeckt an einem warmen Ort etwa 1 Stunde gehen lassen, bis er sich verdoppelt.", "Teig flach und länglich auf ein Blech ausstreichen.", "Mit Olivenöl bestreichen, mit Zucker und Pinienkernen bestreuen.", "Bei 200 °C 18–22 Minuten goldbraun backen; lauwarm oder kalt servieren."], "hinweise": "Den Teig nicht zu dick ausrollen — die Coca soll flach und knusprig sein.\n\nPinienkerne vor dem Backen leicht andrücken, damit sie nicht abfallen.\n\nMit kandierten Früchten wird daraus die festliche Coca de Sant Joan.", "alternative": "", "geschichte": "Die Coca ist ein flaches Backwerk, das im gesamten katalanischsprachigen Raum verbreitet ist — von Katalonien über Valencia bis nach Andorra — und in unzähligen süßen wie herzhaften Varianten existiert. Ihr Ursprung reicht weit zurück; sie gilt als das katalanische Gegenstück zu Fladenbroten und Focacce des Mittelmeerraums. In Andorra hat die süße Coca, oft mit Zucker, Anis und Pinienkernen, einen festen Platz im Festtagskalender und ist besonders mit der Sommersonnenwende (Sant Joan) verbunden, zu der die „coca de Sant Joan“ gebacken wird. Die Form ist charakteristisch länglich und flach, der Teig je nach Rezept brotartig oder feiner und süßer. Coca war lange ein Gebäck, das man zu Hause oder beim Dorfbäcker zu besonderen Anlässen herstellte, und steht damit für die gemeinschaftlichen Feste der Region. Schweinefleisch kommt in der süßen Variante ohnehin nicht vor.", "persoenlich": "", "servier": "", "tags": ["Andorra", "Katalonien", "Pyrenäen", "Hefegebäck", "süß", "Pinienkerne", "Festtag", "Sant Joan", "vegetarisch", "Dessert", "mediterran", "Tradition"]}, {"id": "moules-frites", "status": "published", "date": "", "cover": "", "name": "Moules-frites", "land": "Belgien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Miesmuscheln, in Weißwein mit Sellerie und Zwiebeln gedämpft, serviert mit knusprigen Pommes frites. Das belgische Nationalgericht schlechthin.", "zutaten": ["2 kg frische Miesmuscheln", "2 Zwiebeln, gewürfelt", "3 Stangen Staudensellerie, in Scheiben", "200 ml trockener Weißwein", "50 g Butter", "1 Bund Petersilie", "1 kg Kartoffeln (zum Frittieren)", "Salz und Pfeffer"], "zutatenS": [{"menge": 2.0, "einheit": "kg", "item": "frische Miesmuscheln", "roh": "2 kg frische Miesmuscheln"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, gewürfelt", "roh": "2 Zwiebeln, gewürfelt"}, {"menge": 3.0, "einheit": "Stangen", "item": "Staudensellerie, in Scheiben", "roh": "3 Stangen Staudensellerie, in Scheiben"}, {"menge": 200.0, "einheit": "ml", "item": "trockener Weißwein", "roh": "200 ml trockener Weißwein"}, {"menge": 50.0, "einheit": "g", "item": "Butter", "roh": "50 g Butter"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": 1.0, "einheit": "kg", "item": "Kartoffeln (zum Frittieren)", "roh": "1 kg Kartoffeln (zum Frittieren)"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Muscheln gründlich waschen, Bärte entfernen; geöffnete, die sich nicht schließen, aussortieren.", "Kartoffeln in Stifte schneiden, wässern, trocknen und zweifach frittieren (erst bei 150 °C, dann bei 180 °C goldbraun).", "Butter in einem großen Topf schmelzen, Zwiebeln und Sellerie andünsten.", "Weißwein angießen, aufkochen, Muscheln zugeben und zugedeckt 4–6 Minuten dämpfen, bis sie sich öffnen.", "Geschlossen gebliebene Muscheln entfernen, mit Pfeffer und Petersilie abschmecken.", "Im Topf mit den frischen Pommes und Mayonnaise servieren."], "hinweise": "Muscheln nur kurz dämpfen, sonst werden sie zäh.\n\nDen Muschelsud nicht wegschütten — er ist als Brühe köstlich.\n\nFür extra Aroma einen Lorbeer und etwas Thymian mitdämpfen.", "alternative": "", "geschichte": "Moules-frites verbindet zwei belgische Wahrzeichen: die Miesmuschel und die frittierte Kartoffel. Die Kombination etablierte sich im 19. und frühen 20. Jahrhundert, als Muscheln von der Nordseeküste preiswert ins Binnenland gelangten und Pommes frites — die Belgien für sich als Erfindung beansprucht — zur volkstümlichen Beilage wurden. Gemeinsam ergaben sie eine günstige, sättigende Mahlzeit, die in Brasserien und Frituren des ganzen Landes heimisch wurde. Klassisch werden die Muscheln „marinière“ zubereitet: rasch in einem Sud aus Weißwein, Zwiebel und Sellerie gedämpft, bis sich die Schalen öffnen. Serviert wird im schwarzen Topf, aus dem heraus gegessen wird, die Pommes dazu in Papier oder Schälchen, oft mit Mayonnaise. Die Hochsaison fällt traditionell in die Monate mit „R“ im Namen. Moules-frites steht für die unkomplizierte, gesellige Esskultur Belgiens.", "persoenlich": "", "servier": "", "tags": ["Belgien", "Nordsee", "Muscheln", "Meeresfrüchte", "Pommes frites", "Nationalgericht", "Brasserie", "Weißwein", "gesellig", "Küstenküche", "Hauptgericht", "Klassiker"]}, {"id": "carbonade-flamande", "status": "published", "date": "", "cover": "", "name": "Carbonade flamande", "land": "Belgien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein flämischer Rindfleischeintopf, langsam in dunklem Bier geschmort und mit etwas Lebkuchen und Senf gebunden. Süßlich-herb und tiefdunkel.", "zutaten": ["1 kg Rindfleisch zum Schmoren, in Würfeln", "3 Zwiebeln, in Ringen", "330 ml dunkles belgisches Bier", "2 Scheiben Lebkuchen (pain d'épices)", "2 EL scharfer Senf", "1 EL Rotweinessig", "1 Lorbeerblatt", "40 g Butter", "Salz und Pfeffer"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "Rindfleisch zum Schmoren, in Würfeln", "roh": "1 kg Rindfleisch zum Schmoren, in Würfeln"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln, in Ringen", "roh": "3 Zwiebeln, in Ringen"}, {"menge": 330.0, "einheit": "ml", "item": "dunkles belgisches Bier", "roh": "330 ml dunkles belgisches Bier"}, {"menge": 2.0, "einheit": "Scheiben", "item": "Lebkuchen (pain d'épices)", "roh": "2 Scheiben Lebkuchen (pain d'épices)"}, {"menge": 2.0, "einheit": "EL", "item": "scharfer Senf", "roh": "2 EL scharfer Senf"}, {"menge": 1.0, "einheit": "EL", "item": "Rotweinessig", "roh": "1 EL Rotweinessig"}, {"menge": 1.0, "einheit": "", "item": "Lorbeerblatt", "roh": "1 Lorbeerblatt"}, {"menge": 40.0, "einheit": "g", "item": "Butter", "roh": "40 g Butter"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Rindfleischwürfel salzen, pfeffern und in Butter portionsweise kräftig anbraten, herausnehmen.", "Zwiebeln im Bratfett goldbraun dünsten.", "Fleisch zurückgeben, mit Bier ablöschen und Essig sowie Lorbeer zugeben.", "Lebkuchenscheiben mit Senf bestreichen und mit der Senfseite nach unten auflegen.", "Zugedeckt bei kleiner Hitze 2,5–3 Stunden schmoren, bis das Fleisch zerfällt und die Sauce sämig ist.", "Mit Salz und Pfeffer abschmecken und mit Pommes frites servieren."], "hinweise": "Je länger die Carbonade schmort, desto zarter wird sie — Eile lohnt nicht.\n\nEin leicht süßes Bier ergibt die typische Balance; sehr bittere Sorten meiden.\n\nAm zweiten Tag aufgewärmt schmeckt sie noch intensiver.", "alternative": "", "geschichte": "Die Carbonade flamande (niederländisch „stoofvlees“ oder „stoverij“) ist der flämische Klassiker der Schmorküche und das bierbasierte Gegenstück zum französischen Bœuf bourguignon. Statt Wein verwendet sie das, was in Flandern reichlich vorhanden war: dunkles, oft leicht süßes Bier. Das Gericht entstand als Art, zähere, günstige Rindfleischstücke durch langes, sanftes Schmoren mürbe und schmackhaft zu machen. Charakteristisch ist die Bindung und Süße durch eine Scheibe mit Senf bestrichenen Lebkuchen (pain d'épices), die im Sud zerfällt, sowie ein Schuss Essig oder etwas Zucker für die typische süß-saure Balance. Die Carbonade wird traditionell mit Pommes frites serviert und gehört zum festen Repertoire der flämischen Brasserien. Sie ist von Natur aus ohne Schweinefleisch und zeigt, wie eng belgische Ess- und Bierkultur miteinander verwoben sind.", "persoenlich": "", "servier": "", "tags": ["Belgien", "Flandern", "Rind", "Schmorgericht", "Bier", "Lebkuchen", "süß-herb", "Eintopf", "Brasserie", "Winterküche", "Hauptgericht", "Klassiker"]}, {"id": "gaufre-de-li-ge", "status": "published", "date": "", "cover": "", "name": "Gaufre de Liège", "land": "Belgien", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine dichte, karamellisierte Hefewaffel aus Lüttich mit knusprigen Stücken aus Hagelzucker. Süßes Wahrzeichen Belgiens, warm aus dem Eisen am besten.", "zutaten": ["250 g Mehl", "120 ml lauwarme Milch", "15 g frische Hefe", "1 Ei", "125 g weiche Butter", "150 g Hagelzucker (Perlzucker)", "1 Prise Salz", "1 TL Vanillezucker"], "zutatenS": [{"menge": 250.0, "einheit": "g", "item": "Mehl", "roh": "250 g Mehl"}, {"menge": 120.0, "einheit": "ml", "item": "lauwarme Milch", "roh": "120 ml lauwarme Milch"}, {"menge": 15.0, "einheit": "g", "item": "frische Hefe", "roh": "15 g frische Hefe"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 125.0, "einheit": "g", "item": "weiche Butter", "roh": "125 g weiche Butter"}, {"menge": 150.0, "einheit": "g", "item": "Hagelzucker (Perlzucker)", "roh": "150 g Hagelzucker (Perlzucker)"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}, {"menge": 1.0, "einheit": "TL", "item": "Vanillezucker", "roh": "1 TL Vanillezucker"}], "zubereitung": ["Hefe in der lauwarmen Milch auflösen und kurz anspringen lassen.", "Mehl, Ei, Salz, Vanillezucker und die Hefemilch zu einem Teig verkneten.", "Die weiche Butter stückweise einarbeiten, bis ein glatter, klebriger Teig entsteht.", "Zugedeckt etwa 1 Stunde gehen lassen, dann den Hagelzucker unterheben.", "Portionen formen und im vorgeheizten Waffeleisen 3–5 Minuten goldbraun backen.", "Kurz abkühlen lassen, damit der karamellisierte Zucker fest wird; warm servieren."], "hinweise": "Echten Hagelzucker verwenden — normaler Zucker karamellisiert nicht in Stücken.\n\nDen Teig nicht zu lange gehen lassen, sonst wird die Waffel zu locker.\n\nFrisch gebacken und leicht abgekühlt schmecken sie am besten.", "alternative": "", "geschichte": "Die Lütticher Waffel (Gaufre de Liège) unterscheidet sich grundlegend von der leichteren, rechteckigen Brüsseler Waffel: Sie wird aus einem schweren Hefeteig gebacken, in den grober Hagelzucker (perlzucker) eingearbeitet ist. Beim Backen schmilzt dieser Zucker teilweise und karamellisiert an der Oberfläche, was der Waffel ihre charakteristische knusprige, leicht klebrige Kruste und unregelmäßige Form gibt. Ihren Ursprung hat sie in der Region um Lüttich; einer verbreiteten Erzählung nach soll sie im 18. Jahrhundert am Hof des Fürstbischofs entstanden sein. Über die Jahrhunderte wurde sie vom feinen Gebäck zum allgegenwärtigen Straßenessen, das man warm und ohne weiteres Topping aus der Hand isst. Heute ist sie eines der bekanntesten süßen Symbole Belgiens und an Ständen im ganzen Land zu finden. Als reines Hefegebäck ist sie selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Belgien", "Lüttich", "Waffel", "Hefegebäck", "Hagelzucker", "süß", "Straßenessen", "karamellisiert", "vegetarisch", "Dessert", "Wahrzeichen", "warm"]}, {"id": "evapi", "status": "published", "date": "", "cover": "", "name": "Ćevapi", "land": "Bosnien und Herzegowina", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine, gegrillte Hackfleischröllchen aus Rind und Lamm, serviert im fladenartigen Somun mit rohen Zwiebeln und Ajvar. Bosniens beliebtestes Grillgericht.", "zutaten": ["500 g Rinderhackfleisch", "300 g Lammhackfleisch", "3 Zehen Knoblauch, fein gerieben", "1 TL Natron", "1 TL Salz", "0.5 TL Pfeffer", "4 Fladenbrote (Somun oder Pita)", "2 Zwiebeln, fein gewürfelt", "Ajvar zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Rinderhackfleisch", "roh": "500 g Rinderhackfleisch"}, {"menge": 300.0, "einheit": "g", "item": "Lammhackfleisch", "roh": "300 g Lammhackfleisch"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch, fein gerieben", "roh": "3 Zehen Knoblauch, fein gerieben"}, {"menge": 1.0, "einheit": "TL", "item": "Natron", "roh": "1 TL Natron"}, {"menge": 1.0, "einheit": "TL", "item": "Salz", "roh": "1 TL Salz"}, {"menge": 0.5, "einheit": "TL", "item": "Pfeffer", "roh": "0.5 TL Pfeffer"}, {"menge": 4.0, "einheit": "", "item": "Fladenbrote (Somun oder Pita)", "roh": "4 Fladenbrote (Somun oder Pita)"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, fein gewürfelt", "roh": "2 Zwiebeln, fein gewürfelt"}, {"menge": null, "einheit": "", "item": "Ajvar zum Servieren", "roh": "Ajvar zum Servieren"}], "zubereitung": ["Beide Hackfleischsorten mit Knoblauch, Natron, Salz und Pfeffer gründlich verkneten.", "Die Masse abgedeckt mehrere Stunden, am besten über Nacht, kühl ruhen lassen.", "Mit feuchten Händen kleine, fingerdicke Röllchen formen.", "Über Holzkohle oder in einer heißen Grillpfanne rundum kräftig grillen.", "Fladenbrot kurz mit aufwärmen und aufschneiden.", "Ćevapi im Brot mit rohen Zwiebeln und Ajvar servieren."], "hinweise": "Das Natron macht die Ćevapi locker — nicht weglassen, aber sparsam dosieren.\n\nDie Ruhezeit ist entscheidend für Bindung und Geschmack.\n\nNicht zu lange grillen, sonst werden sie trocken.", "alternative": "", "geschichte": "Ćevapi (oder Ćevapčići) gehören zu den bekanntesten Gerichten des Balkans und sind in Bosnien und Herzegowina besonders identitätsstiftend, allen voran die Sarajevoer und Banja-Luka-Schulen mit jeweils eigenem Stil. Ihre Wurzeln liegen in der osmanischen Grillküche (kebab), die sich über Jahrhunderte in der Region zu einer eigenständigen Tradition entwickelte. Charakteristisch ist die Würzung aus überwiegend Rind- und Lammfleisch — in der mehrheitlich muslimisch geprägten Region traditionell ohne Schwein — fein gewolft, nur dezent gewürzt und über Holzkohle gegrillt. Serviert werden Ćevapi in einer Portion von fünf oder zehn Stück im warmen Fladenbrot Somun, dazu reichlich rohe Zwiebeln, manchmal Kajmak oder Ajvar. Das Gericht ist fest in der Alltags- und Ausgehkultur verankert und wird in spezialisierten Lokalen, den Ćevabdžinicas, gegessen. Es steht sinnbildlich für die geteilte Esskultur Südosteuropas.", "persoenlich": "", "servier": "", "tags": ["Bosnien", "Balkan", "Rind", "Lamm", "Hackfleisch", "Grillgericht", "Somun", "Ajvar", "osmanisch geprägt", "Sarajevo", "Straßenessen", "Hauptgericht"]}, {"id": "bosanski-lonac", "status": "published", "date": "", "cover": "", "name": "Bosanski lonac", "land": "Bosnien und Herzegowina", "kontinent": "Europa", "gang": "Suppe", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein geschichteter Schmortopf aus Rind oder Lamm und vielerlei Gemüse, der über Stunden langsam gart. Der bosnische Eintopf für lange Tafeln.", "zutaten": ["400 g Rindfleisch, in Würfeln", "400 g Lammfleisch, in Würfeln", "4 Kartoffeln, in Stücken", "0.5 Weißkohl, in Streifen", "3 Möhren, in Scheiben", "2 Paprika, in Stücken", "3 Tomaten, gewürfelt", "2 Zwiebeln, in Ringen", "300 ml Brühe oder Wasser", "Salz, Pfeffer, Lorbeer"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Rindfleisch, in Würfeln", "roh": "400 g Rindfleisch, in Würfeln"}, {"menge": 400.0, "einheit": "g", "item": "Lammfleisch, in Würfeln", "roh": "400 g Lammfleisch, in Würfeln"}, {"menge": 4.0, "einheit": "", "item": "Kartoffeln, in Stücken", "roh": "4 Kartoffeln, in Stücken"}, {"menge": 0.5, "einheit": "", "item": "Weißkohl, in Streifen", "roh": "0.5 Weißkohl, in Streifen"}, {"menge": 3.0, "einheit": "", "item": "Möhren, in Scheiben", "roh": "3 Möhren, in Scheiben"}, {"menge": 2.0, "einheit": "", "item": "Paprika, in Stücken", "roh": "2 Paprika, in Stücken"}, {"menge": 3.0, "einheit": "", "item": "Tomaten, gewürfelt", "roh": "3 Tomaten, gewürfelt"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, in Ringen", "roh": "2 Zwiebeln, in Ringen"}, {"menge": 300.0, "einheit": "ml", "item": "Brühe oder Wasser", "roh": "300 ml Brühe oder Wasser"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, Lorbeer", "roh": "Salz, Pfeffer, Lorbeer"}], "zubereitung": ["Fleisch und Gemüse vorbereiten und in mundgerechte Stücke schneiden.", "Topf abwechselnd mit Fleisch und Gemüse schichten, dazwischen salzen und pfeffern.", "Lorbeer einlegen und mit Brühe angießen, bis etwa zwei Drittel bedeckt sind.", "Zugedeckt bei sehr niedriger Hitze auf dem Herd oder im Ofen bei 150 °C 3–4 Stunden garen.", "Nicht umrühren, nur gelegentlich den Topf bewegen, damit die Schichtung erhalten bleibt.", "Direkt aus dem Topf mit Brot servieren."], "hinweise": "Geduld ist entscheidend — das lange, sanfte Garen macht das Gericht aus.\n\nFestkochende Kartoffeln behalten besser ihre Form.\n\nDie Zusammenstellung des Gemüses lässt sich nach Saison frei anpassen.", "alternative": "", "geschichte": "Bosanski lonac — der „bosnische Topf“ — ist ein Schmorgericht, das nach dem Gefäß benannt ist, in dem es zubereitet wird: einem hohen, bauchigen Tontopf. Charakteristisch ist die Zubereitung, bei der Fleisch und Gemüse nicht angebraten, sondern roh in Schichten in den Topf gelegt und dann sehr langsam, traditionell stundenlang über niedriger Glut oder im Backofen, gegart werden. Dabei vermischen sich die Säfte zu einem aromatischen Sud. Das Gericht stammt aus der ländlichen Küche und war ein praktisches Essen, das man ansetzen und sich selbst überlassen konnte, während die Arbeit weiterging. Verwendet werden meist Rind und Lamm — in der Region traditionell ohne Schwein — sowie Kartoffeln, Kohl, Möhren, Paprika und Tomaten, je nach Saison und Vorrat. Bosanski lonac gilt als geselliges Gericht für viele Esser und steht für die unaufgeregte, geduldige Hausmannskost Bosniens.", "persoenlich": "", "servier": "", "tags": ["Bosnien", "Balkan", "Rind", "Lamm", "Eintopf", "Schmorgericht", "Tontopf", "Gemüse", "langsam gegart", "Hausmannskost", "gesellig", "Hauptgericht"]}, {"id": "tufahije", "status": "published", "date": "", "cover": "", "name": "Tufahije", "land": "Bosnien und Herzegowina", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ganze, in Zuckersirup pochierte Äpfel, gefüllt mit gezuckerten Walnüssen und gekrönt mit Schlagsahne. Ein elegantes Dessert mit osmanischen Wurzeln.", "zutaten": ["4 feste, säuerliche Äpfel", "150 g gemahlene Walnüsse", "200 g Zucker", "500 ml Wasser", "1 Zitrone (Saft)", "200 ml Schlagsahne", "1 TL Vanillezucker", "4 Walnusshälften zum Garnieren"], "zutatenS": [{"menge": 4.0, "einheit": "", "item": "feste, säuerliche Äpfel", "roh": "4 feste, säuerliche Äpfel"}, {"menge": 150.0, "einheit": "g", "item": "gemahlene Walnüsse", "roh": "150 g gemahlene Walnüsse"}, {"menge": 200.0, "einheit": "g", "item": "Zucker", "roh": "200 g Zucker"}, {"menge": 500.0, "einheit": "ml", "item": "Wasser", "roh": "500 ml Wasser"}, {"menge": 1.0, "einheit": "", "item": "Zitrone (Saft)", "roh": "1 Zitrone (Saft)"}, {"menge": 200.0, "einheit": "ml", "item": "Schlagsahne", "roh": "200 ml Schlagsahne"}, {"menge": 1.0, "einheit": "TL", "item": "Vanillezucker", "roh": "1 TL Vanillezucker"}, {"menge": 4.0, "einheit": "", "item": "Walnusshälften zum Garnieren", "roh": "4 Walnusshälften zum Garnieren"}], "zubereitung": ["Äpfel schälen und das Kerngehäuse vorsichtig aushöhlen, ohne sie zu durchbrechen.", "Aus Wasser, Zucker und Zitronensaft einen Sirup aufkochen.", "Äpfel im Sirup bei kleiner Hitze 10–15 Minuten weich, aber formstabil pochieren; herausnehmen und abkühlen lassen.", "Gemahlene Walnüsse mit etwas Sirup zu einer formbaren Masse verkneten.", "Die abgekühlten Äpfel mit der Walnussmasse füllen.", "Sahne mit Vanillezucker steif schlagen, auf die Äpfel setzen und mit einer Walnusshälfte garnieren; gekühlt servieren."], "hinweise": "Säuerliche Äpfel halten besser ihre Form und balancieren die Süße.\n\nEtwas vom Sirup über die fertigen Tufahije träufeln für mehr Glanz und Aroma.\n\nVor dem Servieren gut durchkühlen lassen.", "alternative": "", "geschichte": "Tufahije ist ein traditionelles Dessert Bosniens, dessen Name sich vom arabischen Wort für Apfel („tuffah“) ableitet — ein deutlicher Hinweis auf seinen osmanisch-orientalischen Ursprung. Es kam mit der osmanischen Herrschaft auf den Balkan und wurde in Bosnien zu einem festen Bestandteil der Süßspeisenkultur, die für ihre sirupgetränkten und nussgefüllten Spezialitäten bekannt ist. Zubereitet werden ganze, geschälte Äpfel, die schonend in Zuckersirup weichgekocht und anschließend mit einer Füllung aus gemahlenen Walnüssen und Zucker gefüllt werden. Gekrönt wird das Dessert mit einer Haube aus Schlagsahne und oft einer einzelnen Walnusshälfte. Tufahije wird traditionell gekühlt in Glasschalen serviert und gehört zu festlichen Anlässen, Gästebewirtung und dem Ende üppiger Mahlzeiten. Es zeigt die Vorliebe der bosnischen Küche für Desserts, die Süße mit der Frische von Obst und der Textur von Nüssen verbinden, und ist selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Bosnien", "Balkan", "Dessert", "Apfel", "Walnuss", "Sirup", "osmanisch geprägt", "Sahne", "Festtag", "vegetarisch", "gefülltes Obst", "Süßspeise"]}, {"id": "banitsa", "status": "published", "date": "", "cover": "", "name": "Banitsa", "land": "Bulgarien", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine gewundene Blätterteigpastete mit bulgarischem Sirene-Käse und Eiern, knusprig gebacken. Frühstücks- und Festtagsklassiker, oft in Spiralform.", "zutaten": ["400 g Filo-/Yufka-Teigblätter (kori)", "300 g bulgarisches Sirene oder Feta, zerbröselt", "3 Eier", "150 g Naturjoghurt", "80 g Butter, geschmolzen", "0.5 TL Natron", "etwas Öl für die Form"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Filo-/Yufka-Teigblätter (kori)", "roh": "400 g Filo-/Yufka-Teigblätter (kori)"}, {"menge": 300.0, "einheit": "g", "item": "bulgarisches Sirene oder Feta, zerbröselt", "roh": "300 g bulgarisches Sirene oder Feta, zerbröselt"}, {"menge": 3.0, "einheit": "", "item": "Eier", "roh": "3 Eier"}, {"menge": 150.0, "einheit": "g", "item": "Naturjoghurt", "roh": "150 g Naturjoghurt"}, {"menge": 80.0, "einheit": "g", "item": "Butter, geschmolzen", "roh": "80 g Butter, geschmolzen"}, {"menge": 0.5, "einheit": "TL", "item": "Natron", "roh": "0.5 TL Natron"}, {"menge": null, "einheit": "", "item": "etwas Öl für die Form", "roh": "etwas Öl für die Form"}], "zubereitung": ["Eier mit Joghurt, Natron und dem zerbröselten Käse verrühren.", "Jeweils ein Teigblatt mit geschmolzener Butter bestreichen und etwas Füllung darauf verteilen.", "Das Blatt locker zu einer Rolle aufwickeln.", "Die Rollen schneckenförmig in eine geölte runde Form legen.", "Mit restlicher Butter bestreichen und bei 180 °C 35–40 Minuten goldbraun backen.", "Kurz ruhen lassen, dann lauwarm in Stücken servieren."], "hinweise": "Die Teigblätter nicht austrocknen lassen — abgedeckt halten.\n\nEtwas Mineralwasser über die fertige Banitsa geträufelt macht sie besonders saftig.\n\nZu Silvester eine in Folie gewickelte Münze einbacken — bulgarische Glückstradition.", "alternative": "", "geschichte": "Banitsa ist eines der bekanntesten Gebäcke Bulgariens und steht im Land sowohl für den Alltag als auch für besondere Anlässe. Sie besteht aus dünn ausgezogenen Teigblättern (kori), die mit einer Mischung aus bulgarischem Sirene (Salzlakenkäse), Eiern und Joghurt geschichtet oder gerollt und dann gebacken werden. Die Tradition dünn gezogener Teige teilt Bulgarien mit dem gesamten Balkan und reicht über die osmanische Zeit zurück. Eine besondere Rolle spielt die Banitsa zu Silvester und Neujahr: In die festliche „Banitsa s kasmeti“ werden kleine Botschaften oder ein Münzchen eingebacken, die dem Finder Glück für das kommende Jahr verheißen. Auch zum Frühstück, oft begleitet von Ayran oder dem Getränk Boza, ist sie allgegenwärtig. Regional variiert die Form von der klassischen Spirale bis zu geschichteten Blechen. Banitsa gilt als Inbegriff bulgarischer Gastlichkeit und Hausbäckerei und kommt ganz ohne Schweinefleisch aus.", "persoenlich": "", "servier": "", "tags": ["Bulgarien", "Balkan", "vegetarisch", "Blätterteig", "Sirene", "Käse", "Frühstück", "Festtag", "Silvester", "Pastete", "Spirale", "Hausbäckerei"]}, {"id": "shopska-salata", "status": "published", "date": "", "cover": "", "name": "Shopska salata", "land": "Bulgarien", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 10, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein frischer Salat aus Tomaten, Gurken, Paprika und Zwiebeln, großzügig mit geriebenem Sirene-Käse bedeckt. Bulgariens bekanntester Salat, in den Landesfarben.", "zutaten": ["4 reife Tomaten", "1 Salatgurke", "1 grüne Paprika", "1 kleine Zwiebel", "150 g bulgarisches Sirene oder Feta", "3 EL Sonnenblumen- oder Olivenöl", "1 EL Rotweinessig", "1 Bund Petersilie", "Salz"], "zutatenS": [{"menge": 4.0, "einheit": "", "item": "reife Tomaten", "roh": "4 reife Tomaten"}, {"menge": 1.0, "einheit": "", "item": "Salatgurke", "roh": "1 Salatgurke"}, {"menge": 1.0, "einheit": "", "item": "grüne Paprika", "roh": "1 grüne Paprika"}, {"menge": 1.0, "einheit": "", "item": "kleine Zwiebel", "roh": "1 kleine Zwiebel"}, {"menge": 150.0, "einheit": "g", "item": "bulgarisches Sirene oder Feta", "roh": "150 g bulgarisches Sirene oder Feta"}, {"menge": 3.0, "einheit": "EL", "item": "Sonnenblumen- oder Olivenöl", "roh": "3 EL Sonnenblumen- oder Olivenöl"}, {"menge": 1.0, "einheit": "EL", "item": "Rotweinessig", "roh": "1 EL Rotweinessig"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Tomaten, Gurke und Paprika in mundgerechte Stücke schneiden.", "Zwiebel in feine Ringe oder Würfel schneiden.", "Alles in einer Schüssel mischen, salzen und mit Öl und Essig anmachen.", "Den Salat auf Tellern anrichten.", "Das Sirene grob reiben und großzügig über den Salat häufen.", "Mit gehackter Petersilie bestreuen und sofort servieren."], "hinweise": "Den Käse erst zum Schluss darüberreiben, damit er locker bleibt.\n\nGeröstete Paprika statt roher gibt eine rauchigere Note.\n\nAm besten mit sonnengereiften Sommertomaten.", "alternative": "", "geschichte": "Die Shopska salata gilt als nationaler Salat Bulgariens und ist im ganzen Land sowie weit über die Grenzen hinaus bekannt. Ihr Name verweist auf die Region Shopluk rund um Sofia, doch ihre heutige, standardisierte Form entstand maßgeblich im 20. Jahrhundert, als sie unter anderem touristisch als bulgarische Spezialität beworben wurde. Die Zutaten — rote Tomaten, grüne Paprika und Gurken, weißer Sirene-Käse — werden gern mit den Farben der bulgarischen Flagge in Verbindung gebracht. Der Salat folgt dem mediterran-balkanischen Prinzip frischer, roher Gemüse, abgerundet mit dem salzigen Lakenkäse, der fein gerieben wie Schnee über das Gericht gehäuft wird. Traditionell wird die Shopska salata als Vorspeise gegessen und oft von Rakija, dem heimischen Obstbrand, begleitet. Sie ist von Natur aus vegetarisch und ohne Schweinefleisch und steht für die einfache, frische Seite der bulgarischen Küche.", "persoenlich": "", "servier": "", "tags": ["Bulgarien", "Balkan", "Salat", "vegetarisch", "Tomaten", "Gurke", "Sirene", "Vorspeise", "frisch", "Sommerküche", "Rakija", "Nationalgericht"]}, {"id": "tarator", "status": "published", "date": "", "cover": "", "name": "Tarator", "land": "Bulgarien", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine kalte Sommersuppe aus Joghurt, Gurke, Knoblauch, Walnüssen und Dill. Erfrischend, leicht und an heißen Tagen allgegenwärtig.", "zutaten": ["500 g Naturjoghurt", "1 Salatgurke", "2 Zehen Knoblauch", "40 g Walnüsse, gehackt", "2 EL Olivenöl", "1 Bund Dill", "150 ml kaltes Wasser", "Salz", "Eiswürfel zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Naturjoghurt", "roh": "500 g Naturjoghurt"}, {"menge": 1.0, "einheit": "", "item": "Salatgurke", "roh": "1 Salatgurke"}, {"menge": 2.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "2 Zehen Knoblauch"}, {"menge": 40.0, "einheit": "g", "item": "Walnüsse, gehackt", "roh": "40 g Walnüsse, gehackt"}, {"menge": 2.0, "einheit": "EL", "item": "Olivenöl", "roh": "2 EL Olivenöl"}, {"menge": 1.0, "einheit": "Bund", "item": "Dill", "roh": "1 Bund Dill"}, {"menge": 150.0, "einheit": "ml", "item": "kaltes Wasser", "roh": "150 ml kaltes Wasser"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}, {"menge": null, "einheit": "", "item": "Eiswürfel zum Servieren", "roh": "Eiswürfel zum Servieren"}], "zubereitung": ["Gurke schälen und fein würfeln oder grob raspeln.", "Knoblauch mit etwas Salz zu einer Paste zerdrücken.", "Joghurt glatt rühren und mit kaltem Wasser auf die gewünschte Konsistenz verdünnen.", "Gurke, Knoblauch, Walnüsse, Olivenöl und gehackten Dill unterrühren.", "Mit Salz abschmecken und mindestens eine Stunde kühl stellen.", "Eiskalt, gern mit Eiswürfeln und etwas Dill, servieren."], "hinweise": "Sehr kalt servieren — Tarator ist eine Erfrischung, keine warme Suppe.\n\nDie Konsistenz nach Geschmack regeln: dünner als Suppe, dicker als Dip.\n\nGeröstete Walnüsse intensivieren das Aroma.", "alternative": "", "geschichte": "Tarator ist die klassische kalte Joghurtsuppe Bulgariens und ein Inbegriff der sommerlichen Küche des Landes. Sie beruht auf zwei Säulen der balkanischen Ernährung: dem fermentierten Joghurt, für den Bulgarien berühmt ist, und frischen Gurken. Verwandte kalte Joghurt-Gurken-Speisen finden sich im gesamten ehemals osmanischen Raum, von der Türkei bis zum Nahen Osten, wo „Tarator“ teils auch eine Sauce bezeichnet. In Bulgarien hat sich die flüssige, löffelbare Suppenform durchgesetzt, verfeinert mit Knoblauch, Dill, etwas Öl und gehackten Walnüssen. Sie wird eiskalt serviert und gilt als ideale Erfrischung in der Sommerhitze, oft als Vorspeise oder leichtes Mittagessen. Tarator zeigt die zentrale Rolle des Joghurts in der bulgarischen Esskultur und ist von Natur aus vegetarisch und ohne Schweinefleisch. Eine dickere Variante kann auch als Dip gereicht werden.", "persoenlich": "", "servier": "", "tags": ["Bulgarien", "Balkan", "kalte Suppe", "Joghurt", "Gurke", "Walnuss", "Dill", "vegetarisch", "Sommerküche", "erfrischend", "osmanisch geprägt", "Vorspeise"]}, {"id": "sm-rrebr-d-med-karrysild", "status": "published", "date": "", "cover": "", "name": "Smørrebrød med karrysild", "land": "Dänemark", "kontinent": "Europa", "gang": "Frühstück", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Offenes Butterbrot auf dunklem Roggenbrot, belegt mit Hering in cremiger Currysauce und Ei. Das dänische Smørrebrød in einer seiner klassischen Fassungen.", "zutaten": ["4 Scheiben dänisches Roggenbrot (rugbrød)", "300 g Matjes- oder Salzheringsfilets, gewässert", "4 EL Mayonnaise", "100 ml Schmand oder Crème fraîche", "1 EL mildes Currypulver", "1 TL Apfelessig", "2 hartgekochte Eier", "1 Apfel, fein gewürfelt", "Butter, Schnittlauch, Salz"], "zutatenS": [{"menge": 4.0, "einheit": "Scheiben", "item": "dänisches Roggenbrot (rugbrød)", "roh": "4 Scheiben dänisches Roggenbrot (rugbrød)"}, {"menge": 300.0, "einheit": "g", "item": "Matjes- oder Salzheringsfilets, gewässert", "roh": "300 g Matjes- oder Salzheringsfilets, gewässert"}, {"menge": 4.0, "einheit": "EL", "item": "Mayonnaise", "roh": "4 EL Mayonnaise"}, {"menge": 100.0, "einheit": "ml", "item": "Schmand oder Crème fraîche", "roh": "100 ml Schmand oder Crème fraîche"}, {"menge": 1.0, "einheit": "EL", "item": "mildes Currypulver", "roh": "1 EL mildes Currypulver"}, {"menge": 1.0, "einheit": "TL", "item": "Apfelessig", "roh": "1 TL Apfelessig"}, {"menge": 2.0, "einheit": "", "item": "hartgekochte Eier", "roh": "2 hartgekochte Eier"}, {"menge": 1.0, "einheit": "", "item": "Apfel, fein gewürfelt", "roh": "1 Apfel, fein gewürfelt"}, {"menge": null, "einheit": "", "item": "Butter, Schnittlauch, Salz", "roh": "Butter, Schnittlauch, Salz"}], "zubereitung": ["Heringsfilets gut abtropfen lassen und in mundgerechte Stücke schneiden.", "Mayonnaise, Schmand, Currypulver und Essig zu einer Sauce verrühren, leicht salzen.", "Heringsstücke und Apfelwürfel unterheben und mindestens 1 Stunde durchziehen lassen.", "Roggenbrot dünn mit Butter bestreichen.", "Den Curryhering großzügig auf das Brot setzen.", "Mit Eierscheiben und Schnittlauch garnieren und mit Messer und Gabel servieren."], "hinweise": "Salzhering vor der Verwendung ausreichend wässern, sonst wird es zu salzig.\n\nDie Currysauce schmeckt am nächsten Tag noch runder.\n\nEchtes dunkles Roggenbrot ist für den typischen Geschmack entscheidend.", "alternative": "", "geschichte": "Smørrebrød — wörtlich „Butterbrot“ — ist das Herzstück der dänischen Esskultur und entwickelte sich im 19. Jahrhundert von der einfachen Pausenmahlzeit der Arbeiter zur kunstvoll belegten Spezialität. Grundlage ist stets das dichte, dunkle Roggenbrot (rugbrød), dünn mit Butter bestrichen und sorgfältig garniert. Hering gehört zu den ältesten und wichtigsten Belägen, denn der eingelegte Fisch war über Jahrhunderte ein Grundnahrungsmittel im Ostseeraum und ein zentrales Handelsgut. Die Variante „karrysild“ — Hering in einer mit Curry gewürzten Mayonnaise- oder Remouladensauce — entstand, als Currypulver im 20. Jahrhundert populär wurde, und gehört heute zum festen Repertoire des dänischen Mittagstisches und der Festtafel, etwa beim Julefrokost. Smørrebrød folgt klaren Regeln in Reihenfolge und Garnitur und wird mit Messer und Gabel gegessen. Es steht für die dänische Verbindung von Schlichtheit, Handwerk und Sorgfalt.", "persoenlich": "", "servier": "", "tags": ["Dänemark", "Smørrebrød", "Hering", "Fisch", "Roggenbrot", "Curry", "offenes Sandwich", "Skandinavien", "Mittagstisch", "Julefrokost", "eingelegt", "Vorspeise"]}, {"id": "frikadeller", "status": "published", "date": "", "cover": "", "name": "Frikadeller", "land": "Dänemark", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Flache, in Butter goldbraun gebratene Hackfleischbuletten aus Rind und Kalb. Dänische Alltags- und Familienküche, mit Kartoffeln und Soße.", "zutaten": ["400 g Rinderhackfleisch", "200 g Kalbshackfleisch", "1 Zwiebel, fein gerieben", "1 Ei", "3 EL Mehl", "100 ml Milch", "40 g Butter zum Braten", "Salz, Pfeffer, Muskat"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Rinderhackfleisch", "roh": "400 g Rinderhackfleisch"}, {"menge": 200.0, "einheit": "g", "item": "Kalbshackfleisch", "roh": "200 g Kalbshackfleisch"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel, fein gerieben", "roh": "1 Zwiebel, fein gerieben"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 3.0, "einheit": "EL", "item": "Mehl", "roh": "3 EL Mehl"}, {"menge": 100.0, "einheit": "ml", "item": "Milch", "roh": "100 ml Milch"}, {"menge": 40.0, "einheit": "g", "item": "Butter zum Braten", "roh": "40 g Butter zum Braten"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, Muskat", "roh": "Salz, Pfeffer, Muskat"}], "zubereitung": ["Hackfleischsorten mit Zwiebel, Ei, Mehl und Milch zu einer glatten Masse verrühren.", "Mit Salz, Pfeffer und Muskat würzen und 20 Minuten kühl ruhen lassen.", "Mit einem Esslöffel ovale Portionen abstechen und leicht flach formen.", "Butter in der Pfanne erhitzen, bis sie zu schäumen beginnt.", "Frikadeller bei mittlerer Hitze je Seite 4–5 Minuten goldbraun braten.", "Mit Salzkartoffeln und brauner Soße oder Rotkohl servieren."], "hinweise": "Die Masse vor dem Braten ruhen lassen — so halten die Frikadeller besser zusammen.\n\nIn schäumender Butter braten gibt das typische Aroma.\n\nKalt schmecken sie hervorragend auf Roggenbrot.", "alternative": "", "geschichte": "Frikadeller sind ein fester Bestandteil der dänischen Hausmannskost und gelten als inoffizielles Trostessen des Landes. Die flachen, ovalen Buletten gehen auf eine in ganz Nordeuropa verbreitete Tradition gebratener Hackfleischklöße zurück und etablierten sich in Dänemark spätestens im 19. Jahrhundert als erschwingliches, sättigendes Familienessen. Traditionell mischt man Hackfleisch mit Mehl oder Semmelbröseln, Ei, Zwiebel und Milch zu einer geschmeidigen Masse, die in Butter oder Margarine gebraten wird. Während dänische Frikadeller oft auch mit Schweineanteil zubereitet werden, lassen sie sich ebenso gut und traditionell aus Rind und Kalb herstellen — diese Fassung kommt ganz ohne Schwein aus. Serviert werden sie warm mit Kartoffeln und brauner Soße oder kalt als Smørrebrød-Belag. Frikadeller stehen für die unprätentiöse, herzhafte Seite der dänischen Küche und gehören zum Repertoire fast jedes Haushalts.", "persoenlich": "", "servier": "", "tags": ["Dänemark", "Frikadeller", "Rind", "Kalb", "Hackfleisch", "Hausmannskost", "Skandinavien", "gebraten", "Familienessen", "Trostessen", "Kartoffeln", "Hauptgericht"]}, {"id": "bleskiver", "status": "published", "date": "", "cover": "", "name": "Æbleskiver", "land": "Dänemark", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 20, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kugelrunde, fluffige Pfannküchlein aus einer speziellen Mulden-Pfanne, bestäubt mit Puderzucker und mit Marmelade gereicht. Dänisches Adventsgebäck.", "zutaten": ["250 g Mehl", "300 ml Buttermilch", "3 Eier (getrennt)", "2 EL Zucker", "1 TL Backpulver", "1 Prise Kardamom", "Butter zum Backen", "Puderzucker und Marmelade zum Servieren"], "zutatenS": [{"menge": 250.0, "einheit": "g", "item": "Mehl", "roh": "250 g Mehl"}, {"menge": 300.0, "einheit": "ml", "item": "Buttermilch", "roh": "300 ml Buttermilch"}, {"menge": 3.0, "einheit": "", "item": "Eier (getrennt)", "roh": "3 Eier (getrennt)"}, {"menge": 2.0, "einheit": "EL", "item": "Zucker", "roh": "2 EL Zucker"}, {"menge": 1.0, "einheit": "TL", "item": "Backpulver", "roh": "1 TL Backpulver"}, {"menge": 1.0, "einheit": "Prise", "item": "Kardamom", "roh": "1 Prise Kardamom"}, {"menge": null, "einheit": "", "item": "Butter zum Backen", "roh": "Butter zum Backen"}, {"menge": null, "einheit": "", "item": "Puderzucker und Marmelade zum Servieren", "roh": "Puderzucker und Marmelade zum Servieren"}], "zubereitung": ["Mehl, Zucker, Backpulver und Kardamom mischen.", "Eigelb mit Buttermilch verquirlen und unter die Mehlmischung rühren.", "Eiweiß steif schlagen und vorsichtig unterheben.", "Mulden der Æbleskiver-Pfanne mit Butter ausstreichen und erhitzen.", "Teig einfüllen und die Kugeln mit einem Spieß nach und nach drehen, bis sie ringsum goldbraun sind.", "Mit Puderzucker bestäubt und Marmelade servieren."], "hinweise": "Steif geschlagenes Eiweiß macht die Æbleskiver besonders luftig.\n\nGeduldig drehen — nur so werden sie rundum gleichmäßig gebacken.\n\nOhne Spezialpfanne lässt sich der Teig auch als kleine Pancakes backen.", "alternative": "", "geschichte": "Æbleskiver — wörtlich „Apfelscheiben“ — sind kugelförmige Pfannküchlein, die in einer charakteristischen gusseisernen Pfanne mit halbkugelförmigen Mulden gebacken werden. Der Name verweist darauf, dass die Teigkugeln früher mit einem Stück Apfel gefüllt wurden; heute werden sie meist pur gebacken und mit Marmelade und Puderzucker serviert. Æbleskiver sind eng mit der dänischen Advents- und Weihnachtszeit verbunden und werden traditionell zusammen mit Glögg, dem skandinavischen Glühwein, gereicht. Die spezielle Pfanne und die Technik, die Kugeln während des Backens mit einer Stricknadel oder einem Spieß zu drehen, machen das Gebäck zu einem kleinen Handwerk. Über Jahrhunderte gehörten Æbleskiver zu winterlichen Festen und Zusammenkünften und sind bis heute ein beliebtes gemeinschaftliches Backerlebnis in dänischen Familien. Als süßes Teiggebäck sind sie selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Dänemark", "Æbleskiver", "Advent", "Weihnachten", "Pfannkuchen", "süß", "Gebäck", "Skandinavien", "Kardamom", "vegetarisch", "Glögg", "Dessert"]}, {"id": "sauerbraten", "status": "published", "date": "", "cover": "", "name": "Sauerbraten", "land": "Deutschland", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Rinderbraten, tagelang in einer Essig-Gewürz-Beize mariniert und dann zart geschmort, mit einer dunklen, süßsauren Soße. Ein deutscher Sonntagsklassiker.", "zutaten": ["1.2 kg Rinderschmorbraten (z. B. aus der Schulter)", "375 ml Rotweinessig", "375 ml Wasser", "2 Zwiebeln", "2 Möhren", "5 Wacholderbeeren, 3 Nelken, 2 Lorbeerblätter", "50 g Rosinen", "4 Lebkuchen oder Printen", "Öl, Salz, Pfeffer, Zucker"], "zutatenS": [{"menge": 1.2, "einheit": "kg", "item": "Rinderschmorbraten (z. B. aus der Schulter)", "roh": "1.2 kg Rinderschmorbraten (z. B. aus der Schulter)"}, {"menge": 375.0, "einheit": "ml", "item": "Rotweinessig", "roh": "375 ml Rotweinessig"}, {"menge": 375.0, "einheit": "ml", "item": "Wasser", "roh": "375 ml Wasser"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 2.0, "einheit": "", "item": "Möhren", "roh": "2 Möhren"}, {"menge": 5.0, "einheit": "", "item": "Wacholderbeeren, 3 Nelken, 2 Lorbeerblätter", "roh": "5 Wacholderbeeren, 3 Nelken, 2 Lorbeerblätter"}, {"menge": 50.0, "einheit": "g", "item": "Rosinen", "roh": "50 g Rosinen"}, {"menge": 4.0, "einheit": "", "item": "Lebkuchen oder Printen", "roh": "4 Lebkuchen oder Printen"}, {"menge": null, "einheit": "", "item": "Öl, Salz, Pfeffer, Zucker", "roh": "Öl, Salz, Pfeffer, Zucker"}], "zubereitung": ["Essig, Wasser, in Scheiben geschnittene Zwiebeln, Möhren und Gewürze aufkochen und abkühlen lassen.", "Das Fleisch in die Beize legen und zugedeckt 3–4 Tage im Kühlschrank marinieren, täglich wenden.", "Fleisch abtupfen, die Beize aufbewahren; Braten in Öl rundum kräftig anbraten.", "Mit der durchgesiebten Beize ablöschen und zugedeckt 2,5–3 Stunden sanft schmoren.", "Braten herausnehmen; Soße mit Rosinen und zerbröselten Lebkuchen binden und einkochen.", "Mit Zucker, Salz und Pfeffer abschmecken; Braten in Scheiben mit Klößen und Rotkohl servieren."], "hinweise": "Je länger die Beizzeit, desto intensiver Geschmack und Zartheit.\n\nDie Lebkuchen geben Bindung und die typische süßsaure Tiefe.\n\nDazu passen Kartoffel- oder Semmelknödel und Apfelrotkohl.", "alternative": "", "geschichte": "Der Sauerbraten gehört zu den bekanntesten deutschen Schmorgerichten und ist vor allem im Rheinland, in Franken, Schwaben und Westfalen verwurzelt, jeweils mit regionalen Eigenheiten. Sein Prinzip — Fleisch vor dem Garen mehrere Tage in einer sauren Beize aus Essig, Wein, Wasser und Gewürzen einzulegen — diente ursprünglich der Haltbarmachung und dazu, zähere Fleischstücke mürbe zu machen. Die lange Marinade verleiht dem Braten seinen charakteristisch säuerlichen Geschmack, der durch eine süßliche Soße ausbalanciert wird. Im Rheinland wird diese traditionell mit Rosinen und zerstoßenen Lebkuchen oder dem dortigen Aachener Printen gebunden, was die typische süßsaure Note ergibt. Während Sauerbraten historisch teils auch aus Pferdefleisch zubereitet wurde, ist heute Rind die übliche und klassische Wahl. Das Gericht ist von Natur aus ohne Schweinefleisch und gilt als festliches Sonntagsessen, das Geduld und Vorausplanung verlangt.", "persoenlich": "", "servier": "", "tags": ["Deutschland", "Rheinland", "Sauerbraten", "Rind", "Schmorbraten", "süßsauer", "Marinade", "Sonntagsessen", "Lebkuchen", "Rosinen", "Festtag", "Hauptgericht"]}, {"id": "kaesespaetzle", "status": "published", "date": "", "cover": "", "name": "Käsespätzle", "land": "Deutschland", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Frische Eierspätzle, geschichtet mit kräftigem Bergkäse und gekrönt von goldbraunen Röstzwiebeln. Herzhafter Klassiker aus dem Süden Deutschlands.", "zutaten": ["400 g Mehl", "4 Eier", "150 ml Wasser", "250 g würziger Bergkäse, gerieben", "100 g Emmentaler, gerieben", "3 Zwiebeln, in Ringen", "40 g Butter", "Salz, Muskat"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Mehl", "roh": "400 g Mehl"}, {"menge": 4.0, "einheit": "", "item": "Eier", "roh": "4 Eier"}, {"menge": 150.0, "einheit": "ml", "item": "Wasser", "roh": "150 ml Wasser"}, {"menge": 250.0, "einheit": "g", "item": "würziger Bergkäse, gerieben", "roh": "250 g würziger Bergkäse, gerieben"}, {"menge": 100.0, "einheit": "g", "item": "Emmentaler, gerieben", "roh": "100 g Emmentaler, gerieben"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln, in Ringen", "roh": "3 Zwiebeln, in Ringen"}, {"menge": 40.0, "einheit": "g", "item": "Butter", "roh": "40 g Butter"}, {"menge": null, "einheit": "", "item": "Salz, Muskat", "roh": "Salz, Muskat"}], "zubereitung": ["Mehl, Eier, Wasser, Salz und Muskat zu einem zähen, glatten Teig schlagen, bis er Blasen wirft.", "Teig portionsweise durch eine Spätzlepresse oder vom Brett in siedendes Salzwasser schaben.", "Wenn die Spätzle aufschwimmen, mit dem Schaumlöffel herausheben und abtropfen.", "Zwiebelringe in Butter langsam goldbraun rösten.", "Spätzle und geriebenen Käse abwechselnd in eine Form schichten und kurz im Ofen ziehen lassen, bis der Käse schmilzt.", "Mit den Röstzwiebeln bestreut servieren, dazu ein grüner Salat."], "hinweise": "Der Teig muss zäh sein und Blasen werfen — dann werden die Spätzle locker.\n\nEine Mischung kräftiger Käsesorten gibt mehr Tiefe als nur ein Käse.\n\nDie Röstzwiebeln geduldig und langsam bräunen, damit sie nicht bitter werden.", "alternative": "", "geschichte": "Käsespätzle (im Allgäu „Kässpatzen“, in Schwaben „Kässpätzle“) sind ein traditionelles Gericht des süddeutschen und alpenländischen Raums und teilen ihre Wurzeln mit der österreichischen und Schweizer Küche. Spätzle, die handgeschabten Eierteignudeln, gelten als schwäbisches Grundnahrungsmittel und sind dort seit Jahrhunderten dokumentiert; das Wort verweist vermutlich auf die kleine, sperlingsartige Form. In Kombination mit reichlich geriebenem Käse — meist einem würzigen Berg- oder Emmentaler — und Röstzwiebeln entsteht ein sättigendes, vegetarisches Hauptgericht, das die deftige Bauern- und Almküche der Region widerspiegelt. Es war ein Essen, das aus einfachen, haltbaren Vorräten wie Mehl, Eiern und Käse zubereitet werden konnte und besonders in den Bergregionen verbreitet war. Heute sind Käsespätzle ein Aushängeschild der Allgäuer und schwäbischen Küche und stehen in Gasthäusern wie Privathaushalten. Sie kommen von Natur aus ohne Schweinefleisch aus.", "persoenlich": "", "servier": "", "tags": ["Deutschland", "Allgäu", "Schwaben", "Spätzle", "Käse", "vegetarisch", "Alpenküche", "Bergkäse", "Röstzwiebeln", "deftig", "Hausmannskost", "Hauptgericht"]}, {"id": "schwarzwaelder-kirschtorte", "status": "published", "date": "", "cover": "", "name": "Schwarzwälder Kirschtorte", "land": "Deutschland", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Schokoladenbiskuit mit Kirschen, Sahne und Kirschwasser, geschichtet und mit Schokoraspeln verziert. Deutschlands berühmteste Torte.", "zutaten": ["6 Eier", "150 g Zucker", "100 g Mehl", "50 g Kakaopulver", "1 Glas Sauerkirschen (Schattenmorellen)", "600 ml Schlagsahne", "4 EL Kirschwasser", "100 g Zartbitterschokolade (Raspel)", "Sahnesteif, Puderzucker"], "zutatenS": [{"menge": 6.0, "einheit": "", "item": "Eier", "roh": "6 Eier"}, {"menge": 150.0, "einheit": "g", "item": "Zucker", "roh": "150 g Zucker"}, {"menge": 100.0, "einheit": "g", "item": "Mehl", "roh": "100 g Mehl"}, {"menge": 50.0, "einheit": "g", "item": "Kakaopulver", "roh": "50 g Kakaopulver"}, {"menge": 1.0, "einheit": "Glas", "item": "Sauerkirschen (Schattenmorellen)", "roh": "1 Glas Sauerkirschen (Schattenmorellen)"}, {"menge": 600.0, "einheit": "ml", "item": "Schlagsahne", "roh": "600 ml Schlagsahne"}, {"menge": 4.0, "einheit": "EL", "item": "Kirschwasser", "roh": "4 EL Kirschwasser"}, {"menge": 100.0, "einheit": "g", "item": "Zartbitterschokolade (Raspel)", "roh": "100 g Zartbitterschokolade (Raspel)"}, {"menge": null, "einheit": "", "item": "Sahnesteif, Puderzucker", "roh": "Sahnesteif, Puderzucker"}], "zubereitung": ["Eier mit Zucker schaumig schlagen, Mehl und Kakao unterheben und einen Biskuit backen; auskühlen lassen.", "Biskuit zweimal waagerecht durchschneiden und die Böden mit Kirschwasser tränken.", "Kirschen abtropfen lassen, den Saft etwas einkochen oder andicken.", "Sahne mit Sahnesteif steif schlagen.", "Böden abwechselnd mit Sahne und Kirschen füllen, die Torte rundum mit Sahne einstreichen.", "Mit Schokoraspeln, Sahnetupfen und einigen Kirschen verzieren; gut durchkühlen lassen."], "hinweise": "Den Biskuit am Vortag backen — er lässt sich dann besser schneiden.\n\nEchtes Kirschwasser ist für den typischen Geschmack entscheidend.\n\nDie Torte vor dem Servieren mehrere Stunden durchziehen lassen.", "alternative": "", "geschichte": "Die Schwarzwälder Kirschtorte ist die wohl bekannteste deutsche Torte und international ein Sinnbild deutscher Backkunst. Ihre charakteristische Kombination aus Schokoladenbiskuit, Sauerkirschen, Schlagsahne und vor allem dem Kirschwasser (einem Obstbrand aus dem Schwarzwald) gab ihr den Namen. Die genaue Entstehung ist nicht eindeutig belegt; verbreitet ist die Zuschreibung an Konditoren des frühen 20. Jahrhunderts, und ihre große Popularität entfaltete sie ab den 1930er- und besonders den Nachkriegsjahren. Manche Deutungen sehen in der Optik — dunkler Teig, weiße Sahne, rote Kirschen — eine Anspielung auf die Tracht der Schwarzwälder Region. Das Kirschwasser ist für den authentischen Geschmack zentral und unterscheidet die Torte von einfachen Sahnetorten. Heute ist sie ein Klassiker der Kaffeetafel und auf der ganzen Welt als „Black Forest Cake“ bekannt. Als Süßgebäck ist sie selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Deutschland", "Schwarzwald", "Torte", "Kirschen", "Sahne", "Schokolade", "Kirschwasser", "Kaffeetafel", "süß", "vegetarisch", "Backkunst", "Dessert"]}, {"id": "mulgipuder", "status": "published", "date": "", "cover": "", "name": "Mulgipuder", "land": "Estland", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein herzhafter Stampf aus Kartoffeln und Graupen, traditionell mit Röstzwiebeln. Bauernküche aus der südestnischen Region Mulgimaa.", "zutaten": ["600 g mehligkochende Kartoffeln", "150 g Gerstengraupen", "3 Zwiebeln, in Ringen", "50 g Butter", "100 ml Milch", "Salz und Pfeffer"], "zutatenS": [{"menge": 600.0, "einheit": "g", "item": "mehligkochende Kartoffeln", "roh": "600 g mehligkochende Kartoffeln"}, {"menge": 150.0, "einheit": "g", "item": "Gerstengraupen", "roh": "150 g Gerstengraupen"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln, in Ringen", "roh": "3 Zwiebeln, in Ringen"}, {"menge": 50.0, "einheit": "g", "item": "Butter", "roh": "50 g Butter"}, {"menge": 100.0, "einheit": "ml", "item": "Milch", "roh": "100 ml Milch"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Graupen in reichlich Salzwasser etwa 40 Minuten weich kochen.", "Kartoffeln schälen, würfeln und in den letzten 20 Minuten zu den Graupen geben.", "Abgießen, mit etwas Milch und einem Stück Butter zu einem dichten Stampf zerdrücken.", "Mit Salz und Pfeffer kräftig abschmecken.", "Zwiebelringe in reichlich Butter langsam goldbraun rösten.", "Den Stampf mit den Röstzwiebeln und der Bratbutter beträufelt servieren."], "hinweise": "Die Graupen rechtzeitig ansetzen — sie brauchen länger als die Kartoffeln.\n\nReichlich Röstzwiebeln und Butter sind hier der ganze Geschmack.\n\nDazu passt eingelegtes Gemüse oder ein klarer Salat.", "alternative": "Mulgipuder wird klassisch mit ausgelassenem Schweinespeck und dessen Grieben zubereitet. Wir ersetzen das durch reichlich in Butter langsam geröstete Zwiebeln und die nussige Bratbutter — das gibt die nötige herzhafte Tiefe, ganz ohne Schwein. Wer mag, ergänzt knusprig geröstete Buchweizen- oder Brotkrümel.", "geschichte": "Mulgipuder ist eines der bekanntesten traditionellen Gerichte Estlands und stammt aus der südlichen Region Mulgimaa, nach der es benannt ist. Es verbindet zwei Grundpfeiler der estnischen Bauernküche: die Kartoffel und die Gerstengraupe. Beide wurden zusammen gekocht und zu einem dichten Stampf zerdrückt — ein nahrhaftes, günstiges Essen, das die ländliche Bevölkerung über lange Winter trug. Graupen und Gerste haben in der estnischen Esskultur eine besonders lange Geschichte und galten als Grundnahrungsmittel, lange bevor die Kartoffel im 18. und 19. Jahrhundert verbreitet wurde. Traditionell wird Mulgipuder mit ausgelassenem Speck und Röstzwiebeln serviert; in dieser Fassung treten reichlich in Butter geröstete Zwiebeln an die Stelle des Schweinefleischs. Das Gericht wurde 2021 sogar als Teil des nationalen kulinarischen Erbes Estlands hervorgehoben und steht für die bodenständige, getreidegeprägte Küche des Landes.", "persoenlich": "", "servier": "", "tags": ["Estland", "Mulgimaa", "Kartoffeln", "Graupen", "Gerste", "vegetarisch", "Bauernküche", "Stampf", "Röstzwiebeln", "Winterküche", "kulinarisches Erbe", "Hauptgericht"]}, {"id": "rosolje", "status": "published", "date": "", "cover": "", "name": "Rosolje", "land": "Estland", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Estnischer Rote-Bete-Kartoffelsalat mit Apfel, Ei und eingelegter Gurke in einer cremigen Dressing. Leuchtend rosa, süßsäuerlich, ein Festtagssalat.", "zutaten": ["3 Rote Bete, gekocht", "4 festkochende Kartoffeln, gekocht", "1 Apfel", "2 eingelegte Gurken", "3 hartgekochte Eier", "200 g saure Sahne", "1 TL Senf", "Salz, Pfeffer, etwas Essig"], "zutatenS": [{"menge": 3.0, "einheit": "", "item": "Rote Bete, gekocht", "roh": "3 Rote Bete, gekocht"}, {"menge": 4.0, "einheit": "", "item": "festkochende Kartoffeln, gekocht", "roh": "4 festkochende Kartoffeln, gekocht"}, {"menge": 1.0, "einheit": "", "item": "Apfel", "roh": "1 Apfel"}, {"menge": 2.0, "einheit": "", "item": "eingelegte Gurken", "roh": "2 eingelegte Gurken"}, {"menge": 3.0, "einheit": "", "item": "hartgekochte Eier", "roh": "3 hartgekochte Eier"}, {"menge": 200.0, "einheit": "g", "item": "saure Sahne", "roh": "200 g saure Sahne"}, {"menge": 1.0, "einheit": "TL", "item": "Senf", "roh": "1 TL Senf"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, etwas Essig", "roh": "Salz, Pfeffer, etwas Essig"}], "zubereitung": ["Rote Bete, Kartoffeln, Apfel und Gurken in gleichmäßig kleine Würfel schneiden.", "Zwei Eier ebenfalls würfeln, eines für die Garnitur zurückbehalten.", "Saure Sahne mit Senf, Salz, Pfeffer und einem Spritzer Essig zu einem Dressing verrühren.", "Alle Zutaten vorsichtig mit dem Dressing vermengen.", "Mindestens 2 Stunden kühl durchziehen lassen, damit sich die Farbe und Aromen verbinden.", "Mit dem restlichen Ei garniert servieren."], "hinweise": "Die Rote Bete färbt alles rosa — das ist gewollt und typisch.\n\nEtwas Ruhezeit im Kühlschrank verbessert den Geschmack deutlich.\n\nWer es kräftiger mag, gibt mehr eingelegte Gurke und Senf dazu.", "alternative": "", "geschichte": "Rosolje ist ein traditioneller estnischer Salat, der eng mit der Familie der osteuropäischen Rote-Bete-Salate (russisch „vinegret“) verwandt ist und über die historischen Verflechtungen des Baltikums mit dem russischen und deutschbaltischen Raum nach Estland kam. Charakteristisch ist die Kombination aus gekochter Roter Bete, Kartoffeln, Apfel, eingelegter Gurke und Ei, die durch die Bete ihre kräftig rosa Farbe erhält. Während viele Versionen auch gepökeltes Rindfleisch oder Hering enthalten, ist eine vegetarische Variante ebenso üblich und traditionell. Das süßsäuerliche Geschmacksprofil entsteht durch das Zusammenspiel von Apfel, eingelegter Gurke und einem Dressing aus saurer Sahne, oft mit etwas Senf. Rosolje gehört in Estland zu festlichen Anlässen, Feiertagen und der kalten Tafel und ist besonders rund um Weihnachten und Mittsommer beliebt. Es spiegelt die baltische Vorliebe für eingelegte und säuerliche Aromen und kommt in dieser Fassung ohne Schweinefleisch aus.", "persoenlich": "", "servier": "", "tags": ["Estland", "Baltikum", "Rote Bete", "Kartoffelsalat", "Apfel", "Ei", "vegetarisch", "süßsäuerlich", "Festtag", "kalte Küche", "eingelegt", "Vorspeise"]}, {"id": "kama", "status": "published", "date": "", "cover": "", "name": "Kama", "land": "Estland", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 10, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein traditionelles Mehl aus geröstetem Getreide und Erbsen, mit Buttermilch oder Kefir zu einer süßen, sämigen Speise verrührt. Estnisches Urgetreidegericht.", "zutaten": ["100 g Kama-Mehl (geröstete Getreidemischung)", "300 ml Buttermilch oder Kefir", "2 EL Honig oder Zucker", "150 g frische Beeren", "1 Prise Salz"], "zutatenS": [{"menge": 100.0, "einheit": "g", "item": "Kama-Mehl (geröstete Getreidemischung)", "roh": "100 g Kama-Mehl (geröstete Getreidemischung)"}, {"menge": 300.0, "einheit": "ml", "item": "Buttermilch oder Kefir", "roh": "300 ml Buttermilch oder Kefir"}, {"menge": 2.0, "einheit": "EL", "item": "Honig oder Zucker", "roh": "2 EL Honig oder Zucker"}, {"menge": 150.0, "einheit": "g", "item": "frische Beeren", "roh": "150 g frische Beeren"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}], "zubereitung": ["Kama-Mehl mit einer Prise Salz in eine Schüssel geben.", "Buttermilch oder Kefir nach und nach einrühren, bis eine sämige, klumpenfreie Masse entsteht.", "Mit Honig oder Zucker süßen und abschmecken.", "Kurz quellen lassen, damit das Mehl die Flüssigkeit aufnimmt.", "In Schalen anrichten und mit frischen Beeren servieren."], "hinweise": "Die Konsistenz nach Geschmack regeln — von trinkbar bis löffelfest.\n\nSaisonale Beeren wie Walderdbeeren oder Heidelbeeren passen besonders gut.\n\nKama-Mehl gibt es fertig; selbst rösten und mahlen ist aufwendig.", "alternative": "", "geschichte": "Kama ist eine der ältesten und eigenständigsten Spezialitäten der estnischen Küche und gilt als Nationalspeise. Es handelt sich um ein feines Mehl aus einer Mischung gerösteter Getreide — meist Gerste, Roggen, Hafer — und gerösteter Erbsen oder Bohnen, das traditionell als haltbarer Vorrat hergestellt wurde. Geröstetes Getreidemehl dieser Art ist uralt und war praktisch, weil es ohne weiteres Kochen verzehrfähig war: Man musste es nur mit einer Flüssigkeit anrühren. Bauern und Reisende konnten so mit wenig Aufwand eine nahrhafte Mahlzeit zubereiten. Heute wird Kama meist mit Buttermilch, Kefir oder Joghurt und etwas Zucker oder Honig zu einem dickflüssigen, leicht süßen Gericht verrührt und als Frühstück oder Dessert gegessen, oft mit frischen Beeren. Das fertige Kama-Mehl ist in estnischen Geschäften ein Standardprodukt. Es ist rein pflanzlich-getreidebasiert und damit selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Estland", "Kama", "Urgetreide", "geröstet", "Buttermilch", "Kefir", "vegetarisch", "Frühstück", "Beeren", "Nationalspeise", "traditionell", "Dessert"]}, {"id": "karjalanpiirakka", "status": "published", "date": "", "cover": "", "name": "Karjalanpiirakka", "land": "Finnland", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Karelische Piroggen: ein dünner Roggenrand umschließt eine Füllung aus Milchreis, serviert mit Eierbutter. Finnisches Gebäck mit geschützter Herkunft.", "zutaten": ["150 g Roggenmehl", "50 g Weizenmehl", "150 ml Wasser", "150 g Rundkornreis", "700 ml Milch", "3 hartgekochte Eier", "80 g Butter", "Salz"], "zutatenS": [{"menge": 150.0, "einheit": "g", "item": "Roggenmehl", "roh": "150 g Roggenmehl"}, {"menge": 50.0, "einheit": "g", "item": "Weizenmehl", "roh": "50 g Weizenmehl"}, {"menge": 150.0, "einheit": "ml", "item": "Wasser", "roh": "150 ml Wasser"}, {"menge": 150.0, "einheit": "g", "item": "Rundkornreis", "roh": "150 g Rundkornreis"}, {"menge": 700.0, "einheit": "ml", "item": "Milch", "roh": "700 ml Milch"}, {"menge": 3.0, "einheit": "", "item": "hartgekochte Eier", "roh": "3 hartgekochte Eier"}, {"menge": 80.0, "einheit": "g", "item": "Butter", "roh": "80 g Butter"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Reis kurz in Wasser ankochen, dann in der Milch zu einem weichen, salzigen Brei garen; auskühlen lassen.", "Roggen- und Weizenmehl mit Wasser und Salz zu einem festen Teig kneten.", "Teig zu einer Rolle formen, in Stücke teilen und sehr dünn oval ausrollen.", "Milchreis mittig auf die Ovale geben, die Ränder hochklappen und kräuseln.", "Bei 250 °C etwa 15 Minuten backen, danach mit zerlassener Butter bestreichen.", "Hartgekochte Eier mit weicher Butter zerdrücken (munavoi) und auf die warmen Piroggen geben."], "hinweise": "Den Teigrand möglichst dünn ausrollen — das ist typisch.\n\nNach dem Backen sofort mit Butter bestreichen, damit die Piroggen weich werden.\n\nMunavoi nicht vergessen — es gehört untrennbar dazu.", "alternative": "", "geschichte": "Karjalanpiirakka, die karelische Pirogge, stammt aus der Region Karelien und ist heute in ganz Finnland verbreitet und beliebt. Sie besteht aus einem dünn ausgerollten Rand aus Roggenteig, der eine Füllung umschließt — traditionell Milchreisbrei, früher auch Kartoffelpüree oder Gerstenbrei. Die offenen, schiffchenförmigen Piroggen spiegeln die Bedeutung des Roggens in der ostfinnischen Ernährung wider. Serviert werden sie klassisch mit „munavoi“, einer Mischung aus zerdrücktem hartgekochtem Ei und Butter. Die karelische Pirogge ist so eng mit der finnischen Identität verbunden, dass sie als „Karjalanpiirakka“ einen geschützten Status als traditionelle Spezialität in der EU genießt. Sie wird zum Frühstück, als Snack und zu festlichen Anlässen gegessen und ist in finnischen Bäckereien und Supermärkten allgegenwärtig. Als reines Teig-Getreide-Gebäck mit Milchreisfüllung ist sie von Natur aus ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Finnland", "Karelien", "Roggen", "Pirogge", "Milchreis", "Eierbutter", "vegetarisch", "Frühstück", "geschützte Spezialität", "Skandinavien", "Gebäck", "Snack"]}, {"id": "lohikeitto", "status": "published", "date": "", "cover": "", "name": "Lohikeitto", "land": "Finnland", "kontinent": "Europa", "gang": "Suppe", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine cremige Lachssuppe mit Kartoffeln, Lauch und reichlich Dill. Wärmendes Wohlfühlessen des finnischen und nordischen Raums.", "zutaten": ["500 g Lachsfilet, gewürfelt", "5 festkochende Kartoffeln, gewürfelt", "1 Lauchstange, in Ringen", "1 Zwiebel", "1 l Fisch- oder Gemüsebrühe", "200 ml Sahne", "1 Bund Dill", "30 g Butter", "Salz, Pfeffer, Pimentkörner"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Lachsfilet, gewürfelt", "roh": "500 g Lachsfilet, gewürfelt"}, {"menge": 5.0, "einheit": "", "item": "festkochende Kartoffeln, gewürfelt", "roh": "5 festkochende Kartoffeln, gewürfelt"}, {"menge": 1.0, "einheit": "", "item": "Lauchstange, in Ringen", "roh": "1 Lauchstange, in Ringen"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 1.0, "einheit": "l", "item": "Fisch- oder Gemüsebrühe", "roh": "1 l Fisch- oder Gemüsebrühe"}, {"menge": 200.0, "einheit": "ml", "item": "Sahne", "roh": "200 ml Sahne"}, {"menge": 1.0, "einheit": "Bund", "item": "Dill", "roh": "1 Bund Dill"}, {"menge": 30.0, "einheit": "g", "item": "Butter", "roh": "30 g Butter"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, Pimentkörner", "roh": "Salz, Pfeffer, Pimentkörner"}], "zubereitung": ["Zwiebel und Lauch in Butter andünsten.", "Kartoffelwürfel zugeben, mit Brühe auffüllen und etwa 15 Minuten köcheln, bis sie weich sind.", "Sahne angießen und erwärmen, nicht mehr stark kochen.", "Lachswürfel einlegen und bei kleiner Hitze 4–5 Minuten gar ziehen lassen.", "Mit Salz, Pfeffer und Piment abschmecken.", "Reichlich frischen Dill unterrühren und mit dunklem Brot servieren."], "hinweise": "Den Lachs nur ziehen lassen, nicht kochen — sonst wird er trocken.\n\nFrischer Dill ist unverzichtbar und kommt erst zum Schluss dazu.\n\nEtwas vom Fischfond intensiviert den Geschmack der Brühe.", "alternative": "", "geschichte": "Lohikeitto, die finnische Lachssuppe, ist ein Klassiker der nordischen Küche und in Finnland ein verbreitetes, wärmendes Alltagsgericht. Lachs hat in den fisch- und seenreichen Ländern Skandinaviens und im Ostseeraum seit jeher eine zentrale Bedeutung, sowohl als Frischfisch als auch geräuchert oder gebeizt. Die Suppe verbindet ihn mit Grundzutaten der nordischen Ernährung — Kartoffeln, Lauch oder Zwiebeln — in einer durch Sahne gebundenen Brühe, abgeschmeckt mit großzügig frischem Dill, dem Leitkraut der skandinavischen Küche. Solche sämigen Fischsuppen waren eine praktische Art, Fisch sättigend und nahrhaft zu verwerten, und gehören in ähnlichen Formen auch zur schwedischen und norwegischen Tradition. Lohikeitto wird gern an kalten Tagen und zu geselligen Anlässen gegessen und gilt als unkompliziertes, nahrhaftes Wohlfühlessen. Als Fischgericht ist es selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Finnland", "Lachs", "Fischsuppe", "Sahne", "Dill", "Kartoffeln", "Lauch", "Skandinavien", "Wohlfühlessen", "Winterküche", "nordisch", "Suppe"]}, {"id": "korvapuusti", "status": "published", "date": "", "cover": "", "name": "Korvapuusti", "land": "Finnland", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Finnische Zimtschnecken mit Kardamomteig, charakteristisch flach gedrückt und mit Hagelzucker bestreut. Gehören zur finnischen Kaffeepause „kahvitauko“.", "zutaten": ["500 g Mehl", "250 ml lauwarme Milch", "25 g frische Hefe", "80 g Zucker", "1 Ei", "1 TL gemahlener Kardamom", "100 g weiche Butter (Teig)", "Butter, Zucker und Zimt für die Füllung; Hagelzucker"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Mehl", "roh": "500 g Mehl"}, {"menge": 250.0, "einheit": "ml", "item": "lauwarme Milch", "roh": "250 ml lauwarme Milch"}, {"menge": 25.0, "einheit": "g", "item": "frische Hefe", "roh": "25 g frische Hefe"}, {"menge": 80.0, "einheit": "g", "item": "Zucker", "roh": "80 g Zucker"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 1.0, "einheit": "TL", "item": "gemahlener Kardamom", "roh": "1 TL gemahlener Kardamom"}, {"menge": 100.0, "einheit": "g", "item": "weiche Butter (Teig)", "roh": "100 g weiche Butter (Teig)"}, {"menge": null, "einheit": "", "item": "Butter, Zucker und Zimt für die Füllung; Hagelzucker", "roh": "Butter, Zucker und Zimt für die Füllung; Hagelzucker"}], "zubereitung": ["Hefe in lauwarmer Milch auflösen; mit Mehl, Zucker, Ei und Kardamom zu einem Teig kneten.", "Die weiche Butter einarbeiten und den Teig 1 Stunde gehen lassen.", "Teig rechteckig ausrollen, mit weicher Butter bestreichen, mit Zimt und Zucker bestreuen.", "Aufrollen und schräg in keilförmige Stücke schneiden; jedes Stück mittig flach drücken.", "Stücke auf ein Blech setzen, nochmals gehen lassen, mit Ei bestreichen und mit Hagelzucker bestreuen.", "Bei 220 °C 10–12 Minuten goldbraun backen; zur Kaffeepause servieren."], "hinweise": "Kardamom frisch mahlen für das beste Aroma.\n\nDas mittige Flachdrücken gibt die typische Korvapuusti-Form.\n\nNicht zu lange backen, damit sie saftig bleiben.", "alternative": "", "geschichte": "Korvapuusti sind die finnische Variante der nordischen Zimtschnecke und ein fester Bestandteil der finnischen Kaffeekultur. Ihr Name bedeutet wörtlich „geohrfeigt“ und spielt auf die typische Form an: Die gerollten und schräg geschnittenen Teigstücke werden an den Enden flach gedrückt, sodass sie wie ein Ohr aussehen. Charakteristisch für den nordischen Hefeteig ist die kräftige Würzung mit Kardamom, einem Gewürz, das über den Handel früh in die skandinavische Backtradition gelangte. Süße Hefegebäcke wie diese sind in Finnland untrennbar mit dem „pulla“-Backwerk und der geselligen Kaffeepause verbunden, die einen hohen Stellenwert im Alltag hat. Bestreut werden Korvapuusti mit grobem Hagelzucker, der beim Backen knusprige Akzente setzt. Sie werden zu Hause gebacken und in Cafés angeboten und gelten als eines der beliebtesten Gebäcke des Landes. Als süßes Hefegebäck sind sie selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Finnland", "Korvapuusti", "Zimtschnecke", "Kardamom", "Hefegebäck", "Hagelzucker", "Kaffeepause", "süß", "vegetarisch", "Skandinavien", "pulla", "Dessert"]}, {"id": "b-uf-bourguignon", "status": "published", "date": "", "cover": "", "name": "Bœuf bourguignon", "land": "Frankreich", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Rindfleisch, langsam in Rotwein mit Möhren, Zwiebeln und Champignons geschmort. Der burgundische Schmorklassiker der französischen Landküche.", "zutaten": ["1.2 kg Rindfleisch zum Schmoren, in Würfeln", "750 ml kräftiger Rotwein (Burgunder)", "300 g braune Champignons", "12 kleine Schalotten oder Perlzwiebeln", "3 Möhren, in Stücken", "2 EL Tomatenmark", "2 EL Mehl", "1 Bouquet garni (Thymian, Lorbeer, Petersilie)", "Butter, Öl, Salz, Pfeffer"], "zutatenS": [{"menge": 1.2, "einheit": "kg", "item": "Rindfleisch zum Schmoren, in Würfeln", "roh": "1.2 kg Rindfleisch zum Schmoren, in Würfeln"}, {"menge": 750.0, "einheit": "ml", "item": "kräftiger Rotwein (Burgunder)", "roh": "750 ml kräftiger Rotwein (Burgunder)"}, {"menge": 300.0, "einheit": "g", "item": "braune Champignons", "roh": "300 g braune Champignons"}, {"menge": 12.0, "einheit": "", "item": "kleine Schalotten oder Perlzwiebeln", "roh": "12 kleine Schalotten oder Perlzwiebeln"}, {"menge": 3.0, "einheit": "", "item": "Möhren, in Stücken", "roh": "3 Möhren, in Stücken"}, {"menge": 2.0, "einheit": "EL", "item": "Tomatenmark", "roh": "2 EL Tomatenmark"}, {"menge": 2.0, "einheit": "EL", "item": "Mehl", "roh": "2 EL Mehl"}, {"menge": 1.0, "einheit": "", "item": "Bouquet garni (Thymian, Lorbeer, Petersilie)", "roh": "1 Bouquet garni (Thymian, Lorbeer, Petersilie)"}, {"menge": null, "einheit": "", "item": "Butter, Öl, Salz, Pfeffer", "roh": "Butter, Öl, Salz, Pfeffer"}], "zubereitung": ["Rindfleischwürfel trocken tupfen, salzen und in Öl portionsweise sehr kräftig anbraten; herausnehmen.", "Möhren und Schalotten im Bratfett anrösten, Tomatenmark und Mehl zugeben und kurz mitrösten.", "Mit Rotwein ablöschen, das Fleisch zurückgeben und das Bouquet garni einlegen.", "Zugedeckt bei kleiner Hitze 2,5–3 Stunden schmoren, bis das Fleisch zerfällt.", "Champignons in Butter separat anbraten und im letzten Drittel zugeben.", "Bouquet garni entfernen, abschmecken und mit Kartoffeln oder Brot servieren."], "hinweise": "Das kräftige Anbraten ist die Basis für Farbe und Tiefe der Sauce.\n\nEinen Wein verwenden, den man auch trinken würde.\n\nAm zweiten Tag schmeckt das Gericht noch besser.", "alternative": "Klassisch werden in den Bœuf bourguignon Speckwürfel (lardons) vom Schwein gegeben. Wir lassen sie weg und holen die herzhafte Tiefe stattdessen aus sehr kräftigem Anbraten des Rinds, Tomatenmark und reichlich Aromaten. Wer eine rauchige Note möchte, brät einige Würfel geräuchertes Rind separat an und gibt sie zum Schluss dazu.", "geschichte": "Bœuf bourguignon stammt aus dem Burgund, einer für ihre Rotweine und ihr Charolais-Rind berühmten Region Frankreichs. Das Gericht ist ein Paradebeispiel der bäuerlichen „cuisine de terroir“, die regionale Erzeugnisse — hier Rindfleisch und Rotwein — zu einem reichhaltigen Schmorgericht vereint. Ursprünglich war es eine Methode, zähere Fleischstücke durch langes Garen in Wein mürbe und schmackhaft zu machen. Im Lauf des 19. und 20. Jahrhunderts wurde das einst rustikale Gericht durch die klassische französische Küche verfeinert und kodifiziert, unter anderem von Auguste Escoffier, und gilt seither als eines der Aushängeschilder der französischen Küche. Klassisch enthält es einen Speckanteil; in dieser Fassung verzichten wir darauf und setzen auf kräftiges Anbraten und reichlich Aromaten, um die Tiefe zu erreichen. Serviert wird es traditionell mit Kartoffeln, Nudeln oder einfach mit Brot, das die Sauce aufnimmt.", "persoenlich": "", "servier": "", "tags": ["Frankreich", "Burgund", "Rind", "Schmorgericht", "Rotwein", "Champignons", "Landküche", "terroir", "Winterküche", "Klassiker", "Escoffier", "Hauptgericht"]}, {"id": "ratatouille", "status": "published", "date": "", "cover": "", "name": "Ratatouille", "land": "Frankreich", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Geschmortes Sommergemüse aus Aubergine, Zucchini, Paprika und Tomaten mit Kräutern der Provence. Das provenzalische Gemüsegericht schlechthin.", "zutaten": ["1 Aubergine", "2 Zucchini", "2 Paprika (rot und gelb)", "4 reife Tomaten", "2 Zwiebeln", "3 Zehen Knoblauch", "5 EL Olivenöl", "1 EL Kräuter der Provence", "Salz, Pfeffer, frisches Basilikum"], "zutatenS": [{"menge": 1.0, "einheit": "", "item": "Aubergine", "roh": "1 Aubergine"}, {"menge": 2.0, "einheit": "", "item": "Zucchini", "roh": "2 Zucchini"}, {"menge": 2.0, "einheit": "", "item": "Paprika (rot und gelb)", "roh": "2 Paprika (rot und gelb)"}, {"menge": 4.0, "einheit": "", "item": "reife Tomaten", "roh": "4 reife Tomaten"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "3 Zehen Knoblauch"}, {"menge": 5.0, "einheit": "EL", "item": "Olivenöl", "roh": "5 EL Olivenöl"}, {"menge": 1.0, "einheit": "EL", "item": "Kräuter der Provence", "roh": "1 EL Kräuter der Provence"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, frisches Basilikum", "roh": "Salz, Pfeffer, frisches Basilikum"}], "zubereitung": ["Alle Gemüse in gleichmäßige Stücke schneiden.", "Aubergine, Zucchini und Paprika nacheinander in Olivenöl anbraten und beiseitestellen.", "Zwiebeln und Knoblauch andünsten, gehäutete Tomaten zugeben und einköcheln.", "Das angebratene Gemüse zur Tomatensauce geben.", "Mit Kräutern der Provence, Salz und Pfeffer würzen und zugedeckt 25–30 Minuten schmoren.", "Mit frischem Basilikum bestreut warm oder kalt servieren."], "hinweise": "Die Gemüse einzeln anbraten bewahrt ihre Textur.\n\nRatatouille schmeckt am nächsten Tag noch aromatischer.\n\nMit einem Spritzer Olivenöl und Brot ein vollwertiges Essen.", "alternative": "", "geschichte": "Ratatouille stammt aus der Provence, genauer aus der Gegend um Nizza, und ist ein Inbegriff der mediterranen Gemüseküche Südfrankreichs. Der Name leitet sich vom okzitanischen bzw. französischen „touiller“ (umrühren) ab. Ursprünglich war es ein einfaches Gericht der armen Landbevölkerung, das die Fülle des sommerlichen Gemüsegartens verwertete: Aubergine, Zucchini, Paprika, Tomaten, Zwiebeln und Knoblauch, geschmort in Olivenöl und gewürzt mit den Kräutern der Provence. Über die richtige Zubereitung gibt es bis heute Diskussionen — ob alle Gemüse zusammen oder einzeln angeschmort und dann vereint werden, um ihre jeweilige Textur zu wahren. Ratatouille kann als eigenständiges Hauptgericht, als Beilage zu Fleisch oder Fisch und warm wie kalt gegessen werden. Es steht für die sonnige, gemüsebetonte Seite der französischen Küche, ist von Natur aus vegan und kommt selbstverständlich ohne Schweinefleisch aus.", "persoenlich": "", "servier": "", "tags": ["Frankreich", "Provence", "Nizza", "Gemüse", "vegan", "vegetarisch", "Aubergine", "Zucchini", "mediterran", "Sommerküche", "Kräuter der Provence", "Hauptgericht"]}, {"id": "tarte-tatin", "status": "published", "date": "", "cover": "", "name": "Tarte Tatin", "land": "Frankreich", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine gestürzte Apfeltarte, bei der die Äpfel zuerst in Karamell und Butter geschmort und dann unter einem Teigdeckel gebacken werden. Goldbrauner Klassiker der französischen Patisserie.", "zutaten": ["6 feste, säuerliche Äpfel", "150 g Zucker", "80 g Butter", "1 Rolle Blätter- oder Mürbeteig", "1 Prise Zimt (optional)", "1 Zitrone (Saft)"], "zutatenS": [{"menge": 6.0, "einheit": "", "item": "feste, säuerliche Äpfel", "roh": "6 feste, säuerliche Äpfel"}, {"menge": 150.0, "einheit": "g", "item": "Zucker", "roh": "150 g Zucker"}, {"menge": 80.0, "einheit": "g", "item": "Butter", "roh": "80 g Butter"}, {"menge": 1.0, "einheit": "Rolle", "item": "Blätter- oder Mürbeteig", "roh": "1 Rolle Blätter- oder Mürbeteig"}, {"menge": 1.0, "einheit": "Prise", "item": "Zimt (optional)", "roh": "1 Prise Zimt (optional)"}, {"menge": 1.0, "einheit": "", "item": "Zitrone (Saft)", "roh": "1 Zitrone (Saft)"}], "zubereitung": ["Äpfel schälen, vierteln, entkernen und mit Zitronensaft beträufeln.", "In einer ofenfesten Pfanne aus Zucker und Butter ein goldbraunes Karamell herstellen.", "Apfelviertel dicht an dicht in das Karamell legen und einige Minuten darin schmoren.", "Den Teig auf die Äpfel legen, die Ränder einschlagen und einstechen.", "Bei 190 °C 25–30 Minuten goldbraun backen.", "Kurz abkühlen lassen, dann vorsichtig auf einen Teller stürzen, sodass die karamellisierten Äpfel oben liegen; lauwarm servieren."], "hinweise": "Feste Äpfel wählen, damit sie im Karamell nicht zerfallen.\n\nDas Karamell goldbraun, aber nicht zu dunkel führen, sonst wird es bitter.\n\nMit einem Klecks Crème fraîche oder Vanilleeis servieren.", "alternative": "", "geschichte": "Die Tarte Tatin ist eine der berühmtesten Süßspeisen Frankreichs und verdankt ihren Namen den Schwestern Stéphanie und Caroline Tatin, die Ende des 19. Jahrhunderts ein Hotel in Lamotte-Beuvron in der Region Sologne führten. Der verbreiteten Überlieferung nach entstand die gestürzte Tarte durch ein Missgeschick in der Küche: Die Äpfel seien zu lange in Butter und Zucker gegart worden, woraufhin man den Teig kurzerhand obenauf legte und die fertige Tarte stürzte. Ob Legende oder nicht — die Technik, Obst zuerst in Karamell zu schmoren und mit dem Teig nach unten zu stürzen, wurde zum Markenzeichen. Bekannt wurde die Tarte besonders durch das Pariser Restaurant Maxim's. Klassisch werden feste Äpfel verwendet, die im Karamell ihre Form behalten. Die Tarte Tatin steht für die rustikal-elegante Seite der französischen Patisserie und ist als Süßgebäck selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Frankreich", "Sologne", "Tarte Tatin", "Apfel", "Karamell", "Patisserie", "gestürzte Tarte", "süß", "vegetarisch", "Klassiker", "Blätterteig", "Dessert"]}, {"id": "moussaka", "status": "published", "date": "", "cover": "", "name": "Moussaka", "land": "Griechenland", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein geschichteter Auflauf aus Auberginen, Kartoffeln und gewürztem Lamm- oder Rinderhack, gekrönt von einer dicken Béchamelhaube. Griechenlands berühmtester Ofenauflauf.", "zutaten": ["2 große Auberginen", "3 Kartoffeln", "600 g Lamm- oder Rinderhack", "2 Zwiebeln", "400 g passierte Tomaten", "1 TL Zimt, 1 Lorbeerblatt", "60 g Butter, 60 g Mehl, 600 ml Milch (Béchamel)", "1 Ei, 80 g geriebener Käse", "Olivenöl, Salz, Pfeffer, Muskat"], "zutatenS": [{"menge": 2.0, "einheit": "", "item": "große Auberginen", "roh": "2 große Auberginen"}, {"menge": 3.0, "einheit": "", "item": "Kartoffeln", "roh": "3 Kartoffeln"}, {"menge": 600.0, "einheit": "g", "item": "Lamm- oder Rinderhack", "roh": "600 g Lamm- oder Rinderhack"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 400.0, "einheit": "g", "item": "passierte Tomaten", "roh": "400 g passierte Tomaten"}, {"menge": 1.0, "einheit": "TL", "item": "Zimt, 1 Lorbeerblatt", "roh": "1 TL Zimt, 1 Lorbeerblatt"}, {"menge": 60.0, "einheit": "g", "item": "Butter, 60 g Mehl, 600 ml Milch (Béchamel)", "roh": "60 g Butter, 60 g Mehl, 600 ml Milch (Béchamel)"}, {"menge": 1.0, "einheit": "", "item": "Ei, 80 g geriebener Käse", "roh": "1 Ei, 80 g geriebener Käse"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer, Muskat", "roh": "Olivenöl, Salz, Pfeffer, Muskat"}], "zubereitung": ["Auberginen und Kartoffeln in Scheiben schneiden, salzen und in Olivenöl goldbraun braten.", "Zwiebeln dünsten, Hack anbraten, mit Tomaten, Zimt und Lorbeer zu einer dicken Sauce einkochen.", "Aus Butter, Mehl und Milch eine dicke Béchamel rühren, mit Muskat würzen und Ei sowie Käse einrühren.", "In einer Form Kartoffeln, dann Auberginen, dann die Hackfüllung schichten.", "Mit der Béchamel bedecken und bei 180 °C 40–45 Minuten goldbraun backen.", "Vor dem Anschneiden 20 Minuten ruhen lassen, damit die Schichten halten."], "hinweise": "Die Auberginen salzen und ziehen lassen nimmt Bitterstoffe und Wasser.\n\nDie Béchamel ruhig dick führen — sie soll eine stabile Haube bilden.\n\nDas Ruhenlassen ist entscheidend für saubere Stücke.", "alternative": "", "geschichte": "Die griechische Moussaka in ihrer heutigen Form gilt als vergleichsweise modernes Gericht: Sie wurde Anfang des 20. Jahrhunderts maßgeblich vom griechischen Koch Nikolaos Tselementes geprägt, der die mit Béchamel überbackene Variante popularisierte. Ihre Wurzeln reichen jedoch weiter zurück in die Tradition geschichteter Auberginengerichte des östlichen Mittelmeers und des Nahen Ostens, wo verwandte Speisen existieren. Charakteristisch für die griechische Fassung sind die Schichten aus gebratenen Auberginen (und oft Kartoffeln), einer würzigen, mit Zimt und Tomate aromatisierten Hackfleischfüllung und der abschließenden, im Ofen goldbraun gebackenen Béchamelhaube. Verwendet werden traditionell Lamm oder Rind, weshalb die Moussaka von Natur aus ohne Schweinefleisch auskommt. Das Gericht erfordert mehrere Arbeitsschritte und gilt daher als Sonntags- und Festtagsessen. Heute ist es eines der bekanntesten Symbole der griechischen Küche und in Tavernen im ganzen Land verbreitet.", "persoenlich": "", "servier": "", "tags": ["Griechenland", "Moussaka", "Aubergine", "Lamm", "Rind", "Auflauf", "Béchamel", "Ofengericht", "mediterran", "Festtag", "Taverne", "Hauptgericht"]}, {"id": "horiatiki-salata", "status": "published", "date": "", "cover": "", "name": "Horiatiki salata", "land": "Griechenland", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 10, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Der „Bauernsalat“ aus Tomaten, Gurke, Paprika, Zwiebel und Oliven, gekrönt von einem ganzen Stück Feta und Oregano. Ohne Blattsalat, ganz mediterran.", "zutaten": ["4 reife Tomaten", "1 Salatgurke", "1 grüne Paprika", "1 rote Zwiebel", "100 g Kalamata-Oliven", "200 g Feta (am Stück)", "5 EL Olivenöl extra vergine", "1 TL getrockneter Oregano", "Salz, etwas Rotweinessig"], "zutatenS": [{"menge": 4.0, "einheit": "", "item": "reife Tomaten", "roh": "4 reife Tomaten"}, {"menge": 1.0, "einheit": "", "item": "Salatgurke", "roh": "1 Salatgurke"}, {"menge": 1.0, "einheit": "", "item": "grüne Paprika", "roh": "1 grüne Paprika"}, {"menge": 1.0, "einheit": "", "item": "rote Zwiebel", "roh": "1 rote Zwiebel"}, {"menge": 100.0, "einheit": "g", "item": "Kalamata-Oliven", "roh": "100 g Kalamata-Oliven"}, {"menge": 200.0, "einheit": "g", "item": "Feta (am Stück)", "roh": "200 g Feta (am Stück)"}, {"menge": 5.0, "einheit": "EL", "item": "Olivenöl extra vergine", "roh": "5 EL Olivenöl extra vergine"}, {"menge": 1.0, "einheit": "TL", "item": "getrockneter Oregano", "roh": "1 TL getrockneter Oregano"}, {"menge": null, "einheit": "", "item": "Salz, etwas Rotweinessig", "roh": "Salz, etwas Rotweinessig"}], "zubereitung": ["Tomaten in Spalten, Gurke und Paprika in grobe Stücke schneiden.", "Zwiebel in feine Ringe schneiden.", "Gemüse mit den Oliven in einer Schüssel locker mischen, leicht salzen.", "Mit Olivenöl und einem Spritzer Essig beträufeln.", "Das Feta-Stück obenauf legen, nicht unterheben.", "Mit Oregano bestreuen und sofort mit Brot servieren."], "hinweise": "Keinen Blattsalat zugeben — das ist untypisch.\n\nDer Feta kommt als ganzes Stück oben drauf, nicht zerkrümelt.\n\nReife Sommertomaten und gutes Olivenöl machen den Unterschied.", "alternative": "", "geschichte": "Die Horiatiki salata — wörtlich „dörflicher“ oder „Bauernsalat“ — ist der klassische griechische Salat und ein Sinnbild der mediterranen Küche. Anders als oft angenommen enthält er traditionell keinen Blattsalat, sondern besteht aus grob geschnittenem, sonnengereiftem Gemüse: Tomaten, Gurke, grüne Paprika, rote Zwiebel und Kalamata-Oliven, abgerundet mit einem ganzen Stück oder dicken Scheiben Feta und reichlich getrocknetem Oregano. Begossen wird er großzügig mit gutem Olivenöl. Der Salat spiegelt die Logik der ländlichen griechischen Ernährung wider, die auf frischen, lokal verfügbaren Zutaten und hochwertigem Öl beruht. In seiner heutigen Form ist er eng mit der Sommerküche und der Tavernenkultur verbunden und wird als geteilte Vorspeise oder Beilage zu vielen Gerichten gereicht, stets mit Brot zum Auftunken des aromatischen Öls. Er ist von Natur aus vegetarisch und ohne Schweinefleisch und gilt international als einer der bekanntesten Salate.", "persoenlich": "", "servier": "", "tags": ["Griechenland", "Horiatiki", "Bauernsalat", "Salat", "vegetarisch", "Feta", "Oliven", "Tomaten", "mediterran", "Sommerküche", "Olivenöl", "Vorspeise"]}, {"id": "baklava", "status": "published", "date": "", "cover": "", "name": "Baklava", "land": "Griechenland", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Hauchdünne Filoteig-Schichten mit gehackten Nüssen, gebacken und mit Honigsirup getränkt. Ein süßes, sirupschweres Gebäck mit langer Geschichte.", "zutaten": ["400 g Filoteig", "400 g Walnüsse, gehackt", "2 TL Zimt", "200 g Butter, geschmolzen", "250 g Zucker", "200 g Honig", "250 ml Wasser", "1 Zitrone (Saft)"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Filoteig", "roh": "400 g Filoteig"}, {"menge": 400.0, "einheit": "g", "item": "Walnüsse, gehackt", "roh": "400 g Walnüsse, gehackt"}, {"menge": 2.0, "einheit": "TL", "item": "Zimt", "roh": "2 TL Zimt"}, {"menge": 200.0, "einheit": "g", "item": "Butter, geschmolzen", "roh": "200 g Butter, geschmolzen"}, {"menge": 250.0, "einheit": "g", "item": "Zucker", "roh": "250 g Zucker"}, {"menge": 200.0, "einheit": "g", "item": "Honig", "roh": "200 g Honig"}, {"menge": 250.0, "einheit": "ml", "item": "Wasser", "roh": "250 ml Wasser"}, {"menge": 1.0, "einheit": "", "item": "Zitrone (Saft)", "roh": "1 Zitrone (Saft)"}], "zubereitung": ["Walnüsse mit Zimt mischen.", "Filoblätter einzeln in eine gebutterte Form legen, jedes mit Butter bestreichen; nach einigen Blättern eine Nussschicht einstreuen.", "So fortfahren, bis Teig und Nüsse aufgebraucht sind, mit Teigblättern abschließen.", "Das Baklava in Rauten vorschneiden und bei 170 °C 40–45 Minuten goldbraun backen.", "Aus Zucker, Honig, Wasser und Zitronensaft einen Sirup kochen.", "Den heißen Sirup über das gebackene, leicht abgekühlte Baklava gießen und mehrere Stunden durchziehen lassen."], "hinweise": "Heißer Sirup auf warmes Gebäck (oder umgekehrt kalt auf heiß) — nie beides heiß, sonst wird es matschig.\n\nDie Filoblätter abgedeckt halten, damit sie nicht austrocknen.\n\nDas Baklava vor dem Backen vorschneiden, dann lässt es sich später sauber teilen.", "alternative": "", "geschichte": "Baklava ist ein Gebäck mit langer Geschichte, das im gesamten Raum des früheren Osmanischen Reiches und des östlichen Mittelmeers verbreitet ist und von vielen Ländern als Teil ihrer Tradition beansprucht wird, darunter Griechenland. Es besteht aus zahlreichen hauchdünnen Filoteig-Schichten, zwischen die gehackte Nüsse — in Griechenland häufig Walnüsse, oft mit Zimt — geschichtet werden. Nach dem Backen wird das Gebäck mit einem Sirup aus Honig und Zucker getränkt, der ihm seine charakteristische Süße und klebrige Saftigkeit gibt. Die Kunst dünn ausgezogener Teige reicht weit zurück; die heutige geschichtete Form festigte sich in der osmanischen Hofküche. In Griechenland gehört Baklava zu festlichen Anlässen, Feiertagen und der Gästebewirtung und wird in kleinen, rautenförmigen Stücken serviert. Es zeigt die Vorliebe der Region für nuss- und sirupbasierte Süßspeisen und ist als reines Teig-Nuss-Gebäck selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Griechenland", "Baklava", "Filoteig", "Walnüsse", "Honig", "Sirup", "süß", "osmanisch geprägt", "Festtag", "vegetarisch", "Zimt", "Dessert"]}, {"id": "irish-stew", "status": "published", "date": "", "cover": "", "name": "Irish Stew", "land": "Irland", "kontinent": "Europa", "gang": "Suppe", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein schlichter Eintopf aus Lamm oder Hammel, Kartoffeln, Zwiebeln und Möhren, langsam in eigener Brühe geschmort. Das irische Nationalgericht.", "zutaten": ["800 g Lamm- oder Hammelfleisch mit Knochen, in Stücken", "1 kg Kartoffeln", "3 Zwiebeln", "3 Möhren", "1 l Wasser oder Lammbrühe", "1 Zweig Thymian, 1 Lorbeerblatt", "1 Bund Petersilie", "Salz und Pfeffer"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "Lamm- oder Hammelfleisch mit Knochen, in Stücken", "roh": "800 g Lamm- oder Hammelfleisch mit Knochen, in Stücken"}, {"menge": 1.0, "einheit": "kg", "item": "Kartoffeln", "roh": "1 kg Kartoffeln"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln", "roh": "3 Zwiebeln"}, {"menge": 3.0, "einheit": "", "item": "Möhren", "roh": "3 Möhren"}, {"menge": 1.0, "einheit": "l", "item": "Wasser oder Lammbrühe", "roh": "1 l Wasser oder Lammbrühe"}, {"menge": 1.0, "einheit": "Zweig", "item": "Thymian, 1 Lorbeerblatt", "roh": "1 Zweig Thymian, 1 Lorbeerblatt"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Fleisch in einem großen Topf mit Wasser oder Brühe aufsetzen, aufkochen und abschäumen.", "Zwiebeln und Möhren grob schneiden und zugeben, mit Thymian und Lorbeer würzen.", "Etwa 1 Stunde sanft köcheln lassen, bis das Fleisch zart wird.", "Kartoffeln in Stücken zugeben; ein Teil darf zerfallen und die Brühe binden.", "Weitere 30 Minuten garen, bis alles weich ist; mit Salz und Pfeffer abschmecken.", "Mit reichlich gehackter Petersilie bestreut servieren."], "hinweise": "Etwas Kartoffel zerdrücken bindet den Eintopf auf natürliche Weise.\n\nHammel gibt mehr Geschmack, braucht aber längere Garzeit.\n\nAm nächsten Tag schmeckt der Stew noch besser.", "alternative": "", "geschichte": "Der Irish Stew gilt als Nationalgericht Irlands und verkörpert die bodenständige Tradition der irischen Landküche. In seiner ursprünglichen, einfachsten Form besteht er aus nur wenigen Zutaten: Hammel- oder Lammfleisch, Kartoffeln, Zwiebeln und Wasser, langsam zu einem nahrhaften Eintopf geschmort. Diese Schlichtheit hat historische Gründe — Schafe lieferten Wolle und Fleisch, Kartoffeln waren das wichtigste Grundnahrungsmittel, und Brennstoff zum langen Kochen musste sparsam eingesetzt werden. Über die Authentizität späterer Zutaten wie Möhren oder Graupen wird unter Puristen bis heute diskutiert. Traditionell wird Hammel verwendet, dessen kräftiger Geschmack durch langes Garen mild und das zähe Fleisch zart wird; das Gericht ist von Natur aus ohne Schweinefleisch. Der Irish Stew steht sinnbildlich für die Geschichte der irischen Bevölkerung und ihre enge Bindung an Schaf und Kartoffel und wird bis heute als wärmendes Wohlfühlessen geschätzt.", "persoenlich": "", "servier": "", "tags": ["Irland", "Irish Stew", "Lamm", "Hammel", "Eintopf", "Kartoffeln", "Landküche", "Nationalgericht", "Wohlfühlessen", "Winterküche", "schlicht", "Hauptgericht"]}, {"id": "colcannon", "status": "published", "date": "", "cover": "", "name": "Colcannon", "land": "Irland", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Cremiges Kartoffelpüree, durchzogen von Grünkohl oder Wirsing und Frühlingszwiebeln, mit reichlich Butter. Irische Beilage mit Bezug zu Halloween.", "zutaten": ["1 kg mehligkochende Kartoffeln", "300 g Grünkohl oder Wirsing", "4 Frühlingszwiebeln", "100 g Butter", "150 ml Milch oder Sahne", "Salz und Pfeffer"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "mehligkochende Kartoffeln", "roh": "1 kg mehligkochende Kartoffeln"}, {"menge": 300.0, "einheit": "g", "item": "Grünkohl oder Wirsing", "roh": "300 g Grünkohl oder Wirsing"}, {"menge": 4.0, "einheit": "", "item": "Frühlingszwiebeln", "roh": "4 Frühlingszwiebeln"}, {"menge": 100.0, "einheit": "g", "item": "Butter", "roh": "100 g Butter"}, {"menge": 150.0, "einheit": "ml", "item": "Milch oder Sahne", "roh": "150 ml Milch oder Sahne"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Kartoffeln schälen, in Salzwasser weich kochen und abgießen.", "Grünkohl oder Wirsing in Streifen schneiden und in wenig Wasser oder Butter weich dünsten.", "Frühlingszwiebeln kurz in etwas Milch erwärmen.", "Kartoffeln mit Milch und der Hälfte der Butter zu einem cremigen Püree stampfen.", "Kohl und Frühlingszwiebeln unterheben, mit Salz und Pfeffer abschmecken.", "In einer Mulde die restliche Butter zerlaufen lassen und heiß servieren."], "hinweise": "Mehligkochende Kartoffeln ergeben das cremigste Püree.\n\nDen Kohl nicht zu fein hacken — etwas Biss gehört dazu.\n\nDie klassische Buttermulde in der Mitte ist Tradition.", "alternative": "", "geschichte": "Colcannon ist ein traditionelles irisches Gericht aus Kartoffelpüree, das mit gekochtem Grünkohl oder Wirsing und Frühlingszwiebeln (oder Lauch) vermengt und mit reichlich Butter angereichert wird. Der Name leitet sich vermutlich vom gälischen „cál ceannann“ (weißköpfiger Kohl) ab. Als Gericht der Kartoffel- und Kohlküche spiegelt es die Grundnahrungsmittel der irischen Landbevölkerung wider und war ein günstiges, sättigendes Alltagsessen. Besonders verbunden ist Colcannon mit Halloween (Samhain): Traditionell wurden kleine Gegenstände wie eine Münze oder ein Ring in die Schüssel gemischt, die dem Finder Glück oder eine bevorstehende Heirat verheißen sollten. Auch in Liedern und Volksbräuchen findet das Gericht Erwähnung. Während manche Varianten Speck enthalten, ist die klassische Fassung mit Butter, Kohl und Zwiebeln rein vegetarisch und ohne Schweinefleisch. Colcannon wird als Beilage zu Fleischgerichten oder als eigenständiges, herzhaftes Essen serviert.", "persoenlich": "", "servier": "", "tags": ["Irland", "Colcannon", "Kartoffeln", "Grünkohl", "Wirsing", "vegetarisch", "Beilage", "Halloween", "Butter", "Landküche", "Wohlfühlessen", "Püree"]}, {"id": "soda-bread", "status": "published", "date": "", "cover": "", "name": "Soda Bread", "land": "Irland", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein rustikales Brot ohne Hefe, das mit Natron und Buttermilch getrieben und schnell gebacken wird. Mit charakteristischem Kreuz auf der Kruste.", "zutaten": ["450 g Weizenmehl (oder Mischung mit Vollkorn)", "1 TL Natron", "1 TL Salz", "400 ml Buttermilch", "1 EL Haferflocken (optional)"], "zutatenS": [{"menge": 450.0, "einheit": "g", "item": "Weizenmehl (oder Mischung mit Vollkorn)", "roh": "450 g Weizenmehl (oder Mischung mit Vollkorn)"}, {"menge": 1.0, "einheit": "TL", "item": "Natron", "roh": "1 TL Natron"}, {"menge": 1.0, "einheit": "TL", "item": "Salz", "roh": "1 TL Salz"}, {"menge": 400.0, "einheit": "ml", "item": "Buttermilch", "roh": "400 ml Buttermilch"}, {"menge": 1.0, "einheit": "EL", "item": "Haferflocken (optional)", "roh": "1 EL Haferflocken (optional)"}], "zubereitung": ["Mehl, Natron und Salz in einer Schüssel gut vermischen.", "Die Buttermilch zügig einarbeiten, bis ein weicher, klebriger Teig entsteht; nicht lange kneten.", "Den Teig zu einem runden Laib formen und auf ein Blech setzen.", "Ein tiefes Kreuz in die Oberfläche schneiden, optional mit Haferflocken bestreuen.", "Bei 220 °C etwa 35–40 Minuten backen, bis der Laib hohl klingt.", "Auf einem Gitter abkühlen lassen und frisch mit Butter servieren."], "hinweise": "Den Teig nur kurz zusammenfügen — zu viel Kneten macht das Brot zäh.\n\nFrische Buttermilch sorgt für die beste Triebwirkung.\n\nAm ersten Tag frisch genießen; danach toasten.", "alternative": "", "geschichte": "Irisches Soda Bread ist ein hefefreies Brot, das mit Natron (baking soda) und Buttermilch zubereitet wird — die Säure der Buttermilch reagiert mit dem Natron und lässt den Teig aufgehen, ganz ohne lange Geh- und Knetzeiten. Diese Backweise verbreitete sich in Irland im 19. Jahrhundert, nachdem Natron als Backtriebmittel verfügbar wurde. Sie passte ideal zu den Bedingungen vieler irischer Haushalte: Der weiche irische Weizen eignete sich schlecht für Hefeteige, und viele Familien hatten weder einen Backofen noch Zugang zu frischer Hefe, sondern buken in einer gusseisernen Topfform über dem Torffeuer. Charakteristisch ist das tiefe Kreuz, das vor dem Backen in den Laib geschnitten wird — praktisch zum gleichmäßigen Durchbacken, volkstümlich auch als Segens- oder Glückszeichen gedeutet. Soda Bread gehört zum irischen Frühstück und zur Tafel, wird zu Suppen und Eintöpfen gereicht und ist als einfaches Getreidebrot selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Irland", "Soda Bread", "Brot", "hefefrei", "Buttermilch", "Natron", "vegetarisch", "Frühstück", "rustikal", "Landküche", "schnell gebacken", "Beilage"]}, {"id": "plokkfiskur", "status": "published", "date": "", "cover": "", "name": "Plokkfiskur", "land": "Island", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein cremiger Auflauf bzw. Stampf aus gekochtem Weißfisch und Kartoffeln, gebunden mit Béchamel und Zwiebeln. Isländisches Resteessen, das zum Klassiker wurde.", "zutaten": ["600 g Kabeljau- oder Schellfischfilet", "500 g Kartoffeln, gekocht", "1 große Zwiebel", "40 g Butter", "40 g Mehl", "500 ml Milch", "Salz, Pfeffer, Muskat", "dunkles Roggenbrot zum Servieren"], "zutatenS": [{"menge": 600.0, "einheit": "g", "item": "Kabeljau- oder Schellfischfilet", "roh": "600 g Kabeljau- oder Schellfischfilet"}, {"menge": 500.0, "einheit": "g", "item": "Kartoffeln, gekocht", "roh": "500 g Kartoffeln, gekocht"}, {"menge": 1.0, "einheit": "", "item": "große Zwiebel", "roh": "1 große Zwiebel"}, {"menge": 40.0, "einheit": "g", "item": "Butter", "roh": "40 g Butter"}, {"menge": 40.0, "einheit": "g", "item": "Mehl", "roh": "40 g Mehl"}, {"menge": 500.0, "einheit": "ml", "item": "Milch", "roh": "500 ml Milch"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, Muskat", "roh": "Salz, Pfeffer, Muskat"}, {"menge": null, "einheit": "", "item": "dunkles Roggenbrot zum Servieren", "roh": "dunkles Roggenbrot zum Servieren"}], "zubereitung": ["Fisch in leicht gesalzenem Wasser gar ziehen lassen, abtropfen und in Stücke zerpflücken.", "Zwiebel würfeln und in Butter glasig dünsten.", "Mehl darüberstäuben, kurz anschwitzen und mit Milch zu einer Béchamel aufgießen.", "Mit Salz, Pfeffer und Muskat würzen.", "Fisch und in Stücke gebrochene Kartoffeln vorsichtig unterheben und erwärmen.", "Heiß mit gebuttertem Roggenbrot servieren."], "hinweise": "Den Fisch nur grob zerpflücken — Stücke geben Struktur.\n\nDie Sauce nicht zu dünn führen, damit der Plokkfiskur sämig bleibt.\n\nRoggenbrot gehört traditionell dazu.", "alternative": "", "geschichte": "Plokkfiskur — wörtlich „gepflückter Fisch“ — ist ein traditionelles isländisches Gericht, das ursprünglich aus der sparsamen Verwertung von Resten entstand: Übrig gebliebener gekochter Fisch (meist Kabeljau oder Schellfisch) und Kartoffeln wurden zerpflückt und zu einem sättigenden Eintopf oder Stampf verarbeitet. In einer fischreichen Inselnation, in der Kabeljau über Jahrhunderte das wichtigste Nahrungs- und Handelsgut war, lag eine solche Resteküche nahe. Mit der Zeit wurde aus dem schlichten Resteessen ein eigenständiger Klassiker, der oft mit einer Béchamelsauce und gedünsteten Zwiebeln verfeinert wird. Serviert wird Plokkfiskur klassisch mit dunklem Roggenbrot (rúgbrauð) und Butter. Es gilt als isländisches Wohlfühlessen und steht auf vielen Speisekarten, vom Hausmannskost-Lokal bis zur gehobenen Interpretation. Als Fischgericht ist es selbstverständlich ohne Schweinefleisch und spiegelt die enge Bindung Islands an den Fischfang wider.", "persoenlich": "", "servier": "", "tags": ["Island", "Plokkfiskur", "Kabeljau", "Fisch", "Kartoffeln", "Béchamel", "Resteküche", "Wohlfühlessen", "Roggenbrot", "nordisch", "Hausmannskost", "Hauptgericht"]}, {"id": "kjoets-pa", "status": "published", "date": "", "cover": "", "name": "Kjötsúpa", "land": "Island", "kontinent": "Europa", "gang": "Suppe", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine klare, kräftige Lammsuppe mit Wurzelgemüse, Kartoffeln und Kohl. Wärmendes Eintopfgericht der isländischen Schafzucht.", "zutaten": ["800 g Lammfleisch mit Knochen, in Stücken", "4 Kartoffeln", "3 Möhren", "0.25 Steckrübe", "1 Lauchstange", "0.25 Weißkohl", "1.5 l Wasser", "Salz, Pfeffer, getrocknete Suppenkräuter"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "Lammfleisch mit Knochen, in Stücken", "roh": "800 g Lammfleisch mit Knochen, in Stücken"}, {"menge": 4.0, "einheit": "", "item": "Kartoffeln", "roh": "4 Kartoffeln"}, {"menge": 3.0, "einheit": "", "item": "Möhren", "roh": "3 Möhren"}, {"menge": 0.25, "einheit": "", "item": "Steckrübe", "roh": "0.25 Steckrübe"}, {"menge": 1.0, "einheit": "", "item": "Lauchstange", "roh": "1 Lauchstange"}, {"menge": 0.25, "einheit": "", "item": "Weißkohl", "roh": "0.25 Weißkohl"}, {"menge": 1.5, "einheit": "l", "item": "Wasser", "roh": "1.5 l Wasser"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, getrocknete Suppenkräuter", "roh": "Salz, Pfeffer, getrocknete Suppenkräuter"}], "zubereitung": ["Lammfleisch mit Wasser aufsetzen, aufkochen und sorgfältig abschäumen.", "Salzen und etwa 45 Minuten sanft köcheln, bis das Fleisch zart wird.", "Gemüse grob schneiden und zugeben.", "Weitere 25–30 Minuten garen, bis alles weich ist.", "Mit Salz, Pfeffer und Suppenkräutern abschmecken.", "Heiß als sättigender Eintopf servieren."], "hinweise": "Gründliches Abschäumen ergibt eine klare, saubere Brühe.\n\nDas Gemüse je nach Garzeit gestaffelt zugeben.\n\nAufgewärmt schmeckt die Suppe noch intensiver.", "alternative": "", "geschichte": "Kjötsúpa — die isländische Fleisch- bzw. Lammsuppe — gehört zu den ältesten und beständigsten Gerichten der isländischen Küche. Das Schaf war über Jahrhunderte das wichtigste Nutztier der kargen Insel und lieferte Wolle, Milch und Fleisch; entsprechend zentral ist Lamm in der isländischen Ernährung. Die Suppe verbindet Lammfleisch mit dem Gemüse, das im rauen Klima gedeiht oder lagerfähig war: Kartoffeln, Möhren, Steckrübe, Lauch und Kohl. Gewürzt wird sie meist schlicht, traditionell auch mit getrockneten Suppenkräutern. Kjötsúpa war ein praktisches, nahrhaftes Essen, das aus einem Topf eine ganze Familie sättigte und sich gut über die langen, kalten Monate kochen ließ. Bis heute gilt sie als Inbegriff isländischer Hausmannskost und wird besonders im Herbst, zur Schlachtsaison, und im Winter gekocht. Als reines Lamm-Gemüse-Gericht ist sie selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Island", "Kjötsúpa", "Lamm", "Lammsuppe", "Wurzelgemüse", "Kohl", "Eintopf", "nordisch", "Winterküche", "Hausmannskost", "Schafzucht", "Suppe"]}, {"id": "skyr-me-berjum", "status": "published", "date": "", "cover": "", "name": "Skyr með berjum", "land": "Island", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 10, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Cremiges isländisches Skyr, serviert mit frischen Beeren, etwas Milch und Honig. Eiweißreiche Spezialität mit jahrhundertealter Tradition.", "zutaten": ["500 g Skyr (ersatzweise sehr dicker Naturjoghurt)", "100 ml Milch", "200 g frische Beeren (z. B. Blaubeeren)", "2 EL Honig", "1 Prise Vanille (optional)"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Skyr (ersatzweise sehr dicker Naturjoghurt)", "roh": "500 g Skyr (ersatzweise sehr dicker Naturjoghurt)"}, {"menge": 100.0, "einheit": "ml", "item": "Milch", "roh": "100 ml Milch"}, {"menge": 200.0, "einheit": "g", "item": "frische Beeren (z. B. Blaubeeren)", "roh": "200 g frische Beeren (z. B. Blaubeeren)"}, {"menge": 2.0, "einheit": "EL", "item": "Honig", "roh": "2 EL Honig"}, {"menge": 1.0, "einheit": "Prise", "item": "Vanille (optional)", "roh": "1 Prise Vanille (optional)"}], "zubereitung": ["Skyr mit der Milch glatt und cremig rühren.", "Nach Geschmack mit Honig und etwas Vanille süßen.", "In Schalen anrichten.", "Frische Beeren darüber verteilen.", "Mit einem zusätzlichen Faden Honig beträufeln und sofort servieren."], "hinweise": "Echtes Skyr ist dicker als Joghurt — bei Ersatz sehr dicken Joghurt wählen.\n\nSaisonale Beeren passen am besten.\n\nAuch mit Haferflocken ein nahrhaftes Frühstück.", "alternative": "", "geschichte": "Skyr ist eine der ältesten und charakteristischsten Spezialitäten Islands und wird seit der Zeit der Besiedlung im Mittelalter hergestellt. Technisch handelt es sich um einen säuerlichen, dickgelegten Frischkäse, der jedoch wie ein Joghurt gegessen wird. Über Jahrhunderte war Skyr ein zentrales, haltbares Milchprodukt, das die isländische Bevölkerung mit wertvollem Eiweiß versorgte, als andere Nahrung knapp war. Traditionell wurde es aus entrahmter Milch unter Zugabe von Lab und einer Skyr-Kultur hergestellt; ein Teil der alten Charge diente als Starter für die neue. Skyr ist dick, fettarm und eiweißreich und wird klassisch mit etwas Milch glatt gerührt und mit Zucker oder Honig sowie frischen Beeren — etwa Blaubeeren oder den isländischen Krähenbeeren — gegessen. Es wird zum Frühstück, als Dessert und als Zwischenmahlzeit verzehrt. Als reines Milchprodukt mit Früchten ist es selbstverständlich vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Island", "Skyr", "Milchprodukt", "Beeren", "Honig", "eiweißreich", "vegetarisch", "Frühstück", "nordisch", "traditionell", "Dessert", "fettarm"]}, {"id": "risotto-alla-milanese", "status": "published", "date": "", "cover": "", "name": "Risotto alla milanese", "land": "Italien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Cremiges Safranrisotto aus Mailand, leuchtend goldgelb und mit Parmesan vollendet. Klassiker der lombardischen Küche.", "zutaten": ["320 g Risottoreis (Carnaroli oder Arborio)", "1 Zwiebel, fein gewürfelt", "1 l Rinder- oder Gemüsebrühe, heiß", "1 Briefchen Safranfäden", "100 ml Weißwein", "60 g Butter", "80 g Parmesan, gerieben", "Salz"], "zutatenS": [{"menge": 320.0, "einheit": "g", "item": "Risottoreis (Carnaroli oder Arborio)", "roh": "320 g Risottoreis (Carnaroli oder Arborio)"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel, fein gewürfelt", "roh": "1 Zwiebel, fein gewürfelt"}, {"menge": 1.0, "einheit": "l", "item": "Rinder- oder Gemüsebrühe, heiß", "roh": "1 l Rinder- oder Gemüsebrühe, heiß"}, {"menge": 1.0, "einheit": "Briefchen", "item": "Safranfäden", "roh": "1 Briefchen Safranfäden"}, {"menge": 100.0, "einheit": "ml", "item": "Weißwein", "roh": "100 ml Weißwein"}, {"menge": 60.0, "einheit": "g", "item": "Butter", "roh": "60 g Butter"}, {"menge": 80.0, "einheit": "g", "item": "Parmesan, gerieben", "roh": "80 g Parmesan, gerieben"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Safran in etwas heißer Brühe einweichen.", "Zwiebel in der Hälfte der Butter glasig dünsten, Reis zugeben und glasig anschwitzen.", "Mit Weißwein ablöschen und einkochen lassen.", "Nach und nach heiße Brühe angießen und unter Rühren cremig kochen; die Safranbrühe einrühren.", "Nach etwa 18 Minuten vom Herd nehmen.", "Mit restlicher Butter und Parmesan kräftig montieren, salzen und sofort servieren."], "hinweise": "Die Brühe stets heiß angießen, sonst stockt der Garprozess.\n\nDas abschließende Montieren mit Butter und Käse macht die Cremigkeit.\n\nRisotto wartet nicht — direkt nach dem Fertigstellen servieren.", "alternative": "", "geschichte": "Das Risotto alla milanese ist das Wahrzeichengericht der lombardischen Hauptstadt Mailand und verdankt seine leuchtend goldgelbe Farbe und sein feines Aroma dem Safran. Einer verbreiteten Legende nach soll der Safran im 16. Jahrhundert von einem Glasmaler des Mailänder Doms ins Risotto gelangt sein, der das Gewürz zum Färben seiner Glasfenster nutzte — ob historisch belegt oder nicht, die Geschichte ist fest mit dem Gericht verbunden. Risotto als Zubereitungsart spiegelt die Bedeutung des Reisanbaus in der Po-Ebene Norditaliens wider. Der Reis wird angeschwitzt, nach und nach mit heißer Brühe aufgegossen und unter Rühren cremig gekocht, bis er die typische sämige Konsistenz erreicht, und zuletzt mit Butter und Parmesan „mantecato“ (montiert). Traditionell wird Rinderbrühe und teils Rindermark verwendet; das Gericht kommt ohne Schweinefleisch aus und lässt sich mit Gemüsebrühe auch rein vegetarisch zubereiten. Es gilt als Begleiter des Ossobuco, wird aber ebenso solo geschätzt.", "persoenlich": "", "servier": "", "tags": ["Italien", "Mailand", "Lombardei", "Risotto", "Safran", "Reis", "vegetarisch", "Parmesan", "cremig", "norditalienisch", "Klassiker", "Hauptgericht"]}, {"id": "spaghetti-al-pomodoro-e-basilico", "status": "published", "date": "", "cover": "", "name": "Spaghetti al pomodoro e basilico", "land": "Italien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Spaghetti mit einer einfachen Sauce aus reifen Tomaten, Knoblauch, Olivenöl und frischem Basilikum. Die Essenz der italienischen Küche.", "zutaten": ["400 g Spaghetti", "600 g reife Tomaten (oder gute Dosentomaten)", "2 Zehen Knoblauch", "5 EL Olivenöl extra vergine", "1 Bund frisches Basilikum", "Salz", "Parmesan zum Servieren (optional)"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Spaghetti", "roh": "400 g Spaghetti"}, {"menge": 600.0, "einheit": "g", "item": "reife Tomaten (oder gute Dosentomaten)", "roh": "600 g reife Tomaten (oder gute Dosentomaten)"}, {"menge": 2.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "2 Zehen Knoblauch"}, {"menge": 5.0, "einheit": "EL", "item": "Olivenöl extra vergine", "roh": "5 EL Olivenöl extra vergine"}, {"menge": 1.0, "einheit": "Bund", "item": "frisches Basilikum", "roh": "1 Bund frisches Basilikum"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}, {"menge": null, "einheit": "", "item": "Parmesan zum Servieren (optional)", "roh": "Parmesan zum Servieren (optional)"}], "zubereitung": ["Tomaten häuten und grob würfeln (bei Dosentomaten zerdrücken).", "Knoblauch in Olivenöl sanft anduften lassen, nicht bräunen.", "Tomaten zugeben, salzen und 15–20 Minuten zu einer sämigen Sauce einkochen.", "Spaghetti in reichlich Salzwasser al dente kochen.", "Pasta abgießen, mit etwas Nudelwasser zur Sauce geben und schwenken.", "Frisches Basilikum unterheben und sofort, nach Wunsch mit Parmesan, servieren."], "hinweise": "Basilikum erst zum Schluss zugeben, damit das Aroma erhalten bleibt.\n\nEtwas Nudelwasser bindet Sauce und Pasta zu einer Einheit.\n\nDie Qualität von Tomaten und Olivenöl entscheidet über das Gericht.", "alternative": "", "geschichte": "Spaghetti mit Tomatensauce und Basilikum gelten als Inbegriff der italienischen Küche und als Paradebeispiel der „cucina povera“ — der Kochkunst, aus wenigen, guten Zutaten Großes zu machen. Die Tomate kam nach der Entdeckung Amerikas nach Europa und setzte sich in Italien, besonders im Süden um Neapel, ab dem 18. und 19. Jahrhundert als Saucengrundlage durch. In Verbindung mit der industriellen Herstellung getrockneter Pasta in Kampanien entstand eines der bekanntesten Gerichte der Welt. Das Rezept lebt von der Qualität weniger Komponenten: reife Tomaten, gutes Olivenöl, Knoblauch und frisches Basilikum, das erst zum Schluss zugegeben wird, um sein Aroma zu bewahren. Wichtig ist die richtige Garung der Pasta „al dente“ und das Verbinden von Nudeln und Sauce in der Pfanne. Das Gericht ist von Natur aus vegan und ohne Schweinefleisch und steht sinnbildlich für die Philosophie der italienischen Küche, mit Zurückhaltung den Eigengeschmack der Zutaten zu feiern.", "persoenlich": "", "servier": "", "tags": ["Italien", "Neapel", "Spaghetti", "Pasta", "Tomaten", "Basilikum", "vegan", "vegetarisch", "cucina povera", "mediterran", "Klassiker", "Hauptgericht"]}, {"id": "tiramis", "status": "published", "date": "", "cover": "", "name": "Tiramisù", "land": "Italien", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine kühle Schichtspeise aus in Espresso getränkten Löffelbiskuits und einer Creme aus Mascarpone und Ei, bestäubt mit Kakao. Italiens berühmtestes Dessert.", "zutaten": ["300 g Löffelbiskuits (Savoiardi)", "500 g Mascarpone", "4 Eier (getrennt)", "100 g Zucker", "300 ml starker Espresso, abgekühlt", "2 EL Kakaopulver", "optional etwas Marsala oder Amaretto"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "Löffelbiskuits (Savoiardi)", "roh": "300 g Löffelbiskuits (Savoiardi)"}, {"menge": 500.0, "einheit": "g", "item": "Mascarpone", "roh": "500 g Mascarpone"}, {"menge": 4.0, "einheit": "", "item": "Eier (getrennt)", "roh": "4 Eier (getrennt)"}, {"menge": 100.0, "einheit": "g", "item": "Zucker", "roh": "100 g Zucker"}, {"menge": 300.0, "einheit": "ml", "item": "starker Espresso, abgekühlt", "roh": "300 ml starker Espresso, abgekühlt"}, {"menge": 2.0, "einheit": "EL", "item": "Kakaopulver", "roh": "2 EL Kakaopulver"}, {"menge": null, "einheit": "", "item": "optional etwas Marsala oder Amaretto", "roh": "optional etwas Marsala oder Amaretto"}], "zubereitung": ["Eigelb mit Zucker cremig schlagen, Mascarpone unterrühren.", "Eiweiß steif schlagen und vorsichtig unter die Mascarponecreme heben.", "Espresso (nach Wunsch mit etwas Likör) in einen flachen Teller geben.", "Löffelbiskuits kurz darin wenden und eine Lage in eine Form legen.", "Mit Creme bedecken, dann erneut Biskuits und Creme schichten.", "Mit Kakao bestäuben und mindestens 4 Stunden, besser über Nacht, kühlen."], "hinweise": "Die Biskuits nur kurz tunken, sonst werden sie matschig.\n\nDas Durchziehen über Nacht macht das Tiramisù am besten.\n\nDen Kakao erst kurz vor dem Servieren aufstäuben.", "alternative": "", "geschichte": "Tiramisù — wörtlich „zieh mich hinauf“ — ist eines der bekanntesten Desserts Italiens und international ein Synonym für italienische Süßspeisen. Seine Entstehung wird überwiegend der Region Venetien, genauer der Stadt Treviso, und den 1960er- bis 1970er-Jahren zugeschrieben, auch wenn mehrere Lokale und Regionen die Urheberschaft beanspruchen. Das Dessert besteht aus Löffelbiskuits (Savoiardi), die in Espresso getränkt und mit einer luftigen Creme aus Mascarpone, Eigelb und Zucker geschichtet werden; den Abschluss bildet eine Staubschicht aus Kakaopulver. Charakteristisch ist das Zusammenspiel von bitterem Kaffee, süßer Creme und Kakao. Tiramisù wird kalt serviert und muss vor dem Genuss durchziehen, damit sich die Aromen verbinden und die Biskuits weich werden. Es hat sich von einer regionalen Spezialität zu einem weltweit nachgekochten Klassiker entwickelt. Als Süßspeise auf Ei-, Käse- und Kaffeebasis ist es selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Italien", "Venetien", "Treviso", "Tiramisù", "Mascarpone", "Espresso", "Löffelbiskuit", "Kakao", "süß", "vegetarisch", "Schichtdessert", "Dessert"]}, {"id": "flia", "status": "published", "date": "", "cover": "", "name": "Flia", "land": "Kosovo", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein geduldig geschichtetes Fladengericht aus dünnen Teiglagen, das über Glut gebacken und mit Joghurt oder saurer Sahne serviert wird. Festtagsspeise des Hochlands.", "zutaten": ["500 g Mehl", "700 ml Wasser", "1 TL Salz", "100 g Butter, geschmolzen", "200 g saure Sahne oder kajmak (zum Bestreichen/Servieren)", "Joghurt zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Mehl", "roh": "500 g Mehl"}, {"menge": 700.0, "einheit": "ml", "item": "Wasser", "roh": "700 ml Wasser"}, {"menge": 1.0, "einheit": "TL", "item": "Salz", "roh": "1 TL Salz"}, {"menge": 100.0, "einheit": "g", "item": "Butter, geschmolzen", "roh": "100 g Butter, geschmolzen"}, {"menge": 200.0, "einheit": "g", "item": "saure Sahne oder kajmak (zum Bestreichen/Servieren)", "roh": "200 g saure Sahne oder kajmak (zum Bestreichen/Servieren)"}, {"menge": null, "einheit": "", "item": "Joghurt zum Servieren", "roh": "Joghurt zum Servieren"}], "zubereitung": ["Mehl, Wasser und Salz zu einem dünnflüssigen, glatten Teig verrühren.", "Eine gebutterte Form (oder eine schwere Pfanne) im heißen Ofen vorwärmen.", "Mit einem Löffel strahlenförmig dünne Teigstreifen auftragen und unter Oberhitze (Grill) backen, bis sie stocken.", "Die nächste Lage versetzt darüber auftragen, mit Butter bestreichen und erneut backen.", "Den Vorgang vielfach wiederholen, bis ein dicker, geschichteter Fladen entsteht.", "Lauwarm in Stücke schneiden und mit Joghurt oder saurer Sahne servieren."], "hinweise": "Geduld ist entscheidend — jede Schicht muss einzeln stocken.\n\nDie Oberhitze (Grillfunktion) ersetzt im Ofen die traditionelle Gluthaube.\n\nReichlich Butter zwischen den Lagen macht die Flia zart.", "alternative": "", "geschichte": "Flia (auch Fli oder Flija) ist eine traditionelle Spezialität des Kosovo und der albanischen Hochlandregionen und gilt als eines der identitätsstiftenden Gerichte. Charakteristisch ist die aufwendige Zubereitung: Ein dünner Teig aus Mehl, Wasser und Salz wird Schicht für Schicht aufgetragen, wobei jede Lage einzeln über offener Glut oder unter einer mit Glut bedeckten Metallhaube (saç) gebacken wird, bevor die nächste folgt. So entsteht ein vielschichtiges, fächerartiges Gebäck — der Name wird mit „Schichten“ in Verbindung gebracht. Die Zubereitung ist zeitintensiv und traditionell ein gemeinschaftliches, oft weibliches Ereignis, das mit Festen, Familienzusammenkünften und Feiertagen verbunden ist. Serviert wird Flia mit Joghurt, saurer Sahne (kajmak) oder Honig. Das Gericht steht für Gastfreundschaft und Geduld und ist von Natur aus vegetarisch und ohne Schweinefleisch. Es spiegelt die ländliche Tradition des Backens über dem Feuer wider.", "persoenlich": "", "servier": "", "tags": ["Kosovo", "Flia", "Balkan", "Schichtteig", "über Glut gebacken", "saç", "vegetarisch", "Festtag", "Hochland", "Gastfreundschaft", "albanisch geprägt", "Hauptgericht"]}, {"id": "speca-t-mbushur", "status": "published", "date": "", "cover": "", "name": "Speca të mbushur", "land": "Kosovo", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Paprikaschoten, gefüllt mit gewürztem Reis und Rinderhack, in Tomatensud geschmort. Gefülltes Gemüse in der Tradition des Balkans.", "zutaten": ["6 mittelgroße Paprika", "150 g Reis", "400 g Rinderhack", "2 Zwiebeln", "2 EL Tomatenmark", "400 g passierte Tomaten", "1 TL Paprikapulver", "1 Bund Petersilie", "Olivenöl, Salz, Pfeffer"], "zutatenS": [{"menge": 6.0, "einheit": "", "item": "mittelgroße Paprika", "roh": "6 mittelgroße Paprika"}, {"menge": 150.0, "einheit": "g", "item": "Reis", "roh": "150 g Reis"}, {"menge": 400.0, "einheit": "g", "item": "Rinderhack", "roh": "400 g Rinderhack"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 2.0, "einheit": "EL", "item": "Tomatenmark", "roh": "2 EL Tomatenmark"}, {"menge": 400.0, "einheit": "g", "item": "passierte Tomaten", "roh": "400 g passierte Tomaten"}, {"menge": 1.0, "einheit": "TL", "item": "Paprikapulver", "roh": "1 TL Paprikapulver"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer", "roh": "Olivenöl, Salz, Pfeffer"}], "zubereitung": ["Bei den Paprika die Deckel abschneiden und die Kerne entfernen.", "Zwiebeln in Öl dünsten, Hack anbraten, Reis, Paprikapulver und Tomatenmark zugeben und kurz mitrösten.", "Mit gehackter Petersilie, Salz und Pfeffer würzen; die Füllung soll noch leicht roh sein.", "Paprika mit der Reis-Hack-Mischung füllen und dicht in einen Topf stellen.", "Passierte Tomaten mit etwas Wasser angießen, bis die Schoten zur Hälfte bedeckt sind.", "Zugedeckt 45–55 Minuten sanft schmoren, bis Reis und Paprika weich sind; mit Joghurt servieren."], "hinweise": "Den Reis nur halb garen lassen — er quillt beim Schmoren nach.\n\nDie Paprika dicht stellen, damit sie aufrecht bleiben.\n\nEin Klecks Joghurt rundet das Gericht ab.", "alternative": "", "geschichte": "Speca të mbushur — gefüllte Paprika — gehören zur großen Familie der gefüllten Gemüse (Dolma/Japrak), die im gesamten Balkan, im Nahen Osten und im früheren osmanischen Raum verbreitet sind und über Jahrhunderte zur Alltags- wie Festküche gehören. Im Kosovo und in den albanisch geprägten Regionen sind sie ein beliebtes Sommer- und Herbstgericht, wenn Paprika reif und reichlich vorhanden ist. Gefüllt werden die Schoten mit einer Mischung aus Reis und Hackfleisch — in der mehrheitlich muslimisch geprägten Region traditionell aus Rind oder Lamm, also ohne Schwein — gewürzt mit Zwiebel, Kräutern und Paprikapulver. Die gefüllten Schoten werden anschließend in einem Tomaten- oder Brühesud sanft geschmort, bis Reis und Gemüse weich sind und die Aromen sich verbunden haben. Das Gericht steht für die Tradition, Gemüse sättigend und haltbar zu verwerten, und wird oft mit Joghurt serviert. Es spiegelt die geteilte Küchentradition Südosteuropas wider.", "persoenlich": "", "servier": "", "tags": ["Kosovo", "Speca të mbushur", "gefüllte Paprika", "Dolma", "Rind", "Reis", "Balkan", "osmanisch geprägt", "Schmorgericht", "Sommerküche", "Joghurt", "Hauptgericht"]}, {"id": "sheqerpare", "status": "published", "date": "", "cover": "", "name": "Sheqerpare", "land": "Kosovo", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Zarte, mürbe Grießküchlein, nach dem Backen in Zuckersirup getränkt. Süßes Festtagsgebäck mit osmanischen Wurzeln.", "zutaten": ["200 g Mehl", "80 g feiner Grieß", "120 g weiche Butter", "1 Ei", "1 TL Backpulver", "16 Mandeln zum Verzieren", "300 g Zucker (Sirup)", "300 ml Wasser (Sirup)", "1 Zitrone (Saft)"], "zutatenS": [{"menge": 200.0, "einheit": "g", "item": "Mehl", "roh": "200 g Mehl"}, {"menge": 80.0, "einheit": "g", "item": "feiner Grieß", "roh": "80 g feiner Grieß"}, {"menge": 120.0, "einheit": "g", "item": "weiche Butter", "roh": "120 g weiche Butter"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 1.0, "einheit": "TL", "item": "Backpulver", "roh": "1 TL Backpulver"}, {"menge": 16.0, "einheit": "", "item": "Mandeln zum Verzieren", "roh": "16 Mandeln zum Verzieren"}, {"menge": 300.0, "einheit": "g", "item": "Zucker (Sirup)", "roh": "300 g Zucker (Sirup)"}, {"menge": 300.0, "einheit": "ml", "item": "Wasser (Sirup)", "roh": "300 ml Wasser (Sirup)"}, {"menge": 1.0, "einheit": "", "item": "Zitrone (Saft)", "roh": "1 Zitrone (Saft)"}], "zubereitung": ["Aus Zucker, Wasser und Zitronensaft einen Sirup kochen und vollständig abkühlen lassen.", "Butter, Ei, Mehl, Grieß und Backpulver zu einem geschmeidigen Teig verkneten.", "Kleine Kugeln formen, leicht flach drücken und je eine Mandel eindrücken.", "Auf ein Blech setzen und bei 175 °C 18–22 Minuten goldgelb backen.", "Die noch warmen Küchlein in den kalten Sirup legen.", "Den Sirup einige Stunden einziehen lassen, bis die Sheqerpare saftig sind."], "hinweise": "Warmes Gebäck in kalten Sirup — so saugen sich die Küchlein gleichmäßig voll.\n\nDen Teig nicht zu lange kneten, damit die Küchlein mürbe bleiben.\n\nVor dem Servieren vollständig durchziehen lassen.", "alternative": "", "geschichte": "Sheqerpare (von türkisch „şekerpare“, sinngemäß „Zuckerstück“) sind ein süßes Gebäck, das im Kosovo, in Albanien, der Türkei und weiten Teilen des früheren osmanischen Raums verbreitet ist. Es handelt sich um kleine, mürbe Küchlein aus einem Teig mit Grieß oder Mehl, Butter und Ei, die gebacken und anschließend, noch warm, in einem kalten Zuckersirup getränkt werden. Dadurch erhalten sie ihre charakteristische Saftigkeit und intensive Süße. Wie viele sirupgetränkte Süßspeisen der Region gehen Sheqerpare auf die osmanische Hofküche und deren Tradition der „şerbet“-getränkten Gebäcke zurück. Im Kosovo sind sie ein beliebtes Festtags- und Gästegebäck, das besonders zu religiösen Feiertagen, Hochzeiten und Familienanlässen gereicht wird. Oft wird jedes Küchlein mit einer Mandel oder Nuss verziert. Sie spiegeln die ausgeprägte Süßspeisenkultur Südosteuropas wider und sind als reines Teig- und Zuckergebäck selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Kosovo", "Sheqerpare", "Grießgebäck", "Sirup", "süß", "osmanisch geprägt", "Festtag", "Mandeln", "vegetarisch", "Gästegebäck", "Balkan", "Dessert"]}, {"id": "brudet", "status": "published", "date": "", "cover": "", "name": "Brudet", "land": "Kroatien", "kontinent": "Europa", "gang": "Suppe", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein dalmatinischer Fischeintopf aus verschiedenen Fischen und Meeresfrüchten in würziger Tomatensauce, klassisch mit Polenta serviert. Küstenküche der Adria.", "zutaten": ["1.2 kg gemischter Fisch (z. B. Drachenkopf, Meeräsche, Tintenfisch)", "2 Zwiebeln", "3 Zehen Knoblauch", "400 g passierte Tomaten", "100 ml Weißwein", "1 EL Rotweinessig", "5 EL Olivenöl", "1 Bund Petersilie", "Salz, Pfeffer; Polenta zum Servieren"], "zutatenS": [{"menge": 1.2, "einheit": "kg", "item": "gemischter Fisch (z. B. Drachenkopf, Meeräsche, Tintenfisch)", "roh": "1.2 kg gemischter Fisch (z. B. Drachenkopf, Meeräsche, Tintenfisch)"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "3 Zehen Knoblauch"}, {"menge": 400.0, "einheit": "g", "item": "passierte Tomaten", "roh": "400 g passierte Tomaten"}, {"menge": 100.0, "einheit": "ml", "item": "Weißwein", "roh": "100 ml Weißwein"}, {"menge": 1.0, "einheit": "EL", "item": "Rotweinessig", "roh": "1 EL Rotweinessig"}, {"menge": 5.0, "einheit": "EL", "item": "Olivenöl", "roh": "5 EL Olivenöl"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer; Polenta zum Servieren", "roh": "Salz, Pfeffer; Polenta zum Servieren"}], "zubereitung": ["Fisch küchenfertig vorbereiten und in große Stücke schneiden.", "Zwiebeln und Knoblauch in Olivenöl sanft andünsten.", "Tomaten, Wein und Essig zugeben und kurz einkochen.", "Die Fischstücke einlegen (festfleischige zuerst, zarte später) und mit Wasser knapp bedecken.", "Zugedeckt 25–30 Minuten sanft schmoren, dabei nicht umrühren, nur den Topf schwenken.", "Mit Petersilie bestreuen und mit frisch gekochter Polenta servieren."], "hinweise": "Nicht umrühren — nur schwenken, damit der Fisch ganz bleibt.\n\nEine Mischung verschiedener Fische gibt die beste Tiefe.\n\nPolenta nimmt die würzige Sauce ideal auf.", "alternative": "", "geschichte": "Brudet (auch Brodet oder Brodetto) ist ein Fischeintopf der kroatischen Adriaküste und Inseln und gehört zur gemeinsamen kulinarischen Tradition des nördlichen Mittelmeers, mit Verwandten an der italienischen Adriaküste. Sein Ursprung liegt in der Fischerküche: Brudet entstand als Art, den gemischten Fang — verschiedene Fische, oft auch weniger edle Sorten, sowie Tintenfisch oder Muscheln — gemeinsam in einem Topf zu einem sättigenden Gericht zu verarbeiten. Charakteristisch ist die würzige Sauce aus Tomaten, Zwiebeln, Knoblauch, Olivenöl und Essig oder Wein, in der die Fischstücke sanft schmoren. Eine ungeschriebene Regel besagt, den Topf während des Garens nicht umzurühren, sondern nur zu schwenken, damit der Fisch nicht zerfällt. Traditionell wird Brudet mit Polenta serviert, die die aromatische Sauce aufnimmt. Jede Familie und jeder Küstenort pflegt eigene Varianten. Als Fischgericht ist es selbstverständlich ohne Schweinefleisch und steht für die maritime Seite der dalmatinischen Küche.", "persoenlich": "", "servier": "", "tags": ["Kroatien", "Dalmatien", "Adria", "Brudet", "Fisch", "Meeresfrüchte", "Eintopf", "Tomaten", "Polenta", "Küstenküche", "mediterran", "Hauptgericht"]}, {"id": "pa-ticada", "status": "published", "date": "", "cover": "", "name": "Pašticada", "land": "Kroatien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Dalmatinischer Schmorbraten vom Rind, tagelang mariniert und in Wein mit Trockenpflaumen langsam geschmort, serviert mit hausgemachten Gnocchi. Festtagsgericht der Küste.", "zutaten": ["1.5 kg Rinderschmorbraten", "2 Zehen Knoblauch, in Stiften (zum Spicken)", "1 Möhre, in Stiften (zum Spicken)", "500 ml Rotwein", "100 ml Prošek oder süßer Likörwein", "8 Trockenpflaumen", "2 Zwiebeln, 2 EL Tomatenmark", "1 EL Rotweinessig", "Öl, Salz, Pfeffer, Lorbeer, Nelken; Gnocchi zum Servieren"], "zutatenS": [{"menge": 1.5, "einheit": "kg", "item": "Rinderschmorbraten", "roh": "1.5 kg Rinderschmorbraten"}, {"menge": 2.0, "einheit": "Zehen", "item": "Knoblauch, in Stiften (zum Spicken)", "roh": "2 Zehen Knoblauch, in Stiften (zum Spicken)"}, {"menge": 1.0, "einheit": "", "item": "Möhre, in Stiften (zum Spicken)", "roh": "1 Möhre, in Stiften (zum Spicken)"}, {"menge": 500.0, "einheit": "ml", "item": "Rotwein", "roh": "500 ml Rotwein"}, {"menge": 100.0, "einheit": "ml", "item": "Prošek oder süßer Likörwein", "roh": "100 ml Prošek oder süßer Likörwein"}, {"menge": 8.0, "einheit": "", "item": "Trockenpflaumen", "roh": "8 Trockenpflaumen"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, 2 EL Tomatenmark", "roh": "2 Zwiebeln, 2 EL Tomatenmark"}, {"menge": 1.0, "einheit": "EL", "item": "Rotweinessig", "roh": "1 EL Rotweinessig"}, {"menge": null, "einheit": "", "item": "Öl, Salz, Pfeffer, Lorbeer, Nelken; Gnocchi zum Servieren", "roh": "Öl, Salz, Pfeffer, Lorbeer, Nelken; Gnocchi zum Servieren"}], "zubereitung": ["Das Fleisch mit Knoblauch- und Möhrenstiften spicken, mit Essig und etwas Wein übergießen und über Nacht marinieren.", "Abtupfen, salzen und in Öl rundum kräftig anbraten.", "Zwiebeln und Tomatenmark anrösten, mit Rotwein und Prošek ablöschen.", "Fleisch zurückgeben, Trockenpflaumen, Lorbeer und Nelken zugeben.", "Zugedeckt 3–4 Stunden sehr sanft schmoren, bis das Fleisch zart ist.", "Sauce passieren oder pürieren, abschmecken; Fleisch in Scheiben mit Gnocchi servieren."], "hinweise": "Die lange Marinade und das sanfte Schmoren sind entscheidend.\n\nDie Trockenpflaumen geben die typische süßliche Tiefe.\n\nHausgemachte Gnocchi gehören klassisch dazu.", "alternative": "Klassische Pašticada wird oft mit Speck gespickt oder enthält Pancetta. Wir spicken stattdessen nur mit Knoblauch und Möhre und holen die Tiefe aus kräftigem Anbraten, Rotwein und Prošek. Wer eine rauchige Note möchte, gibt etwas geräuchertes Rind in die Sauce.", "geschichte": "Pašticada ist das festliche Schmorgericht Dalmatiens und gilt als eines der aufwendigsten und angesehensten Gerichte der kroatischen Küche. Es wird zu Hochzeiten, Feiertagen und besonderen Anlässen zubereitet und verlangt mehrere Tage Vorbereitung. Ein Stück Rindfleisch wird zunächst mit Knoblauch und Möhre gespickt, in Essig oder Wein mariniert und dann sehr langsam in einer komplexen Sauce aus Rotwein, dem dalmatinischen Likörwein Prošek, Trockenpflaumen, Tomate und Aromaten geschmort, bis es zart zerfällt. Die Kombination aus Säure, Süße der Pflaumen und Tiefe des Weins ergibt das charakteristische süßlich-würzige Aroma. Serviert wird Pašticada klassisch mit hausgemachten Gnocchi (njoki), die die Sauce aufnehmen. Das Gericht spiegelt venezianische und mediterrane Einflüsse der dalmatinischen Küstengeschichte wider. In der klassischen Fassung wird das Fleisch oft mit Speck gespickt; in unserer Variante verzichten wir darauf, ohne an Tiefe zu verlieren.", "persoenlich": "", "servier": "", "tags": ["Kroatien", "Dalmatien", "Pašticada", "Rind", "Schmorbraten", "Rotwein", "Trockenpflaumen", "Gnocchi", "Festtag", "venezianisch geprägt", "süßlich-würzig", "Hauptgericht"]}, {"id": "fritule", "status": "published", "date": "", "cover": "", "name": "Fritule", "land": "Kroatien", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine, frittierte Hefeteigbällchen mit Rosinen und Zitrusaroma, bestäubt mit Puderzucker. Festtagsgebäck der kroatischen Küste, besonders zur Weihnachtszeit.", "zutaten": ["300 g Mehl", "200 ml lauwarme Milch", "15 g frische Hefe", "2 EL Zucker", "1 Ei", "60 g Rosinen", "1 Bio-Zitrone und Orange (Schale)", "1 EL Rum (optional)", "Öl zum Frittieren, Puderzucker"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "Mehl", "roh": "300 g Mehl"}, {"menge": 200.0, "einheit": "ml", "item": "lauwarme Milch", "roh": "200 ml lauwarme Milch"}, {"menge": 15.0, "einheit": "g", "item": "frische Hefe", "roh": "15 g frische Hefe"}, {"menge": 2.0, "einheit": "EL", "item": "Zucker", "roh": "2 EL Zucker"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 60.0, "einheit": "g", "item": "Rosinen", "roh": "60 g Rosinen"}, {"menge": 1.0, "einheit": "", "item": "Bio-Zitrone und Orange (Schale)", "roh": "1 Bio-Zitrone und Orange (Schale)"}, {"menge": 1.0, "einheit": "EL", "item": "Rum (optional)", "roh": "1 EL Rum (optional)"}, {"menge": null, "einheit": "", "item": "Öl zum Frittieren, Puderzucker", "roh": "Öl zum Frittieren, Puderzucker"}], "zubereitung": ["Hefe in lauwarmer Milch mit etwas Zucker auflösen.", "Mehl, Zucker, Ei, Zitrus- und Orangenschale, Rum und die Hefemilch zu einem zähen Teig verrühren; Rosinen unterheben.", "Zugedeckt etwa 1 Stunde gehen lassen, bis der Teig Blasen wirft.", "Öl in einem Topf erhitzen (etwa 170 °C).", "Mit zwei Löffeln kleine Teigportionen abstechen und goldbraun ausbacken.", "Auf Küchenpapier abtropfen lassen und warm mit Puderzucker bestäubt servieren."], "hinweise": "Das Öl nicht zu heiß führen, sonst bleiben die Fritule innen roh.\n\nMit zwei Löffeln gelingen gleichmäßige Kugeln.\n\nFrisch und warm schmecken sie am besten.", "alternative": "", "geschichte": "Fritule sind kleine, frittierte Teigbällchen, die in Kroatien — vor allem an der Adriaküste, in Dalmatien und Istrien — traditionell zur Weihnachts- und Festtagszeit gebacken werden. Sie gehören zur weit verbreiteten mediterranen Familie der frittierten Süßgebäcke und sind mit ähnlichen Spezialitäten in Italien und im weiteren Mittelmeerraum verwandt. Der Hefeteig wird häufig mit Rosinen, abgeriebener Zitrusschale und manchmal einem Schuss Rum oder Weinbrand aromatisiert, zu kleinen Kugeln in heißem Öl ausgebacken und warm mit Puderzucker bestäubt. Ihre kleine, runde Form und die unkomplizierte Zubereitung machten sie zu einem geselligen Gebäck, das in großen Mengen für Feste und Familienzusammenkünfte hergestellt wird. Fritule sind in der Adventszeit auf Weihnachtsmärkten und in Haushalten allgegenwärtig, werden aber auch zu anderen Festen gebacken. Als süßes Hefegebäck sind sie selbstverständlich ohne Schweinefleisch und stehen für die festliche, gastfreundliche Seite der kroatischen Küstenküche.", "persoenlich": "", "servier": "", "tags": ["Kroatien", "Dalmatien", "Istrien", "Fritule", "Hefeteig", "frittiert", "Rosinen", "Weihnachten", "süß", "vegetarisch", "Festtag", "Dessert"]}, {"id": "aukst-zupa", "status": "published", "date": "", "cover": "", "name": "Aukstā zupa", "land": "Lettland", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine kalte, leuchtend pinke Sommersuppe aus Kefir und Roter Bete mit Gurke, Ei und Dill. Erfrischung für heiße Tage im Baltikum.", "zutaten": ["1 l Kefir", "3 Rote Bete, gekocht und geraspelt", "1 Salatgurke", "3 hartgekochte Eier", "3 Frühlingszwiebeln", "1 Bund Dill", "4 Kartoffeln (warm, zum Servieren)", "Salz"], "zutatenS": [{"menge": 1.0, "einheit": "l", "item": "Kefir", "roh": "1 l Kefir"}, {"menge": 3.0, "einheit": "", "item": "Rote Bete, gekocht und geraspelt", "roh": "3 Rote Bete, gekocht und geraspelt"}, {"menge": 1.0, "einheit": "", "item": "Salatgurke", "roh": "1 Salatgurke"}, {"menge": 3.0, "einheit": "", "item": "hartgekochte Eier", "roh": "3 hartgekochte Eier"}, {"menge": 3.0, "einheit": "", "item": "Frühlingszwiebeln", "roh": "3 Frühlingszwiebeln"}, {"menge": 1.0, "einheit": "Bund", "item": "Dill", "roh": "1 Bund Dill"}, {"menge": 4.0, "einheit": "", "item": "Kartoffeln (warm, zum Servieren)", "roh": "4 Kartoffeln (warm, zum Servieren)"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Gurke fein würfeln oder raspeln, Frühlingszwiebeln und Dill hacken.", "Zwei Eier würfeln, eines für die Garnitur zurückbehalten.", "Kefir mit der geraspelten Roten Bete verrühren, bis die Suppe leuchtend rosa ist.", "Gurke, Eier, Frühlingszwiebeln und Dill unterrühren, salzen.", "Mindestens 1 Stunde kühl stellen.", "Eiskalt mit warmen Salzkartoffeln und dem restlichen Ei servieren."], "hinweise": "Sehr kalt servieren — der Kontrast zu den warmen Kartoffeln ist typisch.\n\nReichlich frischer Dill ist entscheidend.\n\nDie Konsistenz mit etwas Wasser oder Buttermilch regeln.", "alternative": "", "geschichte": "Aukstā zupa — die „kalte Suppe“ — ist Lettlands Version der im gesamten Baltikum und Osteuropa verbreiteten kalten Rote-Bete-Kefir-Suppe und ein Inbegriff des lettischen Sommers. Sie gehört zur Familie der kalten Sauermilchsuppen, die sich über die historischen Verbindungen der Region mit dem litauischen, polnischen und russischen Raum verbreiteten. Grundlage ist Kefir oder dicke Sauermilch, die mit gekochter, geraspelter Roter Bete leuchtend rosa gefärbt wird; dazu kommen frische Gurke, hartgekochtes Ei, Frühlingszwiebeln und reichlich Dill. Die Suppe wird eiskalt serviert, oft begleitet von warmen, in der Schale gekochten Kartoffeln, was den Reiz des Temperaturkontrasts ausmacht. Aukstā zupa entstand als erfrischendes, leichtes Sommergericht, das ohne langes Kochen auskommt und die sommerliche Fülle an Gurken, Bete und Kräutern nutzt. Sie ist von Natur aus vegetarisch und ohne Schweinefleisch und gehört zu den beliebtesten saisonalen Gerichten Lettlands.", "persoenlich": "", "servier": "", "tags": ["Lettland", "Baltikum", "Aukstā zupa", "kalte Suppe", "Rote Bete", "Kefir", "Gurke", "Dill", "vegetarisch", "Sommerküche", "erfrischend", "Suppe"]}, {"id": "sklandrausis", "status": "published", "date": "", "cover": "", "name": "Sklandrausis", "land": "Lettland", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine süße Roggenteig-Tarte mit einer Doppelfüllung aus Kartoffel- und Möhrenpüree, gewürzt mit Kümmel und Zimt. Spezialität aus der Region Kurzeme mit geschütztem Status.", "zutaten": ["250 g Roggenmehl", "60 g Butter (Teig)", "100 ml Wasser", "400 g Kartoffeln", "400 g Möhren", "1 Ei", "3 EL Zucker oder Honig", "1 TL Kümmel, 0,5 TL Zimt", "100 ml Sahne"], "zutatenS": [{"menge": 250.0, "einheit": "g", "item": "Roggenmehl", "roh": "250 g Roggenmehl"}, {"menge": 60.0, "einheit": "g", "item": "Butter (Teig)", "roh": "60 g Butter (Teig)"}, {"menge": 100.0, "einheit": "ml", "item": "Wasser", "roh": "100 ml Wasser"}, {"menge": 400.0, "einheit": "g", "item": "Kartoffeln", "roh": "400 g Kartoffeln"}, {"menge": 400.0, "einheit": "g", "item": "Möhren", "roh": "400 g Möhren"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 3.0, "einheit": "EL", "item": "Zucker oder Honig", "roh": "3 EL Zucker oder Honig"}, {"menge": 1.0, "einheit": "TL", "item": "Kümmel, 0,5 TL Zimt", "roh": "1 TL Kümmel, 0,5 TL Zimt"}, {"menge": 100.0, "einheit": "ml", "item": "Sahne", "roh": "100 ml Sahne"}], "zubereitung": ["Roggenmehl mit Butter, etwas Salz und Wasser zu einem festen Teig verkneten.", "Kleine Teigkreise ausrollen und zu randhohen Körbchen formen.", "Kartoffeln weich kochen, mit etwas Kümmel zu Püree stampfen.", "Möhren weich kochen, mit Zucker, Zimt, Ei und Sahne zu einem süßen Püree verarbeiten.", "In die Körbchen zuerst Kartoffel-, dann Möhrenpüree füllen.", "Bei 200 °C 20–25 Minuten backen, bis der Rand fest ist; kalt servieren."], "hinweise": "Der Roggenteig ist fester als Weizenteig — zügig formen.\n\nDie Möhrenfüllung kräftig süßen und würzen, sie gibt den Charakter.\n\nSklandrausis schmeckt kalt am besten und hält mehrere Tage.", "alternative": "", "geschichte": "Sklandrausis (auch sklandu rausis) ist eine traditionelle süße Tarte aus der westlettischen Region Kurzeme (Kurland) und gilt als eines der ältesten überlieferten Gebäcke Lettlands mit livischen Wurzeln. Es genießt als „Sklandrausis“ einen geschützten Status als garantiert traditionelle Spezialität in der EU. Charakteristisch ist der Boden aus Roggenteig, der zu einem kleinen, randhohen Körbchen geformt und mit zwei Schichten gefüllt wird: zuerst einem Kartoffelpüree, darüber einem süßen Möhrenpüree, gewürzt unter anderem mit Kümmel und Zimt. Roggen, Kartoffel und Möhre spiegeln die Grundzutaten der lettischen Bauernküche wider. Das Gebäck wurde traditionell zu Festen, Beerdigungen und Feiertagen hergestellt und ist ungewöhnlich, weil es ein herzhaft anmutendes Wurzelgemüse in ein süßes Gebäck verwandelt. Sklandrausis wird kalt gegessen und hält sich gut. Es ist von Natur aus vegetarisch und ohne Schweinefleisch und gilt als kulinarisches Erbe der Region.", "persoenlich": "", "servier": "", "tags": ["Lettland", "Kurzeme", "Sklandrausis", "Roggen", "Möhre", "Kartoffel", "Tarte", "geschützte Spezialität", "vegetarisch", "kulinarisches Erbe", "süß", "Dessert"]}, {"id": "rupjmaizes-k-rtojums", "status": "published", "date": "", "cover": "", "name": "Rupjmaizes kārtojums", "land": "Lettland", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein geschichtetes Dessert aus zerbröseltem süßem Roggenbrot, Preiselbeer- oder Cranberrymarmelade und Schlagsahne. Die süße Verwandlung des lettischen Roggenbrots.", "zutaten": ["300 g süßes Roggenbrot", "3 EL Zucker", "1 TL Zimt", "200 g Preiselbeer- oder Cranberrymarmelade", "400 ml Schlagsahne", "1 TL Vanillezucker", "50 g frische Cranberries oder Preiselbeeren (optional)"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "süßes Roggenbrot", "roh": "300 g süßes Roggenbrot"}, {"menge": 3.0, "einheit": "EL", "item": "Zucker", "roh": "3 EL Zucker"}, {"menge": 1.0, "einheit": "TL", "item": "Zimt", "roh": "1 TL Zimt"}, {"menge": 200.0, "einheit": "g", "item": "Preiselbeer- oder Cranberrymarmelade", "roh": "200 g Preiselbeer- oder Cranberrymarmelade"}, {"menge": 400.0, "einheit": "ml", "item": "Schlagsahne", "roh": "400 ml Schlagsahne"}, {"menge": 1.0, "einheit": "TL", "item": "Vanillezucker", "roh": "1 TL Vanillezucker"}, {"menge": 50.0, "einheit": "g", "item": "frische Cranberries oder Preiselbeeren (optional)", "roh": "50 g frische Cranberries oder Preiselbeeren (optional)"}], "zubereitung": ["Roggenbrot fein zerbröseln.", "Brösel mit Zucker und Zimt in einer Pfanne ohne Fett leicht anrösten, bis sie duften; auskühlen lassen.", "Sahne mit Vanillezucker steif schlagen.", "In Gläsern abwechselnd Brösel, Marmelade und Sahne schichten.", "Mit einer Sahneschicht abschließen.", "Mehrere Stunden kühl stellen und mit frischen Beeren garniert servieren."], "hinweise": "Echtes süßes Roggenbrot gibt den authentischen Geschmack.\n\nDie Brösel vor dem Schichten gut auskühlen lassen.\n\nDas Dessert vor dem Servieren durchziehen lassen.", "alternative": "", "geschichte": "Rupjmaizes kārtojums — wörtlich „Roggenbrot-Schichtung“ — ist ein klassisches lettisches Dessert, das die zentrale Rolle des dunklen Roggenbrots in der lettischen Esskultur auf süße Weise feiert. Roggenbrot (rupjmaize) ist in Lettland weit mehr als eine Beilage; es ist ein Identitätssymbol und Grundnahrungsmittel mit langer Tradition. Für das Dessert wird süßes Roggenbrot getrocknet, zerbröselt und oft mit Zucker, Zimt und etwas Preiselbeeren oder Cranberries angeröstet, dann schichtweise mit Fruchtmarmelade und steif geschlagener Sahne in Gläsern oder einer Schale angerichtet. Das Ergebnis verbindet die herzhafte, leicht säuerliche Tiefe des Roggenbrots mit der Süße der Sahne und der Frische der Beeren. Das Dessert ist eine clevere Art, übrig gebliebenes Brot zu verwerten, und gehört zu festlichen Anlässen und Sonntagen. Es ist von Natur aus vegetarisch und ohne Schweinefleisch und gilt als typisch lettische Süßspeise.", "persoenlich": "", "servier": "", "tags": ["Lettland", "Baltikum", "Roggenbrot", "Dessert", "Preiselbeeren", "Cranberry", "Sahne", "Schichtdessert", "vegetarisch", "Resteküche", "süß", "Sonntagsessen"]}, {"id": "kaesknoepfle", "status": "published", "date": "", "cover": "", "name": "Käsknöpfle", "land": "Liechtenstein", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine Teigknöpfle, geschichtet mit kräftigem Bergkäse und gekrönt von Röstzwiebeln, oft mit Apfelmus gereicht. Das Nationalgericht Liechtensteins.", "zutaten": ["400 g Mehl", "4 Eier", "150 ml Wasser oder Milch", "250 g würziger Bergkäse, gerieben", "3 Zwiebeln, in Ringen", "50 g Butter", "Salz, Pfeffer, Muskat", "Apfelmus zum Servieren"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Mehl", "roh": "400 g Mehl"}, {"menge": 4.0, "einheit": "", "item": "Eier", "roh": "4 Eier"}, {"menge": 150.0, "einheit": "ml", "item": "Wasser oder Milch", "roh": "150 ml Wasser oder Milch"}, {"menge": 250.0, "einheit": "g", "item": "würziger Bergkäse, gerieben", "roh": "250 g würziger Bergkäse, gerieben"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln, in Ringen", "roh": "3 Zwiebeln, in Ringen"}, {"menge": 50.0, "einheit": "g", "item": "Butter", "roh": "50 g Butter"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, Muskat", "roh": "Salz, Pfeffer, Muskat"}, {"menge": null, "einheit": "", "item": "Apfelmus zum Servieren", "roh": "Apfelmus zum Servieren"}], "zubereitung": ["Mehl, Eier, Wasser, Salz und Muskat zu einem zähen Teig schlagen, bis er Blasen wirft.", "Teig durch ein Knöpflesieb in siedendes Salzwasser drücken.", "Aufgeschwommene Knöpfle abschöpfen und abtropfen lassen.", "Zwiebelringe in Butter langsam goldbraun rösten.", "Knöpfle und geriebenen Käse abwechselnd schichten, bis der Käse schmilzt.", "Mit Röstzwiebeln bestreut und Apfelmus servieren."], "hinweise": "Der Teig muss zäh sein und Blasen werfen.\n\nEine Mischung kräftiger Bergkäse gibt am meisten Geschmack.\n\nApfelmus gehört in Liechtenstein klassisch dazu.", "alternative": "", "geschichte": "Käsknöpfle gelten als das Nationalgericht Liechtensteins und sind eng mit der alpenländischen Küche des Alpenrheintals verwandt, die das Fürstentum mit der Schweiz und Vorarlberg teilt. Knöpfle sind kleine, rundliche Teignocken aus einem Eierteig, verwandt mit den Spätzle, jedoch kürzer und gedrungener. In Liechtenstein werden sie mit reichlich würzigem Bergkäse geschichtet und mit goldbraun gerösteten Zwiebeln serviert. Das Gericht entstand aus der bäuerlichen und alpinen Vorratsküche: Mehl, Eier und Käse waren auch in den Bergen verfügbar und ergaben ein sättigendes, wärmendes Essen. Traditionell werden Käsknöpfle mit Apfelmus serviert, dessen Süße und Säure einen Kontrast zum herzhaften Käse bildet. Das Gericht hat einen hohen Stellenwert in der lokalen Identität und wird zu Festen wie im Alltag gegessen. Es ist von Natur aus vegetarisch und ohne Schweinefleisch und steht sinnbildlich für die deftige Bergküche Liechtensteins.", "persoenlich": "", "servier": "", "tags": ["Liechtenstein", "Käsknöpfle", "Knöpfle", "Bergkäse", "vegetarisch", "Alpenküche", "Röstzwiebeln", "Apfelmus", "Nationalgericht", "deftig", "Alpenrheintal", "Hauptgericht"]}, {"id": "ribel", "status": "published", "date": "", "cover": "", "name": "Ribel", "land": "Liechtenstein", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein in der Pfanne goldbraun geröstetes Gericht aus Mais- und Weizengrieß, in krümelige Stücke zerteilt und süß mit Apfelmus oder Milchkaffee gegessen. Alpenrheintaler Tradition.", "zutaten": ["250 g Maisgrieß (Ribelmais oder Polenta, mittel)", "100 g Weizengrieß", "500 ml Milch", "1 Prise Salz", "60 g Butter", "Apfelmus oder Kompott zum Servieren"], "zutatenS": [{"menge": 250.0, "einheit": "g", "item": "Maisgrieß (Ribelmais oder Polenta, mittel)", "roh": "250 g Maisgrieß (Ribelmais oder Polenta, mittel)"}, {"menge": 100.0, "einheit": "g", "item": "Weizengrieß", "roh": "100 g Weizengrieß"}, {"menge": 500.0, "einheit": "ml", "item": "Milch", "roh": "500 ml Milch"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}, {"menge": 60.0, "einheit": "g", "item": "Butter", "roh": "60 g Butter"}, {"menge": null, "einheit": "", "item": "Apfelmus oder Kompott zum Servieren", "roh": "Apfelmus oder Kompott zum Servieren"}], "zubereitung": ["Mais- und Weizengrieß mit der gesalzenen Milch verrühren und 1–2 Stunden quellen lassen.", "Butter in einer großen Pfanne erhitzen.", "Die Grießmasse hineingeben und bei mittlerer Hitze rösten.", "Mit zwei Gabeln oder dem Pfannenwender die Masse in unregelmäßige Krümel zerteilen.", "Weiterrösten, bis die Ribel goldbraun und leicht knusprig sind.", "Warm mit Apfelmus oder Kompott servieren."], "hinweise": "Das Quellen vorab macht die Ribel locker.\n\nGeduldig rösten — die goldbraunen Krümel sind das Ziel.\n\nKlassisch süß, schmeckt aber auch herzhaft.", "alternative": "", "geschichte": "Ribel (auch Riebel oder Türkenribel) ist eine traditionelle Mehlspeise des Alpenrheintals, die Liechtenstein mit dem benachbarten Vorarlberg und dem St. Galler Rheintal teilt; als „Rheintaler Ribel“ genießt das Gericht in der Region einen geschützten Herkunftsstatus. Grundlage ist Grieß aus Mais (im Dialekt „Türken“) und Weizen, der in Milch oder Wasser eingeweicht, dann in der Pfanne in Butter oder Fett geröstet und mit der Gabel in unregelmäßige Krümel zerteilt wird. Der Mais kam ab dem 18. Jahrhundert ins Rheintal und wurde zum prägenden Getreide der Region, weshalb Ribel über Generationen ein Grundnahrungsmittel der ländlichen Bevölkerung war — sättigend, günstig und aus eigenem Anbau. Gegessen wird Ribel traditionell süß, etwa mit Apfelmus, Kompott, Milch oder Milchkaffee, sowohl zum Frühstück als auch als einfache Hauptmahlzeit. Es ist von Natur aus vegetarisch und ohne Schweinefleisch und steht für die bodenständige Maisküche des Alpenrheintals.", "persoenlich": "", "servier": "", "tags": ["Liechtenstein", "Ribel", "Mais", "Grieß", "Alpenrheintal", "Vorarlberg", "vegetarisch", "Apfelmus", "geschützte Herkunft", "Frühstück", "Maisküche", "Dessert"]}, {"id": "hafalaab", "status": "published", "date": "", "cover": "", "name": "Hafalaab", "land": "Liechtenstein", "kontinent": "Europa", "gang": "Suppe", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine Klöße aus Maisgrieß und Mehl, in kräftiger Rinderbrühe gegart. Ein deftiges traditionelles Gericht Liechtensteins.", "zutaten": ["200 g Maisgrieß", "150 g Weizenmehl", "2 Eier", "150 ml Wasser", "1.5 l kräftige Rinderbrühe", "100 g geräuchertes Rind, gewürfelt", "2 Zwiebeln", "Salz, Pfeffer, Schnittlauch"], "zutatenS": [{"menge": 200.0, "einheit": "g", "item": "Maisgrieß", "roh": "200 g Maisgrieß"}, {"menge": 150.0, "einheit": "g", "item": "Weizenmehl", "roh": "150 g Weizenmehl"}, {"menge": 2.0, "einheit": "", "item": "Eier", "roh": "2 Eier"}, {"menge": 150.0, "einheit": "ml", "item": "Wasser", "roh": "150 ml Wasser"}, {"menge": 1.5, "einheit": "l", "item": "kräftige Rinderbrühe", "roh": "1.5 l kräftige Rinderbrühe"}, {"menge": 100.0, "einheit": "g", "item": "geräuchertes Rind, gewürfelt", "roh": "100 g geräuchertes Rind, gewürfelt"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, Schnittlauch", "roh": "Salz, Pfeffer, Schnittlauch"}], "zubereitung": ["Maisgrieß, Mehl, Eier, Wasser und Salz zu einem festen Teig verkneten.", "Aus dem Teig kleine, längliche Klöße formen.", "Die Brühe zum Sieden bringen.", "Klöße einlegen und etwa 15 Minuten gar ziehen lassen.", "Zwiebeln und geräuchertes Rind in etwas Fett anbraten.", "Hafalaab in der Brühe oder mit den Röstzwiebeln und Rind angerichtet servieren, mit Schnittlauch bestreuen."], "hinweise": "Den Teig fest genug halten, damit die Klöße nicht zerfallen.\n\nEine kräftige, gut gewürzte Brühe ist die Basis.\n\nÜbrige Hafalaab lassen sich am nächsten Tag knusprig braten.", "alternative": "Hafalaab wird traditionell mit Speck und in einer Schweinebrühe zubereitet. Wir verwenden stattdessen eine kräftige Rinderbrühe und angebratenes geräuchertes Rind mit Röstzwiebeln — das liefert die herzhaft-rauchige Tiefe, ganz ohne Schwein.", "geschichte": "Hafalaab ist ein traditionelles Klößchengericht Liechtensteins und der angrenzenden Alpenregion und gilt neben den Käsknöpfle als eine der typischen lokalen Spezialitäten. Der Name bezeichnet kleine, längliche Klöße aus einem Teig, der traditionell Maisgrieß (im Dialekt „Türkenmehl“) und Weizenmehl verbindet — ein weiteres Beispiel für die prägende Rolle des Maises im Alpenrheintal. Die geformten Klöße werden in einer Brühe gegart und in dieser serviert oder herausgenommen und gebraten. Wie viele Gerichte der alpinen Vorratsküche entstand Hafalaab aus einfachen, lagerfähigen Grundzutaten und lieferte eine sättigende Mahlzeit. Traditionell wird das Gericht mit Speck und in einer fleischigen Brühe zubereitet; in unserer Fassung verwenden wir eine kräftige Rinderbrühe und geräuchertes Rind, um es ohne Schwein zuzubereiten. Hafalaab wird als wärmendes, herzhaftes Essen geschätzt und gehört zum kulinarischen Erbe des Fürstentums.", "persoenlich": "", "servier": "", "tags": ["Liechtenstein", "Hafalaab", "Mais", "Klöße", "Rinderbrühe", "Alpenrheintal", "deftig", "kulinarisches Erbe", "Winterküche", "geräuchertes Rind", "Maisküche", "Hauptgericht"]}, {"id": "cepelinai", "status": "published", "date": "", "cover": "", "name": "Cepelinai", "land": "Litauen", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Große, zeppelinförmige Klöße aus rohen und gekochten Kartoffeln, gefüllt mit gewürztem Rinderhack, serviert mit Sauce und Röstzwiebeln. Litauens Nationalgericht.", "zutaten": ["1.5 kg mehligkochende Kartoffeln (roh)", "400 g Kartoffeln (gekocht)", "400 g Rinderhack", "2 Zwiebeln", "2 EL Kartoffelstärke", "200 ml saure Sahne (Sauce)", "Butter, Salz, Pfeffer, Majoran"], "zutatenS": [{"menge": 1.5, "einheit": "kg", "item": "mehligkochende Kartoffeln (roh)", "roh": "1.5 kg mehligkochende Kartoffeln (roh)"}, {"menge": 400.0, "einheit": "g", "item": "Kartoffeln (gekocht)", "roh": "400 g Kartoffeln (gekocht)"}, {"menge": 400.0, "einheit": "g", "item": "Rinderhack", "roh": "400 g Rinderhack"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 2.0, "einheit": "EL", "item": "Kartoffelstärke", "roh": "2 EL Kartoffelstärke"}, {"menge": 200.0, "einheit": "ml", "item": "saure Sahne (Sauce)", "roh": "200 ml saure Sahne (Sauce)"}, {"menge": null, "einheit": "", "item": "Butter, Salz, Pfeffer, Majoran", "roh": "Butter, Salz, Pfeffer, Majoran"}], "zubereitung": ["Rohe Kartoffeln fein reiben und die Flüssigkeit kräftig ausdrücken, die abgesetzte Stärke zurückgeben.", "Mit den zerstampften gekochten Kartoffeln und etwas Stärke zu einer formbaren Masse verkneten, salzen.", "Zwiebeln dünsten, mit dem Hack, Salz, Pfeffer und Majoran zu einer Füllung anbraten; abkühlen lassen.", "Aus der Kartoffelmasse Fladen formen, Füllung daraufgeben und zu Klößen verschließen.", "In siedendem Salzwasser etwa 25–30 Minuten sanft gar ziehen lassen (nicht sprudelnd kochen).", "Mit Röstzwiebeln und saurer Sahne servieren."], "hinweise": "Die geriebenen Kartoffeln gut ausdrücken, sonst zerfallen die Klöße.\n\nDas Wasser darf nur sieden, nicht sprudeln.\n\nReichlich Röstzwiebeln gehören dazu.", "alternative": "Cepelinai werden klassisch mit Schweinehack gefüllt und teils mit Grieben serviert. Wir füllen sie stattdessen mit gewürztem Rinderhack; eine ebenso traditionelle vegetarische Variante nutzt Quark (varškė) oder Pilze. Statt Schweinegrieben sorgen reichlich Röstzwiebeln in Butter für die herzhafte Note.", "geschichte": "Cepelinai gelten als das Nationalgericht Litauens und verdanken ihren Namen ihrer länglichen Form, die an Zeppeline erinnert — die Bezeichnung kam im 20. Jahrhundert auf. Es handelt sich um große Klöße aus einer Mischung roher, geriebener und gekochter, zerstampfter Kartoffeln, die zu einer formbaren Masse verbunden und um eine Füllung gewickelt werden. Die Kartoffel wurde im 18. und 19. Jahrhundert zum Grundnahrungsmittel Litauens, und Cepelinai sind ein Paradebeispiel der daraus entstandenen reichhaltigen Kartoffelküche. Die Klöße werden behutsam in Salzwasser gegart, bis sie eine glatte, leicht gummiartige Hülle bekommen, und mit einer Sauce sowie reichlich Röstzwiebeln serviert. Traditionell ist die Füllung aus Hackfleisch; in unserer Fassung verwenden wir Rind statt des sonst üblichen Schweinefleischs. Auch vegetarische Varianten mit Quark (varškė) oder Pilzen sind verbreitet. Cepelinai sind ein deftiges, sättigendes Sonntags- und Festtagsgericht und ein Stolz der litauischen Küche.", "persoenlich": "", "servier": "", "tags": ["Litauen", "Cepelinai", "Kartoffelklöße", "Rind", "Kartoffeln", "Nationalgericht", "Röstzwiebeln", "saure Sahne", "deftig", "Sonntagsessen", "Baltikum", "Hauptgericht"]}, {"id": "altibar-iai", "status": "published", "date": "", "cover": "", "name": "Šaltibarščiai", "land": "Litauen", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine leuchtend pinke kalte Suppe aus Kefir und Roter Bete mit Gurke, Ei und Dill, serviert mit warmen Kartoffeln. Litauens Sommerklassiker.", "zutaten": ["1 l Kefir", "3 Rote Bete, gekocht und geraspelt", "1 Salatgurke", "3 hartgekochte Eier", "1 Bund Dill", "3 Frühlingszwiebeln", "5 Kartoffeln (warm, zum Servieren)", "Salz"], "zutatenS": [{"menge": 1.0, "einheit": "l", "item": "Kefir", "roh": "1 l Kefir"}, {"menge": 3.0, "einheit": "", "item": "Rote Bete, gekocht und geraspelt", "roh": "3 Rote Bete, gekocht und geraspelt"}, {"menge": 1.0, "einheit": "", "item": "Salatgurke", "roh": "1 Salatgurke"}, {"menge": 3.0, "einheit": "", "item": "hartgekochte Eier", "roh": "3 hartgekochte Eier"}, {"menge": 1.0, "einheit": "Bund", "item": "Dill", "roh": "1 Bund Dill"}, {"menge": 3.0, "einheit": "", "item": "Frühlingszwiebeln", "roh": "3 Frühlingszwiebeln"}, {"menge": 5.0, "einheit": "", "item": "Kartoffeln (warm, zum Servieren)", "roh": "5 Kartoffeln (warm, zum Servieren)"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Gurke fein würfeln, Frühlingszwiebeln und Dill hacken.", "Zwei Eier würfeln, eines zur Garnitur zurückbehalten.", "Kefir mit der geraspelten Roten Bete verrühren, bis die Suppe leuchtend rosa ist.", "Gurke, Eier, Zwiebeln und Dill unterrühren und salzen.", "Mindestens 1 Stunde gut durchkühlen.", "Eiskalt mit warmen Salz- oder Bratkartoffeln und dem restlichen Ei servieren."], "hinweise": "Möglichst kalt servieren — der Temperaturkontrast macht das Gericht aus.\n\nReichlich Dill ist Pflicht.\n\nMit Buttermilch wird die Suppe etwas milder.", "alternative": "", "geschichte": "Šaltibarščiai — die „kalte Bete“ — ist die wohl bekannteste Sommerspeise Litauens und durch ihre intensiv rosa Farbe ein regelrechtes Wahrzeichen der litauischen Küche. Sie gehört zur Familie der kalten Rote-Bete-Sauermilchsuppen, die im gesamten Baltikum, in Polen und in der Region verbreitet sind. Grundlage ist Kefir oder Buttermilch, die mit gekochter, geraspelter Roter Bete ihre charakteristische leuchtend pinke Farbe erhält. Hinzu kommen frische Gurke, hartgekochtes Ei, Frühlingszwiebeln und reichlich Dill. Serviert wird die eiskalte Suppe traditionell mit einer Beilage warmer, in der Schale gekochter oder gebratener Kartoffeln — der Kontrast von kalt und warm ist ein wesentlicher Teil des Genusses. Šaltibarščiai entstand als erfrischendes, schnell zubereitetes Sommergericht, das die saisonale Fülle an Bete, Gurke und Kräutern nutzt. Sie ist von Natur aus vegetarisch und ohne Schweinefleisch und gehört in den heißen Monaten auf nahezu jeden litauischen Tisch.", "persoenlich": "", "servier": "", "tags": ["Litauen", "Šaltibarščiai", "kalte Suppe", "Rote Bete", "Kefir", "Gurke", "Dill", "vegetarisch", "Sommerküche", "Baltikum", "erfrischend", "Suppe"]}, {"id": "akotis", "status": "published", "date": "", "cover": "", "name": "Šakotis", "land": "Litauen", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein hoher, baumkuchenartiger Spießkuchen mit charakteristischen Zacken, Schicht für Schicht über offener Flamme oder im Ofen gebacken. Litauisches Festtags- und Hochzeitsgebäck.", "zutaten": ["10 Eier (getrennt)", "250 g Butter, weich", "250 g Zucker", "250 g Mehl", "50 g Speisestärke", "100 ml saure Sahne", "1 Prise Salz, etwas Vanille"], "zutatenS": [{"menge": 10.0, "einheit": "", "item": "Eier (getrennt)", "roh": "10 Eier (getrennt)"}, {"menge": 250.0, "einheit": "g", "item": "Butter, weich", "roh": "250 g Butter, weich"}, {"menge": 250.0, "einheit": "g", "item": "Zucker", "roh": "250 g Zucker"}, {"menge": 250.0, "einheit": "g", "item": "Mehl", "roh": "250 g Mehl"}, {"menge": 50.0, "einheit": "g", "item": "Speisestärke", "roh": "50 g Speisestärke"}, {"menge": 100.0, "einheit": "ml", "item": "saure Sahne", "roh": "100 ml saure Sahne"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz, etwas Vanille", "roh": "1 Prise Salz, etwas Vanille"}], "zubereitung": ["Butter mit der Hälfte des Zuckers und den Eigelben schaumig schlagen, saure Sahne und Vanille einrühren.", "Mehl und Stärke unterheben, bis ein glatter, fließfähiger Teig entsteht.", "Eiweiß mit dem restlichen Zucker steif schlagen und vorsichtig unterheben.", "Auf einem über der Hitze rotierenden Spieß den Teig in dünnen Schichten auftragen und jede Schicht goldbraun backen lassen, bevor die nächste folgt.", "Alternativ im Ofen mit Grillfunktion Schicht für Schicht auf einem Spieß oder in einer hohen Form backen.", "Vollständig auskühlen lassen und in Stücke schneiden."], "hinweise": "Jede Teigschicht vor der nächsten goldbraun backen lassen — das gibt die typischen Zacken.\n\nDer Teig muss dünnflüssig genug sein, um zu tropfen.\n\nGeduld ist der wichtigste Bestandteil dieses Kuchens.", "alternative": "", "geschichte": "Šakotis — der „verzweigte“ Kuchen, im Deutschen als Baumkuchen bekannt — ist ein traditionelles Festtagsgebäck Litauens und Polens und gehört zu den eindrucksvollsten Backwerken der Region. Sein Name verweist auf die charakteristischen Zacken und „Äste“, die entstehen, wenn flüssiger Eierteig schichtweise auf einen rotierenden Spieß gegossen und über Hitze gebacken wird, sodass herabtropfender Teig die spitzen Auswüchse bildet. Diese Backtechnik des Spießkuchens ist alt und in mehreren europäischen Traditionen verbreitet. In Litauen ist Šakotis untrennbar mit Hochzeiten, Taufen, Weihnachten und anderen großen Festen verbunden; der hohe, baumartige Kuchen wird als festlicher Mittelpunkt präsentiert und in Stücke geteilt. Seine Herstellung ist aufwendig und erfordert Geduld und Geschick, weshalb er oft von spezialisierten Bäckern stammt. Eine ofentaugliche, vereinfachte Form lässt sich auf einem rotierenden Spieß oder geschichtet zubereiten. Als reines Eier-Mehl-Zucker-Gebäck ist er selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Litauen", "Šakotis", "Baumkuchen", "Spießkuchen", "Festtag", "Hochzeit", "süß", "vegetarisch", "Backhandwerk", "Weihnachten", "Baltikum", "Dessert"]}, {"id": "judd-mat-gaardebounen", "status": "published", "date": "", "cover": "", "name": "Judd mat Gaardebounen", "land": "Luxemburg", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Geräucherter Nacken mit dicken Saubohnen in heller Sauce, dazu Salzkartoffeln. Das Nationalgericht Luxemburgs — hier in einer Fassung mit geräuchertem Rind.", "zutaten": ["800 g geräucherte Rinderbrust oder Pastrami am Stück", "600 g dicke Bohnen (Saubohnen), frisch oder TK", "1 Zwiebel", "30 g Butter, 30 g Mehl (helle Mehlschwitze)", "200 ml Brühe vom Fleisch", "1 Bund Bohnenkraut und Petersilie", "800 g Kartoffeln", "Salz, Pfeffer"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "geräucherte Rinderbrust oder Pastrami am Stück", "roh": "800 g geräucherte Rinderbrust oder Pastrami am Stück"}, {"menge": 600.0, "einheit": "g", "item": "dicke Bohnen (Saubohnen), frisch oder TK", "roh": "600 g dicke Bohnen (Saubohnen), frisch oder TK"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 30.0, "einheit": "g", "item": "Butter, 30 g Mehl (helle Mehlschwitze)", "roh": "30 g Butter, 30 g Mehl (helle Mehlschwitze)"}, {"menge": 200.0, "einheit": "ml", "item": "Brühe vom Fleisch", "roh": "200 ml Brühe vom Fleisch"}, {"menge": 1.0, "einheit": "Bund", "item": "Bohnenkraut und Petersilie", "roh": "1 Bund Bohnenkraut und Petersilie"}, {"menge": 800.0, "einheit": "g", "item": "Kartoffeln", "roh": "800 g Kartoffeln"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}], "zubereitung": ["Das geräucherte Rind in Wasser mit Zwiebel und Bohnenkraut etwa 1–1,5 Stunden sanft garen; Brühe aufbewahren.", "Dicke Bohnen kurz blanchieren und nach Wunsch aus der zähen Haut lösen.", "Aus Butter und Mehl eine helle Mehlschwitze rühren und mit der Fleischbrühe zu einer hellen Sauce aufgießen.", "Die Bohnen in der Sauce erwärmen, mit Bohnenkraut, Salz und Pfeffer abschmecken.", "Kartoffeln als Salzkartoffeln kochen.", "Das Fleisch in Scheiben mit den Bohnen in Sauce und Salzkartoffeln servieren."], "hinweise": "Die Garbrühe des Fleischs gibt der Sauce ihren Geschmack.\n\nFrische Saubohnen aus den Hülsen lösen, wenn sie Saison haben.\n\nBohnenkraut ist das klassische Gewürz zu dicken Bohnen.", "alternative": "Das Original besteht aus geräuchertem, gepökeltem Schweinenacken. Da das Gericht kulturell zentral ist, ersetzen wir das Schwein durch geräucherte Rinderbrust oder Pastrami — sie liefern den prägenden Rauchgeschmack und die herzhafte Verbindung mit den Saubohnen, sodass der Charakter des luxemburgischen Klassikers erhalten bleibt.", "geschichte": "Judd mat Gaardebounen — „Nacken mit Saubohnen“ — gilt als das Nationalgericht Luxemburgs. Traditionell besteht es aus geräuchertem und gepökeltem Schweinenacken, der gewässert und gekocht wird, serviert mit dicken Saubohnen (Gaardebounen, Acker- oder Puffbohnen) in einer hellen, mehlgebundenen Sauce und Salzkartoffeln. Das Gericht wurzelt in der bäuerlichen Küche und der Tradition, Fleisch durch Pökeln und Räuchern haltbar zu machen, sowie im Anbau von Ackerbohnen, einer alten Hülsenfrucht der Region. Es wird besonders im Frühsommer gegessen, wenn die frischen Saubohnen Saison haben, und gehört zu Festen, Volksfesten und der nationalen Esskultur. Da das Originalgericht auf geräuchertem Schweinefleisch beruht, das hier kulturell zentral ist, bieten wir eine Fassung mit geräuchertem Rind an, die den charakteristischen Rauchgeschmack und die Verbindung mit den Saubohnen bewahrt. So bleibt das Wesen des luxemburgischen Klassikers erhalten, ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Luxemburg", "Judd mat Gaardebounen", "Nationalgericht", "geräuchertes Rind", "Saubohnen", "dicke Bohnen", "Salzkartoffeln", "Landküche", "Frühsommer", "deftig", "Rauchfleisch", "Hauptgericht"]}, {"id": "gromperekichelcher", "status": "published", "date": "", "cover": "", "name": "Gromperekichelcher", "land": "Luxemburg", "kontinent": "Europa", "gang": "Beilage", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Knusprig frittierte Kartoffelpuffer mit Zwiebel, Petersilie und etwas Schalotte, gewürzt und goldbraun gebacken. Beliebtes Markt- und Festessen Luxemburgs.", "zutaten": ["800 g mehligkochende Kartoffeln", "1 Zwiebel", "2 Schalotten", "1 Ei", "3 EL Mehl", "1 Bund Petersilie", "Öl zum Ausbacken, Salz, Pfeffer, Muskat", "Apfelmus zum Servieren"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "mehligkochende Kartoffeln", "roh": "800 g mehligkochende Kartoffeln"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 2.0, "einheit": "", "item": "Schalotten", "roh": "2 Schalotten"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 3.0, "einheit": "EL", "item": "Mehl", "roh": "3 EL Mehl"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": null, "einheit": "", "item": "Öl zum Ausbacken, Salz, Pfeffer, Muskat", "roh": "Öl zum Ausbacken, Salz, Pfeffer, Muskat"}, {"menge": null, "einheit": "", "item": "Apfelmus zum Servieren", "roh": "Apfelmus zum Servieren"}], "zubereitung": ["Kartoffeln fein reiben und die Flüssigkeit gut ausdrücken.", "Zwiebel und Schalotten fein reiben oder hacken, Petersilie hacken.", "Alles mit Ei und Mehl vermengen, mit Salz, Pfeffer und Muskat würzen.", "Reichlich Öl in einer Pfanne erhitzen.", "Aus der Masse flache Küchlein formen und beidseitig goldbraun und knusprig ausbacken.", "Auf Küchenpapier abtropfen lassen und heiß, gern mit Apfelmus, servieren."], "hinweise": "Die Kartoffeln gut ausdrücken — je trockener die Masse, desto knuspriger.\n\nKräftig mit Zwiebel und Petersilie würzen, das ist typisch.\n\nHeiß aus der Pfanne schmecken sie am besten.", "alternative": "", "geschichte": "Gromperekichelcher — wörtlich „Kartoffelküchlein“ — sind ein traditioneller luxemburgischer Snack und gehören zu den beliebtesten Spezialitäten auf Märkten, Volksfesten und der Schueberfouer, dem großen Jahrmarkt in der Hauptstadt. Es handelt sich um würzige Puffer aus geriebenen rohen Kartoffeln, vermengt mit Zwiebel, Schalotte, Petersilie, Ei und etwas Mehl, die in heißem Fett knusprig goldbraun ausgebacken werden. Sie sind verwandt mit den Kartoffelpuffern und Reibekuchen der gesamten Region und entstanden aus der bäuerlichen Kartoffelküche, die einfache Grundzutaten in ein schmackhaftes Essen verwandelte. Anders als manche Reibekuchenvarianten werden Gromperekichelcher kräftig mit Zwiebel und Kräutern gewürzt, was ihnen ihren typischen Geschmack gibt. Gegessen werden sie heiß aus der Hand, oft mit Apfelmus. Sie sind von Natur aus vegetarisch und ohne Schweinefleisch und stehen für die geselligen, volksnahen Seiten der luxemburgischen Esskultur.", "persoenlich": "", "servier": "", "tags": ["Luxemburg", "Gromperekichelcher", "Kartoffelpuffer", "vegetarisch", "Zwiebel", "Petersilie", "Markt", "Schueberfouer", "Straßenessen", "frittiert", "Apfelmus", "Snack"]}, {"id": "bouneschlupp", "status": "published", "date": "", "cover": "", "name": "Bouneschlupp", "land": "Luxemburg", "kontinent": "Europa", "gang": "Suppe", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine herzhafte grüne Bohnensuppe mit Kartoffeln, Lauch und etwas Sahne. Ländliches Wohlfühlessen Luxemburgs.", "zutaten": ["600 g grüne Bohnen, geputzt", "4 Kartoffeln, gewürfelt", "1 Lauchstange", "2 Zwiebeln", "1.2 l Gemüsebrühe", "100 ml Sahne", "1 Zweig Bohnenkraut", "1 Bund Petersilie", "Butter, Salz, Pfeffer"], "zutatenS": [{"menge": 600.0, "einheit": "g", "item": "grüne Bohnen, geputzt", "roh": "600 g grüne Bohnen, geputzt"}, {"menge": 4.0, "einheit": "", "item": "Kartoffeln, gewürfelt", "roh": "4 Kartoffeln, gewürfelt"}, {"menge": 1.0, "einheit": "", "item": "Lauchstange", "roh": "1 Lauchstange"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 1.2, "einheit": "l", "item": "Gemüsebrühe", "roh": "1.2 l Gemüsebrühe"}, {"menge": 100.0, "einheit": "ml", "item": "Sahne", "roh": "100 ml Sahne"}, {"menge": 1.0, "einheit": "Zweig", "item": "Bohnenkraut", "roh": "1 Zweig Bohnenkraut"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": null, "einheit": "", "item": "Butter, Salz, Pfeffer", "roh": "Butter, Salz, Pfeffer"}], "zubereitung": ["Zwiebeln und Lauch in Butter andünsten.", "Bohnen in Stücke schneiden und mit den Kartoffeln zugeben.", "Mit Gemüsebrühe auffüllen, Bohnenkraut zugeben und etwa 25 Minuten köcheln.", "Einen Teil der Kartoffeln zerdrücken, damit die Suppe leicht bindet.", "Sahne einrühren und mit Salz und Pfeffer abschmecken.", "Mit gehackter Petersilie bestreut servieren."], "hinweise": "Etwas zerdrückte Kartoffel bindet die Suppe auf natürliche Weise.\n\nBohnenkraut ist das klassische Gewürz zu grünen Bohnen.\n\nWer mag, gibt geräucherte Rinderwurst statt Speck dazu.", "alternative": "", "geschichte": "Bouneschlupp — grüne Bohnensuppe — ist eines der bekanntesten Alltagsgerichte Luxemburgs und ein Inbegriff der bodenständigen, ländlichen Küche des Landes. Sie beruht auf grünen Bohnen (Stangen- oder Brechbohnen), die zusammen mit Kartoffeln, Zwiebeln und Lauch zu einer sättigenden Suppe gekocht und oft mit etwas Sahne oder Mehlschwitze gebunden werden. Das Gericht entstand aus der Selbstversorgung der Bauernhaushalte, die das im Sommer reichlich vorhandene Gemüse aus dem eigenen Garten verwerteten und für die kalte Jahreszeit haltbar machten. Während traditionelle Fassungen häufig mit geräucherter Wurst oder Speck angereichert werden, ist die reine Gemüsesuppe ebenso verbreitet und alltäglich. Bouneschlupp wird das ganze Jahr über gegessen und gilt als wärmendes, nahrhaftes Wohlfühlessen. In dieser vegetarischen Fassung holen wir die herzhafte Tiefe aus Lauch, Kartoffeln und einem kräftigen Gemüsefond. Die Suppe steht für die unaufgeregte, gartennahe Esskultur Luxemburgs.", "persoenlich": "", "servier": "", "tags": ["Luxemburg", "Bouneschlupp", "Bohnensuppe", "grüne Bohnen", "Kartoffeln", "Lauch", "vegetarisch", "Landküche", "Wohlfühlessen", "Gartengemüse", "Suppe", "Hausmannskost"]}, {"id": "aljotta", "status": "published", "date": "", "cover": "", "name": "Aljotta", "land": "Malta", "kontinent": "Europa", "gang": "Suppe", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine kräftige maltesische Fischsuppe mit viel Knoblauch, Tomaten, Kräutern und Reis. Mediterrane Küstenküche aus dem Fang des Tages.", "zutaten": ["1 kg gemischter Suppenfisch und Fischabschnitte", "1 ganze Knolle Knoblauch", "400 g reife Tomaten", "1 Zwiebel", "80 g Reis", "1 Bund frische Minze und Majoran", "5 EL Olivenöl", "1 Zitrone", "Salz und Pfeffer"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "gemischter Suppenfisch und Fischabschnitte", "roh": "1 kg gemischter Suppenfisch und Fischabschnitte"}, {"menge": 1.0, "einheit": "ganze Knolle", "item": "Knoblauch", "roh": "1 ganze Knolle Knoblauch"}, {"menge": 400.0, "einheit": "g", "item": "reife Tomaten", "roh": "400 g reife Tomaten"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 80.0, "einheit": "g", "item": "Reis", "roh": "80 g Reis"}, {"menge": 1.0, "einheit": "Bund", "item": "frische Minze und Majoran", "roh": "1 Bund frische Minze und Majoran"}, {"menge": 5.0, "einheit": "EL", "item": "Olivenöl", "roh": "5 EL Olivenöl"}, {"menge": 1.0, "einheit": "", "item": "Zitrone", "roh": "1 Zitrone"}, {"menge": null, "einheit": "", "item": "Salz und Pfeffer", "roh": "Salz und Pfeffer"}], "zubereitung": ["Zwiebel und reichlich Knoblauch in Olivenöl sanft andünsten.", "Tomaten zugeben und einköcheln lassen.", "Mit Wasser aufgießen, salzen und den Fisch sowie die Abschnitte einlegen.", "Etwa 20 Minuten köcheln, dann den Fisch herausnehmen, entgräten und das Fleisch zurückgeben.", "Reis einstreuen und gar kochen.", "Mit frischen Kräutern, Zitronensaft, Salz und Pfeffer abschmecken und heiß servieren."], "hinweise": "Eine Mischung verschiedener Fische gibt die kräftigste Brühe.\n\nMit viel Knoblauch arbeiten — er prägt das Gericht.\n\nFrische Kräuter und Zitrone erst zum Schluss zugeben.", "alternative": "", "geschichte": "Aljotta ist die traditionelle Fischsuppe Maltas und ein Paradebeispiel der mediterranen Inselküche, die stark von der geografischen Lage zwischen Sizilien und Nordafrika geprägt ist. Wie viele Fischsuppen des Mittelmeerraums entstand Aljotta als sparsames Gericht der Fischer, die kleinere Fische und Reste des Fangs zu einer nahrhaften Brühe verarbeiteten. Charakteristisch sind die großzügige Verwendung von Knoblauch, reife Tomaten, frische Kräuter wie Majoran und Minze sowie ein Schuss Zitrone, die der Suppe ihre mediterrane Frische geben. Häufig wird Reis mitgekocht, der die Suppe sättigender macht. Aljotta spiegelt die enge Bindung der maltesischen Bevölkerung an das Meer und die fastenfreundliche, fleischlose Küche der Insel wider, die katholisch geprägt ist und an Fastentagen Fischgerichte schätzte. Sie ist von Natur aus ohne Schweinefleisch und gilt als wärmendes, aromatisches Wohlfühlessen, das die Einfachheit und Frische guter Zutaten feiert.", "persoenlich": "", "servier": "", "tags": ["Malta", "Aljotta", "Fischsuppe", "Fisch", "Knoblauch", "Tomaten", "mediterran", "Küstenküche", "Reis", "Fastenspeise", "Inselküche", "Suppe"]}, {"id": "bragioli", "status": "published", "date": "", "cover": "", "name": "Bragioli", "land": "Malta", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Dünne Rinderscheiben, gefüllt mit einer Mischung aus Ei, Semmelbröseln und Kräutern, gerollt und in Tomatensauce geschmort. Maltesische „Rinderoliven“.", "zutaten": ["8 Scheiben dünn geschnittenes Rindfleisch (Rouladenfleisch)", "3 hartgekochte Eier, gehackt", "80 g Semmelbrösel", "1 Bund Petersilie", "2 Zwiebeln", "400 g passierte Tomaten", "100 ml Rotwein", "Olivenöl, Salz, Pfeffer"], "zutatenS": [{"menge": 8.0, "einheit": "Scheiben", "item": "dünn geschnittenes Rindfleisch (Rouladenfleisch)", "roh": "8 Scheiben dünn geschnittenes Rindfleisch (Rouladenfleisch)"}, {"menge": 3.0, "einheit": "", "item": "hartgekochte Eier, gehackt", "roh": "3 hartgekochte Eier, gehackt"}, {"menge": 80.0, "einheit": "g", "item": "Semmelbrösel", "roh": "80 g Semmelbrösel"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 400.0, "einheit": "g", "item": "passierte Tomaten", "roh": "400 g passierte Tomaten"}, {"menge": 100.0, "einheit": "ml", "item": "Rotwein", "roh": "100 ml Rotwein"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer", "roh": "Olivenöl, Salz, Pfeffer"}], "zubereitung": ["Eier, Semmelbrösel, gehackte Petersilie, etwas Zwiebel, Salz und Pfeffer zu einer Füllung mischen.", "Die Rinderscheiben flach klopfen, mit Füllung belegen und fest aufrollen, mit Küchengarn fixieren.", "Die Rouladen in Olivenöl rundum anbraten und herausnehmen.", "Restliche Zwiebeln andünsten, mit Rotwein ablöschen und passierte Tomaten zugeben.", "Rouladen zurücklegen und zugedeckt 1,5 Stunden sanft schmoren.", "Garn entfernen und Bragioli mit der Sauce zu Kartoffeln oder Pasta servieren."], "hinweise": "Das Fleisch dünn klopfen, damit es sich gut rollen lässt.\n\nLangsam schmoren macht die Rouladen zart.\n\nDie Sauce eignet sich hervorragend für Pasta als Vorspeise.", "alternative": "", "geschichte": "Bragioli, auf Maltesisch oft „beef olives“ genannt, sind gefüllte und geschmorte Rinderrouladen und ein klassisches Festtags- und Sonntagsgericht der maltesischen Küche. Der Name „olives“ bezieht sich nicht auf Oliven, sondern auf die olivenförmige Gestalt der kleinen Fleischrollen. Das Gericht spiegelt die Mischung der Einflüsse wider, die die maltesische Küche prägen — sizilianische, italienische und britische Spuren. Dünn geklopfte Rinderscheiben werden mit einer Farce aus hartgekochtem Ei, Semmelbröseln, Petersilie und Kräutern belegt, aufgerollt und dann langsam in einer Tomaten- und Weinsauce geschmort, bis das Fleisch zart ist. Serviert werden Bragioli mit der Sauce zu Kartoffeln, Reis oder Pasta. Als aufwendigeres Schmorgericht standen sie traditionell bei festlichen Anlässen auf dem Tisch. In dieser Fassung kommt eine Füllung ohne Schweinefleisch zum Einsatz, sodass das herzhafte Aroma erhalten bleibt. Bragioli gelten als eines der wärmsten Beispiele maltesischer Hausmannskost.", "persoenlich": "", "servier": "", "tags": ["Malta", "Bragioli", "beef olives", "Rind", "Rouladen", "Tomatensauce", "Schmorgericht", "Festtag", "Sonntagsessen", "mediterran", "Hausmannskost", "Hauptgericht"]}, {"id": "pastizzi-tal-irkotta", "status": "published", "date": "", "cover": "", "name": "Pastizzi tal-irkotta", "land": "Malta", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Knusprige, rautenförmige Blätterteigtaschen mit cremiger Ricotta-Füllung. Maltas allgegenwärtiges Straßengebäck.", "zutaten": ["1 Packung Blätterteig (oder Filo, mehrfach geschichtet)", "500 g Ricotta", "2 Eier", "1 Bund Petersilie", "2 Frühlingszwiebeln (optional)", "Salz, Pfeffer"], "zutatenS": [{"menge": 1.0, "einheit": "Packung", "item": "Blätterteig (oder Filo, mehrfach geschichtet)", "roh": "1 Packung Blätterteig (oder Filo, mehrfach geschichtet)"}, {"menge": 500.0, "einheit": "g", "item": "Ricotta", "roh": "500 g Ricotta"}, {"menge": 2.0, "einheit": "", "item": "Eier", "roh": "2 Eier"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": 2.0, "einheit": "", "item": "Frühlingszwiebeln (optional)", "roh": "2 Frühlingszwiebeln (optional)"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}], "zubereitung": ["Ricotta mit Ei, gehackter Petersilie, Salz und Pfeffer zu einer cremigen Füllung verrühren.", "Blätterteig ausrollen und in Quadrate schneiden.", "Je einen Klecks Füllung mittig setzen.", "Die Ränder zur typischen Rautenform zusammendrücken, sodass die Füllung sichtbar bleibt.", "Mit verquirltem Ei bestreichen.", "Bei 200 °C 20–25 Minuten goldbraun und knusprig backen; heiß servieren."], "hinweise": "Die Ricotta gut abtropfen lassen, damit die Füllung nicht zu feucht wird.\n\nEchte Pastizzi haben viele dünne Schichten — Blätterteig kommt dem nahe.\n\nHeiß und frisch schmecken sie am besten.", "alternative": "", "geschichte": "Pastizzi sind das bekannteste Straßengebäck Maltas und ein fester Bestandteil der maltesischen Alltagskultur. Die kleinen, rautenförmigen Taschen aus vielschichtigem, knusprigem Teig werden klassisch mit zwei Füllungen angeboten: cremiger Ricotta (irkotta) oder einem Erbsenpüree. Verkauft werden sie heiß in spezialisierten Buden, den „pastizzeriji“, sowie in Bars und Bäckereien, und sie gelten als preiswertes, sättigendes Essen für unterwegs. Das geschichtete Gebäck verweist auf die mediterranen und nahöstlichen Teigtraditionen, die Malta über seine Geschichte als Kreuzungspunkt im Mittelmeer erreichten. Ricotta spielt in der maltesischen Küche eine große Rolle und füllt zahlreiche herzhafte und süße Gebäcke. Pastizzi sind so eng mit der Insel verbunden, dass sie als kulinarisches Wahrzeichen gelten und zu jeder Tageszeit gegessen werden. Die Ricotta-Variante ist von Natur aus vegetarisch und ohne Schweinefleisch und steht sinnbildlich für die unkomplizierte, volksnahe Seite der maltesischen Esskultur.", "persoenlich": "", "servier": "", "tags": ["Malta", "Pastizzi", "Ricotta", "Blätterteig", "vegetarisch", "Straßenessen", "Snack", "mediterran", "Inselküche", "Gebäck", "Frühstück", "irkotta"]}, {"id": "m-m-lig", "status": "published", "date": "", "cover": "", "name": "Mămăligă", "land": "Moldau", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein fester Maisbrei, gestürzt und in Stücke geschnitten, serviert mit Schafskäse (brânză) und saurer Sahne. Das Grundnahrungsmittel Moldaus.", "zutaten": ["250 g Maisgrieß (Polenta, mittel)", "1 l Wasser", "1 TL Salz", "200 g Schafskäse (brânză) oder Feta", "200 g saure Sahne (smântână)", "20 g Butter (optional)"], "zutatenS": [{"menge": 250.0, "einheit": "g", "item": "Maisgrieß (Polenta, mittel)", "roh": "250 g Maisgrieß (Polenta, mittel)"}, {"menge": 1.0, "einheit": "l", "item": "Wasser", "roh": "1 l Wasser"}, {"menge": 1.0, "einheit": "TL", "item": "Salz", "roh": "1 TL Salz"}, {"menge": 200.0, "einheit": "g", "item": "Schafskäse (brânză) oder Feta", "roh": "200 g Schafskäse (brânză) oder Feta"}, {"menge": 200.0, "einheit": "g", "item": "saure Sahne (smântână)", "roh": "200 g saure Sahne (smântână)"}, {"menge": 20.0, "einheit": "g", "item": "Butter (optional)", "roh": "20 g Butter (optional)"}], "zubereitung": ["Wasser mit Salz zum Kochen bringen.", "Maisgrieß langsam einrieseln lassen und dabei kräftig rühren, um Klumpen zu vermeiden.", "Unter gelegentlichem Rühren bei kleiner Hitze etwa 25–30 Minuten zu einem sehr festen Brei kochen.", "Die Mămăligă auf ein Brett stürzen.", "Mit einem Faden oder Messer in dicke Stücke schneiden.", "Mit zerbröseltem Schafskäse und saurer Sahne servieren."], "hinweise": "Den Grieß einrieseln lassen und rühren — so wird der Brei klumpenfrei.\n\nJe länger gerührt und gekocht, desto fester die Mămăligă.\n\nKlassisch mit Schafskäse, saurer Sahne und einem Spiegelei.", "alternative": "", "geschichte": "Mămăligă ist ein fester Maisbrei und gehört zu den ältesten und wichtigsten Grundnahrungsmitteln Moldaus sowie des angrenzenden Rumäniens. Mais kam nach Europa nach der Entdeckung Amerikas und setzte sich in der Region ab dem 17. und 18. Jahrhundert als günstiges, gut gedeihendes Getreide durch. Für die ländliche Bevölkerung wurde Mămăligă zur täglichen Sättigung und galt lange als „Brot der Armen“, das Weizenbrot ersetzte. Der Maisgrieß wird in Wasser unter ständigem Rühren zu einem dichten Brei gekocht, der so fest wird, dass man ihn stürzen und mit einem Faden oder Messer in Stücke schneiden kann. Serviert wird Mămăligă klassisch mit eingelegtem oder frischem Schafskäse (brânză), saurer Sahne (smântână) und manchmal einem Spiegelei. Sie begleitet zahlreiche Gerichte oder bildet selbst die Mahlzeit. Mămăligă ist von Natur aus vegetarisch und ohne Schweinefleisch und gilt als Symbol der bodenständigen moldauischen Küche.", "persoenlich": "", "servier": "", "tags": ["Moldau", "Mămăligă", "Maisbrei", "Polenta", "Schafskäse", "saure Sahne", "vegetarisch", "Grundnahrungsmittel", "Landküche", "Beilage", "brânză", "Hauptgericht"]}, {"id": "sarmale", "status": "published", "date": "", "cover": "", "name": "Sarmale", "land": "Moldau", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "In Kraut- oder Weinblätter gewickelte Röllchen aus Reis und gewürztem Rinderhack, langsam geschmort. Festtagsklassiker Moldaus, hier ohne Schwein.", "zutaten": ["1 Kopf Sauerkraut/Spitzkohl oder Weinblätter", "500 g Rinderhack", "150 g Reis", "2 Zwiebeln", "2 EL Tomatenmark", "400 g passierte Tomaten", "1 Zweig Thymian, 1 Lorbeerblatt, Dill", "Öl, Salz, Pfeffer; saure Sahne zum Servieren"], "zutatenS": [{"menge": 1.0, "einheit": "", "item": "Kopf Sauerkraut/Spitzkohl oder Weinblätter", "roh": "1 Kopf Sauerkraut/Spitzkohl oder Weinblätter"}, {"menge": 500.0, "einheit": "g", "item": "Rinderhack", "roh": "500 g Rinderhack"}, {"menge": 150.0, "einheit": "g", "item": "Reis", "roh": "150 g Reis"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 2.0, "einheit": "EL", "item": "Tomatenmark", "roh": "2 EL Tomatenmark"}, {"menge": 400.0, "einheit": "g", "item": "passierte Tomaten", "roh": "400 g passierte Tomaten"}, {"menge": 1.0, "einheit": "Zweig", "item": "Thymian, 1 Lorbeerblatt, Dill", "roh": "1 Zweig Thymian, 1 Lorbeerblatt, Dill"}, {"menge": null, "einheit": "", "item": "Öl, Salz, Pfeffer; saure Sahne zum Servieren", "roh": "Öl, Salz, Pfeffer; saure Sahne zum Servieren"}], "zubereitung": ["Zwiebeln andünsten und mit Hack, Reis, Tomatenmark, Kräutern, Salz und Pfeffer zu einer Füllung vermengen (Reis bleibt roh).", "Krautblätter ablösen, dicke Rippen flach schneiden.", "Je etwas Füllung auf ein Blatt geben, die Seiten einschlagen und fest aufrollen.", "Die Röllchen dicht in einen Topf schichten.", "Mit passierten Tomaten und Wasser angießen, bis sie knapp bedeckt sind, Lorbeer einlegen.", "Zugedeckt 1,5–2 Stunden sehr sanft schmoren; mit Mămăligă und saurer Sahne servieren."], "hinweise": "Den Reis nur halb so viel nehmen wie Platz ist — er quillt stark.\n\nDie Röllchen dicht schichten, damit sie sich nicht öffnen.\n\nLange, sanfte Garzeit macht Sarmale zart und aromatisch.", "alternative": "Sarmale werden traditionell mit Schweinehack oder einer Schweine-Rind-Mischung gefüllt. Wir verwenden ausschließlich Rinderhack, gut gewürzt mit Zwiebeln und Kräutern; das lange Schmoren sorgt für Zartheit und Tiefe, ganz ohne Schwein.", "geschichte": "Sarmale sind gefüllte Kohl- oder Weinblattröllchen und ein zentrales Festtagsgericht Moldaus und Rumäniens, das zu Weihnachten, Ostern, Hochzeiten und Feiern auf dem Tisch steht. Das Gericht gehört zur großen Familie der gefüllten Blätter (dolma/sarma), die sich über die osmanische Zeit im gesamten Balkan, im Nahen Osten und in Osteuropa verbreitete; der Name leitet sich vom türkischen „sarmak“ (wickeln) ab. Saure Krautblätter oder im Sommer Weinblätter werden mit einer Mischung aus Reis, gehacktem Fleisch, Zwiebeln und Kräutern gefüllt, fest gerollt und in einem Topf geschichtet, oft mit Tomate, langsam über Stunden geschmort. Das lange, sanfte Garen verbindet die Aromen und macht die Röllchen zart. Serviert werden Sarmale traditionell mit Mămăligă und saurer Sahne. Üblicherweise wird Schweinehack verwendet; in dieser Fassung nehmen wir Rind, sodass der festliche Charakter ohne Schwein erhalten bleibt.", "persoenlich": "", "servier": "", "tags": ["Moldau", "Sarmale", "Krautwickel", "Dolma", "Rind", "Reis", "Festtag", "Weihnachten", "osmanisch geprägt", "Schmorgericht", "saure Sahne", "Hauptgericht"]}, {"id": "pl-cint", "status": "published", "date": "", "cover": "", "name": "Plăcintă", "land": "Moldau", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Dünn ausgezogene, gefüllte Teigfladen, klassisch mit Schafskäse, Kartoffel oder Apfel. Allgegenwärtiges moldauisches Gebäck.", "zutaten": ["400 g Mehl", "200 ml warmes Wasser", "4 EL Öl", "1 Prise Salz", "300 g Schafskäse (brânză) oder Feta", "1 Ei", "Butter zum Bestreichen"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Mehl", "roh": "400 g Mehl"}, {"menge": 200.0, "einheit": "ml", "item": "warmes Wasser", "roh": "200 ml warmes Wasser"}, {"menge": 4.0, "einheit": "EL", "item": "Öl", "roh": "4 EL Öl"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}, {"menge": 300.0, "einheit": "g", "item": "Schafskäse (brânză) oder Feta", "roh": "300 g Schafskäse (brânză) oder Feta"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": null, "einheit": "", "item": "Butter zum Bestreichen", "roh": "Butter zum Bestreichen"}], "zubereitung": ["Mehl, Wasser, Öl und Salz zu einem geschmeidigen Teig kneten und ruhen lassen.", "Teig in Portionen teilen und jede sehr dünn ausziehen oder ausrollen.", "Käse mit Ei verrühren und mittig auf den Teig geben.", "Die Ränder über der Füllung einschlagen, sodass ein flaches Päckchen entsteht.", "In einer Pfanne mit etwas Butter beidseitig goldbraun backen (oder im Ofen).", "Lauwarm in Stücke schneiden und servieren."], "hinweise": "Den Teig möglichst dünn ausziehen — das ist typisch.\n\nFür die süße Variante Apfel mit Zimt und Zucker füllen.\n\nFrisch und lauwarm am besten.", "alternative": "", "geschichte": "Plăcintă ist ein traditionelles gefülltes Teiggebäck Moldaus und Rumäniens und gehört zum festen Repertoire der häuslichen Küche. Der Name leitet sich vom lateinischen „placenta“ (Kuchen) ab und verweist auf die lange Geschichte flacher, gefüllter Backwaren in der Region. Charakteristisch ist ein sehr dünn ausgezogener oder ausgerollter Teig, der mit verschiedenen Füllungen versehen, eingeschlagen und in der Pfanne oder im Ofen gebacken wird. Die Füllungen reichen von herzhaft — Schafskäse (brânză) und Ei, Kartoffel, Kürbis oder Kraut — bis süß mit Apfel oder Kirschen. Plăcintă spiegelt die Verwertung einfacher, saisonaler Zutaten wider und war ein praktisches, sättigendes Essen, das man zu Hause buk und als Mahlzeit, Snack oder Süßspeise reichte. Es ist in zahllosen regionalen Varianten verbreitet und gilt als eines der typischsten Gebäcke Moldaus. Mit Käse-, Gemüse- oder Obstfüllung ist es vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Moldau", "Plăcintă", "gefülltes Gebäck", "Schafskäse", "Teigfladen", "vegetarisch", "Snack", "Hausbäckerei", "brânză", "Landküche", "Apfel", "Dessert"]}, {"id": "barbagiuan", "status": "published", "date": "", "cover": "", "name": "Barbagiuan", "land": "Monaco", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine frittierte Teigtaschen, gefüllt mit Mangold und Ricotta. Das Wahrzeichengebäck des Fürstentums Monaco.", "zutaten": ["300 g Mehl", "120 ml Wasser", "3 EL Olivenöl (Teig)", "400 g Mangold (oder Spinat)", "250 g Ricotta", "50 g Parmesan, gerieben", "1 Ei, 1 Zwiebel", "Öl zum Frittieren, Salz, Pfeffer, Muskat"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "Mehl", "roh": "300 g Mehl"}, {"menge": 120.0, "einheit": "ml", "item": "Wasser", "roh": "120 ml Wasser"}, {"menge": 3.0, "einheit": "EL", "item": "Olivenöl (Teig)", "roh": "3 EL Olivenöl (Teig)"}, {"menge": 400.0, "einheit": "g", "item": "Mangold (oder Spinat)", "roh": "400 g Mangold (oder Spinat)"}, {"menge": 250.0, "einheit": "g", "item": "Ricotta", "roh": "250 g Ricotta"}, {"menge": 50.0, "einheit": "g", "item": "Parmesan, gerieben", "roh": "50 g Parmesan, gerieben"}, {"menge": 1.0, "einheit": "", "item": "Ei, 1 Zwiebel", "roh": "1 Ei, 1 Zwiebel"}, {"menge": null, "einheit": "", "item": "Öl zum Frittieren, Salz, Pfeffer, Muskat", "roh": "Öl zum Frittieren, Salz, Pfeffer, Muskat"}], "zubereitung": ["Mehl, Wasser, Olivenöl und Salz zu einem glatten Teig kneten und ruhen lassen.", "Mangold blanchieren, gut ausdrücken und fein hacken; Zwiebel andünsten.", "Mangold, Zwiebel, Ricotta, Parmesan und Ei zu einer Füllung verrühren, mit Muskat würzen.", "Teig sehr dünn ausrollen und kleine Quadrate ausschneiden.", "Je etwas Füllung daraufsetzen, zu Täschchen verschließen und die Ränder andrücken.", "In heißem Öl goldbraun frittieren und warm servieren."], "hinweise": "Den Mangold sehr gut ausdrücken, sonst werden die Taschen feucht.\n\nDen Teig dünn ausrollen für knusprige Hüllen.\n\nAuch im Ofen gebacken eine etwas leichtere Variante.", "alternative": "", "geschichte": "Barbagiuan gilt als das Nationalgericht des Fürstentums Monaco und spiegelt dessen kulinarische Nähe zur ligurischen und niçoiser Küche wider. Der Name bedeutet sinngemäß „Onkel Johannes“ (barba Giuàn) im lokalen Dialekt. Es handelt sich um kleine, raviolo- oder taschenartige Gebäcke aus dünnem Teig, die traditionell mit Mangold (oder Spinat) und Ricotta gefüllt, manchmal mit Lauch, Zwiebel und Parmesan verfeinert und anschließend frittiert werden. Das Gericht gehört zur mediterranen Tradition gefüllter Teigwaren und nutzt das in der Region reichlich vorhandene Blattgemüse. Barbagiuan werden besonders zu Festen, dem monegassischen Nationalfeiertag und festlichen Anlässen zubereitet und als Vorspeise oder Fingerfood gereicht. Sie verkörpern die enge Verflechtung Monacos mit der umliegenden Riviera-Küche. In ihrer klassischen vegetarischen Füllung sind sie von Natur aus ohne Schweinefleisch und gelten als gastfreundliches, geselliges Gebäck.", "persoenlich": "", "servier": "", "tags": ["Monaco", "Barbagiuan", "Mangold", "Ricotta", "Teigtaschen", "frittiert", "vegetarisch", "Riviera", "ligurisch geprägt", "Nationalgericht", "Festtag", "Snack"]}, {"id": "stocafi", "status": "published", "date": "", "cover": "", "name": "Stocafi", "land": "Monaco", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Stockfisch, langsam in Tomaten, Oliven, Kapern und Wein geschmort. Ein monegassisches Schmorgericht aus getrocknetem Kabeljau.", "zutaten": ["800 g Stockfisch (gewässert) oder Kabeljaufilet", "2 Zwiebeln", "600 g passierte Tomaten", "100 g schwarze Oliven", "2 EL Kapern", "150 ml Weißwein", "3 Zehen Knoblauch", "Olivenöl, Kräuter, Salz, Pfeffer"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "Stockfisch (gewässert) oder Kabeljaufilet", "roh": "800 g Stockfisch (gewässert) oder Kabeljaufilet"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 600.0, "einheit": "g", "item": "passierte Tomaten", "roh": "600 g passierte Tomaten"}, {"menge": 100.0, "einheit": "g", "item": "schwarze Oliven", "roh": "100 g schwarze Oliven"}, {"menge": 2.0, "einheit": "EL", "item": "Kapern", "roh": "2 EL Kapern"}, {"menge": 150.0, "einheit": "ml", "item": "Weißwein", "roh": "150 ml Weißwein"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "3 Zehen Knoblauch"}, {"menge": null, "einheit": "", "item": "Olivenöl, Kräuter, Salz, Pfeffer", "roh": "Olivenöl, Kräuter, Salz, Pfeffer"}], "zubereitung": ["Den Stockfisch (falls verwendet) mehrere Tage unter mehrmaligem Wasserwechsel wässern und in Stücke schneiden.", "Zwiebeln und Knoblauch in Olivenöl andünsten.", "Mit Weißwein ablöschen, Tomaten zugeben und kurz einkochen.", "Oliven und Kapern einrühren, mit Kräutern würzen.", "Die Fischstücke einlegen und zugedeckt etwa 30–40 Minuten sanft schmoren.", "Mit Salz und Pfeffer abschmecken und mit Brot oder Kartoffeln servieren."], "hinweise": "Echten Stockfisch lange genug wässern, sonst bleibt er zäh und salzig.\n\nMit frischem Kabeljau gelingt eine schnellere Variante.\n\nOliven und Kapern geben die typische mediterrane Würze.", "alternative": "", "geschichte": "Stocafi ist die monegassische Zubereitung von Stockfisch — luftgetrocknetem, ungesalzenem Kabeljau — und ein traditionelles Gericht des Fürstentums, das eng mit der ligurischen und niçoiser Küche verwandt ist. Getrockneter Fisch war über Jahrhunderte im gesamten Mittelmeerraum ein bedeutendes Handels- und Vorratsgut, das auch fernab der Fanggebiete haltbar blieb und an Fastentagen gegessen wurde. Für Stocafi wird der harte Stockfisch zunächst mehrere Tage gewässert, um ihn wieder geschmeidig zu machen, und dann langsam in einer Sauce aus Tomaten, Zwiebeln, Oliven, Kapern, Knoblauch und Weißwein geschmort, bis er zart ist und die Aromen aufgenommen hat. Manche Versionen geben gegen Ende einen Schuss Anisschnaps oder Kräuter hinzu. Das Gericht steht für die mediterrane Tradition, Stockfisch durch geduldiges Wässern und Schmoren in eine Delikatesse zu verwandeln. Als Fischgericht ist Stocafi selbstverständlich ohne Schweinefleisch und gehört zur festen monegassischen Esskultur.", "persoenlich": "", "servier": "", "tags": ["Monaco", "Stocafi", "Stockfisch", "Kabeljau", "Fisch", "Tomaten", "Oliven", "Kapern", "mediterran", "ligurisch geprägt", "Schmorgericht", "Hauptgericht"]}, {"id": "fougasse-mon-gasque", "status": "published", "date": "", "cover": "", "name": "Fougasse monégasque", "land": "Monaco", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein süßes, flaches Hefegebäck, verziert mit Nüssen, Anis und roten und weißen Zuckerperlen. Festtagsgebäck Monacos in den Landesfarben.", "zutaten": ["400 g Mehl", "150 ml lauwarme Milch", "20 g frische Hefe", "80 g Zucker", "2 Eier", "3 EL Orangenblütenwasser", "1 TL Anissamen", "Mandeln/Walnüsse, rote und weiße Zuckerperlen"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Mehl", "roh": "400 g Mehl"}, {"menge": 150.0, "einheit": "ml", "item": "lauwarme Milch", "roh": "150 ml lauwarme Milch"}, {"menge": 20.0, "einheit": "g", "item": "frische Hefe", "roh": "20 g frische Hefe"}, {"menge": 80.0, "einheit": "g", "item": "Zucker", "roh": "80 g Zucker"}, {"menge": 2.0, "einheit": "", "item": "Eier", "roh": "2 Eier"}, {"menge": 3.0, "einheit": "EL", "item": "Orangenblütenwasser", "roh": "3 EL Orangenblütenwasser"}, {"menge": 1.0, "einheit": "TL", "item": "Anissamen", "roh": "1 TL Anissamen"}, {"menge": null, "einheit": "", "item": "Mandeln/Walnüsse, rote und weiße Zuckerperlen", "roh": "Mandeln/Walnüsse, rote und weiße Zuckerperlen"}], "zubereitung": ["Hefe in lauwarmer Milch mit etwas Zucker auflösen.", "Mehl, Zucker, Eier, Orangenblütenwasser, Anis und die Hefemilch zu einem weichen Teig kneten.", "Zugedeckt etwa 1 Stunde gehen lassen.", "Den Teig flach und oval auf ein Blech drücken.", "Mit verquirltem Ei bestreichen und mit Nüssen sowie roten und weißen Zuckerperlen verzieren.", "Bei 180 °C 20–25 Minuten goldbraun backen; abkühlen lassen und in Stücke brechen."], "hinweise": "Orangenblütenwasser und Anis geben das typische Aroma.\n\nRote und weiße Verzierung greift die Farben Monacos auf.\n\nDen Teig nicht zu dick ausarbeiten — die Fougasse bleibt flach.", "alternative": "", "geschichte": "Die Fougasse monégasque ist ein traditionelles süßes Hefegebäck des Fürstentums Monaco und unterscheidet sich von den herzhaften Fougasses der südfranzösischen Provence. Sie wird besonders zu Weihnachten und festlichen Anlässen gebacken und gehört in Monaco traditionell zur Tafel des „gros souper“, des großen Weihnachtsmahls. Der flache, leicht süße Hefeteig wird mit Orangenblütenwasser und Anis aromatisiert und nach dem Backen mit Mandeln oder Walnüssen sowie roten und weißen Zuckerperlen oder Dragees verziert — die Farben Rot und Weiß sind zugleich die Farben Monacos. Das Gebäck verkörpert die Verbindung der monegassischen Küche mit der provenzalischen und ligurischen Backtradition, in der aromatisierte Festtagsbrote und -kuchen eine lange Geschichte haben. Die Fougasse wird in Stücke gebrochen und geteilt und gehört zu den symbolträchtigen Süßspeisen des Fürstentums. Als reines Hefe-Süßgebäck ist sie selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Monaco", "Fougasse monégasque", "Hefegebäck", "süß", "Anis", "Orangenblütenwasser", "Weihnachten", "gros souper", "vegetarisch", "Festtag", "provenzalisch geprägt", "Dessert"]}, {"id": "ka-amak", "status": "published", "date": "", "cover": "", "name": "Kačamak", "land": "Montenegro", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein cremiger Brei aus Mais- (und teils Kartoffel-)Grieß, verrührt mit Käse und kajmak. Wärmendes Berggericht Montenegros.", "zutaten": ["250 g Maisgrieß", "300 g mehligkochende Kartoffeln", "1 l Wasser", "200 g kajmak (oder Frischkäse/saure Sahne)", "150 g junger Weißkäse, zerbröselt", "40 g Butter", "Salz"], "zutatenS": [{"menge": 250.0, "einheit": "g", "item": "Maisgrieß", "roh": "250 g Maisgrieß"}, {"menge": 300.0, "einheit": "g", "item": "mehligkochende Kartoffeln", "roh": "300 g mehligkochende Kartoffeln"}, {"menge": 1.0, "einheit": "l", "item": "Wasser", "roh": "1 l Wasser"}, {"menge": 200.0, "einheit": "g", "item": "kajmak (oder Frischkäse/saure Sahne)", "roh": "200 g kajmak (oder Frischkäse/saure Sahne)"}, {"menge": 150.0, "einheit": "g", "item": "junger Weißkäse, zerbröselt", "roh": "150 g junger Weißkäse, zerbröselt"}, {"menge": 40.0, "einheit": "g", "item": "Butter", "roh": "40 g Butter"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Kartoffeln schälen, würfeln und in gesalzenem Wasser weich kochen.", "Maisgrieß einrieseln lassen und unter Rühren zu einem dicken Brei kochen.", "Die Kartoffeln im Topf zerdrücken und mit dem Maisbrei verbinden.", "Butter, kajmak und Käse einrühren, bis eine cremige Masse entsteht.", "Bei kleiner Hitze kräftig durchrühren.", "Heiß servieren, nach Wunsch mit zusätzlichem kajmak."], "hinweise": "Kräftig rühren macht den Kačamak besonders cremig.\n\nJunger, leicht salziger Käse passt am besten.\n\nHeiß servieren — abgekühlt wird der Brei fest.", "alternative": "", "geschichte": "Kačamak ist ein traditionelles Brei- bzw. Pürreegericht der Bergregionen Montenegros und des angrenzenden Balkans. Es beruht auf Mais — und in manchen Varianten zusätzlich auf Kartoffeln —, die zu einem dichten, cremigen Brei verkocht und kräftig mit Käse und kajmak (einem rahmigen Milchprodukt) verrührt werden, bis eine geschmeidige, fettreiche Masse entsteht. Das Gericht stammt aus der Hirten- und Bergküche der Region, in der Mais ein wichtiges Getreide und Milchprodukte von Schafen und Kühen reichlich vorhanden waren. Kačamak war ein nahrhaftes, sättigendes Essen, das Familien und Hirten durch die kalten Monate trug und mit einfachen, lokal verfügbaren Zutaten auskam. Es wird heiß gegessen, oft mit zusätzlichem kajmak oder saurer Milch. Das Gericht ist in mehreren Balkanländern in Varianten verbreitet und gilt in Montenegro als typische Bergspezialität. Es ist von Natur aus vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Montenegro", "Kačamak", "Maisbrei", "Kartoffeln", "kajmak", "Käse", "vegetarisch", "Bergküche", "Balkan", "Winterküche", "Hirtenküche", "Hauptgericht"]}, {"id": "crni-ri-ot", "status": "published", "date": "", "cover": "", "name": "Crni rižot", "land": "Montenegro", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Tiefschwarzes Risotto mit Tintenfisch, gefärbt von dessen Tinte, mit Knoblauch, Wein und Olivenöl. Adriatische Küstenspezialität.", "zutaten": ["320 g Risottoreis", "600 g Tintenfisch oder Sepia, küchenfertig", "2 Beutel Sepiatinte", "1 Zwiebel, 3 Zehen Knoblauch", "150 ml Weißwein", "1 l Fischfond, heiß", "5 EL Olivenöl", "1 Bund Petersilie", "Salz, Pfeffer"], "zutatenS": [{"menge": 320.0, "einheit": "g", "item": "Risottoreis", "roh": "320 g Risottoreis"}, {"menge": 600.0, "einheit": "g", "item": "Tintenfisch oder Sepia, küchenfertig", "roh": "600 g Tintenfisch oder Sepia, küchenfertig"}, {"menge": 2.0, "einheit": "Beutel", "item": "Sepiatinte", "roh": "2 Beutel Sepiatinte"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel, 3 Zehen Knoblauch", "roh": "1 Zwiebel, 3 Zehen Knoblauch"}, {"menge": 150.0, "einheit": "ml", "item": "Weißwein", "roh": "150 ml Weißwein"}, {"menge": 1.0, "einheit": "l", "item": "Fischfond, heiß", "roh": "1 l Fischfond, heiß"}, {"menge": 5.0, "einheit": "EL", "item": "Olivenöl", "roh": "5 EL Olivenöl"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}], "zubereitung": ["Tintenfisch in Ringe bzw. Stücke schneiden.", "Zwiebel und Knoblauch in Olivenöl andünsten, Tintenfisch zugeben und kurz anbraten.", "Reis einrühren und glasig anschwitzen, mit Weißwein ablöschen.", "Nach und nach heißen Fischfond angießen und unter Rühren cremig kochen.", "Die Sepiatinte einrühren, bis das Risotto tiefschwarz ist.", "Mit Olivenöl, Petersilie, Salz und Pfeffer vollenden und sofort servieren."], "hinweise": "Den Fond stets heiß angießen für ein gleichmäßiges Garen.\n\nSepiatinte gibt es separat im Beutel zu kaufen.\n\nDas Risotto darf cremig-fließend bleiben, nicht zu trocken.", "alternative": "", "geschichte": "Crni rižot — „schwarzes Risotto“ — ist eine Spezialität der montenegrinischen Adriaküste und gehört zur gemeinsamen kulinarischen Tradition der gesamten östlichen Adria, die Montenegro mit Kroatien und der italienischen Küste teilt. Charakteristisch ist die tiefschwarze Farbe, die durch die Tinte (Sepia) von Tintenfisch oder Sepia entsteht und dem Gericht zugleich ein intensives, meerig-mineralisches Aroma verleiht. Risotto als Zubereitungsart verweist auf den venezianischen und italienischen Einfluss entlang der Adria. Der Reis wird mit Zwiebel und Knoblauch angeschwitzt, mit Weißwein abgelöscht, nach und nach mit Fischfond aufgegossen und mit den Tintenfischstücken und ihrer Tinte zu einer cremigen, dunklen Masse gekocht. Olivenöl und Petersilie runden das Gericht ab. Crni rižot ist ein beliebtes Gericht der Küstenorte und Fischrestaurants und steht für die maritime Seite der montenegrinischen Küche. Als Fisch- und Meeresfrüchtegericht ist es selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Montenegro", "Crni rižot", "schwarzes Risotto", "Tintenfisch", "Sepia", "Reis", "Adria", "Küstenküche", "venezianisch geprägt", "Meeresfrüchte", "mediterran", "Hauptgericht"]}, {"id": "priganice", "status": "published", "date": "", "cover": "", "name": "Priganice", "land": "Montenegro", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine, lockere frittierte Hefeteigbällchen, serviert mit Honig, Käse oder Marmelade. Geselliges Gebäck Montenegros zum Frühstück und Fest.", "zutaten": ["400 g Mehl", "250 ml lauwarmes Wasser oder Milch", "15 g frische Hefe", "1 TL Zucker", "1 Prise Salz", "Öl zum Frittieren", "Honig, kajmak oder Marmelade zum Servieren"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Mehl", "roh": "400 g Mehl"}, {"menge": 250.0, "einheit": "ml", "item": "lauwarmes Wasser oder Milch", "roh": "250 ml lauwarmes Wasser oder Milch"}, {"menge": 15.0, "einheit": "g", "item": "frische Hefe", "roh": "15 g frische Hefe"}, {"menge": 1.0, "einheit": "TL", "item": "Zucker", "roh": "1 TL Zucker"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}, {"menge": null, "einheit": "", "item": "Öl zum Frittieren", "roh": "Öl zum Frittieren"}, {"menge": null, "einheit": "", "item": "Honig, kajmak oder Marmelade zum Servieren", "roh": "Honig, kajmak oder Marmelade zum Servieren"}], "zubereitung": ["Hefe mit Zucker in der lauwarmen Flüssigkeit auflösen.", "Mit Mehl und Salz zu einem weichen, leicht klebrigen Teig verrühren.", "Zugedeckt etwa 45 Minuten gehen lassen, bis er aufgegangen ist.", "Öl in einem Topf erhitzen.", "Mit nassen Händen oder zwei Löffeln kleine Teigportionen abstechen und goldbraun ausbacken.", "Abtropfen lassen und warm mit Honig, kajmak oder Marmelade servieren."], "hinweise": "Der Teig soll weich und klebrig sein — das macht die Priganice locker.\n\nMit nassen Händen lässt sich der Teig leichter abteilen.\n\nWarm servieren, süß oder herzhaft.", "alternative": "", "geschichte": "Priganice sind kleine, frittierte Hefeteigbällchen und ein beliebtes traditionelles Gebäck Montenegros, das auch in Serbien und weiteren Teilen des Balkans verbreitet ist. Sie gehören zur weit gespannten Familie der frittierten Teiggebäcke der Region und sind eng mit Gastfreundschaft und geselligen Anlässen verbunden. Ein einfacher Hefeteig aus Mehl, Wasser oder Milch, Hefe und Salz wird gehen gelassen und dann löffelweise in heißem Öl zu lockeren, goldbraunen Kugeln ausgebacken. Priganice werden warm serviert und können sowohl süß als auch herzhaft gegessen werden: klassisch mit Honig, Marmelade, kajmak oder jungem Käse. Sie galten als unkompliziertes, sättigendes Essen, das schnell aus wenigen Grundzutaten zubereitet werden konnte, und gehören zum Frühstück ebenso wie zu Festen und Familienzusammenkünften. Priganice stehen für die warmherzige, gastfreundliche Seite der montenegrinischen Küche und sind als Hefegebäck selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Montenegro", "Priganice", "Hefeteig", "frittiert", "Honig", "kajmak", "süß", "vegetarisch", "Frühstück", "Balkan", "Gastfreundschaft", "Snack"]}, {"id": "erwtensoep", "status": "published", "date": "", "cover": "", "name": "Erwtensoep", "land": "Niederlande", "kontinent": "Europa", "gang": "Suppe", "art": [], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine sehr dicke Erbsensuppe, so kräftig, dass der Löffel darin steht, mit Wurzelgemüse und geräucherter Wurst. Niederländisches Winteressen — hier mit Rindwurst.", "zutaten": ["500 g getrocknete Spalterbsen", "2 l Wasser oder Gemüsebrühe", "2 Möhren", "0.5 Knollensellerie", "1 Lauchstange", "2 Kartoffeln", "1 geräucherte Rindwurst", "Salz, Pfeffer; Roggenbrot zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "getrocknete Spalterbsen", "roh": "500 g getrocknete Spalterbsen"}, {"menge": 2.0, "einheit": "l", "item": "Wasser oder Gemüsebrühe", "roh": "2 l Wasser oder Gemüsebrühe"}, {"menge": 2.0, "einheit": "", "item": "Möhren", "roh": "2 Möhren"}, {"menge": 0.5, "einheit": "", "item": "Knollensellerie", "roh": "0.5 Knollensellerie"}, {"menge": 1.0, "einheit": "", "item": "Lauchstange", "roh": "1 Lauchstange"}, {"menge": 2.0, "einheit": "", "item": "Kartoffeln", "roh": "2 Kartoffeln"}, {"menge": 1.0, "einheit": "", "item": "geräucherte Rindwurst", "roh": "1 geräucherte Rindwurst"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer; Roggenbrot zum Servieren", "roh": "Salz, Pfeffer; Roggenbrot zum Servieren"}], "zubereitung": ["Spalterbsen mit Wasser aufsetzen, aufkochen und abschäumen.", "Etwa 45 Minuten köcheln, bis die Erbsen zerfallen.", "Gewürfeltes Wurzelgemüse, Lauch und Kartoffeln zugeben und weitere 30 Minuten kochen.", "Die Suppe teilweise zerdrücken oder pürieren, bis sie sehr dick ist.", "Die geräucherte Rindwurst in Scheiben darin erwärmen.", "Kräftig mit Salz und Pfeffer abschmecken und mit Roggenbrot servieren."], "hinweise": "Die Suppe soll sehr dick werden — ruhig lange einkochen.\n\nAm nächsten Tag wird snert noch dicker und schmeckt am besten.\n\nEtwas mehr Brühe nachgießen, falls sie zu fest wird.", "alternative": "Erwtensoep wird klassisch mit Schweinefleisch und Schweine-Rauchwurst (rookworst) gekocht. Wir lassen das Schweinefleisch weg und geben stattdessen eine geräucherte Rindwurst hinein — sie liefert den prägenden Rauchgeschmack, sodass die Suppe ihren herzhaften Charakter behält.", "geschichte": "Erwtensoep, im Volksmund „snert“, ist die klassische niederländische Erbsensuppe und ein Inbegriff des winterlichen Wohlfühlessens der Niederlande. Sie ist berühmt für ihre außergewöhnliche Dicke — ein gutes snert ist so sämig, dass der Löffel aufrecht darin stehen bleiben soll. Grundlage sind getrocknete Spalterbsen, die mit Wurzelgemüse wie Sellerie, Lauch, Möhre und Kartoffel zu einem dichten Eintopf verkocht werden. Traditionell wird die Suppe mit Schweinefleisch und geräucherter Wurst (rookworst) zubereitet; in dieser Fassung ersetzen wir das Schwein durch eine geräucherte Rindwurst, sodass der prägende Rauchgeschmack erhalten bleibt. Erwtensoep ist eng mit der kalten Jahreszeit und besonders mit dem Schlittschuhlaufen auf zugefrorenen Grachten und Kanälen verbunden, wo sie traditionell zur Stärkung gereicht wurde. Serviert wird sie mit dunklem Roggenbrot. Die Suppe steht für die deftige, bodenständige Seite der niederländischen Küche.", "persoenlich": "", "servier": "", "tags": ["Niederlande", "Erwtensoep", "snert", "Erbsensuppe", "Spalterbsen", "Wurzelgemüse", "geräucherte Rindwurst", "Winterküche", "deftig", "Schlittschuhlaufen", "Wohlfühlessen", "Suppe"]}, {"id": "bitterballen", "status": "published", "date": "", "cover": "", "name": "Bitterballen", "land": "Niederlande", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Knusprig frittierte Kugeln mit einer cremigen, würzigen Rinderragout-Füllung, serviert mit Senf. Der klassische niederländische Borrel-Snack.", "zutaten": ["400 g gekochtes Rind- oder Kalbfleisch, fein zerzupft", "60 g Butter", "80 g Mehl", "500 ml kräftige Rinderbrühe", "1 Bund Petersilie", "2 Eier (zum Panieren)", "Mehl und Semmelbrösel zum Panieren", "Öl zum Frittieren, Salz, Pfeffer, Muskat; Senf zum Servieren"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "gekochtes Rind- oder Kalbfleisch, fein zerzupft", "roh": "400 g gekochtes Rind- oder Kalbfleisch, fein zerzupft"}, {"menge": 60.0, "einheit": "g", "item": "Butter", "roh": "60 g Butter"}, {"menge": 80.0, "einheit": "g", "item": "Mehl", "roh": "80 g Mehl"}, {"menge": 500.0, "einheit": "ml", "item": "kräftige Rinderbrühe", "roh": "500 ml kräftige Rinderbrühe"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": 2.0, "einheit": "", "item": "Eier (zum Panieren)", "roh": "2 Eier (zum Panieren)"}, {"menge": null, "einheit": "", "item": "Mehl und Semmelbrösel zum Panieren", "roh": "Mehl und Semmelbrösel zum Panieren"}, {"menge": null, "einheit": "", "item": "Öl zum Frittieren, Salz, Pfeffer, Muskat; Senf zum Servieren", "roh": "Öl zum Frittieren, Salz, Pfeffer, Muskat; Senf zum Servieren"}], "zubereitung": ["Aus Butter und Mehl eine Roux rühren, mit Brühe zu einer sehr dicken Sauce aufkochen.", "Fleisch und gehackte Petersilie einrühren, mit Salz, Pfeffer und Muskat kräftig würzen.", "Die Masse in einer Form mehrere Stunden kalt stellen, bis sie fest ist.", "Mit nassen Händen kleine Kugeln formen.", "Die Kugeln in Mehl, verquirltem Ei und Semmelbröseln panieren.", "In heißem Öl goldbraun und knusprig frittieren und heiß mit Senf servieren."], "hinweise": "Die Ragoutmasse muss vor dem Formen gut durchgekühlt und fest sein.\n\nDoppelt panieren gibt eine besonders stabile Kruste.\n\nVorsicht: Die Füllung wird sehr heiß.", "alternative": "", "geschichte": "Bitterballen sind der wohl bekannteste herzhafte Snack der Niederlande und ein fester Bestandteil der niederländischen „borrel“-Kultur — dem geselligen Beisammensein bei einem Getränk. Sie sind die runde Variante der Kroketten und bestehen aus einer dicken, abgekühlten und panierten Ragoutfüllung, die in heißem Öl knusprig frittiert wird. Die Füllung beruht auf einer kräftigen Mehlschwitze (Roux), gebunden mit Brühe und gewürzt mit Fleisch — klassisch zerzupftes Rindfleisch oder Kalb —, Petersilie und Muskat. Bitterballen werden heiß serviert, traditionell mit grobem Senf zum Dippen, und sind in Cafés, Bars und auf Feiern allgegenwärtig. Ihr Name wird mit dem früher dazu gereichten Kräuterbitter („bittertje“) in Verbindung gebracht. Als auf Rind- oder Kalbfleisch basierender Snack sind sie ohne Schweinefleisch zuzubereiten. Bitterballen verkörpern die gesellige, ungezwungene Seite der niederländischen Esskultur und gehören zu jedem Umtrunk.", "persoenlich": "", "servier": "", "tags": ["Niederlande", "Bitterballen", "Rind", "Kroketten", "frittiert", "borrel", "Snack", "Ragout", "Senf", "gesellig", "Café-Kultur", "Vorspeise"]}, {"id": "stroopwafels", "status": "published", "date": "", "cover": "", "name": "Stroopwafels", "land": "Niederlande", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Zwei dünne, knusprige Waffelscheiben, verklebt mit einer Schicht Karamellsirup. Die berühmte Sirupwaffel aus Gouda.", "zutaten": ["250 g Mehl", "125 g Butter", "80 g brauner Zucker", "1 Ei", "10 g Hefe (oder 1 TL Backpulver)", "1 TL Zimt", "200 g Sirup (z. B. Zuckerrübensirup)", "50 g Butter (Füllung)"], "zutatenS": [{"menge": 250.0, "einheit": "g", "item": "Mehl", "roh": "250 g Mehl"}, {"menge": 125.0, "einheit": "g", "item": "Butter", "roh": "125 g Butter"}, {"menge": 80.0, "einheit": "g", "item": "brauner Zucker", "roh": "80 g brauner Zucker"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 10.0, "einheit": "g", "item": "Hefe (oder 1 TL Backpulver)", "roh": "10 g Hefe (oder 1 TL Backpulver)"}, {"menge": 1.0, "einheit": "TL", "item": "Zimt", "roh": "1 TL Zimt"}, {"menge": 200.0, "einheit": "g", "item": "Sirup (z. B. Zuckerrübensirup)", "roh": "200 g Sirup (z. B. Zuckerrübensirup)"}, {"menge": 50.0, "einheit": "g", "item": "Butter (Füllung)", "roh": "50 g Butter (Füllung)"}], "zubereitung": ["Mehl, Butter, Zucker, Ei, Hefe und Zimt zu einem festen Teig verkneten und kurz ruhen lassen.", "Kleine Teigkugeln formen und im heißen Waffeleisen sehr dünn und knusprig backen.", "Die noch warmen Waffeln vorsichtig waagerecht halbieren.", "Für die Füllung Sirup mit Butter und etwas Zimt erwärmen, bis er streichfähig ist.", "Den Sirup auf eine Waffelhälfte streichen und mit der zweiten zusammensetzen.", "Kurz fest werden lassen; warm auf einer Tasse Kaffee oder Tee servieren."], "hinweise": "Die Waffeln müssen sehr dünn und knusprig sein.\n\nDas Halbieren gelingt nur, solange die Waffeln warm sind.\n\nAuf eine heiße Tasse gelegt, wird der Sirup herrlich weich.", "alternative": "", "geschichte": "Stroopwafels — Sirupwaffeln — sind eines der bekanntesten süßen Gebäcke der Niederlande und stammen ursprünglich aus der Stadt Gouda, wo sie im späten 18. oder frühen 19. Jahrhundert entstanden sein sollen. Der Überlieferung nach wurden sie von Bäckern aus Resten wie Bröseln und Sirup hergestellt, was ihnen den Ruf eines erschwinglichen Gebäcks der einfachen Leute einbrachte. Eine Stroopwafel besteht aus zwei dünnen, in einem speziellen Waffeleisen gebackenen Teigscheiben, die noch warm waagerecht aufgeschnitten und mit einer Schicht aus Karamellsirup (stroop) zusammengeklebt werden. Charakteristisch ist die Kombination aus knuspriger Waffel und zäh-süßer Sirupfüllung. Traditionell legt man die Stroopwafel auf eine dampfende Tasse Kaffee oder Tee, sodass die Wärme den Sirup leicht erweichen lässt. Heute werden sie auf Märkten frisch gebacken sowie abgepackt verkauft und sind ein niederländisches Wahrzeichen. Als süßes Gebäck sind sie selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Niederlande", "Stroopwafels", "Sirupwaffel", "Gouda", "Karamell", "süß", "vegetarisch", "Markt", "Kaffeegebäck", "Wahrzeichen", "stroop", "Dessert"]}, {"id": "tav-e-grav-e", "status": "published", "date": "", "cover": "", "name": "Tavče gravče", "land": "Nordmazedonien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Weiße Bohnen, in einer würzigen Paprika-Zwiebel-Sauce in der irdenen Pfanne gebacken. Das Nationalgericht Nordmazedoniens.", "zutaten": ["500 g weiße Bohnen, über Nacht eingeweicht", "3 Zwiebeln", "2 EL edelsüßes Paprikapulver", "1 TL getrocknete Minze", "1 rote Paprika", "5 EL Sonnenblumen- oder Olivenöl", "1 frische Chili (optional)", "Salz, Pfeffer"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "weiße Bohnen, über Nacht eingeweicht", "roh": "500 g weiße Bohnen, über Nacht eingeweicht"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln", "roh": "3 Zwiebeln"}, {"menge": 2.0, "einheit": "EL", "item": "edelsüßes Paprikapulver", "roh": "2 EL edelsüßes Paprikapulver"}, {"menge": 1.0, "einheit": "TL", "item": "getrocknete Minze", "roh": "1 TL getrocknete Minze"}, {"menge": 1.0, "einheit": "", "item": "rote Paprika", "roh": "1 rote Paprika"}, {"menge": 5.0, "einheit": "EL", "item": "Sonnenblumen- oder Olivenöl", "roh": "5 EL Sonnenblumen- oder Olivenöl"}, {"menge": 1.0, "einheit": "", "item": "frische Chili (optional)", "roh": "1 frische Chili (optional)"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}], "zubereitung": ["Die eingeweichten Bohnen in frischem Wasser etwa 1 Stunde weich, aber nicht zerfallen kochen; abgießen.", "Zwiebeln in Öl glasig dünsten, vom Herd ziehen und Paprikapulver einrühren.", "Bohnen mit den Zwiebeln, etwas Kochwasser, Minze, Salz und Pfeffer mischen.", "Alles in eine irdene Form geben, mit Paprikastreifen und Chili belegen.", "Im Ofen bei 200 °C 30–40 Minuten backen, bis die Flüssigkeit reduziert ist und sich oben eine Kruste bildet.", "Heiß direkt aus der Form mit Brot servieren."], "hinweise": "Die Bohnen vorgaren, aber nicht zerkochen — sie sollen Form behalten.\n\nPaprikapulver erst nach dem Herd einrühren, sonst wird es bitter.\n\nGetrocknete Minze ist die typische Würze.", "alternative": "", "geschichte": "Tavče gravče — wörtlich „Bohnen in der Pfanne“ — gilt als das Nationalgericht Nordmazedoniens und ist nach dem Tongefäß (tavče) benannt, in dem es zubereitet wird. Das Gericht beruht auf weißen Bohnen, einem Grundnahrungsmittel der Region, die zunächst gekocht und dann mit einer Sauce aus reichlich Zwiebeln, Paprikapulver und Kräutern in der irdenen Pfanne im Ofen gebacken werden, bis sich oben eine leicht krustige Schicht bildet. Bohnengerichte gehören seit Langem zur bodenständigen Küche des Balkans und boten eine günstige, nahrhafte Mahlzeit. Charakteristisch ist die kräftige Würze mit rotem Paprikapulver und getrockneter Minze. Während manche Varianten Wurst enthalten, ist die reine Bohnenfassung verbreitet und traditionell. Tavče gravče wird heiß direkt aus der Pfanne gegessen, oft mit Brot, und gehört sowohl zur Alltags- als auch zur Festtagsküche. Es ist von Natur aus vegetarisch und ohne Schweinefleisch und steht sinnbildlich für die einfache, herzhafte Küche Nordmazedoniens.", "persoenlich": "", "servier": "", "tags": ["Nordmazedonien", "Tavče gravče", "weiße Bohnen", "vegetarisch", "Paprika", "Ofengericht", "Balkan", "Nationalgericht", "irdene Pfanne", "Minze", "deftig", "Hauptgericht"]}, {"id": "ajvar", "status": "published", "date": "", "cover": "", "name": "Ajvar", "land": "Nordmazedonien", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine sämige Paste aus gerösteter roter Paprika und Aubergine, mit Knoblauch und Öl. Der Aufstrich- und Beilagenklassiker des Balkans.", "zutaten": ["2 kg rote Spitzpaprika", "1 Aubergine", "4 Zehen Knoblauch", "120 ml Sonnenblumen- oder Olivenöl", "2 EL Rotweinessig", "1 frische Chili (optional)", "Salz"], "zutatenS": [{"menge": 2.0, "einheit": "kg", "item": "rote Spitzpaprika", "roh": "2 kg rote Spitzpaprika"}, {"menge": 1.0, "einheit": "", "item": "Aubergine", "roh": "1 Aubergine"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "4 Zehen Knoblauch"}, {"menge": 120.0, "einheit": "ml", "item": "Sonnenblumen- oder Olivenöl", "roh": "120 ml Sonnenblumen- oder Olivenöl"}, {"menge": 2.0, "einheit": "EL", "item": "Rotweinessig", "roh": "2 EL Rotweinessig"}, {"menge": 1.0, "einheit": "", "item": "frische Chili (optional)", "roh": "1 frische Chili (optional)"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Paprika und Aubergine im Ofen oder über offener Flamme rundum rösten, bis die Haut schwarz wird.", "Abgedeckt ausdampfen lassen, dann häuten und entkernen.", "Das Fruchtfleisch fein hacken oder grob pürieren.", "Mit Knoblauch, Öl, Essig und Salz in einem Topf bei kleiner Hitze einkochen.", "Unter Rühren köcheln, bis eine dicke, glänzende Paste entsteht.", "Heiß in saubere Gläser füllen oder frisch als Beilage servieren."], "hinweise": "Gut gehäutete Paprika ergibt eine feine Paste ohne Hautstücke.\n\nGeduldig einkochen — Ajvar soll dick und konzentriert sein.\n\nIn sterilisierten Gläsern hält es monatelang.", "alternative": "", "geschichte": "Ajvar ist eine der bekanntesten Spezialitäten Nordmazedoniens und des gesamten Balkans und gilt vielerorts als Inbegriff der herbstlichen Vorratsküche. Die sämige Paste wird aus gerösteten roten Paprika hergestellt, oft ergänzt durch geröstete Aubergine, Knoblauch und Öl. Traditionell wird Ajvar im Spätsommer und Herbst in großen Mengen zubereitet, wenn Paprika reif und günstig ist — die gemeinsame Herstellung im Familien- und Nachbarschaftskreis ist ein soziales Ereignis. Die Paprika werden über offener Flamme oder im Ofen geröstet, gehäutet und mit Knoblauch und Öl zu einer Paste verkocht und schließlich in Gläsern haltbar gemacht, um auch im Winter Farbe und Aroma auf den Tisch zu bringen. Ajvar wird als Aufstrich, Beilage oder Dip gegessen, etwa zu Brot, gegrilltem Fleisch oder Käse. Je nach Rezept ist es mild oder scharf. Es ist von Natur aus vegan und ohne Schweinefleisch und steht für die Tradition, die Ernte zu konservieren.", "persoenlich": "", "servier": "", "tags": ["Nordmazedonien", "Ajvar", "Paprika", "Aubergine", "vegan", "vegetarisch", "Aufstrich", "Beilage", "Balkan", "Vorratsküche", "Herbst", "Dip"]}, {"id": "revani", "status": "published", "date": "", "cover": "", "name": "Revani", "land": "Nordmazedonien", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein saftiger Grießkuchen, nach dem Backen mit Zuckersirup getränkt. Süße Spezialität mit osmanischen Wurzeln.", "zutaten": ["200 g feiner Grieß", "100 g Mehl", "4 Eier", "150 g Zucker (Teig)", "100 ml Öl", "1 TL Backpulver", "1 Zitrone (Schale und Saft)", "300 g Zucker und 300 ml Wasser (Sirup)"], "zutatenS": [{"menge": 200.0, "einheit": "g", "item": "feiner Grieß", "roh": "200 g feiner Grieß"}, {"menge": 100.0, "einheit": "g", "item": "Mehl", "roh": "100 g Mehl"}, {"menge": 4.0, "einheit": "", "item": "Eier", "roh": "4 Eier"}, {"menge": 150.0, "einheit": "g", "item": "Zucker (Teig)", "roh": "150 g Zucker (Teig)"}, {"menge": 100.0, "einheit": "ml", "item": "Öl", "roh": "100 ml Öl"}, {"menge": 1.0, "einheit": "TL", "item": "Backpulver", "roh": "1 TL Backpulver"}, {"menge": 1.0, "einheit": "", "item": "Zitrone (Schale und Saft)", "roh": "1 Zitrone (Schale und Saft)"}, {"menge": 300.0, "einheit": "g", "item": "Zucker und 300 ml Wasser (Sirup)", "roh": "300 g Zucker und 300 ml Wasser (Sirup)"}], "zubereitung": ["Eier mit Zucker schaumig schlagen, Öl und Zitronenschale einrühren.", "Grieß, Mehl und Backpulver unterheben.", "Den Teig in eine gefettete Form geben und bei 180 °C 25–30 Minuten goldgelb backen.", "Aus Zucker, Wasser und Zitronensaft einen Sirup kochen.", "Den Sirup gleichmäßig über den noch warmen Kuchen gießen.", "Einige Stunden durchziehen lassen, in Rauten schneiden und servieren."], "hinweise": "Den Grieß im Teig sorgt für die typisch saftige Textur.\n\nHeißer Sirup auf warmen Kuchen zieht am besten ein.\n\nVor dem Servieren gut durchtränken lassen.", "alternative": "", "geschichte": "Revani (auch Ravani) ist ein süßer, sirupgetränkter Grießkuchen, der in Nordmazedonien, Griechenland, der Türkei und weiten Teilen des früheren osmanischen Raums verbreitet ist. Wie viele sirupbasierte Süßspeisen der Region geht er auf die osmanische Hofküche zurück, in der das Tränken von Gebäck mit Zucker- oder Honigsirup eine zentrale Technik war. Charakteristisch für Revani ist die Verwendung von Grieß im Teig, der dem Kuchen eine leicht körnige, saftige Textur verleiht und den Sirup besonders gut aufnimmt. Nach dem Backen wird der noch warme oder abgekühlte Kuchen mit einem aromatisierten Zuckersirup übergossen, sodass er durchtränkt und sehr saftig wird. Oft wird er mit Zitrone oder Orange aromatisiert und in Rauten geschnitten serviert. Revani gehört zu festlichen Anlässen, Gästebewirtung und der Süßspeisenkultur Nordmazedoniens. Als reiner Grieß-Zucker-Kuchen ist er selbstverständlich vegetarisch und ohne Schweinefleisch und spiegelt die ausgeprägte Vorliebe der Region für sirupgetränkte Backwaren wider.", "persoenlich": "", "servier": "", "tags": ["Nordmazedonien", "Revani", "Grießkuchen", "Sirup", "süß", "osmanisch geprägt", "Festtag", "vegetarisch", "Zitrone", "Balkan", "Gästegebäck", "Dessert"]}, {"id": "f-rik-l", "status": "published", "date": "", "cover": "", "name": "Fårikål", "land": "Norwegen", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein schlichter Eintopf aus Lamm bzw. Hammel und Weißkohl, geschichtet und mit ganzen Pfefferkörnern langsam geschmort. Norwegens Nationalgericht.", "zutaten": ["1.5 kg Lamm- oder Hammelfleisch mit Knochen, in Stücken", "1.5 kg Weißkohl", "2 EL ganze schwarze Pfefferkörner", "2 EL Mehl", "500 ml Wasser", "Salz", "Salzkartoffeln zum Servieren"], "zutatenS": [{"menge": 1.5, "einheit": "kg", "item": "Lamm- oder Hammelfleisch mit Knochen, in Stücken", "roh": "1.5 kg Lamm- oder Hammelfleisch mit Knochen, in Stücken"}, {"menge": 1.5, "einheit": "kg", "item": "Weißkohl", "roh": "1.5 kg Weißkohl"}, {"menge": 2.0, "einheit": "EL", "item": "ganze schwarze Pfefferkörner", "roh": "2 EL ganze schwarze Pfefferkörner"}, {"menge": 2.0, "einheit": "EL", "item": "Mehl", "roh": "2 EL Mehl"}, {"menge": 500.0, "einheit": "ml", "item": "Wasser", "roh": "500 ml Wasser"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}, {"menge": null, "einheit": "", "item": "Salzkartoffeln zum Servieren", "roh": "Salzkartoffeln zum Servieren"}], "zubereitung": ["Kohl in dicke Spalten schneiden.", "Fleisch und Kohl abwechselnd in einen großen Topf schichten, dabei mit Salz, Mehl und Pfefferkörnern bestreuen.", "Wasser angießen, bis der Topf zu etwa einem Drittel gefüllt ist.", "Zugedeckt aufkochen, dann bei kleiner Hitze 1,5–2 Stunden sehr sanft schmoren.", "Das Fleisch soll zart vom Knochen fallen und der Kohl mürbe sein.", "Mit Salzkartoffeln servieren."], "hinweise": "Die Pfefferkörner ganz lassen — sie würzen, ohne zu dominieren.\n\nLange, sanfte Garzeit ist entscheidend.\n\nAm nächsten Tag schmeckt Fårikål noch besser.", "alternative": "", "geschichte": "Fårikål — wörtlich „Schaf in Kohl“ — gilt als das Nationalgericht Norwegens und wird traditionell im Herbst gegessen, wenn Lamm geschlachtet wird und Kohl Saison hat. Das Gericht ist Inbegriff der schlichten, ehrlichen norwegischen Küche: In einem großen Topf werden Stücke von Lamm oder Hammel mit Knochen und Weißkohl in Schichten gelegt, mit ganzen schwarzen Pfefferkörnern, Salz und etwas Mehl bestreut und mit Wasser sehr lange sanft geschmort, bis das Fleisch zart vom Knochen fällt und der Kohl mürbe ist. Mehr braucht es nicht — die Zutaten sprechen für sich. Fårikål hat in Norwegen einen so hohen Stellenwert, dass ihm ein eigener Feiertag, der „Fårikålens dag“ am letzten Donnerstag im September, gewidmet ist. Das Gericht spiegelt die Bedeutung der Schafzucht und der einfachen Eintopfküche im kühlen Klima wider. Als reines Lamm-Kohl-Gericht ist es selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Norwegen", "Fårikål", "Lamm", "Hammel", "Weißkohl", "Eintopf", "Nationalgericht", "Herbst", "Skandinavien", "schlicht", "Schmorgericht", "Hauptgericht"]}, {"id": "gravlaks", "status": "published", "date": "", "cover": "", "name": "Gravlaks", "land": "Norwegen", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Lachsfilet, mehrere Tage in Salz, Zucker und Dill gebeizt, hauchdünn aufgeschnitten und mit süßer Senfsauce serviert. Skandinavische Delikatesse.", "zutaten": ["800 g Lachsfilet mit Haut (sehr frisch)", "60 g grobes Salz", "50 g Zucker", "2 Bund frischer Dill", "1 TL grob gemahlener weißer Pfeffer", "3 EL süßer Senf (Sauce)", "1 EL Weißweinessig, etwas Öl (Sauce)"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "Lachsfilet mit Haut (sehr frisch)", "roh": "800 g Lachsfilet mit Haut (sehr frisch)"}, {"menge": 60.0, "einheit": "g", "item": "grobes Salz", "roh": "60 g grobes Salz"}, {"menge": 50.0, "einheit": "g", "item": "Zucker", "roh": "50 g Zucker"}, {"menge": 2.0, "einheit": "Bund", "item": "frischer Dill", "roh": "2 Bund frischer Dill"}, {"menge": 1.0, "einheit": "TL", "item": "grob gemahlener weißer Pfeffer", "roh": "1 TL grob gemahlener weißer Pfeffer"}, {"menge": 3.0, "einheit": "EL", "item": "süßer Senf (Sauce)", "roh": "3 EL süßer Senf (Sauce)"}, {"menge": 1.0, "einheit": "EL", "item": "Weißweinessig, etwas Öl (Sauce)", "roh": "1 EL Weißweinessig, etwas Öl (Sauce)"}], "zubereitung": ["Salz, Zucker und Pfeffer mischen und das Lachsfilet rundum damit einreiben.", "Reichlich gehackten Dill auf das Fleisch legen.", "Den Lachs in Folie wickeln, in eine Form legen und mit einem Gewicht beschweren.", "2–3 Tage im Kühlschrank beizen, dabei täglich wenden.", "Für die Sauce Senf, Essig, etwas Zucker, Öl und Dill verrühren.", "Den Lachs trocken tupfen, hauchdünn aufschneiden und mit der Sauce und Brot servieren."], "hinweise": "Nur sehr frischen Lachs in Sushi-Qualität verwenden.\n\nDas Beschweren sorgt für eine feste Textur.\n\nSchräg und dünn aufschneiden für die beste Konsistenz.", "alternative": "", "geschichte": "Gravlaks (auch Gravad Lachs) ist eine traditionelle skandinavische Art, Lachs zu konservieren, und in Norwegen, Schweden und Dänemark gleichermaßen verbreitet. Der Name leitet sich von „graven Lachs“ ab — wörtlich „vergrabener Lachs“: Historisch wurde der Fisch von Fischern in Salz eingerieben und im Sand vergraben oder beschwert, um ihn durch milde Fermentation und Beizen haltbar zu machen. Die heutige Methode verzichtet auf das Vergraben und beizt den Lachs stattdessen mehrere Tage in einer Mischung aus Salz, Zucker und reichlich frischem Dill, beschwert im Kühlschrank, bis das Fleisch fest und aromatisch ist. Anschließend wird das Filet hauchdünn aufgeschnitten und klassisch mit einer süßlich-würzigen Senf-Dill-Sauce (hovmästarsås) sowie Brot serviert. Gravlaks gehört zu festlichen Anlässen, Buffets und der Weihnachtstafel Skandinaviens. Als reiner gebeizter Fisch ist er selbstverständlich ohne Schweinefleisch und zählt zu den elegantesten Spezialitäten der nordischen Küche.", "persoenlich": "", "servier": "", "tags": ["Norwegen", "Gravlaks", "Lachs", "gebeizt", "Dill", "Fisch", "Skandinavien", "Senfsauce", "Festtag", "Buffet", "nordisch", "Vorspeise"]}, {"id": "lefse", "status": "published", "date": "", "cover": "", "name": "Lefse", "land": "Norwegen", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Weiche Fladen aus Kartoffelteig, auf der Platte gebacken und süß mit Butter, Zucker und Zimt gefüllt. Traditionelles norwegisches Gebäck.", "zutaten": ["600 g mehligkochende Kartoffeln", "200 g Mehl", "50 g Butter", "60 ml Sahne", "1 Prise Salz", "Butter, Zucker und Zimt zum Füllen"], "zutatenS": [{"menge": 600.0, "einheit": "g", "item": "mehligkochende Kartoffeln", "roh": "600 g mehligkochende Kartoffeln"}, {"menge": 200.0, "einheit": "g", "item": "Mehl", "roh": "200 g Mehl"}, {"menge": 50.0, "einheit": "g", "item": "Butter", "roh": "50 g Butter"}, {"menge": 60.0, "einheit": "ml", "item": "Sahne", "roh": "60 ml Sahne"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}, {"menge": null, "einheit": "", "item": "Butter, Zucker und Zimt zum Füllen", "roh": "Butter, Zucker und Zimt zum Füllen"}], "zubereitung": ["Kartoffeln kochen, schälen und fein zerstampfen; vollständig auskühlen lassen.", "Mit Butter, Sahne und Salz vermengen, dann das Mehl unterarbeiten.", "Den Teig portionieren und sehr dünn rund ausrollen.", "Die Fladen auf einer heißen, trockenen Pfanne oder Platte beidseitig backen, bis sich helle Flecken bilden.", "Abkühlen lassen oder warm mit Butter bestreichen.", "Mit Zucker und Zimt bestreuen, zusammenrollen und servieren."], "hinweise": "Den Kartoffelteig erst kalt verarbeiten, dann lässt er sich dünn ausrollen.\n\nAuf einer trockenen, heißen Platte backen — ohne Fett.\n\nLefse hält sich gut und lässt sich später wieder erwärmen.", "alternative": "", "geschichte": "Lefse ist ein traditionelles norwegisches Fladengebäck mit langer Geschichte und zahlreichen regionalen Varianten. Besonders verbreitet ist die Kartoffel-Lefse (potetlefse), bei der gekochte, zerstampfte Kartoffeln mit Mehl, Butter und etwas Sahne zu einem Teig verarbeitet, sehr dünn ausgerollt und auf einer heißen, trockenen Platte (takke) gebacken werden. Die Kartoffel wurde in Norwegen zu einem zentralen Grundnahrungsmittel, und Lefse war eine Art, sie haltbar und vielseitig zu verwenden. Die weichen Fladen lassen sich gut lagern und wurden traditionell in größeren Mengen für den Vorrat und für Feste gebacken. Gegessen wird Lefse oft süß: mit Butter bestrichen und mit Zucker und Zimt bestreut, dann zusammengerollt oder gefaltet. Sie gehört zur Weihnachts- und Festtagsküche ebenso wie zum Alltag und ist in norwegischstämmigen Gemeinden bis heute ein Stück gelebter Tradition. Als Kartoffel-Mehl-Gebäck ist sie selbstverständlich vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Norwegen", "Lefse", "Kartoffelfladen", "vegetarisch", "Zimt", "Zucker", "Skandinavien", "Weihnachten", "Vorratsküche", "Fladenbrot", "süß", "Snack"]}, {"id": "wiener-schnitzel", "status": "published", "date": "", "cover": "", "name": "Wiener Schnitzel", "land": "Österreich", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine dünn geklopfte Kalbsschnitte in goldener, luftiger Panade, in Butterschmalz schwimmend ausgebacken. Wahrzeichen der Wiener Küche.", "zutaten": ["4 Kalbsschnitzel (je ca. 150 g)", "100 g Mehl", "2 Eier", "150 g Semmelbrösel", "200 g Butterschmalz (oder neutrales Öl)", "1 Zitrone", "Salz"], "zutatenS": [{"menge": 4.0, "einheit": "", "item": "Kalbsschnitzel (je ca. 150 g)", "roh": "4 Kalbsschnitzel (je ca. 150 g)"}, {"menge": 100.0, "einheit": "g", "item": "Mehl", "roh": "100 g Mehl"}, {"menge": 2.0, "einheit": "", "item": "Eier", "roh": "2 Eier"}, {"menge": 150.0, "einheit": "g", "item": "Semmelbrösel", "roh": "150 g Semmelbrösel"}, {"menge": 200.0, "einheit": "g", "item": "Butterschmalz (oder neutrales Öl)", "roh": "200 g Butterschmalz (oder neutrales Öl)"}, {"menge": 1.0, "einheit": "", "item": "Zitrone", "roh": "1 Zitrone"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Die Schnitzel zwischen Folie dünn klopfen und salzen.", "Drei Teller mit Mehl, verquirltem Ei und Semmelbröseln vorbereiten.", "Schnitzel zuerst in Mehl, dann durchs Ei ziehen und in Bröseln wenden, die Panade nur leicht andrücken.", "Reichlich Butterschmalz erhitzen, sodass das Schnitzel schwimmen kann.", "Bei mittlerer bis hoher Hitze backen und die Pfanne dabei schwenken, damit die Panade souffliert.", "Wenden, goldbraun fertig backen, abtropfen und mit Zitrone servieren."], "hinweise": "Genug Fett verwenden, damit das Schnitzel schwimmt — das lässt die Panade aufgehen.\n\nDie Panade nur leicht andrücken, nicht festpressen.\n\nSofort servieren, solange die Panade knusprig ist.", "alternative": "", "geschichte": "Das Wiener Schnitzel ist das bekannteste Gericht der österreichischen Küche und ein Symbol Wiens. Per Definition und nach österreichischem Recht besteht das echte Wiener Schnitzel aus Kalbfleisch; die Variante aus anderem Fleisch muss als „Schnitzel Wiener Art“ gekennzeichnet werden. Eine dünn geklopfte Kalbsschnitte wird in Mehl, verquirltem Ei und Semmelbröseln paniert und in reichlich heißem Butterschmalz oder Öl schwimmend ausgebacken, sodass die Panade luftig aufgeht und sich vom Fleisch leicht abhebt — das berühmte „Soufflieren“. Die Herkunft ist umstritten; eine verbreitete, allerdings nicht belegte Erzählung verbindet es mit der norditalienischen Cotoletta alla milanese. Spätestens im 19. Jahrhundert wurde das panierte Schnitzel zum festen Bestandteil der Wiener Küche. Serviert wird es klassisch mit Kartoffelsalat oder Petersilienkartoffeln und einer Zitronenspalte. Da das echte Wiener Schnitzel aus Kalb besteht, ist es von Natur aus ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Österreich", "Wien", "Wiener Schnitzel", "Kalb", "paniert", "Butterschmalz", "Klassiker", "Wahrzeichen", "Wiener Küche", "Zitrone", "festlich", "Hauptgericht"]}, {"id": "tafelspitz", "status": "published", "date": "", "cover": "", "name": "Tafelspitz", "land": "Österreich", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Zartes Rindfleisch, sanft in würziger Brühe gekocht, serviert mit Apfel-Kren und Röstkartoffeln. Ein Klassiker der Wiener bürgerlichen Küche.", "zutaten": ["1.2 kg Tafelspitz (Rind)", "2 Möhren", "0.5 Knollensellerie", "1 Lauchstange, 1 Zwiebel", "1 TL Pfefferkörner, 1 Lorbeerblatt, Liebstöckel", "1 Apfel und 100 g Meerrettich (Apfelkren)", "Salz; Kartoffeln und Schnittlauch zum Servieren"], "zutatenS": [{"menge": 1.2, "einheit": "kg", "item": "Tafelspitz (Rind)", "roh": "1.2 kg Tafelspitz (Rind)"}, {"menge": 2.0, "einheit": "", "item": "Möhren", "roh": "2 Möhren"}, {"menge": 0.5, "einheit": "", "item": "Knollensellerie", "roh": "0.5 Knollensellerie"}, {"menge": 1.0, "einheit": "", "item": "Lauchstange, 1 Zwiebel", "roh": "1 Lauchstange, 1 Zwiebel"}, {"menge": 1.0, "einheit": "TL", "item": "Pfefferkörner, 1 Lorbeerblatt, Liebstöckel", "roh": "1 TL Pfefferkörner, 1 Lorbeerblatt, Liebstöckel"}, {"menge": 1.0, "einheit": "", "item": "Apfel und 100 g Meerrettich (Apfelkren)", "roh": "1 Apfel und 100 g Meerrettich (Apfelkren)"}, {"menge": null, "einheit": "", "item": "Salz; Kartoffeln und Schnittlauch zum Servieren", "roh": "Salz; Kartoffeln und Schnittlauch zum Servieren"}], "zubereitung": ["Eine halbierte Zwiebel ohne Fett dunkel anrösten (für Farbe und Aroma).", "Tafelspitz in siedendes Wasser geben, abschäumen und salzen.", "Geröstete Zwiebel, grob geschnittenes Wurzelgemüse und Gewürze zugeben.", "Bei sehr kleiner Hitze 2,5–3 Stunden gar ziehen lassen, nicht sprudelnd kochen.", "Für den Apfelkren Apfel und Meerrettich fein reiben und mischen.", "Das Fleisch quer zur Faser aufschneiden und mit Brühe, Apfelkren und Röstkartoffeln servieren."], "hinweise": "Die Brühe nur ziehen lassen — sprudelndes Kochen macht das Fleisch zäh.\n\nQuer zur Faser schneiden für zarte Scheiben.\n\nDie Suppe vorab mit Einlage als eigenen Gang servieren.", "alternative": "", "geschichte": "Tafelspitz ist ein klassisches Gericht der Wiener Küche und benannt nach dem gleichnamigen Teilstück des Rindfleischs, einem mageren, zarten Stück aus der Hüfte. Das in Brühe gekochte Rindfleisch hat in Wien eine besonders ehrwürdige Tradition und war ein Lieblingsessen des Kaisers Franz Joseph I., was zu seinem Ruf als Gericht der bürgerlich-höfischen Küche beitrug. Das Fleisch wird zusammen mit Wurzelgemüse und Gewürzen sehr sanft in Wasser gegart, bis es zart ist; die dabei entstehende kräftige Rindsuppe wird oft als eigener Gang mit Einlage vorab serviert. Der Tafelspitz selbst wird in Scheiben quer zur Faser geschnitten und klassisch mit Apfelkren (geriebener Meerrettich mit Apfel), Schnittlauchsauce und Rösterdäpfeln (Röstkartoffeln) gereicht. Das Gericht verkörpert die Wiener Tradition der Rindfleischküche, die zahlreiche Teilstücke unterscheidet und schätzt. Als reines Rindfleischgericht ist Tafelspitz von Natur aus ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Österreich", "Wien", "Tafelspitz", "Rind", "gekocht", "Rindsuppe", "Apfelkren", "Meerrettich", "bürgerliche Küche", "Klassiker", "Kaiser Franz Joseph", "Hauptgericht"]}, {"id": "sachertorte", "status": "published", "date": "", "cover": "", "name": "Sachertorte", "land": "Österreich", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine dichte Schokoladentorte mit einer Schicht Marillenmarmelade unter einer dunklen Schokoladenglasur. Wiens berühmteste Torte.", "zutaten": ["140 g Zartbitterschokolade", "140 g Butter", "110 g Puderzucker", "6 Eier (getrennt)", "140 g Mehl", "200 g Marillenmarmelade (Aprikose)", "200 g Schokolade und 150 g Zucker (Glasur)"], "zutatenS": [{"menge": 140.0, "einheit": "g", "item": "Zartbitterschokolade", "roh": "140 g Zartbitterschokolade"}, {"menge": 140.0, "einheit": "g", "item": "Butter", "roh": "140 g Butter"}, {"menge": 110.0, "einheit": "g", "item": "Puderzucker", "roh": "110 g Puderzucker"}, {"menge": 6.0, "einheit": "", "item": "Eier (getrennt)", "roh": "6 Eier (getrennt)"}, {"menge": 140.0, "einheit": "g", "item": "Mehl", "roh": "140 g Mehl"}, {"menge": 200.0, "einheit": "g", "item": "Marillenmarmelade (Aprikose)", "roh": "200 g Marillenmarmelade (Aprikose)"}, {"menge": 200.0, "einheit": "g", "item": "Schokolade und 150 g Zucker (Glasur)", "roh": "200 g Schokolade und 150 g Zucker (Glasur)"}], "zubereitung": ["Geschmolzene Schokolade mit Butter und Puderzucker schaumig rühren, Eigelbe einrühren.", "Eiweiß steif schlagen, mit dem Mehl abwechselnd unter die Masse heben.", "In einer Springform bei 170 °C etwa 50–60 Minuten backen; auskühlen lassen.", "Den Boden einmal durchschneiden, mit erwärmter Marillenmarmelade bestreichen und zusammensetzen, außen dünn mit Marmelade überziehen.", "Für die Glasur Zucker mit Wasser aufkochen, Schokolade darin schmelzen und glatt rühren.", "Die Torte mit der Glasur überziehen, fest werden lassen und mit Schlagobers servieren."], "hinweise": "Die Marmelade durch ein Sieb streichen für eine glatte Schicht.\n\nDie Glasur in einem Guss auftragen, dann wird sie spiegelglatt.\n\nMit ungesüßtem Schlagobers servieren — er balanciert die Süße.", "alternative": "", "geschichte": "Die Sachertorte ist die wohl berühmteste Torte Österreichs und ein Wahrzeichen Wiens. Sie wurde 1832 vom damals erst sechzehnjährigen Franz Sacher erfunden, der als Lehrling am Hof des Fürsten Metternich ein Dessert für hohe Gäste kreieren sollte. Sein Sohn Eduard Sacher verfeinerte das Rezept später, und die Torte wurde im von ihm gegründeten Hotel Sacher zum Mythos. Charakteristisch ist die Kombination aus einem dichten, nicht zu süßen Schokoladenbiskuit, einer Schicht Marillenmarmelade (Aprikosenkonfitüre) und einer glänzenden, dunklen Schokoladenglasur. Über die „echte“ Sachertorte und die Frage, ob die Marmelade nur unter der Glasur oder auch in der Mitte liegt, gab es sogar einen jahrelangen Rechtsstreit zwischen dem Hotel Sacher und der Konditorei Demel. Serviert wird die Torte klassisch mit ungesüßtem Schlagobers (Schlagsahne). Als Schokoladen-Süßspeise ist sie selbstverständlich vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Österreich", "Wien", "Sachertorte", "Schokolade", "Marillenmarmelade", "Torte", "süß", "vegetarisch", "Kaffeehaus", "Klassiker", "Hotel Sacher", "Dessert"]}, {"id": "pierogi-ruskie", "status": "published", "date": "", "cover": "", "name": "Pierogi ruskie", "land": "Polen", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Gefüllte Teigtaschen mit Kartoffel und Quark, gekocht und mit Butter und Zwiebeln serviert. Polens beliebteste Pierogi-Variante.", "zutaten": ["400 g Mehl", "1 Ei", "180 ml warmes Wasser", "500 g gekochte Kartoffeln", "250 g Quark/Topfen (twaróg)", "2 Zwiebeln", "50 g Butter", "Salz, Pfeffer"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Mehl", "roh": "400 g Mehl"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 180.0, "einheit": "ml", "item": "warmes Wasser", "roh": "180 ml warmes Wasser"}, {"menge": 500.0, "einheit": "g", "item": "gekochte Kartoffeln", "roh": "500 g gekochte Kartoffeln"}, {"menge": 250.0, "einheit": "g", "item": "Quark/Topfen (twaróg)", "roh": "250 g Quark/Topfen (twaróg)"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 50.0, "einheit": "g", "item": "Butter", "roh": "50 g Butter"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}], "zubereitung": ["Mehl, Ei, Wasser und Salz zu einem geschmeidigen Teig kneten und ruhen lassen.", "Eine Zwiebel würfeln, anbraten und mit den zerdrückten Kartoffeln und Quark zu einer Füllung mischen, würzen.", "Den Teig dünn ausrollen und Kreise ausstechen.", "Je etwas Füllung daraufsetzen, zu Halbmonden falten und die Ränder fest verschließen.", "In siedendem Salzwasser kochen, bis die Pierogi aufschwimmen, dann noch 2 Minuten ziehen lassen.", "Mit in Butter gerösteten Zwiebeln servieren."], "hinweise": "Die Ränder gut verschließen, damit keine Füllung austritt.\n\nGekochte Pierogi anschließend in Butter schwenken für mehr Aroma.\n\nReste lassen sich am nächsten Tag knusprig anbraten.", "alternative": "", "geschichte": "Pierogi gehören zu den bekanntesten Gerichten der polnischen Küche, und die Variante „pierogi ruskie“ — wörtlich „ruthenische Pierogi“ — ist eine der beliebtesten. Der Name verweist nicht auf Russland, sondern auf die historische Region Ruthenien (heute Grenzgebiet zwischen Polen und der Ukraine), aus der die Füllung stammt. Gefüllt werden die halbmondförmigen Teigtaschen mit einer Mischung aus gekochten Kartoffeln und Quark oder Topfen (twaróg), gewürzt mit gebratenen Zwiebeln. Pierogi haben in Polen eine lange Tradition und gehören sowohl zur Alltagsküche als auch zu Festtagen, etwa Weihnachten. Der dünn ausgerollte Teig wird mit der Füllung gefüllt, sorgfältig verschlossen und in Salzwasser gekocht; anschließend werden die Pierogi oft in Butter geschwenkt und mit gerösteten Zwiebeln serviert. Pierogi ruskie sind von Natur aus vegetarisch und ohne Schweinefleisch und gelten als gemütliches, sättigendes Wohlfühlessen, das in vielen polnischen Haushalten von Hand zubereitet wird.", "persoenlich": "", "servier": "", "tags": ["Polen", "Pierogi", "pierogi ruskie", "Teigtaschen", "Kartoffel", "Quark", "vegetarisch", "Röstzwiebeln", "Weihnachten", "Wohlfühlessen", "twaróg", "Hauptgericht"]}, {"id": "bigos", "status": "published", "date": "", "cover": "", "name": "Bigos", "land": "Polen", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Der „Jägereintopf“ aus Sauerkraut und Weißkohl, langsam mit Rindfleisch, geräucherter Rindwurst und Trockenpflaumen geschmort. Polens herzhaftes Nationalgericht.", "zutaten": ["700 g Sauerkraut", "500 g Weißkohl", "500 g Rindfleisch zum Schmoren", "300 g geräucherte Rindwurst", "30 g getrocknete Pilze", "8 Trockenpflaumen", "2 Zwiebeln, 2 Lorbeerblätter, Piment, Wacholder", "Öl, Salz, Pfeffer"], "zutatenS": [{"menge": 700.0, "einheit": "g", "item": "Sauerkraut", "roh": "700 g Sauerkraut"}, {"menge": 500.0, "einheit": "g", "item": "Weißkohl", "roh": "500 g Weißkohl"}, {"menge": 500.0, "einheit": "g", "item": "Rindfleisch zum Schmoren", "roh": "500 g Rindfleisch zum Schmoren"}, {"menge": 300.0, "einheit": "g", "item": "geräucherte Rindwurst", "roh": "300 g geräucherte Rindwurst"}, {"menge": 30.0, "einheit": "g", "item": "getrocknete Pilze", "roh": "30 g getrocknete Pilze"}, {"menge": 8.0, "einheit": "", "item": "Trockenpflaumen", "roh": "8 Trockenpflaumen"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, 2 Lorbeerblätter, Piment, Wacholder", "roh": "2 Zwiebeln, 2 Lorbeerblätter, Piment, Wacholder"}, {"menge": null, "einheit": "", "item": "Öl, Salz, Pfeffer", "roh": "Öl, Salz, Pfeffer"}], "zubereitung": ["Getrocknete Pilze einweichen; Rindfleisch würfeln und kräftig anbraten.", "Zwiebeln andünsten, Sauerkraut und in Streifen geschnittenen Weißkohl zugeben.", "Fleisch, eingeweichte Pilze (mit Wasser), Trockenpflaumen und Gewürze zugeben.", "Zugedeckt bei kleiner Hitze mindestens 2 Stunden schmoren, gelegentlich umrühren.", "Die in Scheiben geschnittene Rindwurst zugeben und mitschmoren.", "Mit Salz und Pfeffer abschmecken; am besten an den Folgetagen erneut aufwärmen und mit Brot servieren."], "hinweise": "Bigos wird durch mehrfaches Aufwärmen über Tage immer besser.\n\nGetrocknete Pilze und Pflaumen geben Tiefe und eine dezente Süße.\n\nGeduldig und lange schmoren ist der Schlüssel.", "alternative": "Klassischer Bigos enthält verschiedene Schweinefleischsorten und Schweinewurst (kiełbasa). Wir verwenden stattdessen Rindfleisch und geräucherte Rindwurst; getrocknete Pilze und Trockenpflaumen sorgen für zusätzliche Tiefe, sodass der herzhafte, rauchige Charakter ohne Schwein erhalten bleibt.", "geschichte": "Bigos, oft als „Jägereintopf“ übersetzt, gilt als eines der Nationalgerichte Polens und hat eine lange Geschichte in der polnischen und litauischen Adelsküche, wo es seit Jahrhunderten in Liedern und Literatur verewigt ist. Grundlage sind Sauerkraut und frischer Weißkohl, die zusammen mit Fleisch, Zwiebeln, getrockneten Pilzen, Trockenpflaumen und Gewürzen über lange Zeit geschmort werden. Charakteristisch ist, dass Bigos durch mehrfaches Aufwärmen über mehrere Tage immer besser wird, da sich die Aromen verbinden und vertiefen — traditionell kochte man große Mengen vor. Üblicherweise enthält Bigos verschiedene Schweinefleischsorten und -würste; in dieser Fassung verwenden wir Rindfleisch und geräucherte Rindwurst, sodass die herzhaft-rauchige Tiefe und der Charakter des Gerichts ohne Schwein erhalten bleiben. Bigos wird besonders in der kalten Jahreszeit und zu Festen wie Weihnachten gegessen und mit Brot oder Kartoffeln serviert. Es verkörpert die deftige, geduldige Schmorküche Polens.", "persoenlich": "", "servier": "", "tags": ["Polen", "Bigos", "Jägereintopf", "Sauerkraut", "Weißkohl", "Rind", "geräucherte Rindwurst", "Trockenpflaumen", "Winterküche", "Nationalgericht", "Schmorgericht", "Hauptgericht"]}, {"id": "sernik", "status": "published", "date": "", "cover": "", "name": "Sernik", "land": "Polen", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein dichter, cremiger Käsekuchen aus polnischem Quark (twaróg), oft mit Rosinen oder Zitrusaroma. Die polnische Käsekuchentradition.", "zutaten": ["1 kg Quark (twaróg, fettreich)", "200 g Zucker", "5 Eier", "80 g Butter, weich", "2 EL Speisestärke", "1 Zitrone (Schale) oder Vanille", "200 g Mürbeteig (Boden)", "60 g Rosinen (optional)"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "Quark (twaróg, fettreich)", "roh": "1 kg Quark (twaróg, fettreich)"}, {"menge": 200.0, "einheit": "g", "item": "Zucker", "roh": "200 g Zucker"}, {"menge": 5.0, "einheit": "", "item": "Eier", "roh": "5 Eier"}, {"menge": 80.0, "einheit": "g", "item": "Butter, weich", "roh": "80 g Butter, weich"}, {"menge": 2.0, "einheit": "EL", "item": "Speisestärke", "roh": "2 EL Speisestärke"}, {"menge": 1.0, "einheit": "", "item": "Zitrone (Schale) oder Vanille", "roh": "1 Zitrone (Schale) oder Vanille"}, {"menge": 200.0, "einheit": "g", "item": "Mürbeteig (Boden)", "roh": "200 g Mürbeteig (Boden)"}, {"menge": 60.0, "einheit": "g", "item": "Rosinen (optional)", "roh": "60 g Rosinen (optional)"}], "zubereitung": ["Den Mürbeteigboden in eine Form drücken und kurz vorbacken.", "Quark mehrmals durch ein Sieb streichen oder pürieren, damit er fein wird.", "Butter mit Zucker schaumig rühren, Eigelbe und Quark einarbeiten, Stärke und Aroma zugeben.", "Eiweiß steif schlagen und vorsichtig unterheben; nach Wunsch Rosinen zugeben.", "Die Masse auf den Boden geben und bei 160 °C etwa 60–70 Minuten backen.", "Im ausgeschalteten Ofen langsam abkühlen lassen, damit der Kuchen nicht reißt."], "hinweise": "Fettreichen Quark verwenden und gut passieren — das macht die Creme fein.\n\nLangsames Abkühlen im Ofen verhindert Risse.\n\nAm besten gekühlt am nächsten Tag servieren.", "alternative": "", "geschichte": "Sernik ist der polnische Käsekuchen und eines der beliebtesten Desserts des Landes mit einer langen Tradition. Anders als der mit Frischkäse zubereitete amerikanische Cheesecake beruht der echte Sernik auf einem speziellen, fettreichen Quark (twaróg ser), der dem Kuchen seine charakteristisch dichte, zugleich cremige und leicht körnige Textur gibt. Käsekuchen aus Quark haben in Polen und Mitteleuropa eine lange Geschichte; eine berühmte regionale Variante ist der „sernik krakowski“ aus Krakau mit einem charakteristischen Teiggitter. Der Quark wird mit Eiern, Zucker und oft etwas Zitronen- oder Vanillearoma zu einer Masse verrührt, häufig auf einem Mürbeteigboden gebacken und gelegentlich mit Rosinen verfeinert. Sernik gehört zu Feiertagen wie Ostern und Weihnachten ebenso wie zur sonntäglichen Kaffeetafel und wird in vielen Haushalten nach überliefertem Familienrezept gebacken. Als Quark-Süßspeise ist er selbstverständlich vegetarisch und ohne Schweinefleisch und gilt als Inbegriff polnischer Backtradition.", "persoenlich": "", "servier": "", "tags": ["Polen", "Sernik", "Käsekuchen", "Quark", "twaróg", "süß", "vegetarisch", "Ostern", "Weihnachten", "Kaffeetafel", "Backtradition", "Dessert"]}, {"id": "bacalhau-br-s", "status": "published", "date": "", "cover": "", "name": "Bacalhau à brás", "land": "Portugal", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Zerzupfter Stockfisch mit dünnen Kartoffelstäbchen und Zwiebeln, gebunden mit Ei und bestreut mit Oliven und Petersilie. Lissabonner Klassiker.", "zutaten": ["500 g Stockfisch (bacalhau), gewässert und zerzupft", "600 g Kartoffeln (in dünne Stäbchen geschnitten)", "2 Zwiebeln", "6 Eier", "100 g schwarze Oliven", "1 Bund Petersilie", "3 Zehen Knoblauch", "Olivenöl, Salz, Pfeffer"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Stockfisch (bacalhau), gewässert und zerzupft", "roh": "500 g Stockfisch (bacalhau), gewässert und zerzupft"}, {"menge": 600.0, "einheit": "g", "item": "Kartoffeln (in dünne Stäbchen geschnitten)", "roh": "600 g Kartoffeln (in dünne Stäbchen geschnitten)"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 6.0, "einheit": "", "item": "Eier", "roh": "6 Eier"}, {"menge": 100.0, "einheit": "g", "item": "schwarze Oliven", "roh": "100 g schwarze Oliven"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "3 Zehen Knoblauch"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer", "roh": "Olivenöl, Salz, Pfeffer"}], "zubereitung": ["Die Kartoffelstäbchen in Öl knusprig frittieren und abtropfen lassen.", "Zwiebeln und Knoblauch in Olivenöl glasig dünsten.", "Den zerzupften Stockfisch zugeben und kurz mitbraten.", "Die frittierten Kartoffeln unterheben.", "Verquirlte Eier angießen und bei kleiner Hitze rühren, bis die Masse cremig bindet (nicht fest stocken).", "Mit Oliven und reichlich Petersilie bestreut sofort servieren."], "hinweise": "Den Stockfisch ausreichend wässern, sonst wird es zu salzig.\n\nDas Ei nur cremig binden lassen, nicht durchgaren.\n\nSofort servieren, solange es cremig ist.", "alternative": "", "geschichte": "Bacalhau à brás ist eines der bekanntesten Gerichte der portugiesischen Küche und stammt aus Lissabon, traditionell aus dem Stadtviertel Bairro Alto. Es gehört zur immensen Familie der portugiesischen Bacalhau-Gerichte: Getrockneter und gesalzener Kabeljau (bacalhau) ist seit Jahrhunderten ein nationales Grundnahrungsmittel und kulturelles Symbol Portugals, obwohl der Fisch aus fernen Gewässern stammt — man sagt, es gebe für jeden Tag des Jahres ein Bacalhau-Rezept. Für à brás wird der gewässerte, zerzupfte Stockfisch mit fein geschnittenen, frittierten Kartoffelstäbchen (oder Strohkartoffeln) und gedünsteten Zwiebeln vermengt und mit verquirltem Ei gebunden, das die Masse cremig zusammenhält, ohne fest zu stocken. Garniert wird mit schwarzen Oliven und frischer Petersilie. Das Gericht ist eine clevere, sättigende Art, Stockfisch zu verwerten, und gehört zur Alltags- wie Wohlfühlküche. Als Fisch-Ei-Kartoffel-Gericht ist es selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Portugal", "Lissabon", "Bacalhau à brás", "Stockfisch", "Kabeljau", "Fisch", "Kartoffeln", "Ei", "Oliven", "Klassiker", "Wohlfühlessen", "Hauptgericht"]}, {"id": "caldo-verde", "status": "published", "date": "", "cover": "", "name": "Caldo verde", "land": "Portugal", "kontinent": "Europa", "gang": "Suppe", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine grüne Suppe aus Kartoffelpüree und feinen Streifen von Grünkohl, vollendet mit gutem Olivenöl. Portugals beliebteste Suppe, hier ohne Schwein.", "zutaten": ["500 g mehligkochende Kartoffeln", "300 g Grünkohl (sehr fein geschnitten)", "1 Zwiebel", "3 Zehen Knoblauch", "1.2 l Gemüsebrühe", "6 EL Olivenöl extra vergine", "1 geräucherte Rindwurst (optional)", "Salz, Pfeffer; Maisbrot zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "mehligkochende Kartoffeln", "roh": "500 g mehligkochende Kartoffeln"}, {"menge": 300.0, "einheit": "g", "item": "Grünkohl (sehr fein geschnitten)", "roh": "300 g Grünkohl (sehr fein geschnitten)"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "3 Zehen Knoblauch"}, {"menge": 1.2, "einheit": "l", "item": "Gemüsebrühe", "roh": "1.2 l Gemüsebrühe"}, {"menge": 6.0, "einheit": "EL", "item": "Olivenöl extra vergine", "roh": "6 EL Olivenöl extra vergine"}, {"menge": 1.0, "einheit": "", "item": "geräucherte Rindwurst (optional)", "roh": "1 geräucherte Rindwurst (optional)"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer; Maisbrot zum Servieren", "roh": "Salz, Pfeffer; Maisbrot zum Servieren"}], "zubereitung": ["Zwiebel und Knoblauch in etwas Olivenöl andünsten.", "Gewürfelte Kartoffeln zugeben, mit Brühe auffüllen und weich kochen.", "Die Suppe fein pürieren, bis eine sämige Basis entsteht; salzen und pfeffern.", "Den sehr fein geschnittenen Grünkohl einrühren und nur 4–5 Minuten mitgaren, damit er grün bleibt.", "Optional eine geräucherte Rindwurst in Scheiben kurz mitziehen lassen.", "Mit einem großzügigen Schuss Olivenöl und Maisbrot servieren."], "hinweise": "Den Grünkohl so fein wie möglich schneiden — das ist typisch.\n\nNur kurz mitgaren, damit die Suppe leuchtend grün bleibt.\n\nEin gutes Olivenöl zum Schluss macht den Geschmack aus.", "alternative": "Caldo verde wird klassisch mit Scheiben portugiesischer Schweinewurst (chouriço) zubereitet. Wir lassen diese weg; die herzhafte Tiefe kommt aus Knoblauch, gutem Olivenöl und der Kartoffelbasis. Wer mag, gibt eine geräucherte Rindwurst statt chouriço hinein.", "geschichte": "Caldo verde — „grüne Brühe“ — gilt als eine der beliebtesten und bekanntesten Suppen Portugals und stammt ursprünglich aus der nördlichen Region Minho. Die Grundlage ist denkbar einfach und bäuerlich: Kartoffeln werden mit Zwiebel und Knoblauch weich gekocht und zu einer sämigen Basis püriert, in die anschließend hauchfein geschnittener Grünkohl (couve galega) gegeben und nur kurz mitgegart wird, damit er seine Farbe behält. Ein großzügiger Schuss gutes Olivenöl rundet die Suppe ab. Traditionell wird Caldo verde mit Scheiben einer geräucherten Wurst (chouriço) und mit Maisbrot (broa) serviert; in dieser Fassung verzichten wir auf die Schweinewurst und holen die herzhafte Tiefe aus Olivenöl, Knoblauch und einer kräftigen Gemüsebasis, optional mit einer geräucherten Rindwurst. Caldo verde gehört in Portugal zu Festen, Hochzeiten und der Alltagsküche gleichermaßen und steht für die schlichte, gemüsebetonte Seite der portugiesischen Küche.", "persoenlich": "", "servier": "", "tags": ["Portugal", "Minho", "Caldo verde", "Grünkohl", "Kartoffeln", "Suppe", "vegetarisch", "Olivenöl", "Landküche", "Festtag", "geräucherte Rindwurst", "Wohlfühlessen"]}, {"id": "past-is-de-nata", "status": "published", "date": "", "cover": "", "name": "Pastéis de nata", "land": "Portugal", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine Blätterteigtörtchen mit cremiger Eier-Vanille-Füllung und karamellisierter Oberfläche. Portugals berühmtestes Gebäck.", "zutaten": ["1 Rolle Blätterteig", "500 ml Milch", "6 Eigelb", "200 g Zucker", "40 g Mehl oder Stärke", "1 Zimtstange und 1 Stück Zitronenschale", "Zimt und Puderzucker zum Servieren"], "zutatenS": [{"menge": 1.0, "einheit": "Rolle", "item": "Blätterteig", "roh": "1 Rolle Blätterteig"}, {"menge": 500.0, "einheit": "ml", "item": "Milch", "roh": "500 ml Milch"}, {"menge": 6.0, "einheit": "", "item": "Eigelb", "roh": "6 Eigelb"}, {"menge": 200.0, "einheit": "g", "item": "Zucker", "roh": "200 g Zucker"}, {"menge": 40.0, "einheit": "g", "item": "Mehl oder Stärke", "roh": "40 g Mehl oder Stärke"}, {"menge": 1.0, "einheit": "", "item": "Zimtstange und 1 Stück Zitronenschale", "roh": "1 Zimtstange und 1 Stück Zitronenschale"}, {"menge": null, "einheit": "", "item": "Zimt und Puderzucker zum Servieren", "roh": "Zimt und Puderzucker zum Servieren"}], "zubereitung": ["Milch mit Zimtstange und Zitronenschale erwärmen; ziehen lassen und abseihen.", "Zucker, Mehl und Eigelbe verrühren, die warme Milch einrühren und zu einer Creme einkochen; abkühlen lassen.", "Blätterteig fest aufrollen, in Scheiben schneiden und in Muffinförmchen zu Mulden ausdrücken.", "Die Creme in die Teigmulden füllen.", "Bei sehr hoher Hitze (möglichst 250 °C) backen, bis Teig knusprig ist und die Oberfläche dunkle Flecken bekommt.", "Lauwarm mit etwas Zimt und Puderzucker servieren."], "hinweise": "Sehr hohe Hitze erzeugt die typischen karamellisierten Flecken.\n\nDie Creme darf nicht zu fest werden — sie soll cremig bleiben.\n\nLauwarm schmecken Pastéis de nata am besten.", "alternative": "", "geschichte": "Pastéis de nata sind die berühmtesten Süßgebäcke Portugals und international ein Wahrzeichen der portugiesischen Küche. Ihren Ursprung haben sie im Hieronymitenkloster (Mosteiro dos Jerónimos) im Lissabonner Stadtteil Belém, wo Mönche schon vor dem 18. Jahrhundert die Törtchen herstellten. Klöster nutzten große Mengen Eigelb — Eiweiß diente unter anderem zum Stärken von Wäsche und zum Klären von Wein —, woraus zahlreiche eigelbreiche Süßspeisen entstanden. Nach der Auflösung der Klöster wurde das Rezept 1837 an eine nahegelegene Zuckerraffinerie verkauft, aus der die bis heute bestehende „Fábrica de Pastéis de Belém“ hervorging, deren Originalrezept als Geheimnis gilt; diese Törtchen heißen geschützt „Pastéis de Belém“. Charakteristisch sind der knusprige, vielschichtige Blätterteig und die cremige Eiercreme, die bei sehr hoher Hitze gebacken wird, bis die Oberfläche dunkle, karamellisierte Flecken bekommt. Serviert werden sie lauwarm, oft mit Zimt und Puderzucker. Als reines Teig-Ei-Gebäck sind sie selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Portugal", "Lissabon", "Belém", "Pastéis de nata", "Blätterteig", "Eiercreme", "süß", "vegetarisch", "Klostergebäck", "Wahrzeichen", "Zimt", "Dessert"]}, {"id": "mici", "status": "published", "date": "", "cover": "", "name": "Mici", "land": "Rumänien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine, fingerförmige Grillröllchen aus gewürztem Rind- und Lammhack, über Holzkohle gebraten und mit Senf serviert. Rumäniens beliebtestes Grillgericht.", "zutaten": ["500 g Rinderhack", "300 g Lammhack", "4 Zehen Knoblauch, fein gerieben", "1 TL gemahlener Kreuzkümmel", "0.5 TL Natron", "100 ml Rinderbrühe (kalt)", "1 TL Pfeffer, 1 TL Salz, Prise Piment", "Senf und Brot zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Rinderhack", "roh": "500 g Rinderhack"}, {"menge": 300.0, "einheit": "g", "item": "Lammhack", "roh": "300 g Lammhack"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch, fein gerieben", "roh": "4 Zehen Knoblauch, fein gerieben"}, {"menge": 1.0, "einheit": "TL", "item": "gemahlener Kreuzkümmel", "roh": "1 TL gemahlener Kreuzkümmel"}, {"menge": 0.5, "einheit": "TL", "item": "Natron", "roh": "0.5 TL Natron"}, {"menge": 100.0, "einheit": "ml", "item": "Rinderbrühe (kalt)", "roh": "100 ml Rinderbrühe (kalt)"}, {"menge": 1.0, "einheit": "TL", "item": "Pfeffer, 1 TL Salz, Prise Piment", "roh": "1 TL Pfeffer, 1 TL Salz, Prise Piment"}, {"menge": null, "einheit": "", "item": "Senf und Brot zum Servieren", "roh": "Senf und Brot zum Servieren"}], "zubereitung": ["Beide Hackfleischsorten mit Knoblauch, Kreuzkümmel, Natron, Pfeffer, Salz und Piment gründlich verkneten.", "Nach und nach die kalte Brühe einarbeiten, bis die Masse geschmeidig ist.", "Abgedeckt mehrere Stunden, am besten über Nacht, kühl ruhen lassen.", "Mit feuchten Händen kleine, fingerdicke Röllchen formen.", "Über Holzkohle oder in einer heißen Grillpfanne rundum kräftig grillen.", "Heiß mit Senf und Brot servieren."], "hinweise": "Die Ruhezeit über Nacht ist entscheidend für Geschmack und Bindung.\n\nEtwas kalte Brühe macht die Mici saftig.\n\nNicht zu lange grillen, sonst werden sie trocken.", "alternative": "Manche Mici-Rezepte verwenden eine Fleischmischung mit Schweineanteil. Wir nehmen ausschließlich Rind und Lamm, kräftig gewürzt mit Knoblauch und Kreuzkümmel — die Röllchen bleiben saftig und aromatisch, ganz ohne Schwein.", "geschichte": "Mici (auch Mititei, „die Kleinen“) gehören zu den beliebtesten Gerichten Rumäniens und sind ein fester Bestandteil von Grillfesten, Volksfesten und Sommerabenden. Es handelt sich um kleine, längliche Röllchen aus gewürztem Hackfleisch, die ohne Hülle über Holzkohle gegrillt werden. Charakteristisch ist die kräftige Würzung mit Knoblauch, Pfeffer, Kreuzkümmel und etwas Natron, das die Röllchen locker macht; oft wird auch etwas Brühe oder Mineralwasser untergearbeitet. Einer verbreiteten Anekdote nach sollen Mici im 19. Jahrhundert in einem Bukarester Wirtshaus entstanden sein, als die Wursthüllen ausgingen und man die gewürzte Masse kurzerhand ohne Darm grillte. Serviert werden Mici klassisch mit Senf, Brot und einem kühlen Getränk. Während manche Rezepte eine Fleischmischung mit Schweineanteil verwenden, lassen sie sich ebenso traditionell aus Rind und Lamm zubereiten — diese Fassung kommt ohne Schwein aus. Mici verkörpern die gesellige, volksnahe Seite der rumänischen Esskultur.", "persoenlich": "", "servier": "", "tags": ["Rumänien", "Mici", "Mititei", "Rind", "Lamm", "Hackfleisch", "Grillgericht", "Knoblauch", "Senf", "Sommerküche", "Straßenessen", "Hauptgericht"]}, {"id": "ciorb-r-d-u-ean", "status": "published", "date": "", "cover": "", "name": "Ciorbă rădăuțeană", "land": "Rumänien", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Geflügel"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine säuerliche Hähnchensuppe mit Wurzelgemüse, gebunden mit Ei und saurer Sahne und verfeinert mit Knoblauch und Essig. Wärmende rumänische Suppe.", "zutaten": ["600 g Hähnchenbrust oder -schenkel", "2 Möhren", "1 Petersilienwurzel, 0,5 Sellerie", "1 Zwiebel, 1 rote Paprika", "2 Eigelb", "200 g saure Sahne", "4 Zehen Knoblauch", "3 EL Essig", "Salz, Pfeffer, Liebstöckel"], "zutatenS": [{"menge": 600.0, "einheit": "g", "item": "Hähnchenbrust oder -schenkel", "roh": "600 g Hähnchenbrust oder -schenkel"}, {"menge": 2.0, "einheit": "", "item": "Möhren", "roh": "2 Möhren"}, {"menge": 1.0, "einheit": "", "item": "Petersilienwurzel, 0,5 Sellerie", "roh": "1 Petersilienwurzel, 0,5 Sellerie"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel, 1 rote Paprika", "roh": "1 Zwiebel, 1 rote Paprika"}, {"menge": 2.0, "einheit": "", "item": "Eigelb", "roh": "2 Eigelb"}, {"menge": 200.0, "einheit": "g", "item": "saure Sahne", "roh": "200 g saure Sahne"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "4 Zehen Knoblauch"}, {"menge": 3.0, "einheit": "EL", "item": "Essig", "roh": "3 EL Essig"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, Liebstöckel", "roh": "Salz, Pfeffer, Liebstöckel"}], "zubereitung": ["Hähnchen mit Wasser aufsetzen, aufkochen und abschäumen.", "Gewürfeltes Wurzelgemüse, Zwiebel und Paprika zugeben und garen, bis alles weich ist.", "Fleisch herausnehmen, zerkleinern und zurück in die Suppe geben.", "Eigelb mit saurer Sahne verquirlen, mit etwas heißer Brühe temperieren und einrühren (nicht mehr kochen).", "Mit Essig, zerdrücktem Knoblauch, Salz, Pfeffer und Liebstöckel abschmecken.", "Heiß als erster Gang servieren."], "hinweise": "Die Ei-Sahne-Mischung temperieren, damit sie nicht gerinnt.\n\nErst nach dem Binden mit Essig und Knoblauch abschmecken.\n\nReichlich Knoblauch ist hier typisch.", "alternative": "", "geschichte": "Ciorbă bezeichnet in Rumänien die große Familie der säuerlichen Suppen, deren typische Säure traditionell aus Borș (fermentiertem Weizenkleie-Sud) oder aus Essig und Zitrone stammt. Die Ciorbă rădăuțeană stammt aus der Stadt Rădăuți in der nördlichen Region Bukowina und wurde dort in der zweiten Hälfte des 20. Jahrhunderts bekannt. Sie ist eine vergleichsweise junge, aber fest etablierte Variante, die mit Hähnchenfleisch statt der sonst verbreiteten Innereien zubereitet wird und dadurch milder ist. Die Suppe verbindet Hähnchen und Wurzelgemüse in einer säuerlichen Brühe, die am Ende mit einer Mischung aus Ei und saurer Sahne gebunden („temperiert“) und mit reichlich Knoblauch und Essig abgeschmeckt wird. Die säuerlich-cremige, knoblauchbetonte Note ist charakteristisch. Ciorbă gehört in Rumänien zu fast jeder Mahlzeit als erster Gang und gilt als wärmendes Wohlfühlessen. Als Geflügelsuppe ist die Ciorbă rădăuțeană selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Rumänien", "Bukowina", "Ciorbă", "Hähnchensuppe", "säuerlich", "saure Sahne", "Knoblauch", "Wurzelgemüse", "Geflügel", "Wohlfühlessen", "Vorspeise", "Suppe"]}, {"id": "cozonac", "status": "published", "date": "", "cover": "", "name": "Cozonac", "land": "Rumänien", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein geflochtenes Hefe-Süßbrot mit einer Spirale aus Walnuss- und Kakaofüllung. Festtagsgebäck Rumäniens zu Ostern und Weihnachten.", "zutaten": ["600 g Mehl", "250 ml Milch", "30 g frische Hefe", "150 g Zucker", "3 Eier", "100 g Butter", "250 g gemahlene Walnüsse (Füllung)", "3 EL Kakao und 100 g Zucker (Füllung)", "1 Bio-Zitrone (Schale), Prise Salz"], "zutatenS": [{"menge": 600.0, "einheit": "g", "item": "Mehl", "roh": "600 g Mehl"}, {"menge": 250.0, "einheit": "ml", "item": "Milch", "roh": "250 ml Milch"}, {"menge": 30.0, "einheit": "g", "item": "frische Hefe", "roh": "30 g frische Hefe"}, {"menge": 150.0, "einheit": "g", "item": "Zucker", "roh": "150 g Zucker"}, {"menge": 3.0, "einheit": "", "item": "Eier", "roh": "3 Eier"}, {"menge": 100.0, "einheit": "g", "item": "Butter", "roh": "100 g Butter"}, {"menge": 250.0, "einheit": "g", "item": "gemahlene Walnüsse (Füllung)", "roh": "250 g gemahlene Walnüsse (Füllung)"}, {"menge": 3.0, "einheit": "EL", "item": "Kakao und 100 g Zucker (Füllung)", "roh": "3 EL Kakao und 100 g Zucker (Füllung)"}, {"menge": 1.0, "einheit": "", "item": "Bio-Zitrone (Schale), Prise Salz", "roh": "1 Bio-Zitrone (Schale), Prise Salz"}], "zubereitung": ["Hefe in warmer Milch mit etwas Zucker auflösen.", "Mehl, Zucker, Eier, Zitronenschale, Salz und die Hefemilch zu einem Teig kneten, weiche Butter einarbeiten.", "Zugedeckt 1–1,5 Stunden gehen lassen, bis sich der Teig verdoppelt.", "Walnüsse mit Kakao, Zucker und etwas warmer Milch zu einer streichfähigen Füllung mischen.", "Teig ausrollen, mit Füllung bestreichen, aufrollen und zu zwei Strängen flechten; in Kastenformen geben.", "Nochmals gehen lassen, mit Ei bestreichen und bei 175 °C 40–50 Minuten backen; auskühlen lassen."], "hinweise": "Der Teig muss gut gehen — Geduld macht den Cozonac luftig.\n\nDie Füllung nicht zu trocken anrühren, damit die Spirale saftig bleibt.\n\nVor dem Anschneiden vollständig auskühlen lassen.", "alternative": "", "geschichte": "Cozonac ist das klassische süße Hefebrot Rumäniens und gehört untrennbar zu den großen Festen, vor allem Ostern und Weihnachten. Es zählt zur weit verbreiteten Familie der gefüllten Hefezöpfe und -brote Südost- und Mitteleuropas und hat in Rumänien einen besonders hohen symbolischen Stellenwert: Das Backen des Cozonac in den Tagen vor dem Fest ist ein Ritual, das ganze Familien einbindet, und ein gelungener, luftiger Cozonac gilt als Stolz der Bäckerin. Der reichhaltige, mit Eiern, Butter und Milch angesetzte Hefeteig wird dünn ausgerollt, mit einer Füllung aus gemahlenen Walnüssen, Kakao, Zucker und oft Rosinen oder Lokum bestrichen, aufgerollt und zu einem Zopf geflochten, bevor er gebacken wird. Beim Anschneiden zeigt sich die charakteristische dunkle Spirale. Cozonac wird in Scheiben zum Fest gereicht und oft verschenkt. Als süßes Hefegebäck ist er selbstverständlich vegetarisch und ohne Schweinefleisch und steht sinnbildlich für die festliche Backtradition Rumäniens.", "persoenlich": "", "servier": "", "tags": ["Rumänien", "Cozonac", "Hefezopf", "Süßbrot", "Walnuss", "Kakao", "Ostern", "Weihnachten", "süß", "vegetarisch", "Festtag", "Dessert"]}, {"id": "piadina", "status": "published", "date": "", "cover": "", "name": "Piadina", "land": "San Marino", "kontinent": "Europa", "gang": "Beilage", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein dünnes, auf der Platte gebackenes Fladenbrot, warm gefüllt mit Frischkäse und Rucola. Allgegenwärtiges Brot der Romagna und San Marinos.", "zutaten": ["400 g Mehl", "150 ml lauwarmes Wasser oder Milch", "50 g Olivenöl oder weiche Butter", "0.5 TL Backpulver", "1 Prise Salz", "200 g Squacquerone oder Frischkäse", "1 Hand Rucola"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Mehl", "roh": "400 g Mehl"}, {"menge": 150.0, "einheit": "ml", "item": "lauwarmes Wasser oder Milch", "roh": "150 ml lauwarmes Wasser oder Milch"}, {"menge": 50.0, "einheit": "g", "item": "Olivenöl oder weiche Butter", "roh": "50 g Olivenöl oder weiche Butter"}, {"menge": 0.5, "einheit": "TL", "item": "Backpulver", "roh": "0.5 TL Backpulver"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}, {"menge": 200.0, "einheit": "g", "item": "Squacquerone oder Frischkäse", "roh": "200 g Squacquerone oder Frischkäse"}, {"menge": 1.0, "einheit": "Hand", "item": "Rucola", "roh": "1 Hand Rucola"}], "zubereitung": ["Mehl, Backpulver, Salz, Fett und Flüssigkeit zu einem geschmeidigen Teig kneten und ruhen lassen.", "Den Teig in Portionen teilen und dünn rund ausrollen.", "Auf einer heißen, trockenen Platte oder Pfanne beidseitig backen, bis sich braune Flecken bilden.", "Die Piadina warm vom Feuer nehmen.", "Mit Frischkäse bestreichen und Rucola belegen.", "Zusammenklappen und sofort servieren."], "hinweise": "Auf trockener, heißer Platte backen — kein zusätzliches Fett in der Pfanne.\n\nWarm füllen, damit der Käse leicht schmilzt.\n\nDen Teig nicht zu dick ausrollen.", "alternative": "", "geschichte": "Die Piadina (lokal auch „piada“) ist ein dünnes, ungesäuertes Fladenbrot, das San Marino mit der italienischen Region Romagna teilt, in deren Mitte die Republik liegt. Sie hat eine lange, bäuerliche Tradition und galt über Jahrhunderte als das „Brot der Armen“ — eine schnelle, günstige Alternative zum gesäuerten Brot, gebacken aus Mehl, Wasser oder Milch, etwas Fett und Salz auf einer heißen Tonplatte (teglia) oder Eisenplatte. Die Piadina wird warm gegessen und nach Belieben gefüllt: klassisch mit dem cremigen Frischkäse Squacquerone und Rucola, mit anderem Käse, Gemüse oder Kräutern. In San Marino und der Romagna ist sie allgegenwärtig und wird an spezialisierten Ständen (piadinerie) frisch zubereitet. Sie verkörpert die unkomplizierte, alltägliche Esskultur der Region. In der vegetarischen Füllung mit Käse und Rucola ist sie selbstverständlich ohne Schweinefleisch und gehört zu den identitätsstiftenden Speisen des Gebiets.", "persoenlich": "", "servier": "", "tags": ["San Marino", "Romagna", "Piadina", "Fladenbrot", "Squacquerone", "Rucola", "vegetarisch", "Straßenessen", "Snack", "mediterran", "bäuerlich", "Beilage"]}, {"id": "nidi-di-rondine", "status": "published", "date": "", "cover": "", "name": "Nidi di rondine", "land": "San Marino", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "„Schwalbennester“: gerollte Pastateigblätter mit Käse- und Gemüsefüllung, in Béchamel und Tomatensauce überbacken. Festliches Ofengericht San Marinos.", "zutaten": ["300 g frische Lasagneblätter", "300 g Spinat", "250 g Ricotta", "150 g geriebener Käse (z. B. Fontina)", "500 ml Béchamelsauce", "300 g Tomatensauce", "50 g Parmesan", "Salz, Pfeffer, Muskat"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "frische Lasagneblätter", "roh": "300 g frische Lasagneblätter"}, {"menge": 300.0, "einheit": "g", "item": "Spinat", "roh": "300 g Spinat"}, {"menge": 250.0, "einheit": "g", "item": "Ricotta", "roh": "250 g Ricotta"}, {"menge": 150.0, "einheit": "g", "item": "geriebener Käse (z. B. Fontina)", "roh": "150 g geriebener Käse (z. B. Fontina)"}, {"menge": 500.0, "einheit": "ml", "item": "Béchamelsauce", "roh": "500 ml Béchamelsauce"}, {"menge": 300.0, "einheit": "g", "item": "Tomatensauce", "roh": "300 g Tomatensauce"}, {"menge": 50.0, "einheit": "g", "item": "Parmesan", "roh": "50 g Parmesan"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, Muskat", "roh": "Salz, Pfeffer, Muskat"}], "zubereitung": ["Spinat blanchieren, ausdrücken, hacken und mit Ricotta, der Hälfte des Käses, Salz, Pfeffer und Muskat verrühren.", "Die Lasagneblätter kurz vorgaren und abtropfen.", "Die Füllung dünn auf die Blätter streichen und diese fest aufrollen.", "Die Rollen in etwa fingerbreite Scheiben schneiden und aufrecht („Nester“) in eine Form setzen.", "Mit Béchamel und Tomatensauce übergießen, mit restlichem Käse und Parmesan bestreuen.", "Bei 190 °C 25–30 Minuten goldbraun überbacken; kurz ruhen lassen und servieren."], "hinweise": "Die Rollen fest wickeln, damit die Nester beim Schneiden halten.\n\nAufrecht in die Form setzen, damit die typische Nestform sichtbar bleibt.\n\nDie Füllung kräftig würzen, sie trägt das Gericht.", "alternative": "Traditionell werden Nidi di rondine oft mit Schinken gefüllt. Wir verwenden stattdessen eine Füllung aus Spinat, Ricotta und Käse — sie macht das Gericht ebenso reichhaltig und cremig, ganz ohne Schwein. Wer eine herzhaft-rauchige Note möchte, kann etwas geräucherten Rinderschinken einarbeiten.", "geschichte": "Nidi di rondine — „Schwalbennester“ — sind ein traditionelles Ofengericht San Marinos und gelten als eine der charakteristischen Speisen der kleinen Republik. Der Name beschreibt die Form: Frisch ausgerollte Pastateigblätter werden mit einer Füllung bestrichen, fest aufgerollt und dann in Scheiben geschnitten, sodass beim Aufstellen runde, nestartige Röllchen entstehen. Diese werden dicht in eine Form gesetzt, mit Béchamel und Tomatensauce übergossen, mit Käse bestreut und im Ofen überbacken. Das Gericht gehört zur festlichen Tafel und zu Sonntagen und spiegelt die enge Verwandtschaft der sanmarinesischen mit der emilianischen und romagnolischen Küche wider, in der gefüllte und überbackene Pasta eine große Rolle spielt. Traditionell enthält die Füllung oft Schinken; in dieser Fassung verwenden wir eine Füllung aus Käse, Spinat und Kräutern, sodass das Gericht ohne Schwein auskommt, ohne an Reichhaltigkeit zu verlieren. Nidi di rondine stehen für die festliche, hausgemachte Pastakultur San Marinos.", "persoenlich": "", "servier": "", "tags": ["San Marino", "Nidi di rondine", "Schwalbennester", "Pasta", "Spinat", "Ricotta", "überbacken", "vegetarisch", "Festtag", "Béchamel", "emilianisch geprägt", "Hauptgericht"]}, {"id": "torta-tre-monti", "status": "published", "date": "", "cover": "", "name": "Torta Tre Monti", "land": "San Marino", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine Schichttorte aus knusprigen Waffelblättern und Haselnuss-Schokoladencreme, überzogen mit Schokolade. Das süße Wahrzeichen San Marinos.", "zutaten": ["1 Packung runde Waffelblätter (cialde/Oblaten)", "300 g Haselnusscreme (gianduia)", "100 g geröstete Haselnüsse, gehackt", "200 g Zartbitterschokolade", "100 g Milchschokolade", "50 g Butter"], "zutatenS": [{"menge": 1.0, "einheit": "Packung", "item": "runde Waffelblätter (cialde/Oblaten)", "roh": "1 Packung runde Waffelblätter (cialde/Oblaten)"}, {"menge": 300.0, "einheit": "g", "item": "Haselnusscreme (gianduia)", "roh": "300 g Haselnusscreme (gianduia)"}, {"menge": 100.0, "einheit": "g", "item": "geröstete Haselnüsse, gehackt", "roh": "100 g geröstete Haselnüsse, gehackt"}, {"menge": 200.0, "einheit": "g", "item": "Zartbitterschokolade", "roh": "200 g Zartbitterschokolade"}, {"menge": 100.0, "einheit": "g", "item": "Milchschokolade", "roh": "100 g Milchschokolade"}, {"menge": 50.0, "einheit": "g", "item": "Butter", "roh": "50 g Butter"}], "zubereitung": ["Haselnusscreme leicht erwärmen, damit sie streichfähig wird, und mit gehackten Haselnüssen mischen.", "Ein Waffelblatt dünn mit der Creme bestreichen, ein weiteres Blatt darauflegen.", "So Blatt für Blatt schichten, bis ein Stapel entsteht; leicht beschweren und kühl fest werden lassen.", "Zartbitter- und Milchschokolade mit der Butter schmelzen.", "Den Waffelstapel rundum mit der geschmolzenen Schokolade überziehen.", "Vollständig fest werden lassen und in Stücke schneiden."], "hinweise": "Den Stapel beim Festwerden leicht beschweren, damit er kompakt bleibt.\n\nDie Schokolade nicht zu heiß auftragen, sonst weichen die Waffeln auf.\n\nMit einem heißen, scharfen Messer schneiden.", "alternative": "", "geschichte": "Die Torta Tre Monti — „Torte der drei Berge“ — ist die bekannteste Süßspeise San Marinos und ein kulinarisches Wahrzeichen der Republik. Ihr Name und ihre Gestaltung verweisen auf die drei Gipfel des Monte Titano mit ihren drei Festungstürmen, die das Wappen und die Flagge San Marinos zieren. Die Torte besteht aus mehreren Lagen dünner, knuspriger Waffelblätter (cialde), die mit einer Creme aus Haselnüssen, Kakao und Schokolade verbunden und anschließend mit Schokolade überzogen werden. Sie entstand im 20. Jahrhundert und entwickelte sich zu einem beliebten Mitbringsel und Symbol für Besucher der Republik. Die Kombination aus knusprigen Schichten und cremiger Nuss-Schokoladenfüllung ist charakteristisch und macht sie zu einem festen Bestandteil des sanmarinesischen Süßwarensortiments. Die Torta Tre Monti gehört zu festlichen Anlässen und wird in Scheiben serviert. Als reine Waffel-Schokoladen-Süßspeise ist sie selbstverständlich vegetarisch und ohne Schweinefleisch und steht sinnbildlich für die Identität der kleinen Republik.", "persoenlich": "", "servier": "", "tags": ["San Marino", "Torta Tre Monti", "Waffeltorte", "Haselnuss", "Schokolade", "Schichttorte", "süß", "vegetarisch", "Wahrzeichen", "Monte Titano", "gianduia", "Dessert"]}, {"id": "koettbullar", "status": "published", "date": "", "cover": "", "name": "Köttbullar", "land": "Schweden", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 20, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine Hackfleischbällchen in cremiger Bratensauce, serviert mit Kartoffelpüree und Preiselbeeren. Schwedens berühmtestes Gericht.", "zutaten": ["400 g Rinderhack", "200 g Kalbshack", "1 Zwiebel, fein gerieben", "50 g Semmelbrösel", "100 ml Milch", "1 Ei", "300 ml Sahne und 200 ml Brühe (Sauce)", "Butter, Mehl, Salz, Pfeffer, Piment; Preiselbeeren zum Servieren"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Rinderhack", "roh": "400 g Rinderhack"}, {"menge": 200.0, "einheit": "g", "item": "Kalbshack", "roh": "200 g Kalbshack"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel, fein gerieben", "roh": "1 Zwiebel, fein gerieben"}, {"menge": 50.0, "einheit": "g", "item": "Semmelbrösel", "roh": "50 g Semmelbrösel"}, {"menge": 100.0, "einheit": "ml", "item": "Milch", "roh": "100 ml Milch"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 300.0, "einheit": "ml", "item": "Sahne und 200 ml Brühe (Sauce)", "roh": "300 ml Sahne und 200 ml Brühe (Sauce)"}, {"menge": null, "einheit": "", "item": "Butter, Mehl, Salz, Pfeffer, Piment; Preiselbeeren zum Servieren", "roh": "Butter, Mehl, Salz, Pfeffer, Piment; Preiselbeeren zum Servieren"}], "zubereitung": ["Semmelbrösel in Milch einweichen.", "Hackfleisch mit Zwiebel, eingeweichten Bröseln, Ei, Salz, Pfeffer und Piment zu einer Masse verkneten.", "Kleine Bällchen formen und in Butter rundum goldbraun braten; herausnehmen.", "Im Bratfett etwas Mehl anschwitzen, mit Brühe und Sahne zu einer Sauce aufgießen.", "Die Bällchen in der Sauce kurz fertig garen.", "Mit Kartoffelpüree und Preiselbeeren servieren."], "hinweise": "Eingeweichte Brösel machen die Bällchen besonders saftig.\n\nDie Bällchen gleich groß formen, damit sie gleichmäßig garen.\n\nPreiselbeeren gehören für den süß-säuerlichen Kontrast dazu.", "alternative": "Köttbullar werden traditionell aus einer Mischung von Rind- und Schweinehack zubereitet. Wir verwenden Rind und Kalb; eingeweichte Semmelbrösel und Milch sorgen für Saftigkeit, sodass die Bällchen ohne Schwein zart und aromatisch bleiben.", "geschichte": "Köttbullar — schwedische Fleischbällchen — gelten als das bekannteste Gericht der schwedischen Küche und sind weltweit zu einem Symbol für Schweden geworden. Kleine, gewürzte Hackfleischbällchen werden in Butter gebraten und mit einer cremigen Bratensauce (gräddsås) serviert, dazu Kartoffelpüree, eingelegte Gurken und vor allem Preiselbeerkompott (lingonsylt), dessen Süße und Säure einen Kontrast zum herzhaften Fleisch bildet. Köttbullar gehören zur schwedischen Hausmannskost (husmanskost) und zum festlichen Julbord, dem weihnachtlichen Büfett. Interessanterweise wird das Rezept teils auf Einflüsse aus dem Osmanischen Reich zurückgeführt, die König Karl XII. im frühen 18. Jahrhundert nach Schweden gebracht haben soll. Traditionell wird eine Mischung aus Rind- und Schweinehack verwendet; in dieser Fassung nehmen wir Rind und Kalb, sodass die Bällchen ohne Schwein zubereitet werden. Köttbullar verkörpern die gemütliche, familiäre Seite der schwedischen Esskultur und werden in vielen Haushalten nach überliefertem Rezept zubereitet.", "persoenlich": "", "servier": "", "tags": ["Schweden", "Köttbullar", "Fleischbällchen", "Rind", "Kalb", "Rahmsauce", "Preiselbeeren", "husmanskost", "Julbord", "Skandinavien", "Wohlfühlessen", "Hauptgericht"]}, {"id": "janssons-frestelse", "status": "published", "date": "", "cover": "", "name": "Janssons frestelse", "land": "Schweden", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein cremiges Kartoffelgratin mit Zwiebeln und eingelegten Sprotten, überbacken mit Sahne. Schwedischer Weihnachtsklassiker.", "zutaten": ["1 kg festkochende Kartoffeln", "2 Zwiebeln", "1 Dose eingelegte Sprotten oder Sardellen (ansjovis)", "300 ml Sahne", "100 ml Milch", "40 g Butter", "3 EL Semmelbrösel", "Salz, Pfeffer"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "festkochende Kartoffeln", "roh": "1 kg festkochende Kartoffeln"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 1.0, "einheit": "Dose", "item": "eingelegte Sprotten oder Sardellen (ansjovis)", "roh": "1 Dose eingelegte Sprotten oder Sardellen (ansjovis)"}, {"menge": 300.0, "einheit": "ml", "item": "Sahne", "roh": "300 ml Sahne"}, {"menge": 100.0, "einheit": "ml", "item": "Milch", "roh": "100 ml Milch"}, {"menge": 40.0, "einheit": "g", "item": "Butter", "roh": "40 g Butter"}, {"menge": 3.0, "einheit": "EL", "item": "Semmelbrösel", "roh": "3 EL Semmelbrösel"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}], "zubereitung": ["Kartoffeln und Zwiebeln in feine Streifen bzw. Scheiben schneiden.", "Zwiebeln in Butter glasig dünsten.", "In einer gebutterten Form Kartoffeln, Zwiebeln und Sprotten abwechselnd schichten.", "Etwas vom Einlegesud sowie Sahne und Milch angießen.", "Mit Butterflöckchen und Semmelbröseln bestreuen.", "Bei 200 °C 45–55 Minuten backen, bis die Kartoffeln weich und die Oberfläche goldbraun sind."], "hinweise": "Etwas Einlegesud der Fischchen gibt zusätzliche Würze.\n\nDie Kartoffeln dünn schneiden, damit sie gleichmäßig garen.\n\nVor dem Servieren kurz ruhen lassen.", "alternative": "", "geschichte": "Janssons frestelse — „Janssons Versuchung“ — ist ein klassisches schwedisches Kartoffelgratin und ein fester Bestandteil des weihnachtlichen Julbord-Büfetts. Das Gericht besteht aus fein geschnittenen Kartoffeln und Zwiebeln, die schichtweise mit eingelegten schwedischen Sprotten oder Sardellen (ansjovis) belegt, mit Sahne übergossen und im Ofen überbacken werden, bis sie weich und goldbraun sind. Die salzig-würzigen Fischchen geben dem cremigen Gratin seine charakteristische Tiefe. Der Ursprung des Namens ist nicht eindeutig geklärt; verbreitet sind Erzählungen, die ihn mit einem Opernsänger oder einem Film der frühen 20. Jahrhunderts in Verbindung bringen. Das Gericht etablierte sich im Lauf des 20. Jahrhunderts als Weihnachtsspezialität und wird auch zu anderen festlichen Anlässen und Buffets serviert. Es lässt sich gut vorbereiten und im Ofen fertig garen. Da es auf Kartoffeln, Zwiebeln, Sahne und eingelegtem Fisch beruht, ist es selbstverständlich ohne Schweinefleisch und gehört zu den beliebtesten Beilagen der schwedischen Festtafel.", "persoenlich": "", "servier": "", "tags": ["Schweden", "Janssons frestelse", "Kartoffelgratin", "Sprotten", "Sardellen", "Sahne", "Weihnachten", "Julbord", "Skandinavien", "überbacken", "Fisch", "Beilage"]}, {"id": "kanelbullar", "status": "published", "date": "", "cover": "", "name": "Kanelbullar", "land": "Schweden", "kontinent": "Europa", "gang": "Snack", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Weiche Zimtschnecken aus Kardamomteig mit Zimt-Butter-Füllung, bestreut mit Hagelzucker. Herzstück der schwedischen Kaffeepause „fika“.", "zutaten": ["500 g Mehl", "250 ml lauwarme Milch", "25 g frische Hefe", "80 g Zucker", "80 g Butter (Teig)", "1 TL gemahlener Kardamom", "100 g weiche Butter, Zucker und Zimt (Füllung)", "Ei und Hagelzucker zum Bestreichen"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Mehl", "roh": "500 g Mehl"}, {"menge": 250.0, "einheit": "ml", "item": "lauwarme Milch", "roh": "250 ml lauwarme Milch"}, {"menge": 25.0, "einheit": "g", "item": "frische Hefe", "roh": "25 g frische Hefe"}, {"menge": 80.0, "einheit": "g", "item": "Zucker", "roh": "80 g Zucker"}, {"menge": 80.0, "einheit": "g", "item": "Butter (Teig)", "roh": "80 g Butter (Teig)"}, {"menge": 1.0, "einheit": "TL", "item": "gemahlener Kardamom", "roh": "1 TL gemahlener Kardamom"}, {"menge": null, "einheit": "", "item": "100 g weiche Butter, Zucker und Zimt (Füllung)", "roh": "100 g weiche Butter, Zucker und Zimt (Füllung)"}, {"menge": null, "einheit": "", "item": "Ei und Hagelzucker zum Bestreichen", "roh": "Ei und Hagelzucker zum Bestreichen"}], "zubereitung": ["Hefe in lauwarmer Milch auflösen; mit Mehl, Zucker, Kardamom und weicher Butter zu einem Teig kneten.", "Zugedeckt etwa 45 Minuten gehen lassen.", "Teig rechteckig ausrollen, mit weicher Butter bestreichen und mit Zimt und Zucker bestreuen.", "Aufrollen, in Stücke schneiden und auf ein Blech setzen (oder zu Knoten schlingen).", "Nochmals gehen lassen, mit Ei bestreichen und mit Hagelzucker bestreuen.", "Bei 220 °C 8–10 Minuten goldbraun backen; lauwarm zur fika servieren."], "hinweise": "Kardamom frisch mahlen für das beste Aroma.\n\nNicht zu lange backen, damit sie saftig bleiben.\n\nMit Hagelzucker bestreut sind sie original schwedisch.", "alternative": "", "geschichte": "Kanelbullar — schwedische Zimtschnecken — sind eines der bekanntesten Gebäcke Schwedens und untrennbar mit der schwedischen Kaffeekultur und dem Ritual der „fika“ verbunden, der bewussten Pause bei Kaffee und etwas Süßem. Sie verbreiteten sich in Schweden im 20. Jahrhundert, als die Zutaten erschwinglich wurden, und entwickelten sich zu einem nationalen Symbol; seit 1999 gibt es sogar einen „Kanelbullens dag“ (Tag der Zimtschnecke) am 4. Oktober. Charakteristisch für den nordischen Hefeteig ist die Würzung mit Kardamom. Der Teig wird ausgerollt, mit einer Füllung aus weicher Butter, Zucker und Zimt bestrichen, aufgerollt und in Stücke geschnitten oder zu Knoten geschlungen, mit Ei bestrichen und mit grobem Hagelzucker bestreut gebacken. Kanelbullar werden frisch und leicht warm gegessen und in schwedischen Haushalten ebenso wie in Cafés (konditori) angeboten. Als süßes Hefegebäck sind sie selbstverständlich vegetarisch und ohne Schweinefleisch und verkörpern die gemütliche, gesellige Seite der schwedischen Esskultur.", "persoenlich": "", "servier": "", "tags": ["Schweden", "Kanelbullar", "Zimtschnecke", "Kardamom", "Hefegebäck", "fika", "Hagelzucker", "süß", "vegetarisch", "Skandinavien", "Kaffeepause", "Dessert"]}, {"id": "kaesefondue", "status": "published", "date": "", "cover": "", "name": "Käsefondue", "land": "Schweiz", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Geschmolzener Käse mit Weißwein und Knoblauch in einem Topf, in den Brotstücke getunkt werden. Das gesellige Nationalgericht der Schweiz.", "zutaten": ["400 g Gruyère, gerieben", "400 g Vacherin Fribourgeois oder Emmentaler, gerieben", "300 ml trockener Weißwein", "1 Zehe Knoblauch", "2 TL Maisstärke", "2 EL Kirsch (optional)", "1 Laib Weißbrot, gewürfelt", "Pfeffer, Muskat"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Gruyère, gerieben", "roh": "400 g Gruyère, gerieben"}, {"menge": 400.0, "einheit": "g", "item": "Vacherin Fribourgeois oder Emmentaler, gerieben", "roh": "400 g Vacherin Fribourgeois oder Emmentaler, gerieben"}, {"menge": 300.0, "einheit": "ml", "item": "trockener Weißwein", "roh": "300 ml trockener Weißwein"}, {"menge": 1.0, "einheit": "Zehe", "item": "Knoblauch", "roh": "1 Zehe Knoblauch"}, {"menge": 2.0, "einheit": "TL", "item": "Maisstärke", "roh": "2 TL Maisstärke"}, {"menge": 2.0, "einheit": "EL", "item": "Kirsch (optional)", "roh": "2 EL Kirsch (optional)"}, {"menge": 1.0, "einheit": "Laib", "item": "Weißbrot, gewürfelt", "roh": "1 Laib Weißbrot, gewürfelt"}, {"menge": null, "einheit": "", "item": "Pfeffer, Muskat", "roh": "Pfeffer, Muskat"}], "zubereitung": ["Das Caquelon mit der halbierten Knoblauchzehe ausreiben.", "Weißwein im Topf erwärmen.", "Den geriebenen Käse nach und nach unter Rühren einschmelzen.", "Maisstärke im Kirsch (oder etwas Wein) anrühren und einrühren, bis das Fondue cremig bindet.", "Mit Pfeffer und Muskat würzen.", "Auf dem Rechaud warm halten und Brotstücke an Gabeln hineintunken."], "hinweise": "Stetig in Achterbewegung rühren, damit der Käse cremig bleibt.\n\nDas Fondue nicht zu heiß werden lassen, sonst gerinnt es.\n\nTrockenen, säurebetonten Weißwein wählen.", "alternative": "", "geschichte": "Das Käsefondue gilt als eines der Nationalgerichte der Schweiz und verkörpert wie kein anderes die gesellige Esskultur des Landes. Sein Ursprung liegt in der alpinen Notwendigkeit, im Winter haltbar gemachten Käse und hart gewordenes Brot zu verwerten: Indem man den Käse mit etwas Wein schmolz, ließ er sich auch in fortgeschrittenem Reifezustand genießen. Im 20. Jahrhundert wurde das Fondue gezielt als nationales Gericht popularisiert und entwickelte sich zu einem Symbol für Schweizer Gemütlichkeit. Klassisch werden Käsesorten wie Gruyère und Vacherin (in der Freiburger Variante „moitié-moitié“) mit Weißwein, etwas Knoblauch und einem Spritzer Kirsch im Caquelon, einem dickwandigen Topf, geschmolzen und mit Maisstärke gebunden. Am Tisch wird der Topf auf einem Rechaud warm gehalten, und die Gäste tunken Brotstücke an langen Gabeln in den geschmolzenen Käse. Ungeschriebene Regeln und gesellige Bräuche begleiten das Essen. Als reines Käsegericht ist Fondue selbstverständlich ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Schweiz", "Käsefondue", "Gruyère", "Vacherin", "Käse", "vegetarisch", "Weißwein", "Alpenküche", "gesellig", "Nationalgericht", "Winterküche", "Hauptgericht"]}, {"id": "roesti", "status": "published", "date": "", "cover": "", "name": "Rösti", "land": "Schweiz", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein knuspriger, goldbrauner Fladen aus geriebenen Kartoffeln, in der Pfanne gebraten. Schweizer Klassiker, einst Bauernfrühstück.", "zutaten": ["1 kg festkochende Kartoffeln", "50 g Butter", "2 EL neutrales Öl", "Salz, Pfeffer"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "festkochende Kartoffeln", "roh": "1 kg festkochende Kartoffeln"}, {"menge": 50.0, "einheit": "g", "item": "Butter", "roh": "50 g Butter"}, {"menge": 2.0, "einheit": "EL", "item": "neutrales Öl", "roh": "2 EL neutrales Öl"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}], "zubereitung": ["Kartoffeln (roh oder am Vortag gekocht) schälen und grob raspeln.", "Mit Salz und Pfeffer würzen; bei rohen Kartoffeln überschüssige Flüssigkeit ausdrücken.", "Butter und Öl in einer Pfanne erhitzen.", "Die Kartoffeln einfüllen, flach drücken und bei mittlerer Hitze braten, bis sich unten eine goldbraune Kruste bildet.", "Den Fladen als Ganzes wenden (z. B. mithilfe eines Tellers) und die andere Seite knusprig braten.", "Heiß als Beilage oder mit Käse, Ei und Gemüse als Hauptgericht servieren."], "hinweise": "Genug Fett verwenden, damit die Kruste knusprig wird.\n\nNicht zu früh wenden — erst wenn die Unterseite fest und goldbraun ist.\n\nRohe Kartoffeln gut ausdrücken, sonst wird die Rösti matschig.", "alternative": "", "geschichte": "Rösti ist eines der bekanntesten Gerichte der Schweiz und hat seinen Ursprung als einfaches, sättigendes Bauernfrühstück, vor allem im Kanton Bern. Geriebene Kartoffeln werden in der Pfanne in Fett zu einem flachen, goldbraunen Fladen mit knuspriger Kruste gebraten. Ursprünglich verwendete man am Vortag gekochte Kartoffeln, doch auch rohe geriebene Kartoffeln sind verbreitet. Rösti steht so sehr für die Deutschschweiz, dass die sprachlich-kulturelle Grenze zur französischsprachigen Schweiz scherzhaft „Röstigraben“ („Röstigraben“) genannt wird. Vom Berner Frühstück entwickelte sich Rösti zur beliebten Beilage im ganzen Land, etwa zum Zürcher Geschnetzelten, und wird auch mit Käse, Ei oder Gemüse zu einem Hauptgericht aufgewertet. Die Kunst liegt darin, einen zusammenhängenden, außen knusprigen und innen weichen Fladen zu braten und ihn als Ganzes zu wenden. In der schlichten Grundform aus Kartoffeln und Fett ist Rösti selbstverständlich vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Schweiz", "Rösti", "Kartoffeln", "vegetarisch", "Beilage", "Bauernfrühstück", "Bern", "knusprig", "Alpenküche", "Röstigraben", "gebraten", "Hauptgericht"]}, {"id": "zuercher-geschnetzeltes", "status": "published", "date": "", "cover": "", "name": "Zürcher Geschnetzeltes", "land": "Schweiz", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Feine Kalbfleischstreifen in einer cremigen Sauce aus Weißwein, Sahne und Champignons, klassisch mit Rösti. Spezialität aus Zürich.", "zutaten": ["700 g Kalbfleisch (z. B. aus der Nuss), in Streifen", "250 g Champignons", "1 Zwiebel", "150 ml Weißwein", "200 ml Sahne", "100 ml Kalbsfond", "40 g Butter", "Mehl, Salz, Pfeffer, Petersilie"], "zutatenS": [{"menge": 700.0, "einheit": "g", "item": "Kalbfleisch (z. B. aus der Nuss), in Streifen", "roh": "700 g Kalbfleisch (z. B. aus der Nuss), in Streifen"}, {"menge": 250.0, "einheit": "g", "item": "Champignons", "roh": "250 g Champignons"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 150.0, "einheit": "ml", "item": "Weißwein", "roh": "150 ml Weißwein"}, {"menge": 200.0, "einheit": "ml", "item": "Sahne", "roh": "200 ml Sahne"}, {"menge": 100.0, "einheit": "ml", "item": "Kalbsfond", "roh": "100 ml Kalbsfond"}, {"menge": 40.0, "einheit": "g", "item": "Butter", "roh": "40 g Butter"}, {"menge": null, "einheit": "", "item": "Mehl, Salz, Pfeffer, Petersilie", "roh": "Mehl, Salz, Pfeffer, Petersilie"}], "zubereitung": ["Kalbfleischstreifen salzen, leicht mehlieren und in heißer Butter portionsweise kurz anbraten; herausnehmen.", "Zwiebel und in Scheiben geschnittene Champignons im Bratfett andünsten.", "Mit Weißwein ablöschen und etwas einkochen.", "Kalbsfond und Sahne zugeben und zu einer cremigen Sauce einköcheln.", "Das Fleisch mit dem ausgetretenen Saft zurückgeben und nur kurz erwärmen, nicht mehr kochen.", "Mit Salz, Pfeffer und Petersilie abschmecken und mit Rösti servieren."], "hinweise": "Das Kalbfleisch nur kurz garen, sonst wird es zäh.\n\nDas Fleisch am Ende nur in der Sauce erwärmen.\n\nRösti ist die klassische Beilage.", "alternative": "", "geschichte": "Zürcher Geschnetzeltes (im Dialekt „Züri-Gschnätzlets“) ist die bekannteste Fleischspezialität der Stadt Zürich und ein Klassiker der Deutschschweizer Küche. Das Gericht besteht aus feinen Streifen vom Kalbfleisch, die kurz angebraten und in einer cremigen Sauce aus Zwiebeln, Weißwein, Kalbsfond und Sahne geschmort werden; Champignons gehören in der verbreiteten Variante dazu. Charakteristisch ist die zarte, helle Sauce, die das schnell gegarte Kalbfleisch saftig hält. Das Gericht etablierte sich im 20. Jahrhundert als Aushängeschild der Zürcher Gastronomie und wird klassisch mit Rösti serviert, die die Sauce aufnimmt. In manchen Versionen werden auch Kalbsnieren mitverarbeitet. Zürcher Geschnetzeltes steht für die feinere, bürgerliche Seite der Schweizer Küche und ist in Restaurants im ganzen Land verbreitet. Da es auf Kalbfleisch beruht, ist es von Natur aus ohne Schweinefleisch und gilt als eines der repräsentativsten Gerichte der Region Zürich.", "persoenlich": "", "servier": "", "tags": ["Schweiz", "Zürich", "Zürcher Geschnetzeltes", "Kalb", "Rahmsauce", "Champignons", "Weißwein", "Rösti", "bürgerliche Küche", "Klassiker", "Deutschschweiz", "Hauptgericht"]}, {"id": "pljeskavica", "status": "published", "date": "", "cover": "", "name": "Pljeskavica", "land": "Serbien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine große, flache Frikadelle aus gewürztem Rind- und Lammhack, über Holzkohle gegrillt und in Fladenbrot mit Zwiebeln und Ajvar serviert. Serbisches Grill-Wahrzeichen.", "zutaten": ["500 g Rinderhack", "300 g Lammhack", "1 Zwiebel, sehr fein gewürfelt", "3 Zehen Knoblauch", "1 TL Paprikapulver, 0,5 TL Natron", "Salz, Pfeffer", "4 Fladenbrote (lepinja)", "Zwiebeln, Ajvar und Kajmak zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Rinderhack", "roh": "500 g Rinderhack"}, {"menge": 300.0, "einheit": "g", "item": "Lammhack", "roh": "300 g Lammhack"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel, sehr fein gewürfelt", "roh": "1 Zwiebel, sehr fein gewürfelt"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "3 Zehen Knoblauch"}, {"menge": 1.0, "einheit": "TL", "item": "Paprikapulver, 0,5 TL Natron", "roh": "1 TL Paprikapulver, 0,5 TL Natron"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}, {"menge": 4.0, "einheit": "", "item": "Fladenbrote (lepinja)", "roh": "4 Fladenbrote (lepinja)"}, {"menge": null, "einheit": "", "item": "Zwiebeln, Ajvar und Kajmak zum Servieren", "roh": "Zwiebeln, Ajvar und Kajmak zum Servieren"}], "zubereitung": ["Beide Hackfleischsorten mit Zwiebel, Knoblauch, Paprikapulver, Natron, Salz und Pfeffer gründlich verkneten.", "Die Masse abgedeckt mehrere Stunden, am besten über Nacht, kühl ruhen lassen.", "Aus der Masse große, flache, runde Frikadellen formen.", "Über Holzkohle oder in einer heißen Grillpfanne je Seite kräftig grillen.", "Das Fladenbrot kurz mit aufwärmen.", "Pljeskavica im Brot mit rohen Zwiebeln, Ajvar und Kajmak servieren."], "hinweise": "Gründliches Kneten und Ruhen macht die Pljeskavica saftig und kompakt.\n\nDie Frikadelle flach formen, damit sie gleichmäßig durchgrillt.\n\nAjvar und Kajmak gehören klassisch dazu.", "alternative": "", "geschichte": "Pljeskavica ist eines der bekanntesten Gerichte Serbiens und des Balkans und gehört zur gemeinsamen Grilltradition (roštilj) der Region, die ihre Wurzeln in der osmanischen Küche hat. Es handelt sich um eine große, flache, runde Frikadelle aus gewürztem Hackfleisch — in der mehrheitlich nicht schweinefleischverzehrenden Grilltradition häufig aus Rind und Lamm —, die über Holzkohle gegrillt wird. Charakteristisch sind die kräftige Würzung mit Zwiebel und Paprika sowie das gründliche Durchkneten, das der Frikadelle ihre dichte, saftige Textur gibt. Pljeskavica wird klassisch im Fladenbrot (lepinja) mit rohen Zwiebeln, Ajvar, Kajmak und Salat serviert und gilt als herzhaftes Fast Food ebenso wie als Grillfestessen. Eine besonders bekannte, üppige Variante ist die „leskovačka pljeskavica“ aus der Stadt Leskovac. In dieser Fassung kommt sie ganz ohne Schwein aus. Pljeskavica verkörpert die gesellige Grillkultur Serbiens und gehört zu Sommerabenden und Feiern.", "persoenlich": "", "servier": "", "tags": ["Serbien", "Pljeskavica", "Balkan", "Rind", "Lamm", "Grillgericht", "roštilj", "Ajvar", "Kajmak", "osmanisch geprägt", "Straßenessen", "Hauptgericht"]}, {"id": "gibanica", "status": "published", "date": "", "cover": "", "name": "Gibanica", "land": "Serbien", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine geschichtete Filoteigpastete mit einer Füllung aus Weißkäse, Quark und Eiern, knusprig und saftig zugleich. Festtagsgebäck Serbiens.", "zutaten": ["400 g Filoteigblätter (kore)", "300 g Weißkäse (sirene/Feta), zerbröselt", "300 g Quark", "4 Eier", "200 ml Joghurt", "100 ml Mineralwasser", "80 ml Öl", "Salz"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Filoteigblätter (kore)", "roh": "400 g Filoteigblätter (kore)"}, {"menge": 300.0, "einheit": "g", "item": "Weißkäse (sirene/Feta), zerbröselt", "roh": "300 g Weißkäse (sirene/Feta), zerbröselt"}, {"menge": 300.0, "einheit": "g", "item": "Quark", "roh": "300 g Quark"}, {"menge": 4.0, "einheit": "", "item": "Eier", "roh": "4 Eier"}, {"menge": 200.0, "einheit": "ml", "item": "Joghurt", "roh": "200 ml Joghurt"}, {"menge": 100.0, "einheit": "ml", "item": "Mineralwasser", "roh": "100 ml Mineralwasser"}, {"menge": 80.0, "einheit": "ml", "item": "Öl", "roh": "80 ml Öl"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Käse, Quark, Eier und Joghurt zu einer Füllmasse verrühren, salzen.", "Eine Form mit Öl auspinseln.", "Filoblätter einzeln kurz in der Masse wenden, locker zerknüllen und einschichten.", "Zwischendurch mit Öl und Mineralwasser beträufeln, mit einem glatten Blatt abschließen.", "Mit Öl bestreichen und bei 190 °C 40–45 Minuten goldbraun und knusprig backen.", "Etwas ruhen lassen, in Stücke schneiden und mit Joghurt servieren."], "hinweise": "Die Blätter locker einschichten — das macht die Gibanica saftig.\n\nMineralwasser sorgt für eine besonders luftige Füllung.\n\nLauwarm schmeckt sie am besten.", "alternative": "", "geschichte": "Gibanica gehört zu den bekanntesten und beliebtesten Gerichten Serbiens und ist auch in den Nachbarländern des Balkans verbreitet. Es handelt sich um eine Pastete aus dünnen Filoteigblättern (kore), die mit einer Mischung aus Weißkäse (oft sirene oder ein junger Schafskäse), Quark, Eiern und manchmal Joghurt oder Mineralwasser geschichtet und gebacken wird. Die Blätter werden zerknüllt, getränkt und locker eingeschichtet, sodass eine Pastete entsteht, die außen knusprig und innen saftig-cremig ist. Gibanica gehört traditionell zum festlichen Frühstück, zu Feiertagen wie dem orthodoxen Weihnachtsfest und zur Gästebewirtung und wird oft mit Joghurt gereicht. Die Zubereitung mit handgezogenem oder fertigem Filoteig hat eine lange Tradition in der Region und teilt ihre Wurzeln mit den verwandten Pasteten des gesamten Balkans und der osmanischen Küche. In der klassischen Käsefüllung ist Gibanica von Natur aus vegetarisch und ohne Schweinefleisch und gilt als Inbegriff serbischer Gastlichkeit.", "persoenlich": "", "servier": "", "tags": ["Serbien", "Gibanica", "Filoteig", "Weißkäse", "Quark", "vegetarisch", "Frühstück", "Festtag", "Balkan", "Pastete", "osmanisch geprägt", "Hauptgericht"]}, {"id": "prebranac", "status": "published", "date": "", "cover": "", "name": "Prebranac", "land": "Serbien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Geschmorte weiße Bohnen mit reichlich karamellisierten Zwiebeln und Paprikapulver, langsam im Ofen gebacken. Serbisches Bohnengericht, oft zur Fastenzeit.", "zutaten": ["500 g weiße Bohnen, über Nacht eingeweicht", "6 Zwiebeln", "2 EL edelsüßes Paprikapulver", "2 Lorbeerblätter", "100 ml Öl", "1 frische Chili (optional)", "Salz, Pfeffer"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "weiße Bohnen, über Nacht eingeweicht", "roh": "500 g weiße Bohnen, über Nacht eingeweicht"}, {"menge": 6.0, "einheit": "", "item": "Zwiebeln", "roh": "6 Zwiebeln"}, {"menge": 2.0, "einheit": "EL", "item": "edelsüßes Paprikapulver", "roh": "2 EL edelsüßes Paprikapulver"}, {"menge": 2.0, "einheit": "", "item": "Lorbeerblätter", "roh": "2 Lorbeerblätter"}, {"menge": 100.0, "einheit": "ml", "item": "Öl", "roh": "100 ml Öl"}, {"menge": 1.0, "einheit": "", "item": "frische Chili (optional)", "roh": "1 frische Chili (optional)"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}], "zubereitung": ["Die eingeweichten Bohnen in frischem Wasser mit Lorbeer weich, aber nicht zerfallen kochen; abgießen.", "Zwiebeln in Ringe schneiden und in reichlich Öl langsam goldbraun und fast karamellisiert dünsten.", "Vom Herd ziehen und das Paprikapulver einrühren.", "Bohnen und Zwiebeln in einer Form abwechselnd schichten, dazwischen salzen und pfeffern.", "Etwas Bohnenwasser angießen.", "Im Ofen bei 190 °C 40–50 Minuten backen, bis sich oben eine Kruste bildet; mit Brot servieren."], "hinweise": "Viel Zwiebel ist entscheidend — sie gibt die süßliche Tiefe.\n\nPaprikapulver erst nach dem Herd einrühren, sonst wird es bitter.\n\nSchmeckt warm wie kalt und am nächsten Tag noch besser.", "alternative": "", "geschichte": "Prebranac ist ein traditionelles serbisches Bohnengericht und in ähnlicher Form auf dem gesamten Balkan verbreitet. Es beruht auf weißen Bohnen, die mit einer großen Menge langsam gedünsteter, fast karamellisierter Zwiebeln und Paprikapulver geschichtet und im Ofen gebacken werden, bis die Aromen verschmelzen und sich oben eine leicht krustige Schicht bildet. Das Verhältnis von viel Zwiebel zu Bohnen ist charakteristisch und gibt dem Gericht seine süßlich-würzige Tiefe. Prebranac hat eine besondere Bedeutung in der orthodoxen Fastenzeit (posno), in der tierische Produkte gemieden werden — als rein pflanzliches, sättigendes Gericht ist es dann ideal. Es gehört zugleich zur Alltags- und Festtagsküche und wird als Hauptgericht oder Beilage gegessen, oft mit Brot. Bohnengerichte gehören seit Langem zur bodenständigen Küche der Region und boten eine günstige, nahrhafte Mahlzeit. Prebranac ist von Natur aus vegan und ohne Schweinefleisch und steht für die einfache, gemüsebetonte Seite der serbischen Küche.", "persoenlich": "", "servier": "", "tags": ["Serbien", "Prebranac", "weiße Bohnen", "vegan", "vegetarisch", "Zwiebeln", "Paprika", "Fastenspeise", "Balkan", "Ofengericht", "bäuerlich", "Hauptgericht"]}, {"id": "bryndzov-halu-ky", "status": "published", "date": "", "cover": "", "name": "Bryndzové halušky", "land": "Slowakei", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine Kartoffelnocken mit cremigem Schafskäse (bryndza) und gerösteten Zwiebeln. Das Nationalgericht der Slowakei.", "zutaten": ["1 kg mehligkochende Kartoffeln", "250 g Mehl", "1 Ei", "300 g bryndza (Schafsfrischkäse)", "3 Zwiebeln", "60 g Butter", "Salz; Schnittlauch zum Servieren"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "mehligkochende Kartoffeln", "roh": "1 kg mehligkochende Kartoffeln"}, {"menge": 250.0, "einheit": "g", "item": "Mehl", "roh": "250 g Mehl"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 300.0, "einheit": "g", "item": "bryndza (Schafsfrischkäse)", "roh": "300 g bryndza (Schafsfrischkäse)"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln", "roh": "3 Zwiebeln"}, {"menge": 60.0, "einheit": "g", "item": "Butter", "roh": "60 g Butter"}, {"menge": null, "einheit": "", "item": "Salz; Schnittlauch zum Servieren", "roh": "Salz; Schnittlauch zum Servieren"}], "zubereitung": ["Kartoffeln fein reiben und mit Mehl, Ei und Salz zu einem zähen Teig verrühren.", "Den Teig portionsweise durch ein Halušky- oder Spätzlesieb in siedendes Salzwasser drücken.", "Aufgeschwommene Nocken abschöpfen und abtropfen lassen.", "Bryndza mit etwas heißem Kochwasser cremig rühren.", "Die warmen Nocken mit dem Käse vermengen, bis alles cremig ist.", "Zwiebelringe in Butter goldbraun rösten und mit etwas Schnittlauch über die Halušky geben."], "hinweise": "Den Teig zügig verarbeiten, damit die geriebenen Kartoffeln nicht dunkel werden.\n\nDen Käse mit etwas Kochwasser geschmeidig machen.\n\nSofort servieren, solange die Masse cremig ist.", "alternative": "Klassisch werden Bryndzové halušky mit ausgelassenem Speck und dessen Fett serviert. Wir verwenden stattdessen reichlich in Butter goldbraun geröstete Zwiebeln — sie geben die herzhafte, leicht süßliche Tiefe, ganz ohne Schwein.", "geschichte": "Bryndzové halušky gelten als das Nationalgericht der Slowakei und verkörpern die Hirten- und Bergküche der Karpaten. Das Gericht verbindet zwei Grundpfeiler der slowakischen Ernährung: kleine Kartoffelnocken (halušky), die einem Spätzle- oder Gnocchi-Teig ähneln, und bryndza, einen würzig-cremigen Schafskäse, der traditionell von den Schäfern in den Bergen hergestellt wurde. Die Verbindung von Kartoffel und Schafskäse spiegelt die Almwirtschaft wider, in der Schafe Milch und Käse lieferten. Der warme Käse wird mit den frisch gekochten Nocken vermengt, bis eine cremige, leicht salzige Masse entsteht. Traditionell wird das Gericht mit ausgelassenem Speck und dessen Fett gekrönt; in dieser Fassung treten goldbraun geröstete Zwiebeln und etwas Butter an die Stelle des Schweinefleischs. Bryndzové halušky werden im ganzen Land geschätzt, von Berghütten bis zu Restaurants, und gelten als identitätsstiftendes Gericht. In dieser Variante kommen sie ohne Schwein aus.", "persoenlich": "", "servier": "", "tags": ["Slowakei", "Bryndzové halušky", "Kartoffelnocken", "bryndza", "Schafskäse", "vegetarisch", "Karpaten", "Hirtenküche", "Nationalgericht", "Röstzwiebeln", "Bergküche", "Hauptgericht"]}, {"id": "zemiakov-placky", "status": "published", "date": "", "cover": "", "name": "Zemiakové placky", "land": "Slowakei", "kontinent": "Europa", "gang": "Beilage", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 20, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Knusprige Kartoffelpuffer mit Knoblauch und Majoran, in der Pfanne goldbraun gebraten. Beliebter Kartoffelklassiker der slowakischen Küche.", "zutaten": ["800 g mehligkochende Kartoffeln", "4 Zehen Knoblauch", "1 Ei", "4 EL Mehl", "1 TL getrockneter Majoran", "Öl zum Braten, Salz, Pfeffer"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "mehligkochende Kartoffeln", "roh": "800 g mehligkochende Kartoffeln"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "4 Zehen Knoblauch"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 4.0, "einheit": "EL", "item": "Mehl", "roh": "4 EL Mehl"}, {"menge": 1.0, "einheit": "TL", "item": "getrockneter Majoran", "roh": "1 TL getrockneter Majoran"}, {"menge": null, "einheit": "", "item": "Öl zum Braten, Salz, Pfeffer", "roh": "Öl zum Braten, Salz, Pfeffer"}], "zubereitung": ["Kartoffeln fein reiben und die Flüssigkeit gut ausdrücken.", "Mit zerdrücktem Knoblauch, Ei, Mehl, Majoran, Salz und Pfeffer zu einem Teig vermengen.", "Reichlich Öl in einer Pfanne erhitzen.", "Aus dem Teig dünne Fladen formen und in das heiße Öl geben.", "Beidseitig goldbraun und knusprig braten.", "Auf Küchenpapier abtropfen lassen und heiß servieren."], "hinweise": "Die Kartoffeln gut ausdrücken — je trockener, desto knuspriger.\n\nKnoblauch und Majoran sind die typische slowakische Würze.\n\nDünn ausbacken für maximale Knusprigkeit.", "alternative": "", "geschichte": "Zemiakové placky — Kartoffelpuffer — gehören zur bodenständigen Alltagsküche der Slowakei und sind in ähnlicher Form in ganz Mitteleuropa verbreitet. Sie spiegeln die zentrale Rolle der Kartoffel in der Ernährung der Region wider, die seit dem 18. und 19. Jahrhundert zum Grundnahrungsmittel wurde. Geriebene rohe Kartoffeln werden mit Mehl, Ei, reichlich Knoblauch und dem in der slowakischen Küche typischen Majoran zu einem Teig vermengt und in heißem Fett zu dünnen, knusprigen Fladen ausgebacken. Charakteristisch für die slowakische Variante ist die kräftige Würzung mit Knoblauch und Majoran, die den Puffern ihr unverwechselbares Aroma gibt. Zemiakové placky waren ein günstiges, sättigendes Essen, das aus einfachen Vorräten zubereitet werden konnte, und werden als Hauptgericht, Beilage oder Snack gegessen, oft pur oder mit etwas Sauerrahm. Sie sind von Natur aus vegetarisch und ohne Schweinefleisch und gehören zu den beliebten, schnell zubereiteten Gerichten der slowakischen Hausmannskost.", "persoenlich": "", "servier": "", "tags": ["Slowakei", "Zemiakové placky", "Kartoffelpuffer", "vegetarisch", "Knoblauch", "Majoran", "gebraten", "Hausmannskost", "Snack", "Mitteleuropa", "knusprig", "Beilage"]}, {"id": "ance-s-makom", "status": "published", "date": "", "cover": "", "name": "Šúľance s makom", "land": "Slowakei", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Kleine Kartoffelteig-Röllchen, geschwenkt in gemahlenem Mohn und Zucker mit zerlassener Butter. Süße slowakische Mehlspeise.", "zutaten": ["500 g gekochte Kartoffeln (vom Vortag)", "200 g Mehl", "1 Ei", "120 g gemahlener Mohn", "80 g Zucker", "60 g Butter", "1 Prise Salz"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "gekochte Kartoffeln (vom Vortag)", "roh": "500 g gekochte Kartoffeln (vom Vortag)"}, {"menge": 200.0, "einheit": "g", "item": "Mehl", "roh": "200 g Mehl"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 120.0, "einheit": "g", "item": "gemahlener Mohn", "roh": "120 g gemahlener Mohn"}, {"menge": 80.0, "einheit": "g", "item": "Zucker", "roh": "80 g Zucker"}, {"menge": 60.0, "einheit": "g", "item": "Butter", "roh": "60 g Butter"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}], "zubereitung": ["Kartoffeln fein zerdrücken und mit Mehl, Ei und Salz zu einem glatten Teig verkneten.", "Aus dem Teig fingerdicke Rollen formen und in kurze, längliche Stücke schneiden, die Enden leicht anspitzen.", "Die Šúľance in siedendem Salzwasser garen, bis sie aufschwimmen; abtropfen lassen.", "Mohn mit Zucker mischen.", "Die Röllchen in zerlassener Butter schwenken.", "Mit der Mohn-Zucker-Mischung bestreuen und heiß servieren."], "hinweise": "Kartoffeln vom Vortag ergeben einen besseren, festeren Teig.\n\nDen Mohn frisch mahlen für das beste Aroma.\n\nHeiß servieren, mit reichlich zerlassener Butter.", "alternative": "", "geschichte": "Šúľance s makom sind eine traditionelle süße Mehlspeise der Slowakei und in ähnlicher Form in der gesamten mitteleuropäischen Küche verbreitet. Es handelt sich um kleine, längliche Röllchen aus einem Kartoffel-Mehl-Teig, die von Hand geformt (das Wort „šúľať“ bedeutet rollen), gekocht und anschließend in zerlassener Butter, gemahlenem Mohn und Zucker geschwenkt werden. Mohn hat in der slowakischen und mitteleuropäischen Küche eine lange Tradition und spielt besonders in süßen Gerichten und Festtagsspeisen eine wichtige Rolle. Süße Hauptgerichte und Mehlspeisen waren in der Region weit verbreitet und galten als vollwertige Mahlzeit, nicht nur als Nachtisch. Šúľance s makom waren ein günstiges, sättigendes Essen aus einfachen Zutaten und werden bis heute als wohlig-süßes Gericht geschätzt, das an Kindheit und Großmutterküche erinnert. Als reine Kartoffel-Mehl-Mohn-Speise sind sie selbstverständlich vegetarisch und ohne Schweinefleisch und stehen für die süße Seite der slowakischen Hausmannskost.", "persoenlich": "", "servier": "", "tags": ["Slowakei", "Šúľance", "Mohn", "Kartoffelteig", "süß", "vegetarisch", "Mehlspeise", "Mitteleuropa", "Hausmannskost", "Großmutterküche", "Butter", "Dessert"]}, {"id": "truklji", "status": "published", "date": "", "cover": "", "name": "Štruklji", "land": "Slowenien", "kontinent": "Europa", "gang": "Beilage", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Gerollte, gefüllte Teigrollen aus dünnem Teig, klassisch mit Quark (skuta), gedämpft oder gekocht. Vielseitige slowenische Spezialität.", "zutaten": ["300 g Mehl", "150 ml lauwarmes Wasser", "1 Ei", "2 EL Öl", "500 g Quark (skuta)", "2 Eier (Füllung)", "50 g saure Sahne", "Salz, etwas Zucker; Butterbrösel zum Servieren"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "Mehl", "roh": "300 g Mehl"}, {"menge": 150.0, "einheit": "ml", "item": "lauwarmes Wasser", "roh": "150 ml lauwarmes Wasser"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 2.0, "einheit": "EL", "item": "Öl", "roh": "2 EL Öl"}, {"menge": 500.0, "einheit": "g", "item": "Quark (skuta)", "roh": "500 g Quark (skuta)"}, {"menge": 2.0, "einheit": "", "item": "Eier (Füllung)", "roh": "2 Eier (Füllung)"}, {"menge": 50.0, "einheit": "g", "item": "saure Sahne", "roh": "50 g saure Sahne"}, {"menge": null, "einheit": "", "item": "Salz, etwas Zucker; Butterbrösel zum Servieren", "roh": "Salz, etwas Zucker; Butterbrösel zum Servieren"}], "zubereitung": ["Mehl, Wasser, Ei, Öl und Salz zu einem geschmeidigen Teig kneten und ruhen lassen.", "Den Teig sehr dünn ausziehen oder ausrollen.", "Quark mit Eiern, saurer Sahne und etwas Salz und Zucker zu einer Füllung verrühren.", "Die Füllung auf dem Teig verstreichen und diesen fest aufrollen.", "Die Rolle in ein Tuch wickeln und in siedendem Wasser garen oder dämpfen (ca. 30 Minuten).", "In Scheiben schneiden und mit gerösteten Butterbröseln servieren."], "hinweise": "Den Teig möglichst dünn ausziehen — das ist die Kunst der Štruklji.\n\nIm Tuch gegart behält die Rolle ihre Form.\n\nMit Butterbröseln bestreut schmecken sie am besten.", "alternative": "", "geschichte": "Štruklji gehören zu den bekanntesten und ältesten Gerichten der slowenischen Küche und sind in zahllosen regionalen Varianten überliefert. Es handelt sich um gerollte Teigrollen, bei denen ein dünn ausgezogener Teig mit einer Füllung bestrichen, fest aufgerollt und dann gekocht, gedämpft oder gebacken wird. Die Füllungen sind außerordentlich vielfältig und reichen von herzhaft bis süß: am verbreitetsten ist Quark (skuta), daneben gibt es Varianten mit Estragon, Walnuss, Äpfeln oder Kräutern. Štruklji haben in Slowenien eine so große Bedeutung, dass mehr als hundert verschiedene Sorten dokumentiert sind und sie als Teil des nationalen kulinarischen Erbes gelten. Sie können als Beilage zu Fleischgerichten, als eigenständiges Gericht oder als Dessert serviert werden. Ihre Wurzeln reichen weit zurück und verbinden bäuerliche Tradition mit festlicher Tafel. Die Quark-Variante ist von Natur aus vegetarisch und ohne Schweinefleisch und steht sinnbildlich für die Vielfalt und Tiefe der slowenischen Küche.", "persoenlich": "", "servier": "", "tags": ["Slowenien", "Štruklji", "Teigrolle", "Quark", "skuta", "vegetarisch", "kulinarisches Erbe", "gedämpft", "Beilage", "Hausmannskost", "vielseitig", "Dessert"]}, {"id": "ganci", "status": "published", "date": "", "cover": "", "name": "Žganci", "land": "Slowenien", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein krümeliger Brei aus Buchweizen- oder Maismehl, mit Butter oder Grieben. Bodenständiges Grundnahrungsmittel der slowenischen Bauernküche.", "zutaten": ["300 g Buchweizenmehl (oder Maismehl)", "750 ml Wasser", "1 TL Salz", "60 g Butter"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "Buchweizenmehl (oder Maismehl)", "roh": "300 g Buchweizenmehl (oder Maismehl)"}, {"menge": 750.0, "einheit": "ml", "item": "Wasser", "roh": "750 ml Wasser"}, {"menge": 1.0, "einheit": "TL", "item": "Salz", "roh": "1 TL Salz"}, {"menge": 60.0, "einheit": "g", "item": "Butter", "roh": "60 g Butter"}], "zubereitung": ["Salzwasser zum Kochen bringen.", "Das Buchweizenmehl in die Mitte einrieseln lassen, sodass ein Kegel entsteht; nicht rühren.", "Etwa 15 Minuten bei kleiner Hitze kochen, dann einen Teil des Wassers abschöpfen.", "Mit einem Kochlöffel oder einer Gabel das Mehl in unregelmäßige Krümel zerteilen und mit dem restlichen Wasser verbinden.", "Zerlassene Butter darübergeben und untermischen.", "Warm als Beilage, zum Frühstück mit Milch oder zu Sauerkraut servieren."], "hinweise": "Das Mehl als Kegel einrieseln lassen und erst nach dem Garen zerteilen.\n\nMit reichlich Butter werden die Žganci besonders aromatisch.\n\nAuch zu Eintöpfen und Sauerkraut eine klassische Beilage.", "alternative": "", "geschichte": "Žganci sind eine traditionelle slowenische Mehlspeise und gehörten über Generationen zu den wichtigsten Grundnahrungsmitteln der ländlichen Bevölkerung. Klassisch werden sie aus Buchweizenmehl (ajdovi žganci) zubereitet, daneben gibt es Varianten aus Mais- oder Weizenmehl. Buchweizen hat in Slowenien eine lange Tradition und prägt zahlreiche Gerichte des Landes. Für Žganci wird das Mehl in heißem Salzwasser zu einem festen Brei gekocht, der anschließend mit einer Gabel oder einem Holzlöffel in unregelmäßige Krümel zerteilt und mit Fett — traditionell Butter oder Grieben — verfeinert wird. Das Gericht war ein günstiges, sättigendes Essen, das Bauern und Arbeitern Kraft gab und zu vielen Tageszeiten gegessen wurde, oft zum Frühstück mit Milch oder als Beilage zu Eintöpfen und Sauerkraut. Žganci spiegeln die schlichte, getreidebetonte Seite der slowenischen Küche wider. In der Fassung mit Butter sind sie von Natur aus vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Slowenien", "Žganci", "Buchweizen", "Brei", "vegetarisch", "Bauernküche", "Grundnahrungsmittel", "Butter", "Frühstück", "schlicht", "Getreideküche", "Beilage"]}, {"id": "prekmurska-gibanica", "status": "published", "date": "", "cover": "", "name": "Prekmurska gibanica", "land": "Slowenien", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine reichhaltige Schichtmehlspeise mit Mohn, Walnuss, Apfel und Quark zwischen dünnen Teigblättern. Das Festtagsgebäck der Region Prekmurje.", "zutaten": ["400 g dünne Strudel-/Filoteigblätter", "150 g gemahlener Mohn", "150 g gemahlene Walnüsse", "500 g geriebener Apfel", "400 g Quark", "200 g Zucker (auf die Füllungen verteilt)", "200 ml saure Sahne und 100 g Butter", "2 Eier; Rosinen, Zimt nach Geschmack"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "dünne Strudel-/Filoteigblätter", "roh": "400 g dünne Strudel-/Filoteigblätter"}, {"menge": 150.0, "einheit": "g", "item": "gemahlener Mohn", "roh": "150 g gemahlener Mohn"}, {"menge": 150.0, "einheit": "g", "item": "gemahlene Walnüsse", "roh": "150 g gemahlene Walnüsse"}, {"menge": 500.0, "einheit": "g", "item": "geriebener Apfel", "roh": "500 g geriebener Apfel"}, {"menge": 400.0, "einheit": "g", "item": "Quark", "roh": "400 g Quark"}, {"menge": 200.0, "einheit": "g", "item": "Zucker (auf die Füllungen verteilt)", "roh": "200 g Zucker (auf die Füllungen verteilt)"}, {"menge": 200.0, "einheit": "ml", "item": "saure Sahne und 100 g Butter", "roh": "200 ml saure Sahne und 100 g Butter"}, {"menge": 2.0, "einheit": "", "item": "Eier; Rosinen, Zimt nach Geschmack", "roh": "2 Eier; Rosinen, Zimt nach Geschmack"}], "zubereitung": ["Die vier Füllungen separat anrühren: Mohn mit Zucker, Walnuss mit Zucker, geriebenen Apfel mit Zimt, Quark mit Ei und Zucker.", "Eine Form mit Butter ausstreichen und ein Teigblatt einlegen, mit Butter und etwas saurer Sahne beträufeln.", "Nacheinander die Füllungen einschichten, jeweils durch ein Teigblatt getrennt und mit Butter/Sahne beträufelt.", "Die Schichtung wiederholen, bis alle Füllungen verbraucht sind, mit Teigblättern abschließen.", "Mit verquirltem Ei und saurer Sahne bestreichen.", "Bei 180 °C 50–60 Minuten backen; gut auskühlen lassen und in Stücke schneiden."], "hinweise": "Jede Schicht mit Butter und saurer Sahne beträufeln — das macht die Gibanica saftig.\n\nVollständig auskühlen lassen, damit sich die Schichten setzen.\n\nDie Reihenfolge Mohn–Quark–Walnuss–Apfel ist klassisch.", "alternative": "", "geschichte": "Die Prekmurska gibanica ist eine der berühmtesten Süßspeisen Sloweniens und stammt aus der nordöstlichen Region Prekmurje. Sie genießt einen geschützten Status als traditionelle Spezialität in der EU. Charakteristisch ist ihr aufwendiger, vielschichtiger Aufbau: Zwischen dünnen Teig- oder Strudelblättern werden vier klassische Füllungen geschichtet — Mohn, Walnuss, geriebener Apfel und Quark —, oft jede zweimal, sodass ein hoher, reichhaltiger Kuchen mit acht oder mehr Lagen entsteht. Diese Kombination spiegelt die Fülle und Symbolik einer Festtagsspeise wider und galt als Ausdruck von Wohlstand und Gastfreundschaft. Die Prekmurska gibanica wurde traditionell zu großen Festen, Hochzeiten und Feiertagen gebacken und erfordert Geduld und Geschick. Mit Sahne oder saurer Sahne verfeinert, ist sie besonders saftig und gehaltvoll. Als reine Mehlspeise mit pflanzlichen und Milchfüllungen ist sie selbstverständlich vegetarisch und ohne Schweinefleisch und gilt als kulinarisches Wahrzeichen Sloweniens.", "persoenlich": "", "servier": "", "tags": ["Slowenien", "Prekmurje", "Prekmurska gibanica", "Mohn", "Walnuss", "Apfel", "Quark", "Schichtgebäck", "geschützte Spezialität", "vegetarisch", "Festtag", "Dessert"]}, {"id": "paella-valenciana", "status": "published", "date": "", "cover": "", "name": "Paella valenciana", "land": "Spanien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Safranreis aus der flachen Pfanne mit Huhn, Kaninchen, grünen Bohnen und Garrofó-Bohnen. Das Original aus Valencia.", "zutaten": ["400 g Paellareis (Rundkorn, z. B. Bomba)", "500 g Hähnchenteile", "400 g Kaninchenteile", "200 g grüne Flachbohnen", "150 g weiße Garrofó- oder dicke Bohnen", "1 Tomate, gerieben", "1 Briefchen Safran, 1 TL Paprikapulver", "1.2 l Hühnerbrühe", "Olivenöl, Salz, Rosmarin"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Paellareis (Rundkorn, z. B. Bomba)", "roh": "400 g Paellareis (Rundkorn, z. B. Bomba)"}, {"menge": 500.0, "einheit": "g", "item": "Hähnchenteile", "roh": "500 g Hähnchenteile"}, {"menge": 400.0, "einheit": "g", "item": "Kaninchenteile", "roh": "400 g Kaninchenteile"}, {"menge": 200.0, "einheit": "g", "item": "grüne Flachbohnen", "roh": "200 g grüne Flachbohnen"}, {"menge": 150.0, "einheit": "g", "item": "weiße Garrofó- oder dicke Bohnen", "roh": "150 g weiße Garrofó- oder dicke Bohnen"}, {"menge": 1.0, "einheit": "", "item": "Tomate, gerieben", "roh": "1 Tomate, gerieben"}, {"menge": 1.0, "einheit": "Briefchen", "item": "Safran, 1 TL Paprikapulver", "roh": "1 Briefchen Safran, 1 TL Paprikapulver"}, {"menge": 1.2, "einheit": "l", "item": "Hühnerbrühe", "roh": "1.2 l Hühnerbrühe"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Rosmarin", "roh": "Olivenöl, Salz, Rosmarin"}], "zubereitung": ["Huhn und Kaninchen in der Paellapfanne in Olivenöl rundum kräftig anbraten.", "Die Bohnen zugeben und mitbraten.", "Geriebene Tomate und Paprikapulver einrühren und kurz anrösten.", "Mit heißer Brühe auffüllen, Safran und Rosmarin zugeben und etwa 20 Minuten köcheln.", "Den Reis gleichmäßig einstreuen und ohne weiteres Rühren bei mittlerer Hitze garen, bis die Flüssigkeit aufgenommen ist.", "Zum Schluss die Hitze kurz erhöhen, damit sich der socarrat (Kruste) bildet; vor dem Servieren ruhen lassen."], "hinweise": "Nach dem Einstreuen des Reises nicht mehr umrühren.\n\nDie knusprige Kruste (socarrat) am Boden ist begehrt — am Ende kurz stärker erhitzen.\n\nDie Paella vor dem Servieren einige Minuten ruhen lassen.", "alternative": "", "geschichte": "Die Paella valenciana ist das berühmteste Reisgericht Spaniens und stammt aus der Region Valencia, wo sie als Inbegriff der regionalen Identität gilt. Anders als die international verbreiteten Meeresfrüchte- oder gemischten Paellas enthält die authentische valencianische Paella traditionell kein Schwein und keine Meeresfrüchte, sondern Huhn, Kaninchen, grüne Flachbohnen (bajoqueta), die weiße Garrofó-Bohne, Tomate und Safran. Sie entstand als Mittagessen der Landarbeiter im Umland von Valencia, die das Gericht im Freien über Holzfeuer aus dem zubereiteten, was Hof und Feld hergaben — Reis aus der Albufera-Region, Geflügel, Kaninchen und Gemüse. Charakteristisch sind die flache, breite Pfanne (die eigentliche „paella“), die dünne Reisschicht und die begehrte geröstete Kruste am Boden, der „socarrat“. Die Paella valenciana ist von Natur aus ohne Schweinefleisch und steht sinnbildlich für die gesellige, im Freien zelebrierte Esskultur der Region.", "persoenlich": "", "servier": "", "tags": ["Spanien", "Valencia", "Paella", "Reis", "Huhn", "Kaninchen", "Safran", "Bohnen", "Klassiker", "socarrat", "im Freien", "Hauptgericht"]}, {"id": "gazpacho-andaluz", "status": "published", "date": "", "cover": "", "name": "Gazpacho andaluz", "land": "Spanien", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine kalte, pürierte Suppe aus reifen Tomaten, Gurke, Paprika, Knoblauch und Olivenöl. Erfrischung aus dem heißen Andalusien.", "zutaten": ["1 kg reife Tomaten", "1 Salatgurke", "1 grüne Paprika", "1 Zehe Knoblauch", "50 g altbackenes Weißbrot", "5 EL Olivenöl extra vergine", "2 EL Sherry- oder Weinessig", "Salz, kaltes Wasser"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "reife Tomaten", "roh": "1 kg reife Tomaten"}, {"menge": 1.0, "einheit": "", "item": "Salatgurke", "roh": "1 Salatgurke"}, {"menge": 1.0, "einheit": "", "item": "grüne Paprika", "roh": "1 grüne Paprika"}, {"menge": 1.0, "einheit": "Zehe", "item": "Knoblauch", "roh": "1 Zehe Knoblauch"}, {"menge": 50.0, "einheit": "g", "item": "altbackenes Weißbrot", "roh": "50 g altbackenes Weißbrot"}, {"menge": 5.0, "einheit": "EL", "item": "Olivenöl extra vergine", "roh": "5 EL Olivenöl extra vergine"}, {"menge": 2.0, "einheit": "EL", "item": "Sherry- oder Weinessig", "roh": "2 EL Sherry- oder Weinessig"}, {"menge": null, "einheit": "", "item": "Salz, kaltes Wasser", "roh": "Salz, kaltes Wasser"}], "zubereitung": ["Tomaten, Gurke und Paprika grob zerteilen.", "Das Brot kurz in Wasser einweichen.", "Alle Gemüse mit Knoblauch, Brot, Olivenöl, Essig und Salz fein pürieren.", "Mit etwas kaltem Wasser auf die gewünschte Konsistenz verdünnen.", "Für eine besonders feine Suppe durch ein Sieb passieren.", "Mindestens 2 Stunden gut durchkühlen und eiskalt servieren, nach Wunsch mit Gemüsewürfeln."], "hinweise": "Sehr reife, aromatische Tomaten sind entscheidend.\n\nGutes Olivenöl gibt dem Gazpacho Tiefe und Cremigkeit.\n\nEiskalt servieren — am besten über Nacht durchgekühlt.", "alternative": "", "geschichte": "Gazpacho ist die berühmteste kalte Suppe Spaniens und stammt aus der südlichen Region Andalusien, wo die heißen Sommer eine erfrischende, ungekochte Speise nahelegten. Die Ursprünge reichen weit zurück; frühe Formen beruhten auf Brot, Olivenöl, Essig, Knoblauch und Wasser, die zerstoßen wurden — die Tomate kam erst nach der Einführung amerikanischer Zutaten hinzu und prägt das heutige, rote Gazpacho. Es war ursprünglich ein einfaches, sättigendes Essen der Landarbeiter, das aus haltbaren Grundzutaten und dem Gemüse der Saison bereitet wurde. Für das moderne Gazpacho andaluz werden reife Tomaten, Gurke, Paprika, Knoblauch, Brot, Olivenöl und Essig fein püriert und eiskalt serviert, oft mit fein gewürfeltem Gemüse als Einlage. Es ist leicht, vitaminreich und ideal für heiße Tage. Als rein pflanzliches Gericht ist Gazpacho von Natur aus vegan und ohne Schweinefleisch und gilt als Inbegriff der sommerlichen, mediterranen Küche Südspaniens.", "persoenlich": "", "servier": "", "tags": ["Spanien", "Andalusien", "Gazpacho", "kalte Suppe", "Tomaten", "Gurke", "Paprika", "vegan", "vegetarisch", "Sommerküche", "mediterran", "Vorspeise"]}, {"id": "tortilla-espa-ola", "status": "published", "date": "", "cover": "", "name": "Tortilla española", "land": "Spanien", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein dickes, saftiges Omelett aus Kartoffeln, Zwiebeln und Ei, in der Pfanne gewendet. Spaniens allgegenwärtige Kartoffeltortilla.", "zutaten": ["600 g festkochende Kartoffeln", "1 Zwiebel", "6 Eier", "200 ml Olivenöl", "Salz"], "zutatenS": [{"menge": 600.0, "einheit": "g", "item": "festkochende Kartoffeln", "roh": "600 g festkochende Kartoffeln"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 6.0, "einheit": "", "item": "Eier", "roh": "6 Eier"}, {"menge": 200.0, "einheit": "ml", "item": "Olivenöl", "roh": "200 ml Olivenöl"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Kartoffeln in dünne Scheiben schneiden, Zwiebel in Streifen.", "Beides in reichlich Olivenöl bei mittlerer Hitze weich, aber nicht braun garen; abtropfen lassen.", "Eier verquirlen, salzen und die Kartoffeln und Zwiebeln untermengen; kurz ziehen lassen.", "Wenig Öl in einer Pfanne erhitzen und die Masse hineingeben, bei mittlerer Hitze stocken lassen.", "Die Tortilla mithilfe eines Tellers wenden und die andere Seite fertig garen.", "Innen saftig belassen; warm oder kalt servieren."], "hinweise": "Die Kartoffeln im Öl gar ziehen, nicht braten.\n\nDie Mitte darf leicht cremig bleiben — das ist typisch.\n\nMit einem Teller gelingt das Wenden am besten.", "alternative": "", "geschichte": "Die Tortilla española (auch tortilla de patatas) ist eines der bekanntesten und beliebtesten Gerichte Spaniens und in praktisch jeder Bar, jedem Haushalt und jeder Tapas-Auswahl des Landes zu finden. Sie besteht im Kern aus nur wenigen Zutaten: Kartoffeln, Eiern und Olivenöl, häufig ergänzt durch Zwiebeln. Die in Öl sanft gegarten Kartoffeln werden mit verquirltem Ei vermengt und in der Pfanne zu einem dicken, runden Omelett gebraten, das einmal gewendet wird, sodass es innen saftig und außen goldgelb ist. Die Tortilla verbreitete sich im 19. Jahrhundert als günstiges, sättigendes Essen und wurde zu einem nationalen Grundgericht. Bis heute wird über die „richtige“ Zubereitung diskutiert — vor allem über die Frage, ob mit oder ohne Zwiebeln und wie flüssig die Mitte sein darf. Sie wird warm oder kalt, als Hauptgericht, Tapa oder im Brot (bocadillo) gegessen. Als Kartoffel-Ei-Gericht ist sie selbstverständlich vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Spanien", "Tortilla española", "Kartoffeltortilla", "Ei", "Kartoffeln", "vegetarisch", "Tapas", "Olivenöl", "Klassiker", "bocadillo", "Hausmannskost", "Hauptgericht"]}, {"id": "sv-kov-na-smetan", "status": "published", "date": "", "cover": "", "name": "Svíčková na smetaně", "land": "Tschechien", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Rinderlende in einer cremigen, pürierten Wurzelgemüsesauce, serviert mit Semmelknödeln, Preiselbeeren und Sahne. Das Nationalgericht Tschechiens.", "zutaten": ["1 kg Rinderlende oder Tafelspitz", "2 Möhren", "0.5 Knollensellerie, 1 Petersilienwurzel", "2 Zwiebeln", "250 ml Sahne", "1 EL Mehl", "5 Pimentkörner, 1 Lorbeerblatt, Thymian, etwas Essig und Zucker", "Butter, Salz; Semmelknödel und Preiselbeeren zum Servieren"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "Rinderlende oder Tafelspitz", "roh": "1 kg Rinderlende oder Tafelspitz"}, {"menge": 2.0, "einheit": "", "item": "Möhren", "roh": "2 Möhren"}, {"menge": 0.5, "einheit": "", "item": "Knollensellerie, 1 Petersilienwurzel", "roh": "0.5 Knollensellerie, 1 Petersilienwurzel"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 250.0, "einheit": "ml", "item": "Sahne", "roh": "250 ml Sahne"}, {"menge": 1.0, "einheit": "EL", "item": "Mehl", "roh": "1 EL Mehl"}, {"menge": 5.0, "einheit": "", "item": "Pimentkörner, 1 Lorbeerblatt, Thymian, etwas Essig und Zucker", "roh": "5 Pimentkörner, 1 Lorbeerblatt, Thymian, etwas Essig und Zucker"}, {"menge": null, "einheit": "", "item": "Butter, Salz; Semmelknödel und Preiselbeeren zum Servieren", "roh": "Butter, Salz; Semmelknödel und Preiselbeeren zum Servieren"}], "zubereitung": ["Das Rindfleisch salzen und in Butter rundum kräftig anbraten; herausnehmen.", "Grob geschnittenes Wurzelgemüse und Zwiebeln mit den Gewürzen anrösten.", "Fleisch zurückgeben, mit etwas Wasser angießen und zugedeckt 2–2,5 Stunden schmoren, bis es zart ist.", "Fleisch herausnehmen; das Lorbeerblatt entfernen und die Gemüsesauce fein pürieren.", "Mit etwas Mehl gebunden und Sahne verfeinern, mit Essig, Zucker und Salz zur süßlich-säuerlichen Balance abschmecken.", "Das Fleisch in Scheiben mit der Sauce, Semmelknödeln, Sahne und Preiselbeeren servieren."], "hinweise": "Reichlich Wurzelgemüse gibt der pürierten Sauce ihre Cremigkeit.\n\nDie Balance aus süß (Zucker, Preiselbeeren) und säuerlich (Essig) ist typisch.\n\nSemmelknödel gehören untrennbar dazu.", "alternative": "", "geschichte": "Svíčková na smetaně gilt als eines der Nationalgerichte Tschechiens und steht für die festliche, sonntägliche Tafel. Im Zentrum steht ein Stück Rinderlende (svíčková), das mariniert, mit reichlich Wurzelgemüse — Möhre, Sellerie, Petersilienwurzel — und Gewürzen geschmort und dann zu einer charakteristisch cremigen, leicht süßlich-säuerlichen Sauce verarbeitet wird, indem das Gemüse püriert und mit Sahne verfeinert wird. Das Gericht entwickelte sich in der bürgerlichen und gehobenen böhmischen Küche und wurde zu einem Inbegriff tschechischer Festessen. Serviert wird die Svíčková klassisch mit Semmelknödeln (houskové knedlíky), die die Sauce aufnehmen, sowie einem Klecks Schlagsahne, Preiselbeerkompott und einer Zitronenscheibe. Die Balance aus zartem Rind, samtiger Sauce, süßen Preiselbeeren und Sahne ist charakteristisch. Als reines Rindfleischgericht ist Svíčková von Natur aus ohne Schweinefleisch und gilt als das tschechische Sonntagsessen schlechthin.", "persoenlich": "", "servier": "", "tags": ["Tschechien", "Svíčková", "Rind", "Rahmsauce", "Wurzelgemüse", "Semmelknödel", "Preiselbeeren", "Nationalgericht", "Sonntagsessen", "böhmisch", "Festtag", "Hauptgericht"]}, {"id": "brambor-ky", "status": "published", "date": "", "cover": "", "name": "Bramboráky", "land": "Tschechien", "kontinent": "Europa", "gang": "Beilage", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 20, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Knusprige Kartoffelpuffer mit Knoblauch und Majoran, in der Pfanne goldbraun gebraten. Beliebter böhmischer Kartoffelklassiker.", "zutaten": ["800 g mehligkochende Kartoffeln", "4 Zehen Knoblauch", "1 Ei", "4 EL Mehl", "1 TL getrockneter Majoran", "Öl zum Braten, Salz, Pfeffer"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "mehligkochende Kartoffeln", "roh": "800 g mehligkochende Kartoffeln"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "4 Zehen Knoblauch"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 4.0, "einheit": "EL", "item": "Mehl", "roh": "4 EL Mehl"}, {"menge": 1.0, "einheit": "TL", "item": "getrockneter Majoran", "roh": "1 TL getrockneter Majoran"}, {"menge": null, "einheit": "", "item": "Öl zum Braten, Salz, Pfeffer", "roh": "Öl zum Braten, Salz, Pfeffer"}], "zubereitung": ["Kartoffeln fein reiben und überschüssige Flüssigkeit ausdrücken.", "Mit zerdrücktem Knoblauch, Ei, Mehl, Majoran, Salz und Pfeffer zu einem Teig vermengen.", "Reichlich Öl in einer Pfanne erhitzen.", "Dünne Fladen formen und ins heiße Öl geben.", "Beidseitig goldbraun und knusprig braten.", "Auf Küchenpapier abtropfen lassen und heiß servieren."], "hinweise": "Die geriebenen Kartoffeln gut ausdrücken für maximale Knusprigkeit.\n\nKnoblauch und Majoran großzügig verwenden — das ist typisch böhmisch.\n\nDünn ausbacken, damit sie durchgaren und knusprig werden.", "alternative": "", "geschichte": "Bramboráky (auch bramborák oder cmunda) sind herzhafte Kartoffelpuffer und gehören zu den beliebtesten einfachen Gerichten der tschechischen Küche. Sie spiegeln die zentrale Rolle der Kartoffel in der böhmischen und mährischen Ernährung wider, die seit dem 18. und 19. Jahrhundert zum Grundnahrungsmittel wurde. Geriebene rohe Kartoffeln werden mit Mehl, Ei, reichlich Knoblauch und dem in der tschechischen Küche typischen Majoran zu einem Teig vermengt und in heißem Fett zu dünnen, knusprigen Fladen ausgebacken. Charakteristisch ist die kräftige Würzung mit Knoblauch und Majoran. Bramboráky waren ein günstiges, sättigendes Essen, das aus einfachen Vorräten zubereitet werden konnte, und sind sowohl als Hauptgericht und Beilage als auch als Snack und Imbiss verbreitet, etwa auf Märkten und Festen. In manchen Regionen werden sie auch mit Sauerkraut oder als Hülle für andere Speisen gereicht. In der klassischen Form sind sie von Natur aus vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Tschechien", "Bramboráky", "Kartoffelpuffer", "vegetarisch", "Knoblauch", "Majoran", "böhmisch", "gebraten", "Snack", "Markt", "knusprig", "Beilage"]}, {"id": "ovocn-knedl-ky", "status": "published", "date": "", "cover": "", "name": "Ovocné knedlíky", "land": "Tschechien", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Gefüllte Teigklöße mit ganzen Früchten wie Erdbeeren oder Pflaumen, übergossen mit Quark, Butterbröseln und Zucker. Süße böhmische Mehlspeise.", "zutaten": ["500 g Quark (oder gekochte Kartoffeln)", "250 g Mehl", "1 Ei", "500 g ganze Früchte (Erdbeeren, Pflaumen, Aprikosen)", "80 g Butter", "80 g Semmelbrösel (oder gemahlener Mohn)", "Zucker, Prise Salz; Quark zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Quark (oder gekochte Kartoffeln)", "roh": "500 g Quark (oder gekochte Kartoffeln)"}, {"menge": 250.0, "einheit": "g", "item": "Mehl", "roh": "250 g Mehl"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 500.0, "einheit": "g", "item": "ganze Früchte (Erdbeeren, Pflaumen, Aprikosen)", "roh": "500 g ganze Früchte (Erdbeeren, Pflaumen, Aprikosen)"}, {"menge": 80.0, "einheit": "g", "item": "Butter", "roh": "80 g Butter"}, {"menge": 80.0, "einheit": "g", "item": "Semmelbrösel (oder gemahlener Mohn)", "roh": "80 g Semmelbrösel (oder gemahlener Mohn)"}, {"menge": null, "einheit": "", "item": "Zucker, Prise Salz; Quark zum Servieren", "roh": "Zucker, Prise Salz; Quark zum Servieren"}], "zubereitung": ["Quark mit Mehl, Ei und einer Prise Salz zu einem geschmeidigen Teig verkneten und kurz ruhen lassen.", "Den Teig portionieren, flach drücken und je eine Frucht einwickeln, zu Klößen formen.", "In siedendem Salzwasser garen, bis die Knödel aufschwimmen, dann noch einige Minuten ziehen lassen.", "Semmelbrösel in Butter goldbraun rösten.", "Die Knödel in den Butterbröseln wenden.", "Mit Zucker und Quark bestreut warm servieren."], "hinweise": "Die Früchte gut im Teig verschließen, damit kein Saft austritt.\n\nDie Knödel nur ziehen, nicht sprudelnd kochen.\n\nMit gerösteten Butterbröseln oder Mohn servieren.", "alternative": "", "geschichte": "Ovocné knedlíky — Obstknödel — sind eine traditionelle süße Mehlspeise der tschechischen Küche und ein beliebtes sommerliches Gericht. Sie gehören zur großen mitteleuropäischen Tradition der Klöße und süßen Hauptgerichte, die in Böhmen, Mähren und den Nachbarländern weit verbreitet ist. Ein Teig — klassisch aus Quark, Kartoffeln oder Grieß — wird um ganze Früchte wie Erdbeeren, Pflaumen, Aprikosen oder Heidelbeeren gewickelt, zu Klößen geformt und in Wasser gegart. Serviert werden sie warm, übergossen mit zerlassener Butter, gerösteten Bröseln oder gemahlenem Mohn und Zucker, oft mit einem Klecks Quark oder saurer Sahne. In Mitteleuropa galten solche süßen Mehlspeisen als vollwertiges Hauptgericht, nicht nur als Nachtisch, und nutzten das saisonale Obst aus Garten und Feld. Ovocné knedlíky erinnern an Kindheit und Großmutterküche und werden besonders in der Obstsaison gekocht. Als Teig-Obst-Speise sind sie selbstverständlich vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Tschechien", "Ovocné knedlíky", "Obstknödel", "Quark", "Früchte", "süß", "vegetarisch", "Mehlspeise", "böhmisch", "Sommerküche", "Großmutterküche", "Dessert"]}, {"id": "borsch", "status": "published", "date": "", "cover": "", "name": "Borsch", "land": "Ukraine", "kontinent": "Europa", "gang": "Suppe", "art": [], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine kräftig rote Rote-Bete-Suppe mit Kohl, Wurzelgemüse und Rind, vollendet mit saurer Sahne und Dill. Das Nationalgericht der Ukraine.", "zutaten": ["500 g Rindfleisch mit Knochen (für die Brühe)", "3 Rote Bete", "0.25 Weißkohl", "2 Möhren, 2 Kartoffeln, 1 Zwiebel", "2 EL Tomatenmark", "1 EL Essig oder Zitronensaft", "1 Bund Dill", "Öl, Salz, Pfeffer, Lorbeer; saure Sahne zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Rindfleisch mit Knochen (für die Brühe)", "roh": "500 g Rindfleisch mit Knochen (für die Brühe)"}, {"menge": 3.0, "einheit": "", "item": "Rote Bete", "roh": "3 Rote Bete"}, {"menge": 0.25, "einheit": "", "item": "Weißkohl", "roh": "0.25 Weißkohl"}, {"menge": 2.0, "einheit": "", "item": "Möhren, 2 Kartoffeln, 1 Zwiebel", "roh": "2 Möhren, 2 Kartoffeln, 1 Zwiebel"}, {"menge": 2.0, "einheit": "EL", "item": "Tomatenmark", "roh": "2 EL Tomatenmark"}, {"menge": 1.0, "einheit": "EL", "item": "Essig oder Zitronensaft", "roh": "1 EL Essig oder Zitronensaft"}, {"menge": 1.0, "einheit": "Bund", "item": "Dill", "roh": "1 Bund Dill"}, {"menge": null, "einheit": "", "item": "Öl, Salz, Pfeffer, Lorbeer; saure Sahne zum Servieren", "roh": "Öl, Salz, Pfeffer, Lorbeer; saure Sahne zum Servieren"}], "zubereitung": ["Rindfleisch mit Wasser aufsetzen, aufkochen, abschäumen und etwa 1,5 Stunden zu einer Brühe garen.", "Rote Bete und Möhren raspeln, mit Zwiebel, Tomatenmark und etwas Essig in Öl andünsten (Essig erhält die rote Farbe).", "Gewürfelte Kartoffeln und geschnittenen Kohl in die Brühe geben und garen.", "Die geschmorte Rote-Bete-Mischung zugeben und kurz mitkochen.", "Mit Salz, Pfeffer und Lorbeer abschmecken; das Fleisch zerkleinert zurückgeben.", "Mit saurer Sahne und reichlich frischem Dill servieren."], "hinweise": "Etwas Essig oder Zitrone bewahrt die kräftig rote Farbe der Bete.\n\nBorsch schmeckt am nächsten Tag noch besser.\n\nMit saurer Sahne und Dill gehört der typische Abschluss dazu.", "alternative": "Borsch wird je nach Familie mit Rind, Schwein oder ganz ohne Fleisch zubereitet. Wir verwenden Rindfleisch für eine kräftige Brühe; für eine rein pflanzliche, ebenso traditionelle Fassung lässt sich das Fleisch weglassen und durch eine kräftige Gemüsebrühe und Bohnen ersetzen.", "geschichte": "Borsch ist das bekannteste Gericht der Ukraine und so eng mit der nationalen Identität verbunden, dass die ukrainische Kochkunst des Borsch in die UNESCO-Liste des dringend erhaltungsbedürftigen immateriellen Kulturerbes aufgenommen wurde. Die kräftig rote Suppe erhält ihre Farbe von der Roten Bete und vereint zudem Kohl, Möhren, Zwiebeln, Kartoffeln und Tomaten in einer herzhaften Brühe. Borsch hat zahllose regionale und familiäre Varianten — fast jede Familie hat ihr eigenes Rezept. Die Suppe entstand in der bäuerlichen Küche und nutzte das lagerfähige Wurzelgemüse, das durch die langen Winter trug. Traditionell wird Borsch oft mit Fleisch zubereitet und mit einem Klecks saurer Sahne (smetana) sowie frischem Dill und Knoblauchbrötchen (pampuschky) serviert. In dieser Fassung verwenden wir Rindfleisch statt des sonst teils üblichen Schweinefleischs; eine rein pflanzliche Variante ist ebenso verbreitet. Borsch steht sinnbildlich für die ukrainische Esskultur und Gastfreundschaft.", "persoenlich": "", "servier": "", "tags": ["Ukraine", "Borsch", "Rote Bete", "Suppe", "Kohl", "Rind", "saure Sahne", "Dill", "Nationalgericht", "UNESCO-Kulturerbe", "Winterküche", "Hauptgericht"]}, {"id": "varenyky", "status": "published", "date": "", "cover": "", "name": "Varenyky", "land": "Ukraine", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Gefüllte Teigtaschen mit Kartoffel, Quark oder Kirschen, gekocht und mit gerösteten Zwiebeln oder saurer Sahne serviert. Ukrainische Klöße in vielen Varianten.", "zutaten": ["400 g Mehl", "1 Ei", "180 ml warmes Wasser", "500 g gekochte Kartoffeln", "200 g Quark (oder entkernte Kirschen für süße Variante)", "2 Zwiebeln", "50 g Butter", "Salz, Pfeffer; saure Sahne zum Servieren"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Mehl", "roh": "400 g Mehl"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 180.0, "einheit": "ml", "item": "warmes Wasser", "roh": "180 ml warmes Wasser"}, {"menge": 500.0, "einheit": "g", "item": "gekochte Kartoffeln", "roh": "500 g gekochte Kartoffeln"}, {"menge": 200.0, "einheit": "g", "item": "Quark (oder entkernte Kirschen für süße Variante)", "roh": "200 g Quark (oder entkernte Kirschen für süße Variante)"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 50.0, "einheit": "g", "item": "Butter", "roh": "50 g Butter"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer; saure Sahne zum Servieren", "roh": "Salz, Pfeffer; saure Sahne zum Servieren"}], "zubereitung": ["Mehl, Ei, Wasser und Salz zu einem geschmeidigen Teig kneten und ruhen lassen.", "Kartoffeln zerdrücken, mit Quark und einer angebratenen Zwiebel zu einer Füllung verrühren, würzen.", "Den Teig dünn ausrollen und Kreise ausstechen.", "Je etwas Füllung daraufsetzen, zu Halbmonden falten und die Ränder fest verschließen.", "In siedendem Salzwasser kochen, bis die Varenyky aufschwimmen, dann noch kurz ziehen lassen.", "Mit in Butter gerösteten Zwiebeln und saurer Sahne servieren."], "hinweise": "Die Ränder gut verschließen, damit keine Füllung austritt.\n\nFür die süße Variante Kirschen einfüllen und mit Zucker und Sahne servieren.\n\nGekochte Varenyky in Butter schwenken für mehr Aroma.", "alternative": "", "geschichte": "Varenyky gehören zu den bekanntesten und beliebtesten Gerichten der Ukraine und sind tief in der nationalen Esskultur verankert. Es handelt sich um halbmondförmige, gefüllte Teigtaschen, die mit den unterschiedlichsten Füllungen zubereitet werden — herzhaft mit Kartoffeln, Quark, Sauerkraut oder Pilzen, süß mit Kirschen, Beeren oder Quark. Sie sind mit den Pierogi der polnischen und den Teigtaschen der weiteren osteuropäischen Küche verwandt und teilen eine lange gemeinsame Tradition. Varenyky gehören sowohl zur Alltags- als auch zur Festtagsküche und spielen bei Feiern, Familienzusammenkünften und Bräuchen eine Rolle; das gemeinsame Füllen und Formen ist oft ein geselliges Ereignis. Der dünn ausgerollte Teig wird mit der Füllung versehen, sorgfältig verschlossen und in Salzwasser gekocht; anschließend werden die Varenyky oft mit gerösteten Zwiebeln, Butter oder saurer Sahne (smetana) serviert. In den vegetarischen Füllungen mit Kartoffel, Quark oder Kirsche sind sie selbstverständlich ohne Schweinefleisch und gelten als ukrainisches Wohlfühlessen.", "persoenlich": "", "servier": "", "tags": ["Ukraine", "Varenyky", "Teigtaschen", "Kartoffel", "Quark", "Kirschen", "vegetarisch", "Röstzwiebeln", "saure Sahne", "Festtag", "Wohlfühlessen", "Hauptgericht"]}, {"id": "deruny", "status": "published", "date": "", "cover": "", "name": "Deruny", "land": "Ukraine", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 20, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Knusprige Kartoffelpuffer aus geriebenen Kartoffeln und Zwiebeln, serviert mit saurer Sahne. Beliebter ukrainischer Kartoffelklassiker.", "zutaten": ["800 g mehligkochende Kartoffeln", "1 Zwiebel", "1 Ei", "3 EL Mehl", "Öl zum Braten, Salz, Pfeffer", "saure Sahne zum Servieren"], "zutatenS": [{"menge": 800.0, "einheit": "g", "item": "mehligkochende Kartoffeln", "roh": "800 g mehligkochende Kartoffeln"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 3.0, "einheit": "EL", "item": "Mehl", "roh": "3 EL Mehl"}, {"menge": null, "einheit": "", "item": "Öl zum Braten, Salz, Pfeffer", "roh": "Öl zum Braten, Salz, Pfeffer"}, {"menge": null, "einheit": "", "item": "saure Sahne zum Servieren", "roh": "saure Sahne zum Servieren"}], "zubereitung": ["Kartoffeln und Zwiebel fein reiben und überschüssige Flüssigkeit ausdrücken.", "Mit Ei, Mehl, Salz und Pfeffer zu einem Teig vermengen.", "Reichlich Öl in einer Pfanne erhitzen.", "Dünne Fladen formen und ins heiße Öl geben.", "Beidseitig goldbraun und knusprig braten.", "Auf Küchenpapier abtropfen lassen und heiß mit saurer Sahne servieren."], "hinweise": "Die geriebenen Kartoffeln gut ausdrücken für knusprige Deruny.\n\nDie Zwiebel verhindert, dass die Masse dunkel wird.\n\nMit saurer Sahne servieren — klassisch und unverzichtbar.", "alternative": "", "geschichte": "Deruny sind ukrainische Kartoffelpuffer und gehören zu den beliebtesten Alltagsgerichten des Landes. Sie spiegeln die zentrale Rolle der Kartoffel in der ukrainischen und osteuropäischen Küche wider, die seit dem 18. und 19. Jahrhundert zum Grundnahrungsmittel wurde. Geriebene rohe Kartoffeln werden mit Zwiebel, Ei und etwas Mehl zu einem Teig vermengt und in heißem Öl zu knusprigen Fladen ausgebacken. Verwandte Kartoffelpuffer finden sich in vielen Ländern der Region; in der Ukraine sind Deruny besonders mit den nördlichen Regionen wie Polissja verbunden. Sie waren ein günstiges, sättigendes Essen, das aus einfachen Vorräten zubereitet werden konnte, und werden bis heute als Hauptgericht, Beilage oder Snack gegessen. Klassisch werden sie mit saurer Sahne (smetana) serviert, manchmal auch mit Pilzsauce. In der einfachen Form aus Kartoffeln, Zwiebeln und Ei sind sie von Natur aus vegetarisch und ohne Schweinefleisch und gelten als ukrainisches Wohlfühlessen.", "persoenlich": "", "servier": "", "tags": ["Ukraine", "Deruny", "Kartoffelpuffer", "vegetarisch", "Zwiebel", "saure Sahne", "gebraten", "Hausmannskost", "Snack", "Polissja", "Wohlfühlessen", "Hauptgericht"]}, {"id": "guly-s", "status": "published", "date": "", "cover": "", "name": "Gulyás", "land": "Ungarn", "kontinent": "Europa", "gang": "Suppe", "art": ["Fleisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine kräftige Suppe aus Rindfleisch, Zwiebeln, Kartoffeln und reichlich Paprika. Das ursprüngliche ungarische Gulasch der Hirten.", "zutaten": ["700 g Rindfleisch (Wade oder Schulter), gewürfelt", "3 Zwiebeln", "3 EL edelsüßes Paprikapulver", "3 Kartoffeln", "2 Möhren, 1 Paprika, 2 Tomaten", "1 TL Kümmel, 2 Zehen Knoblauch", "1.5 l Wasser oder Rinderbrühe", "Öl, Salz, Pfeffer"], "zutatenS": [{"menge": 700.0, "einheit": "g", "item": "Rindfleisch (Wade oder Schulter), gewürfelt", "roh": "700 g Rindfleisch (Wade oder Schulter), gewürfelt"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln", "roh": "3 Zwiebeln"}, {"menge": 3.0, "einheit": "EL", "item": "edelsüßes Paprikapulver", "roh": "3 EL edelsüßes Paprikapulver"}, {"menge": 3.0, "einheit": "", "item": "Kartoffeln", "roh": "3 Kartoffeln"}, {"menge": 2.0, "einheit": "", "item": "Möhren, 1 Paprika, 2 Tomaten", "roh": "2 Möhren, 1 Paprika, 2 Tomaten"}, {"menge": 1.0, "einheit": "TL", "item": "Kümmel, 2 Zehen Knoblauch", "roh": "1 TL Kümmel, 2 Zehen Knoblauch"}, {"menge": 1.5, "einheit": "l", "item": "Wasser oder Rinderbrühe", "roh": "1.5 l Wasser oder Rinderbrühe"}, {"menge": null, "einheit": "", "item": "Öl, Salz, Pfeffer", "roh": "Öl, Salz, Pfeffer"}], "zubereitung": ["Zwiebeln in Öl goldgelb dünsten, vom Herd ziehen und das Paprikapulver einrühren.", "Rindfleischwürfel zugeben und mit Kümmel und Knoblauch anrösten.", "Mit Wasser oder Brühe auffüllen und bei kleiner Hitze etwa 1,5 Stunden sanft garen.", "Gewürfelte Kartoffeln, Möhren, Paprika und Tomaten zugeben.", "Weitergaren, bis das Fleisch zart und das Gemüse weich ist.", "Mit Salz und Pfeffer abschmecken; nach Wunsch kleine Teigtropfen (csipetke) mitkochen."], "hinweise": "Das Paprikapulver erst nach dem Herd einrühren, sonst wird es bitter.\n\nLange, sanfte Garzeit macht das Rindfleisch zart.\n\nMit frischem Brot servieren.", "alternative": "", "geschichte": "Gulyás ist das bekannteste Gericht Ungarns und untrennbar mit der nationalen Identität verbunden. Anders als das im Ausland verbreitete dicke „Gulasch“ ist der ungarische Gulyás traditionell eine Suppe (gulyásleves). Sein Name leitet sich von den Rinderhirten (gulyás) der ungarischen Tiefebene ab, die das Gericht über offenem Feuer im Kessel (bogrács) kochten. Ursprünglich ein einfaches Hirtenessen aus Rindfleisch, Zwiebeln und Wasser, wurde es durch die Paprika geprägt, die ab dem 18. und 19. Jahrhundert zum charakteristischen Gewürz der ungarischen Küche wurde und dem Gulyás seine rote Farbe und Tiefe gibt. Hinzu kommen Kartoffeln, Möhren und oft kleine Teigtropfen (csipetke). Der ungarische Gulyás ist von Natur aus mit Rindfleisch zubereitet und kommt ohne Schweinefleisch aus. Er steht sinnbildlich für die Pusztaküche und die Bedeutung der Paprika und wird bis heute als wärmendes, geselliges Gericht geschätzt.", "persoenlich": "", "servier": "", "tags": ["Ungarn", "Gulyás", "Gulaschsuppe", "Rind", "Paprika", "Suppe", "Puszta", "Hirtenküche", "Nationalgericht", "Kessel", "Winterküche", "Hauptgericht"]}, {"id": "hal-szl", "status": "published", "date": "", "cover": "", "name": "Halászlé", "land": "Ungarn", "kontinent": "Europa", "gang": "Suppe", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine feurig rote Fischsuppe aus Süßwasserfisch und viel Paprika. Festtagssuppe der ungarischen Flusslandschaften.", "zutaten": ["1.5 kg Süßwasserfisch (Karpfen, Wels), küchenfertig", "3 Zwiebeln", "3 EL edelsüßes Paprikapulver", "1 TL scharfes Paprikapulver", "2 Tomaten, 1 Paprika", "1.5 l Wasser", "Salz"], "zutatenS": [{"menge": 1.5, "einheit": "kg", "item": "Süßwasserfisch (Karpfen, Wels), küchenfertig", "roh": "1.5 kg Süßwasserfisch (Karpfen, Wels), küchenfertig"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln", "roh": "3 Zwiebeln"}, {"menge": 3.0, "einheit": "EL", "item": "edelsüßes Paprikapulver", "roh": "3 EL edelsüßes Paprikapulver"}, {"menge": 1.0, "einheit": "TL", "item": "scharfes Paprikapulver", "roh": "1 TL scharfes Paprikapulver"}, {"menge": 2.0, "einheit": "", "item": "Tomaten, 1 Paprika", "roh": "2 Tomaten, 1 Paprika"}, {"menge": 1.5, "einheit": "l", "item": "Wasser", "roh": "1.5 l Wasser"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Fischköpfe, Gräten und Abschnitte mit Zwiebeln und Wasser zu einem kräftigen Fischsud kochen.", "Den Sud durch ein Sieb passieren und zurück in den Topf geben.", "Paprikapulver, gewürfelte Tomaten und Paprika einrühren.", "Die filetierten Fischstücke in den Sud legen.", "Bei kleiner Hitze sanft garen, dabei nicht umrühren, nur den Topf schwenken.", "Mit Salz abschmecken und heiß mit Brot servieren."], "hinweise": "Der Sud aus Kopf und Gräten ist die geschmackliche Basis.\n\nNicht umrühren, damit der Fisch ganz bleibt.\n\nReichlich gutes Paprikapulver gibt Farbe und Tiefe.", "alternative": "", "geschichte": "Halászlé — die ungarische Fischersuppe — ist eine kräftige, scharf-paprizierte Suppe aus Süßwasserfisch und gehört zu den traditionsreichsten Gerichten Ungarns. Sie entstand bei den Fischern entlang der großen Flüsse, vor allem der Donau und der Theiß, sowie am Plattensee, die ihren Fang — häufig Karpfen, aber auch Wels und andere Süßwasserfische — über offenem Feuer im Kessel zu einer würzigen Suppe verkochten. Charakteristisch ist die intensive rote Farbe und Schärfe durch reichlich ungarisches Paprikapulver. Regionale Schulen unterscheiden sich: Die Variante aus Szeged wird passiert und sämig, die aus Baja mit Nudeln serviert. Halászlé hat einen festen Platz in der Festtagsküche und gehört in vielen Familien traditionell zum Heiligabend. Die Zubereitung gilt als kleine Kunst, und der Fischsud aus Kopf und Gräten bildet die geschmackliche Grundlage. Als reine Fischsuppe ist Halászlé selbstverständlich ohne Schweinefleisch und steht für die Verbindung der ungarischen Küche mit ihren Gewässern.", "persoenlich": "", "servier": "", "tags": ["Ungarn", "Halászlé", "Fischsuppe", "Karpfen", "Paprika", "scharf", "Donau", "Theiß", "Festtag", "Heiligabend", "Süßwasserfisch", "Suppe"]}, {"id": "dobos-torta", "status": "published", "date": "", "cover": "", "name": "Dobos torta", "land": "Ungarn", "kontinent": "Europa", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine vielschichtige Biskuittorte mit Schokoladenbuttercreme und einer knackigen Karamellschicht obenauf. Klassiker der ungarischen Konditorkunst.", "zutaten": ["6 Eier", "150 g Zucker (Biskuit)", "120 g Mehl", "250 g Butter (Creme)", "150 g Zartbitterschokolade (Creme)", "3 Eier und 100 g Zucker (Creme)", "150 g Zucker (Karamell)"], "zutatenS": [{"menge": 6.0, "einheit": "", "item": "Eier", "roh": "6 Eier"}, {"menge": 150.0, "einheit": "g", "item": "Zucker (Biskuit)", "roh": "150 g Zucker (Biskuit)"}, {"menge": 120.0, "einheit": "g", "item": "Mehl", "roh": "120 g Mehl"}, {"menge": 250.0, "einheit": "g", "item": "Butter (Creme)", "roh": "250 g Butter (Creme)"}, {"menge": 150.0, "einheit": "g", "item": "Zartbitterschokolade (Creme)", "roh": "150 g Zartbitterschokolade (Creme)"}, {"menge": 3.0, "einheit": "", "item": "Eier und 100 g Zucker (Creme)", "roh": "3 Eier und 100 g Zucker (Creme)"}, {"menge": 150.0, "einheit": "g", "item": "Zucker (Karamell)", "roh": "150 g Zucker (Karamell)"}], "zubereitung": ["Aus Eiern, Zucker und Mehl mehrere dünne, runde Biskuitböden backen (meist sechs).", "Für die Creme Eier mit Zucker über dem Wasserbad cremig schlagen, abkühlen lassen.", "Weiche Butter und geschmolzene Schokolade einrühren, bis eine glatte Buttercreme entsteht.", "Die Böden mit der Schokoladencreme schichten und auch außen einstreichen.", "Für die Karamelldecke Zucker hellbraun schmelzen und auf einen Biskuitboden gießen, sofort in Tortenstücke vorschneiden.", "Die karamellisierte Platte auf die Torte setzen; gut durchkühlen lassen."], "hinweise": "Die Biskuitböden möglichst gleich groß und dünn backen.\n\nDas Karamell zügig verarbeiten, bevor es erstarrt.\n\nDie Torte vor dem Servieren durchkühlen lassen.", "alternative": "", "geschichte": "Die Dobos torta (Dobos-Torte) ist eine der berühmtesten Torten Ungarns und ein Meilenstein der mitteleuropäischen Konditorkunst. Sie wurde 1885 vom Budapester Konditor József C. Dobos kreiert und auf der Budapester Nationalausstellung vorgestellt. Charakteristisch sind die zahlreichen dünnen Biskuitböden, die mit Schokoladenbuttercreme geschichtet werden, sowie die markante oberste Schicht aus hartem, glänzendem Karamell, die in Tortenstücke geschnitten und oft dekorativ aufgesetzt wird. Zu ihrer Zeit war die Torte eine Innovation: Die Karamelldecke und die haltbare Buttercreme machten sie ungewöhnlich lange frisch, was sie auch für den Versand und die damalige Lagerung geeignet machte. Dobos hielt sein Rezept lange geheim und gab es erst Jahre später an die Budapester Konditorinnung weiter. Die Dobos torta gilt bis heute als Symbol der ungarischen Kaffeehaus- und Backkultur. Als reine Biskuit-Buttercreme-Karamell-Torte ist sie selbstverständlich vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Ungarn", "Budapest", "Dobos torta", "Biskuittorte", "Schokolade", "Buttercreme", "Karamell", "süß", "vegetarisch", "Kaffeehaus", "Konditorkunst", "Dessert"]}, {"id": "carciofi-alla-romana", "status": "published", "date": "", "cover": "", "name": "Carciofi alla romana", "land": "Vatikanstadt", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ganze Artischocken, geschmort in Olivenöl mit Minze, Petersilie und Knoblauch. Römische Spezialität aus dem Umfeld des Vatikans.", "zutaten": ["6 große Artischocken", "1 Bund Minze (möglichst mentuccia)", "1 Bund Petersilie", "4 Zehen Knoblauch", "120 ml Olivenöl", "1 Zitrone", "Salz, Pfeffer, Wasser"], "zutatenS": [{"menge": 6.0, "einheit": "", "item": "große Artischocken", "roh": "6 große Artischocken"}, {"menge": 1.0, "einheit": "Bund", "item": "Minze (möglichst mentuccia)", "roh": "1 Bund Minze (möglichst mentuccia)"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "4 Zehen Knoblauch"}, {"menge": 120.0, "einheit": "ml", "item": "Olivenöl", "roh": "120 ml Olivenöl"}, {"menge": 1.0, "einheit": "", "item": "Zitrone", "roh": "1 Zitrone"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer, Wasser", "roh": "Salz, Pfeffer, Wasser"}], "zubereitung": ["Artischocken putzen, die äußeren harten Blätter entfernen und in Zitronenwasser legen.", "Minze, Petersilie und Knoblauch fein hacken, mit Salz, Pfeffer und etwas Öl mischen.", "Die Kräutermischung zwischen die Blätter und in die Mitte der Artischocken drücken.", "Die Artischocken kopfüber dicht in einen Topf stellen.", "Mit Olivenöl und etwas Wasser angießen, sodass sie zur Hälfte bedeckt sind.", "Zugedeckt 30–40 Minuten sanft schmoren, bis sie butterzart sind; lauwarm servieren."], "hinweise": "Die Artischocken in Zitronenwasser legen, damit sie nicht braun werden.\n\nKopfüber schmoren, damit die Füllung im Inneren bleibt.\n\nLauwarm mit etwas vom Schmoröl servieren.", "alternative": "", "geschichte": "Die Vatikanstadt besitzt keine eigenständige Nationalküche; gegessen wird die römisch-italienische Küche der umgebenden Stadt Rom. Carciofi alla romana — Artischocken nach römischer Art — gehören zu den klassischen Gerichten dieser Küche und sind besonders im Frühjahr verbreitet, wenn die römische Artischocke (carciofo romanesco) Saison hat. Das Gericht hat tiefe Wurzeln in der römischen Tradition, in der die Artischocke seit Jahrhunderten eine herausragende Rolle spielt — auch in der jüdisch-römischen Küche des historischen Ghettos. Für die römische Variante werden ganze, geputzte Artischocken mit einer Füllung aus Minze (mentuccia), Petersilie und Knoblauch versehen und kopfüber in Olivenöl und etwas Wasser sanft geschmort, bis sie butterzart sind. Anders als die frittierten „carciofi alla giudia“ werden sie also gedünstet. Das Gericht ist ein fester Bestandteil der römischen Tafel und der Saisonküche. Als reines Gemüsegericht ist es von Natur aus vegan und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Vatikanstadt", "Rom", "Carciofi alla romana", "Artischocken", "vegan", "vegetarisch", "Minze", "Olivenöl", "römisch", "Saisonküche", "mediterran", "Beilage"]}, {"id": "cacio-e-pepe", "status": "published", "date": "", "cover": "", "name": "Cacio e pepe", "land": "Vatikanstadt", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Pasta mit einer cremigen Sauce aus nur Pecorino-Käse und schwarzem Pfeffer. Die Essenz der römischen Küche.", "zutaten": ["400 g Pasta (Tonnarelli oder Spaghetti)", "200 g Pecorino Romano, fein gerieben", "2 TL schwarzer Pfeffer, frisch gemahlen", "Salz (sparsam, der Käse ist salzig)"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Pasta (Tonnarelli oder Spaghetti)", "roh": "400 g Pasta (Tonnarelli oder Spaghetti)"}, {"menge": 200.0, "einheit": "g", "item": "Pecorino Romano, fein gerieben", "roh": "200 g Pecorino Romano, fein gerieben"}, {"menge": 2.0, "einheit": "TL", "item": "schwarzer Pfeffer, frisch gemahlen", "roh": "2 TL schwarzer Pfeffer, frisch gemahlen"}, {"menge": null, "einheit": "", "item": "Salz (sparsam, der Käse ist salzig)", "roh": "Salz (sparsam, der Käse ist salzig)"}], "zubereitung": ["Pasta in wenig Salzwasser al dente kochen; das stärkehaltige Nudelwasser aufbewahren.", "Pfeffer in einer Pfanne kurz trocken anrösten, bis er duftet.", "Den geriebenen Pecorino mit etwas lauwarmem (nicht kochendem) Nudelwasser zu einer glatten Creme rühren.", "Die abgetropfte Pasta mit dem gerösteten Pfeffer und etwas Nudelwasser schwenken.", "Die Käsecreme zugeben und unter Schwenken zu einer cremigen Sauce emulgieren.", "Mit zusätzlichem Pecorino und Pfeffer bestreut sofort servieren."], "hinweise": "Das Nudelwasser darf nicht zu heiß sein, sonst verklumpt der Käse.\n\nStärkehaltiges Nudelwasser ist der Schlüssel zur cremigen Emulsion.\n\nZügig arbeiten und sofort servieren.", "alternative": "", "geschichte": "Cacio e pepe — „Käse und Pfeffer“ — ist eines der bekanntesten Gerichte der römischen Küche, die auch in der Vatikanstadt die alltägliche Küche darstellt, da der Vatikan keine eigenständige Nationalküche besitzt. Das Gericht ist ein Paradebeispiel der „cucina povera“: Aus nur drei Zutaten — Pasta, Pecorino Romano und schwarzem Pfeffer — entsteht ein erstaunlich reichhaltiges Gericht. Seine Wurzeln liegen in der Hirten- und Arbeiterküche der Region Latium; getrockneter Pecorino, Pfeffer und Pasta waren haltbare, transportable Grundzutaten, die auch unterwegs eine sättigende Mahlzeit ergaben. Die Kunst liegt in der Emulsion: Aus dem geriebenen Pecorino und stärkehaltigem Nudelwasser wird eine cremige Sauce gerührt, die die Pasta umhüllt, ohne zu verklumpen. Cacio e pepe gehört zu den vier klassischen römischen Pastagerichten und ist heute weit über Rom hinaus beliebt. Als reines Käse-Pasta-Gericht ist es von Natur aus vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Vatikanstadt", "Rom", "Cacio e pepe", "Pasta", "Pecorino", "Pfeffer", "vegetarisch", "cucina povera", "römisch", "Latium", "Klassiker", "Hauptgericht"]}, {"id": "maritozzi", "status": "published", "date": "", "cover": "", "name": "Maritozzi", "land": "Vatikanstadt", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Weiche, leicht süße Hefebrötchen, aufgeschnitten und üppig mit Schlagsahne gefüllt. Römisches Frühstücksgebäck.", "zutaten": ["400 g Mehl", "150 ml lauwarme Milch", "20 g frische Hefe", "70 g Zucker", "1 Ei", "50 g Butter, 1 EL Honig", "1 Bio-Orange (Schale)", "300 ml Schlagsahne; Puderzucker"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Mehl", "roh": "400 g Mehl"}, {"menge": 150.0, "einheit": "ml", "item": "lauwarme Milch", "roh": "150 ml lauwarme Milch"}, {"menge": 20.0, "einheit": "g", "item": "frische Hefe", "roh": "20 g frische Hefe"}, {"menge": 70.0, "einheit": "g", "item": "Zucker", "roh": "70 g Zucker"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": 50.0, "einheit": "g", "item": "Butter, 1 EL Honig", "roh": "50 g Butter, 1 EL Honig"}, {"menge": 1.0, "einheit": "", "item": "Bio-Orange (Schale)", "roh": "1 Bio-Orange (Schale)"}, {"menge": 300.0, "einheit": "ml", "item": "Schlagsahne; Puderzucker", "roh": "300 ml Schlagsahne; Puderzucker"}], "zubereitung": ["Hefe in lauwarmer Milch mit etwas Zucker auflösen.", "Mehl, Zucker, Ei, Honig, Orangenschale und die Hefemilch zu einem Teig kneten, weiche Butter einarbeiten.", "Zugedeckt etwa 1,5 Stunden gehen lassen.", "Längliche Brötchen formen, nochmals gehen lassen und bei 180 °C goldbraun backen; auskühlen lassen.", "Die Brötchen längs einschneiden.", "Steif geschlagene Sahne hineinfüllen, glatt streichen und mit Puderzucker bestäuben."], "hinweise": "Den Teig gut gehen lassen, damit die Brötchen luftig werden.\n\nErst nach dem Auskühlen mit Sahne füllen.\n\nDie Sahnefüllung großzügig und glatt abstreichen.", "alternative": "", "geschichte": "Maritozzi sind ein traditionelles süßes Hefegebäck der römischen Küche, die auch in der Vatikanstadt die alltägliche Esskultur prägt, da der Vatikan keine eigene Nationalküche hat. Die weichen, ovalen Brötchen aus einem leicht süßen, mit etwas Orangenschale und Honig aromatisierten Hefeteig werden aufgeschnitten und großzügig mit Schlagsahne gefüllt. Ihr Ursprung reicht weit zurück; eine verbreitete Erzählung verbindet den Namen mit dem römischen Dialektwort „maritozzo“ für den künftigen Ehemann („marito“), der seiner Verlobten das Gebäck — manchmal mit einem versteckten Ring oder Schmuckstück — schenkte, weshalb die Maritozzi besonders mit der Fastenzeit und dem Frühjahr in Verbindung gebracht werden. Heute sind sie ein beliebtes Frühstücksgebäck, das in römischen Bars zum Cappuccino gegessen wird, und haben über Rom hinaus an Popularität gewonnen. Als süßes Hefegebäck mit Sahnefüllung sind sie selbstverständlich vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Vatikanstadt", "Rom", "Maritozzi", "Hefegebäck", "Sahne", "süß", "Frühstück", "vegetarisch", "römisch", "Cappuccino", "Fastenzeit", "Dessert"]}, {"id": "fish-and-chips", "status": "published", "date": "", "cover": "", "name": "Fish and Chips", "land": "Vereinigtes Königreich", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "In knusprigem Bierteig frittierter Weißfisch mit dicken Pommes, serviert mit Essig und Erbsenpüree. Das britische Nationalgericht zum Mitnehmen.", "zutaten": ["4 Filets von Kabeljau oder Schellfisch", "200 g Mehl", "250 ml kaltes Bier (oder Sprudelwasser)", "1 TL Backpulver", "1 kg mehligkochende Kartoffeln", "Öl zum Frittieren, Salz, Malzessig", "300 g grüne Erbsen (mushy peas)"], "zutatenS": [{"menge": 4.0, "einheit": "", "item": "Filets von Kabeljau oder Schellfisch", "roh": "4 Filets von Kabeljau oder Schellfisch"}, {"menge": 200.0, "einheit": "g", "item": "Mehl", "roh": "200 g Mehl"}, {"menge": 250.0, "einheit": "ml", "item": "kaltes Bier (oder Sprudelwasser)", "roh": "250 ml kaltes Bier (oder Sprudelwasser)"}, {"menge": 1.0, "einheit": "TL", "item": "Backpulver", "roh": "1 TL Backpulver"}, {"menge": 1.0, "einheit": "kg", "item": "mehligkochende Kartoffeln", "roh": "1 kg mehligkochende Kartoffeln"}, {"menge": null, "einheit": "", "item": "Öl zum Frittieren, Salz, Malzessig", "roh": "Öl zum Frittieren, Salz, Malzessig"}, {"menge": 300.0, "einheit": "g", "item": "grüne Erbsen (mushy peas)", "roh": "300 g grüne Erbsen (mushy peas)"}], "zubereitung": ["Kartoffeln in dicke Stäbchen schneiden, wässern, trocknen und zweifach frittieren (erst sanft, dann heiß und knusprig).", "Mehl, Backpulver und Salz mit kaltem Bier zu einem dickflüssigen Teig verrühren.", "Die Fischfilets in Mehl wenden, durch den Teig ziehen.", "In heißem Öl (ca. 180 °C) goldbraun und knusprig ausbacken.", "Erbsen weich kochen und grob zu mushy peas zerdrücken.", "Fisch und Chips mit Salz und Malzessig sowie den Erbsen servieren."], "hinweise": "Kaltes Bier und kalter Teig ergeben eine besonders knusprige Hülle.\n\nDie Chips zweifach frittieren — erst weich garen, dann knusprig bräunen.\n\nMit Malzessig beträufeln — typisch britisch.", "alternative": "", "geschichte": "Fish and Chips gelten als das britische Nationalgericht und sind seit dem 19. Jahrhundert fest in der Esskultur des Vereinigten Königreichs verankert. Die Kombination aus frittiertem Fisch und frittierten Kartoffelstäbchen entstand in der Zeit der Industrialisierung, als sie zum erschwinglichen, sättigenden Essen der Arbeiterklasse wurde. Der frittierte Fisch geht vermutlich auf jüdische Einwanderer zurück, die fritierten Fisch nach britischer Überlieferung mitbrachten, während die „chips“ — dicke, frittierte Kartoffelstäbchen — sich parallel verbreiteten; im Lauf des 19. Jahrhunderts wuchsen beide zur klassischen Kombination zusammen. Die spezialisierten Imbisse, die „chippies“, wurden zu einer britischen Institution. Verwendet wird meist Kabeljau oder Schellfisch, in einem knusprigen Bier- oder Wasserteig ausgebacken, traditionell mit Malzessig beträufelt und mit Erbsenpüree (mushy peas) serviert. Klassisch isst man Fish and Chips aus Papier. Als Fisch- und Kartoffelgericht ist es selbstverständlich ohne Schweinefleisch und steht sinnbildlich für britisches Alltags-Comfortfood.", "persoenlich": "", "servier": "", "tags": ["Vereinigtes Königreich", "Fish and Chips", "Kabeljau", "Fisch", "Bierteig", "Pommes", "Nationalgericht", "mushy peas", "Malzessig", "Comfortfood", "Imbiss", "Hauptgericht"]}, {"id": "shepherd-s-pie", "status": "published", "date": "", "cover": "", "name": "Shepherd's Pie", "land": "Vereinigtes Königreich", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Geschmortes Lammhack mit Gemüse unter einer goldbraunen Haube aus Kartoffelpüree, im Ofen überbacken. Britischer Auflaufklassiker.", "zutaten": ["600 g Lammhack", "2 Möhren", "1 Zwiebel", "100 g Erbsen", "2 EL Tomatenmark, 1 EL Worcestersauce", "300 ml Lamm- oder Gemüsebrühe", "1 kg mehligkochende Kartoffeln", "60 g Butter, etwas Milch", "Öl, Salz, Pfeffer, Thymian"], "zutatenS": [{"menge": 600.0, "einheit": "g", "item": "Lammhack", "roh": "600 g Lammhack"}, {"menge": 2.0, "einheit": "", "item": "Möhren", "roh": "2 Möhren"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 100.0, "einheit": "g", "item": "Erbsen", "roh": "100 g Erbsen"}, {"menge": 2.0, "einheit": "EL", "item": "Tomatenmark, 1 EL Worcestersauce", "roh": "2 EL Tomatenmark, 1 EL Worcestersauce"}, {"menge": 300.0, "einheit": "ml", "item": "Lamm- oder Gemüsebrühe", "roh": "300 ml Lamm- oder Gemüsebrühe"}, {"menge": 1.0, "einheit": "kg", "item": "mehligkochende Kartoffeln", "roh": "1 kg mehligkochende Kartoffeln"}, {"menge": 60.0, "einheit": "g", "item": "Butter, etwas Milch", "roh": "60 g Butter, etwas Milch"}, {"menge": null, "einheit": "", "item": "Öl, Salz, Pfeffer, Thymian", "roh": "Öl, Salz, Pfeffer, Thymian"}], "zubereitung": ["Zwiebel und Möhren würfeln und andünsten, das Lammhack zugeben und kräftig anbraten.", "Tomatenmark und Worcestersauce einrühren, mit Brühe auffüllen und mit Thymian würzen.", "Erbsen zugeben und die Füllung einköcheln, bis sie sämig ist; in eine Auflaufform geben.", "Kartoffeln kochen und mit Butter und Milch zu einem cremigen Püree stampfen.", "Das Püree auf die Füllung streichen und mit einer Gabel die Oberfläche aufrauen.", "Bei 200 °C 25–30 Minuten goldbraun überbacken."], "hinweise": "Die aufgeraute Püreeoberfläche wird besonders knusprig.\n\nDie Füllung gut einkochen, damit der Auflauf nicht wässrig wird.\n\nMit Lamm ist es Shepherd's, mit Rind Cottage Pie.", "alternative": "", "geschichte": "Shepherd's Pie ist ein klassischer britischer Auflauf und ein Inbegriff der heimeligen britischen Hausmannskost. Charakteristisch ist die Schichtung aus einer herzhaften Hackfleischfüllung mit Gemüse und einer Haube aus Kartoffelpüree, die im Ofen goldbraun überbacken wird. Der Name „Shepherd“ (Schäfer) verweist darauf, dass das Gericht traditionell mit Lammfleisch zubereitet wird — wird Rindfleisch verwendet, spricht man von „Cottage Pie“. Die Speise entstand im 18. und 19. Jahrhundert als sparsame Art, Reste von gebratenem Fleisch mit Kartoffeln zu einer neuen Mahlzeit zu verwerten, nachdem die Kartoffel in Großbritannien und Irland zum Grundnahrungsmittel geworden war. Sie war ein günstiges, sättigendes Essen für ländliche und arbeitende Haushalte. Heute gilt Shepherd's Pie als beliebtes Wohlfühlgericht, das warm und mit Gemüsebeilage serviert wird. Mit Lammhack zubereitet ist es von Natur aus ohne Schweinefleisch und steht sinnbildlich für die bodenständige britische Küche.", "persoenlich": "", "servier": "", "tags": ["Vereinigtes Königreich", "Shepherd's Pie", "Lamm", "Kartoffelpüree", "Auflauf", "Hausmannskost", "Comfortfood", "Ofengericht", "Resteküche", "Winterküche", "britisch", "Hauptgericht"]}, {"id": "scones", "status": "published", "date": "", "cover": "", "name": "Scones", "land": "Vereinigtes Königreich", "kontinent": "Europa", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Lockere, leicht süße Backwerke, aufgeschnitten und mit Clotted Cream und Marmelade serviert. Herzstück der britischen Teestunde.", "zutaten": ["350 g Mehl", "1 EL Backpulver", "80 g kalte Butter", "40 g Zucker", "150 ml Milch", "1 Ei (zum Bestreichen)", "Clotted Cream und Marmelade zum Servieren"], "zutatenS": [{"menge": 350.0, "einheit": "g", "item": "Mehl", "roh": "350 g Mehl"}, {"menge": 1.0, "einheit": "EL", "item": "Backpulver", "roh": "1 EL Backpulver"}, {"menge": 80.0, "einheit": "g", "item": "kalte Butter", "roh": "80 g kalte Butter"}, {"menge": 40.0, "einheit": "g", "item": "Zucker", "roh": "40 g Zucker"}, {"menge": 150.0, "einheit": "ml", "item": "Milch", "roh": "150 ml Milch"}, {"menge": 1.0, "einheit": "", "item": "Ei (zum Bestreichen)", "roh": "1 Ei (zum Bestreichen)"}, {"menge": null, "einheit": "", "item": "Clotted Cream und Marmelade zum Servieren", "roh": "Clotted Cream und Marmelade zum Servieren"}], "zubereitung": ["Mehl, Backpulver und Zucker mischen, die kalte Butter einreiben, bis eine krümelige Masse entsteht.", "Die Milch zügig einarbeiten, bis ein weicher Teig entsteht; nicht lange kneten.", "Den Teig fingerdick ausrollen und runde Scones ausstechen.", "Auf ein Blech setzen und mit verquirltem Ei bestreichen.", "Bei 200 °C 12–15 Minuten goldbraun und hoch aufgegangen backen.", "Lauwarm aufschneiden und mit Clotted Cream und Marmelade servieren."], "hinweise": "Den Teig nur kurz zusammenfügen, sonst werden die Scones fest.\n\nMit kalter Butter arbeiten für eine lockere Krume.\n\nBeim Ausstechen gerade nach unten drücken, nicht drehen — dann gehen sie höher auf.", "alternative": "", "geschichte": "Scones sind ein klassisches britisches Backwerk und untrennbar mit der Tradition des Nachmittagstees (afternoon tea) und besonders des „cream tea“ verbunden. Ihre Ursprünge liegen in den britischen Inseln, vermutlich in Schottland, wo frühe Formen auf einer Platte gebacken wurden; mit der Verbreitung von Backpulver und Öfen im 19. Jahrhundert entstand der heutige, lockere, hoch aufgehende Scone. Der Teig aus Mehl, Butter, etwas Zucker und Milch oder Buttermilch wird nur kurz zusammengefügt, ausgestochen und rasch gebacken. Klassisch werden Scones lauwarm aufgeschnitten und mit Clotted Cream (einem dicken Rahm) und Erdbeer- oder Himbeermarmelade serviert. Eine bis heute scherzhaft geführte regionale Debatte zwischen Devon und Cornwall dreht sich um die „richtige“ Reihenfolge von Sahne und Marmelade. Scones gehören zur Teekultur, zu Festen und zum Sonntag und werden oft auch mit Rosinen gebacken. Als Backwerk sind sie selbstverständlich vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Vereinigtes Königreich", "Scones", "afternoon tea", "cream tea", "Clotted Cream", "Marmelade", "Gebäck", "süß", "vegetarisch", "Teestunde", "britisch", "Dessert"]}, {"id": "draniki", "status": "published", "date": "", "cover": "", "name": "Draniki", "land": "Belarus", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 20, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Knusprige Kartoffelpuffer aus fein geriebenen Kartoffeln, serviert mit saurer Sahne. Das Nationalgericht von Belarus.", "zutaten": ["1 kg mehligkochende Kartoffeln", "1 Zwiebel", "2 EL Mehl", "1 Ei", "Öl zum Braten, Salz, Pfeffer", "saure Sahne zum Servieren"], "zutatenS": [{"menge": 1.0, "einheit": "kg", "item": "mehligkochende Kartoffeln", "roh": "1 kg mehligkochende Kartoffeln"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 2.0, "einheit": "EL", "item": "Mehl", "roh": "2 EL Mehl"}, {"menge": 1.0, "einheit": "", "item": "Ei", "roh": "1 Ei"}, {"menge": null, "einheit": "", "item": "Öl zum Braten, Salz, Pfeffer", "roh": "Öl zum Braten, Salz, Pfeffer"}, {"menge": null, "einheit": "", "item": "saure Sahne zum Servieren", "roh": "saure Sahne zum Servieren"}], "zubereitung": ["Kartoffeln und Zwiebel fein reiben und überschüssige Flüssigkeit ausdrücken.", "Mit Mehl, Ei, Salz und Pfeffer zu einem Teig vermengen.", "Reichlich Öl in einer Pfanne erhitzen.", "Esslöffelweise dünne Fladen ins heiße Öl geben.", "Beidseitig goldbraun und knusprig braten.", "Auf Küchenpapier abtropfen lassen und heiß mit saurer Sahne servieren."], "hinweise": "Die geriebenen Kartoffeln gut ausdrücken für knusprige Draniki.\n\nDie Zwiebel verhindert das Braunwerden der Masse.\n\nKlassisch mit reichlich saurer Sahne servieren.", "alternative": "", "geschichte": "Draniki gelten als das Nationalgericht von Belarus und spiegeln die herausragende Rolle der Kartoffel in der belarussischen Küche wider — Belarus ist für seine vielfältige Kartoffelküche bekannt, und die Kartoffel ist tief in der nationalen Esskultur verankert. Draniki sind knusprige Puffer aus fein geriebenen rohen Kartoffeln, die mit Zwiebel und etwas Mehl oder Ei gebunden und in heißem Öl goldbraun ausgebacken werden. Im Unterschied zu manchen Nachbarvarianten wird der Teig oft besonders schlicht gehalten, damit der Kartoffelgeschmack im Vordergrund steht. Das Gericht entstand in der bäuerlichen Küche als günstiges, sättigendes Essen aus dem wichtigsten Grundnahrungsmittel und wurde zu einem Symbol der belarussischen Identität. Serviert werden Draniki klassisch mit saurer Sahne (smetana), manchmal mit gedünsteten Pilzen oder Zwiebeln. In der einfachen Form aus Kartoffeln und Zwiebeln sind sie von Natur aus vegetarisch und ohne Schweinefleisch und gehören zur Alltags- wie Festtagsküche.", "persoenlich": "", "servier": "", "tags": ["Belarus", "Draniki", "Kartoffelpuffer", "vegetarisch", "Zwiebel", "saure Sahne", "Nationalgericht", "Kartoffelküche", "gebraten", "Hausmannskost", "Snack", "Hauptgericht"]}, {"id": "chaladnik", "status": "published", "date": "", "cover": "", "name": "Chaladnik", "land": "Belarus", "kontinent": "Europa", "gang": "Vorspeise", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine kalte, leuchtend rosa Suppe aus Roter Bete und Kefir mit Gurke, Ei und Dill, serviert mit warmen Kartoffeln. Belarussische Sommererfrischung.", "zutaten": ["1 l Kefir", "3 Rote Bete, gekocht und geraspelt", "1 Salatgurke", "3 hartgekochte Eier", "1 Bund Dill", "3 Frühlingszwiebeln", "5 Kartoffeln (warm, zum Servieren)", "Salz"], "zutatenS": [{"menge": 1.0, "einheit": "l", "item": "Kefir", "roh": "1 l Kefir"}, {"menge": 3.0, "einheit": "", "item": "Rote Bete, gekocht und geraspelt", "roh": "3 Rote Bete, gekocht und geraspelt"}, {"menge": 1.0, "einheit": "", "item": "Salatgurke", "roh": "1 Salatgurke"}, {"menge": 3.0, "einheit": "", "item": "hartgekochte Eier", "roh": "3 hartgekochte Eier"}, {"menge": 1.0, "einheit": "Bund", "item": "Dill", "roh": "1 Bund Dill"}, {"menge": 3.0, "einheit": "", "item": "Frühlingszwiebeln", "roh": "3 Frühlingszwiebeln"}, {"menge": 5.0, "einheit": "", "item": "Kartoffeln (warm, zum Servieren)", "roh": "5 Kartoffeln (warm, zum Servieren)"}, {"menge": null, "einheit": "", "item": "Salz", "roh": "Salz"}], "zubereitung": ["Gurke fein würfeln, Frühlingszwiebeln und Dill hacken.", "Zwei Eier würfeln, eines für die Garnitur zurückbehalten.", "Kefir mit der geraspelten Roten Bete verrühren, bis die Suppe leuchtend rosa ist.", "Gurke, Eier, Zwiebeln und Dill unterrühren und salzen.", "Mindestens 1 Stunde gut durchkühlen.", "Eiskalt mit warmen Salzkartoffeln und dem restlichen Ei servieren."], "hinweise": "Sehr kalt servieren — der Kontrast zu den warmen Kartoffeln ist typisch.\n\nReichlich frischer Dill gehört dazu.\n\nMit etwas Wasser oder Buttermilch die Konsistenz regeln.", "alternative": "", "geschichte": "Chaladnik (auch Kholodnik) ist die belarussische kalte Rote-Bete-Suppe und gehört zur Familie der kalten Sauermilchsuppen, die in Belarus, Litauen, Polen und der gesamten Region verbreitet sind. Der Name leitet sich vom Wort für „kalt“ ab. Grundlage ist Kefir oder dicke Sauermilch, die mit gekochter, geraspelter Roter Bete leuchtend rosa gefärbt wird; hinzu kommen frische Gurke, hartgekochtes Ei, Frühlingszwiebeln und reichlich Dill. Die Suppe wird eiskalt serviert, traditionell begleitet von warmen, in der Schale gekochten Kartoffeln, deren Wärme einen reizvollen Kontrast zur kühlen Suppe bildet. Chaladnik entstand als erfrischendes, leichtes Sommergericht, das ohne langes Kochen auskommt und die sommerliche Fülle an Bete, Gurke und Kräutern nutzt. Sie spiegelt die enge kulinarische Verwandtschaft der Länder zwischen Ostsee und Belarus wider. Als Gericht aus Sauermilch und Gemüse ist sie von Natur aus vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Belarus", "Chaladnik", "kalte Suppe", "Rote Bete", "Kefir", "Gurke", "Dill", "vegetarisch", "Sommerküche", "erfrischend", "osteuropäisch", "Suppe"]}, {"id": "kartoflyanaya-babka", "status": "published", "date": "", "cover": "", "name": "Kartoflyanaya babka", "land": "Belarus", "kontinent": "Europa", "gang": "Hauptgericht", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein im Ofen gebackener Auflauf aus geriebenen Kartoffeln und Zwiebeln mit knuspriger Oberfläche, serviert mit saurer Sahne. Herzhafte belarussische Kartoffelspezialität.", "zutaten": ["1.2 kg mehligkochende Kartoffeln", "2 Zwiebeln", "2 Eier", "60 g Butter", "2 EL Mehl", "Salz, Pfeffer; saure Sahne zum Servieren"], "zutatenS": [{"menge": 1.2, "einheit": "kg", "item": "mehligkochende Kartoffeln", "roh": "1.2 kg mehligkochende Kartoffeln"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 2.0, "einheit": "", "item": "Eier", "roh": "2 Eier"}, {"menge": 60.0, "einheit": "g", "item": "Butter", "roh": "60 g Butter"}, {"menge": 2.0, "einheit": "EL", "item": "Mehl", "roh": "2 EL Mehl"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer; saure Sahne zum Servieren", "roh": "Salz, Pfeffer; saure Sahne zum Servieren"}], "zubereitung": ["Kartoffeln fein reiben und überschüssige Flüssigkeit ausdrücken.", "Zwiebeln würfeln und in Butter goldbraun rösten.", "Geriebene Kartoffeln mit Röstzwiebeln, Eiern, Mehl, Salz und Pfeffer vermengen.", "Die Masse in eine gebutterte Auflaufform geben und glatt streichen.", "Mit Butterflöckchen belegen und bei 190 °C 50–60 Minuten backen, bis die Oberfläche goldbraun und knusprig ist.", "Etwas ruhen lassen, in Stücke schneiden und mit saurer Sahne servieren."], "hinweise": "Die Kartoffeln gut ausdrücken, damit die Babka nicht wässrig wird.\n\nReichlich Röstzwiebeln geben die herzhafte Tiefe.\n\nVor dem Anschneiden kurz ruhen lassen.", "alternative": "Traditionell wird die Kartoffelbabka mit ausgelassenem Speck und Grieben vom Schwein zubereitet. Wir verwenden stattdessen reichlich in Butter geröstete Zwiebeln — sie geben die herzhafte Tiefe, ganz ohne Schwein. Wer eine rauchige Note möchte, brät etwas geräuchertes Rind mit an.", "geschichte": "Kartoflyanaya babka — „Kartoffelbabka“ — ist ein traditioneller belarussischer Kartoffelauflauf und ein weiteres Beispiel für die zentrale Rolle der Kartoffel in der Küche des Landes. Anders als die in der Pfanne gebratenen Draniki wird die Babka aus einer Masse geriebener Kartoffeln und Zwiebeln in einer Form im Ofen gebacken, bis sie innen weich und saftig und außen goldbraun und knusprig ist. Das Gericht entstand in der bäuerlichen Küche als sättigendes, einfaches Essen, das eine ganze Familie aus dem wichtigsten Grundnahrungsmittel versorgte. Traditionell wird die Babka mit ausgelassenem Speck und Grieben angereichert; in dieser Fassung verwenden wir reichlich geröstete Zwiebeln und Butter, sodass sie ohne Schwein auskommt. Serviert wird sie warm, klassisch mit saurer Sahne (smetana). Kartoflyanaya babka gehört zur herzhaften Alltags- und Festtagsküche von Belarus und steht sinnbildlich für die erfindungsreiche Kartoffelküche des Landes.", "persoenlich": "", "servier": "", "tags": ["Belarus", "Kartoflyanaya babka", "Kartoffelauflauf", "vegetarisch", "Zwiebeln", "Ofengericht", "saure Sahne", "Kartoffelküche", "Röstzwiebeln", "Hausmannskost", "deftig", "Hauptgericht"]}, {"id": "koshari", "status": "published", "date": "", "cover": "", "name": "Koshari", "land": "Ägypten", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein sättigendes Schichtgericht aus Reis, Linsen und Nudeln mit Kichererbsen, würziger Tomatensauce und knusprigen Röstzwiebeln. Das Nationalgericht Ägyptens.", "zutaten": ["200 g Reis", "200 g braune Linsen", "150 g kleine Nudeln (Makkaroni und Vermicelli)", "200 g gekochte Kichererbsen", "3 Zwiebeln (zum Frittieren)", "500 g passierte Tomaten", "3 Zehen Knoblauch, 2 EL Essig", "1 TL Kreuzkümmel, Chili", "Öl, Salz"], "zutatenS": [{"menge": 200.0, "einheit": "g", "item": "Reis", "roh": "200 g Reis"}, {"menge": 200.0, "einheit": "g", "item": "braune Linsen", "roh": "200 g braune Linsen"}, {"menge": 150.0, "einheit": "g", "item": "kleine Nudeln (Makkaroni und Vermicelli)", "roh": "150 g kleine Nudeln (Makkaroni und Vermicelli)"}, {"menge": 200.0, "einheit": "g", "item": "gekochte Kichererbsen", "roh": "200 g gekochte Kichererbsen"}, {"menge": 3.0, "einheit": "", "item": "Zwiebeln (zum Frittieren)", "roh": "3 Zwiebeln (zum Frittieren)"}, {"menge": 500.0, "einheit": "g", "item": "passierte Tomaten", "roh": "500 g passierte Tomaten"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch, 2 EL Essig", "roh": "3 Zehen Knoblauch, 2 EL Essig"}, {"menge": 1.0, "einheit": "TL", "item": "Kreuzkümmel, Chili", "roh": "1 TL Kreuzkümmel, Chili"}, {"menge": null, "einheit": "", "item": "Öl, Salz", "roh": "Öl, Salz"}], "zubereitung": ["Linsen weich kochen; Reis und Nudeln separat garen.", "Zwiebeln in feine Ringe schneiden und in reichlich Öl knusprig goldbraun frittieren.", "Für die Sauce Knoblauch anbraten, passierte Tomaten, Essig, Kreuzkümmel und Chili zugeben und einkochen.", "Reis, Linsen, Nudeln und Kichererbsen vermengen oder schichten.", "Mit der würzigen Tomatensauce übergießen.", "Großzügig mit den knusprigen Röstzwiebeln bestreuen und servieren."], "hinweise": "Die Röstzwiebeln sehr knusprig frittieren — sie sind das Herz des Gerichts.\n\nEssig und Knoblauch geben der Sauce die typische Würze.\n\nAlle Komponenten warm zusammenführen und sofort servieren.", "alternative": "", "geschichte": "Koshari (auch Kushari) gilt als das Nationalgericht Ägyptens und ist das allgegenwärtige Straßen- und Alltagsessen des Landes, besonders in Kairo. Es ist ein außergewöhnliches Mischgericht, das Reis, braune Linsen, kleine Nudeln und Kichererbsen in einer Schüssel vereint, gekrönt von einer würzigen, mit Essig und Knoblauch abgeschmeckten Tomatensauce und reichlich knusprig frittierten Zwiebeln. Seine Wurzeln sind ein Spiegel der Handelsgeschichte: Der Reis-Linsen-Kern erinnert an indische Gerichte wie Kichari, die Nudeln und Tomaten kamen über mediterrane und italienische Einflüsse hinzu, sodass Koshari im 19. und frühen 20. Jahrhundert in seiner heutigen Form entstand. Als rein pflanzliches, günstiges und sehr sättigendes Gericht wurde es zum Essen der einfachen Leute und ist von Natur aus vegan und ohne Schweinefleisch. Spezialisierte Koshari-Lokale servieren es in großen Mengen. Koshari verkörpert die multikulturelle, erfinderische Seite der ägyptischen Küche.", "persoenlich": "", "servier": "", "tags": ["Ägypten", "Koshari", "Kushari", "Reis", "Linsen", "Nudeln", "Kichererbsen", "vegan", "vegetarisch", "Röstzwiebeln", "Straßenessen", "Nationalgericht"]}, {"id": "ful-medames", "status": "published", "date": "", "cover": "", "name": "Ful medames", "land": "Ägypten", "kontinent": "Afrika", "gang": "Frühstück", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Langsam geschmorte Saubohnen, zerdrückt und mit Olivenöl, Zitrone, Knoblauch und Kreuzkümmel angemacht. Ägyptens uraltes Frühstücksgericht.", "zutaten": ["400 g getrocknete Saubohnen (Ful, Ackerbohnen)", "4 EL Olivenöl", "2 Zitronen (Saft)", "4 Zehen Knoblauch", "1 TL gemahlener Kreuzkümmel", "2 Tomaten, 1 Bund Petersilie", "Salz; Fladenbrot und Eier zum Servieren"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "getrocknete Saubohnen (Ful, Ackerbohnen)", "roh": "400 g getrocknete Saubohnen (Ful, Ackerbohnen)"}, {"menge": 4.0, "einheit": "EL", "item": "Olivenöl", "roh": "4 EL Olivenöl"}, {"menge": 2.0, "einheit": "", "item": "Zitronen (Saft)", "roh": "2 Zitronen (Saft)"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "4 Zehen Knoblauch"}, {"menge": 1.0, "einheit": "TL", "item": "gemahlener Kreuzkümmel", "roh": "1 TL gemahlener Kreuzkümmel"}, {"menge": 2.0, "einheit": "", "item": "Tomaten, 1 Bund Petersilie", "roh": "2 Tomaten, 1 Bund Petersilie"}, {"menge": null, "einheit": "", "item": "Salz; Fladenbrot und Eier zum Servieren", "roh": "Salz; Fladenbrot und Eier zum Servieren"}], "zubereitung": ["Die Saubohnen über Nacht einweichen.", "In frischem Wasser sehr langsam mehrere Stunden weich schmoren, bis sie zerfallen.", "Knoblauch mit Salz und Kreuzkümmel zerdrücken.", "Die Bohnen teilweise zerdrücken und mit Knoblauch, Olivenöl und Zitronensaft anmachen.", "Mit gewürfelten Tomaten und gehackter Petersilie verfeinern.", "Warm mit Fladenbrot und nach Wunsch einem hartgekochten Ei servieren."], "hinweise": "Sehr langes, sanftes Garen macht die Bohnen cremig.\n\nReichlich Zitrone, Knoblauch und Kreuzkümmel geben den typischen Geschmack.\n\nMit Fladenbrot zum Auftunken servieren.", "alternative": "", "geschichte": "Ful medames — geschmorte Saubohnen (Ackerbohnen) — ist eines der ältesten und wichtigsten Gerichte der ägyptischen Küche und gilt neben Koshari als nationales Grundgericht. Seine Geschichte reicht außerordentlich weit zurück; Saubohnen gehören zu den ältesten Kulturpflanzen der Region, und Hinweise auf das Gericht oder seine Vorläufer reichen bis in die Antike. Die getrockneten Bohnen werden über viele Stunden, traditionell über Nacht, sehr langsam weich geschmort und dann zerdrückt und mit Olivenöl, Zitronensaft, Knoblauch, Kreuzkümmel und Salz angemacht; oft kommen gehackte Tomaten, Petersilie oder ein hartgekochtes Ei dazu. Ful medames ist vor allem als sättigendes, eiweißreiches Frühstück verbreitet und wird mit Fladenbrot gegessen, das zum Auftunken dient. Als günstiges, nahrhaftes Essen ist es in allen Bevölkerungsschichten beliebt und von Natur aus vegan und ohne Schweinefleisch. Ful medames verkörpert die uralte, bohnenbasierte Tradition der ägyptischen Alltagsküche.", "persoenlich": "", "servier": "", "tags": ["Ägypten", "Ful medames", "Saubohnen", "Ackerbohnen", "vegan", "vegetarisch", "Frühstück", "Olivenöl", "Kreuzkümmel", "antik", "Grundnahrungsmittel", "Hauptgericht"]}, {"id": "molokhia", "status": "published", "date": "", "cover": "", "name": "Molokhia", "land": "Ägypten", "kontinent": "Afrika", "gang": "Suppe", "art": [], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein sämiger grüner Eintopf aus fein gehackten Jutemalvenblättern mit Knoblauch und Koriander, serviert über Reis und mit Hähnchen. Ägyptisches Traditionsgericht.", "zutaten": ["500 g Molokhia-Blätter (frisch, TK oder getrocknet)", "1.2 l Hähnchen- oder Gemüsebrühe", "1 Hähnchen, in Teilen (optional)", "6 Zehen Knoblauch", "2 TL gemahlener Koriander", "3 EL Butter oder Öl (Takleya)", "Salz; Reis und Fladenbrot zum Servieren"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Molokhia-Blätter (frisch, TK oder getrocknet)", "roh": "500 g Molokhia-Blätter (frisch, TK oder getrocknet)"}, {"menge": 1.2, "einheit": "l", "item": "Hähnchen- oder Gemüsebrühe", "roh": "1.2 l Hähnchen- oder Gemüsebrühe"}, {"menge": 1.0, "einheit": "", "item": "Hähnchen, in Teilen (optional)", "roh": "1 Hähnchen, in Teilen (optional)"}, {"menge": 6.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "6 Zehen Knoblauch"}, {"menge": 2.0, "einheit": "TL", "item": "gemahlener Koriander", "roh": "2 TL gemahlener Koriander"}, {"menge": 3.0, "einheit": "EL", "item": "Butter oder Öl (Takleya)", "roh": "3 EL Butter oder Öl (Takleya)"}, {"menge": null, "einheit": "", "item": "Salz; Reis und Fladenbrot zum Servieren", "roh": "Salz; Reis und Fladenbrot zum Servieren"}], "zubereitung": ["Eine kräftige Brühe ansetzen (mit Hähnchen, falls verwendet, das separat gar gekocht wird).", "Die Molokhia-Blätter sehr fein hacken (frisch) oder vorbereiten (TK/getrocknet).", "Die Blätter in die siedende Brühe geben und bei kleiner Hitze garen; nicht stark kochen.", "Für die Takleya Knoblauch fein hacken und in Butter oder Öl mit dem Koriander goldgelb braten, bis es duftet.", "Die Takleya in die Molokhia einrühren — sie verströmt das typische Aroma.", "Mit Salz abschmecken und über Reis, mit dem Hähnchen und Fladenbrot servieren."], "hinweise": "Die Molokhia nur sanft garen, nicht sprudelnd kochen.\n\nDie Takleya aus Knoblauch und Koriander ist der aromatische Schlüssel.\n\nÜber Reis und mit Fladenbrot servieren.", "alternative": "", "geschichte": "Molokhia (auch Mulukhiyah) ist ein traditionsreiches Gericht der ägyptischen Küche und im gesamten östlichen Mittelmeerraum verbreitet. Es wird aus den Blättern der Jutemalve zubereitet, die fein gehackt werden und der Speise ihre charakteristische grüne Farbe und leicht schleimig-sämige Konsistenz geben. Das Gericht hat eine sehr lange Geschichte in Ägypten; Hinweise auf den Verzehr der Pflanze reichen bis in die Antike zurück, und Molokhia gilt vielen als uraltes Essen des Niltals. Die gehackten Blätter werden in einer Brühe gegart und mit einer aromatischen „Takleya“ aus in Öl oder Butter gebratenem Knoblauch und gemahlenem Koriander vollendet, die kurz vor dem Servieren untergerührt wird und den typischen Duft erzeugt. Molokhia wird klassisch über Reis und häufig mit Hähnchen, Kaninchen oder als vegetarische Variante mit Gemüsebrühe serviert. Als Gericht aus Blattgemüse und Geflügel oder rein pflanzlich ist es von Natur aus ohne Schweinefleisch und gehört zur Alltags- wie Festtagsküche Ägyptens.", "persoenlich": "", "servier": "", "tags": ["Ägypten", "Molokhia", "Mulukhiyah", "Jutemalve", "Blattgemüse", "Knoblauch", "Koriander", "Eintopf", "antik", "Niltal", "Reis", "Hauptgericht"]}, {"id": "chakhchoukha", "status": "published", "date": "", "cover": "", "name": "Chakhchoukha", "land": "Algerien", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "In Stücke gezupftes, dünnes Fladenbrot, getränkt in einer würzigen Tomaten-Kichererbsen-Sauce mit Lamm. Herzhaftes Festtagsgericht aus dem algerischen Hochland.", "zutaten": ["500 g dünnes Fladenbrot (rougag), in Stücke gezupft", "600 g Lammfleisch, gewürfelt", "2 Zwiebeln", "400 g passierte Tomaten, 2 EL Tomatenmark", "200 g gekochte Kichererbsen", "1 TL Ras el-Hanout, 1 TL Paprika, 0,5 TL Kreuzkümmel", "5 EL Olivenöl", "Salz, Pfeffer"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "dünnes Fladenbrot (rougag), in Stücke gezupft", "roh": "500 g dünnes Fladenbrot (rougag), in Stücke gezupft"}, {"menge": 600.0, "einheit": "g", "item": "Lammfleisch, gewürfelt", "roh": "600 g Lammfleisch, gewürfelt"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 400.0, "einheit": "g", "item": "passierte Tomaten, 2 EL Tomatenmark", "roh": "400 g passierte Tomaten, 2 EL Tomatenmark"}, {"menge": 200.0, "einheit": "g", "item": "gekochte Kichererbsen", "roh": "200 g gekochte Kichererbsen"}, {"menge": 1.0, "einheit": "TL", "item": "Ras el-Hanout, 1 TL Paprika, 0,5 TL Kreuzkümmel", "roh": "1 TL Ras el-Hanout, 1 TL Paprika, 0,5 TL Kreuzkümmel"}, {"menge": 5.0, "einheit": "EL", "item": "Olivenöl", "roh": "5 EL Olivenöl"}, {"menge": null, "einheit": "", "item": "Salz, Pfeffer", "roh": "Salz, Pfeffer"}], "zubereitung": ["Zwiebeln in Olivenöl andünsten, Lammwürfel zugeben und rundum anbraten.", "Tomatenmark und Gewürze einrühren und kurz mitrösten.", "Passierte Tomaten und Wasser angießen, salzen und das Fleisch sanft weich schmoren.", "Kichererbsen zugeben und die Sauce einige Minuten mitkochen.", "Die gezupften Brotstücke in einer Schüssel mit der heißen Sauce übergießen und kurz ziehen lassen, bis sie weich sind.", "Mit Fleisch und Kichererbsen anrichten und heiß servieren."], "hinweise": "Das Brot wirklich klein zupfen, damit es die Sauce gut aufnimmt.\n\nDie Sauce darf reichlich sein — das Brot saugt viel auf.\n\nMit Ras el-Hanout und Kreuzkümmel kräftig würzen.", "alternative": "", "geschichte": "Chakhchoukha gehört zu den traditionsreichsten Gerichten Algeriens und stammt aus den Hochland- und Aurès-Regionen sowie dem Süden des Landes, etwa um Biskra. Es ist ein Gericht der Festtage und großen Familienfeiern. Im Zentrum steht ein sehr dünnes, von Hand gebackenes Fladenbrot (rougag oder m'semmen), das nach dem Backen in kleine Stücke gezupft wird — eine geduldige Handarbeit, die traditionell von den Frauen der Familie geleistet wird. Diese Brotstücke werden in einer kräftigen, mit Tomaten, Kichererbsen und der nordafrikanischen Gewürzmischung sowie Lamm zubereiteten Sauce (marqa) getränkt, bis sie weich sind und die Aromen aufgenommen haben. Die Würzung mit Ras el-Hanout, Kreuzkümmel und Paprika ist charakteristisch. Chakhchoukha spiegelt die berberischen Wurzeln der algerischen Küche und die Tradition wider, Brot als zentrales Element einer Mahlzeit zu nutzen. Als Lamm-Gemüse-Gericht ist es von Natur aus ohne Schweinefleisch und gilt als sättigendes, geselliges Festessen.", "persoenlich": "", "servier": "", "tags": ["Algerien", "Chakhchoukha", "Fladenbrot", "Lamm", "Kichererbsen", "Tomatensauce", "Ras el-Hanout", "berberisch", "Festtag", "Aurès", "Maghreb", "Hauptgericht"]}, {"id": "chorba-frik", "status": "published", "date": "", "cover": "", "name": "Chorba frik", "land": "Algerien", "kontinent": "Afrika", "gang": "Suppe", "art": [], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine herzhafte Suppe aus Grünkern (Freekeh), Lamm, Tomaten und Kräutern. Die klassische algerische Ramadan-Suppe.", "zutaten": ["400 g Lammfleisch, gewürfelt", "120 g Frik (Freekeh/Grünkern)", "2 Zwiebeln", "400 g passierte Tomaten, 1 EL Tomatenmark", "150 g Kichererbsen", "1 Bund Koriander und Minze", "1 TL Zimt, 1 TL Ras el-Hanout", "Olivenöl, Salz, Pfeffer"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Lammfleisch, gewürfelt", "roh": "400 g Lammfleisch, gewürfelt"}, {"menge": 120.0, "einheit": "g", "item": "Frik (Freekeh/Grünkern)", "roh": "120 g Frik (Freekeh/Grünkern)"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 400.0, "einheit": "g", "item": "passierte Tomaten, 1 EL Tomatenmark", "roh": "400 g passierte Tomaten, 1 EL Tomatenmark"}, {"menge": 150.0, "einheit": "g", "item": "Kichererbsen", "roh": "150 g Kichererbsen"}, {"menge": 1.0, "einheit": "Bund", "item": "Koriander und Minze", "roh": "1 Bund Koriander und Minze"}, {"menge": 1.0, "einheit": "TL", "item": "Zimt, 1 TL Ras el-Hanout", "roh": "1 TL Zimt, 1 TL Ras el-Hanout"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer", "roh": "Olivenöl, Salz, Pfeffer"}], "zubereitung": ["Zwiebeln in Olivenöl andünsten, Lammwürfel zugeben und anbraten.", "Tomatenmark und Gewürze einrühren, dann passierte Tomaten und Wasser angießen.", "Kichererbsen zugeben und das Fleisch sanft weich kochen.", "Den gewaschenen Frik einstreuen und unter gelegentlichem Rühren gar kochen, bis die Suppe sämig wird.", "Reichlich gehackten Koriander und Minze einrühren.", "Mit Salz, Pfeffer und einem Spritzer Zitrone abschmecken und heiß servieren."], "hinweise": "Frik gibt der Suppe Biss und ein rauchiges Aroma — nicht durch Reis ersetzen.\n\nFrische Kräuter erst zum Schluss zugeben.\n\nDie Suppe darf schön sämig sein; bei Bedarf Wasser nachgießen.", "alternative": "", "geschichte": "Chorba frik ist eine der bekanntesten Suppen Algeriens und ein fester Bestandteil des Fastenmonats Ramadan, in dem sie traditionell zum abendlichen Fastenbrechen (Iftar) auf den Tisch kommt. Ihr Name verweist auf die zentrale Zutat: Frik (Freekeh) ist geröstetes, noch grün geerntetes und gedroschenes Weizenkorn, das der Suppe ihren charakteristischen, leicht rauchigen Geschmack und Biss verleiht. Freekeh hat im Maghreb und im östlichen Mittelmeerraum eine lange Tradition. Die Suppe verbindet das Korn mit Lammfleisch, Tomaten, Zwiebeln, Kichererbsen und reichlich frischen Kräutern wie Koriander und Minze, gewürzt mit nordafrikanischen Gewürzen. Sie ist nahrhaft und wärmend und gilt als ideale Speise, um nach einem Fastentag wieder zu Kräften zu kommen. Jede Region und Familie pflegt ihre eigene Variante. Chorba frik spiegelt die getreidereiche, kräutergewürzte Seite der algerischen Küche wider und ist als Lamm-Getreide-Suppe von Natur aus ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Algerien", "Chorba frik", "Freekeh", "Grünkern", "Lamm", "Suppe", "Ramadan", "Iftar", "Koriander", "Maghreb", "Tomaten", "Hauptgericht"]}, {"id": "kalb-el-louz", "status": "published", "date": "", "cover": "", "name": "Kalb el louz", "land": "Algerien", "kontinent": "Afrika", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein saftiger Grießkuchen mit Mandeln, nach dem Backen mit Orangenblüten-Sirup getränkt. Beliebtes algerisches Süßgebäck, besonders im Ramadan.", "zutaten": ["400 g feiner Grieß", "150 g gemahlene Mandeln", "150 g Zucker (Teig)", "120 g geschmolzene Butter", "1 TL Backpulver", "20 ganze Mandeln zum Verzieren", "400 g Zucker und 400 ml Wasser (Sirup)", "3 EL Orangenblütenwasser"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "feiner Grieß", "roh": "400 g feiner Grieß"}, {"menge": 150.0, "einheit": "g", "item": "gemahlene Mandeln", "roh": "150 g gemahlene Mandeln"}, {"menge": 150.0, "einheit": "g", "item": "Zucker (Teig)", "roh": "150 g Zucker (Teig)"}, {"menge": 120.0, "einheit": "g", "item": "geschmolzene Butter", "roh": "120 g geschmolzene Butter"}, {"menge": 1.0, "einheit": "TL", "item": "Backpulver", "roh": "1 TL Backpulver"}, {"menge": 20.0, "einheit": "", "item": "ganze Mandeln zum Verzieren", "roh": "20 ganze Mandeln zum Verzieren"}, {"menge": 400.0, "einheit": "g", "item": "Zucker und 400 ml Wasser (Sirup)", "roh": "400 g Zucker und 400 ml Wasser (Sirup)"}, {"menge": 3.0, "einheit": "EL", "item": "Orangenblütenwasser", "roh": "3 EL Orangenblütenwasser"}], "zubereitung": ["Grieß, gemahlene Mandeln, Zucker und Backpulver mischen.", "Die geschmolzene Butter einarbeiten, bis eine krümelig-feuchte Masse entsteht; kurz ruhen lassen.", "Die Masse in eine Form drücken, in Rauten vorschneiden und je eine Mandel eindrücken.", "Bei 180 °C 25–30 Minuten goldbraun backen.", "Aus Zucker, Wasser und Orangenblütenwasser einen Sirup kochen.", "Den Sirup über den noch warmen Kuchen gießen und mehrere Stunden einziehen lassen."], "hinweise": "Heißer Sirup auf warmes Gebäck zieht am besten ein.\n\nDie Masse vor dem Backen ruhen lassen, damit der Grieß quillt.\n\nVor dem Servieren gut durchtränken lassen.", "alternative": "", "geschichte": "Kalb el louz — wörtlich „Herz der Mandel“ — ist eine der beliebtesten Süßspeisen Algeriens und gehört besonders im Fastenmonat Ramadan zu den traditionellen Nachspeisen. Es handelt sich um einen saftigen Kuchen auf Grießbasis, der mit Mandeln verfeinert und nach dem Backen großzügig mit einem duftenden Sirup aus Zucker und Orangenblütenwasser getränkt wird, sodass er besonders feucht und süß wird. Häufig wird in die Mitte eine ganze Mandel gedrückt, was dem Gebäck seinen Namen gibt. Sirupgetränkte Grießsüßspeisen haben im gesamten Maghreb und im früheren osmanischen Raum eine lange Tradition; das Orangenblütenwasser ist ein charakteristisches Aroma der nordafrikanischen Konditorei. Kalb el louz wird in Rauten geschnitten und kühl oder bei Zimmertemperatur serviert, oft zum Tee. Es spiegelt die ausgeprägte Vorliebe der algerischen Küche für mandel- und sirupbasierte Süßigkeiten wider. Als reines Grieß-Mandel-Gebäck ist es von Natur aus vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Algerien", "Kalb el louz", "Grießkuchen", "Mandeln", "Orangenblütenwasser", "Sirup", "süß", "Ramadan", "vegetarisch", "Maghreb", "Konditorei", "Dessert"]}, {"id": "bazin", "status": "published", "date": "", "cover": "", "name": "Bazin", "land": "Libyen", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein fester Teigkloß aus Gerstenmehl, serviert in einer würzigen Tomaten-Lamm-Sauce mit Ei. Das Nationalgericht Libyens.", "zutaten": ["400 g Gerstenmehl (plus etwas Weizenmehl)", "600 ml Wasser (Teig)", "600 g Lammfleisch, gewürfelt", "2 Zwiebeln, 3 EL Tomatenmark", "2 Kartoffeln", "1 TL scharfes Paprikapulver, 1 TL Kurkuma, Bharat-Gewürz", "4 Eier (hartgekocht)", "Olivenöl, Salz"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Gerstenmehl (plus etwas Weizenmehl)", "roh": "400 g Gerstenmehl (plus etwas Weizenmehl)"}, {"menge": 600.0, "einheit": "ml", "item": "Wasser (Teig)", "roh": "600 ml Wasser (Teig)"}, {"menge": 600.0, "einheit": "g", "item": "Lammfleisch, gewürfelt", "roh": "600 g Lammfleisch, gewürfelt"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln, 3 EL Tomatenmark", "roh": "2 Zwiebeln, 3 EL Tomatenmark"}, {"menge": 2.0, "einheit": "", "item": "Kartoffeln", "roh": "2 Kartoffeln"}, {"menge": 1.0, "einheit": "TL", "item": "scharfes Paprikapulver, 1 TL Kurkuma, Bharat-Gewürz", "roh": "1 TL scharfes Paprikapulver, 1 TL Kurkuma, Bharat-Gewürz"}, {"menge": 4.0, "einheit": "", "item": "Eier (hartgekocht)", "roh": "4 Eier (hartgekocht)"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz", "roh": "Olivenöl, Salz"}], "zubereitung": ["Für die Sauce Zwiebeln in Öl andünsten, Lamm anbraten, Tomatenmark und Gewürze einrühren.", "Mit Wasser auffüllen, Kartoffeln zugeben und das Fleisch weich schmoren.", "Für den Teig Gerstenmehl nach und nach in kochendes Salzwasser einrühren und zu einer sehr festen Masse verkochen.", "Den Teig kräftig durcharbeiten und zu einer glatten Kuppel formen.", "Den Teigkloß in die Mitte einer Schüssel setzen und mit der Sauce umgeben.", "Mit Lamm, Kartoffeln und hartgekochten Eiern anrichten und gemeinschaftlich servieren."], "hinweise": "Den Teig zügig und kräftig durcharbeiten, damit er glatt und fest wird.\n\nDie Sauce kräftig würzen — sie trägt das Gericht.\n\nTraditionell isst man gemeinsam aus einer Schüssel.", "alternative": "", "geschichte": "Bazin gilt als das Nationalgericht Libyens und ist ein traditionsreiches Essen, das besonders zu Feiertagen, Familienfeiern und religiösen Festen zubereitet wird. Im Zentrum steht ein fester, ungesäuerter Teigkloß, der aus Gerstenmehl (und teils Weizenmehl) mit Wasser zu einer dichten Masse gekocht und mit einem speziellen Stock zu einer glatten, halbkugelförmigen Kuppel geformt wird — eine kraftvolle Handarbeit. Gerste hat in der libyschen und nordafrikanischen Ernährung eine lange Geschichte als Grundnahrungsmittel. Der Teigkloß wird in die Mitte einer Schüssel gesetzt und von einer kräftigen, würzigen Sauce (marqa) aus Tomaten, Lamm, Kartoffeln und der scharfen Gewürzpaste umgeben, dazu kommen hartgekochte Eier. Gegessen wird traditionell gemeinschaftlich aus einer Schüssel, indem man Stücke des Teigs abbricht und in die Sauce taucht. Bazin verkörpert die gemeinschaftliche, gastfreundliche Esskultur Libyens und ist als Gersten-Lamm-Gericht von Natur aus ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Libyen", "Bazin", "Gerste", "Teigkloß", "Lamm", "Tomatensauce", "Ei", "Nationalgericht", "Festtag", "Maghreb", "gemeinschaftlich", "Hauptgericht"]}, {"id": "sharba-libiya", "status": "published", "date": "", "cover": "", "name": "Sharba libiya", "land": "Libyen", "kontinent": "Afrika", "gang": "Suppe", "art": [], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine würzige Lammsuppe mit Tomaten, feinen Nudeln, Minze und reichlich Gewürzen. Libyens klassische Ramadan-Suppe.", "zutaten": ["400 g Lammfleisch, klein gewürfelt", "1 Zwiebel", "3 EL Tomatenmark, 400 g passierte Tomaten", "100 g feine Nudeln (orzo)", "2 EL getrocknete Minze", "1 TL Kurkuma, 1 TL bharat, etwas Chili", "1 Bund frische Petersilie", "Olivenöl, Salz, Pfeffer"], "zutatenS": [{"menge": 400.0, "einheit": "g", "item": "Lammfleisch, klein gewürfelt", "roh": "400 g Lammfleisch, klein gewürfelt"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel", "roh": "1 Zwiebel"}, {"menge": 3.0, "einheit": "EL", "item": "Tomatenmark, 400 g passierte Tomaten", "roh": "3 EL Tomatenmark, 400 g passierte Tomaten"}, {"menge": 100.0, "einheit": "g", "item": "feine Nudeln (orzo)", "roh": "100 g feine Nudeln (orzo)"}, {"menge": 2.0, "einheit": "EL", "item": "getrocknete Minze", "roh": "2 EL getrocknete Minze"}, {"menge": 1.0, "einheit": "TL", "item": "Kurkuma, 1 TL bharat, etwas Chili", "roh": "1 TL Kurkuma, 1 TL bharat, etwas Chili"}, {"menge": 1.0, "einheit": "Bund", "item": "frische Petersilie", "roh": "1 Bund frische Petersilie"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer", "roh": "Olivenöl, Salz, Pfeffer"}], "zubereitung": ["Zwiebel in Olivenöl andünsten, Lammwürfel zugeben und anbraten.", "Tomatenmark und Gewürze einrühren und kurz mitrösten.", "Passierte Tomaten und Wasser angießen, salzen und das Fleisch sanft weich kochen.", "Die feinen Nudeln einstreuen und gar kochen, bis die Suppe sämig ist.", "Reichlich getrocknete Minze und frische Petersilie einrühren.", "Mit Salz, Pfeffer und einem Spritzer Zitrone abschmecken und heiß servieren."], "hinweise": "Getrocknete Minze ist das prägende Aroma — nicht weglassen.\n\nDie Nudeln erst gegen Ende zugeben, damit sie nicht zerkochen.\n\nBei Bedarf Wasser nachgießen, die Suppe soll sämig, nicht dick sein.", "alternative": "", "geschichte": "Sharba libiya — die libysche Suppe — ist eine der bekanntesten Speisen Libyens und gehört, ähnlich wie verwandte Suppen im Maghreb, fest zum Fastenmonat Ramadan, in dem sie das abendliche Fastenbrechen einleitet. Die Suppe verbindet Lammfleisch mit einer tomatenreichen Basis, feinen Nudeln (orzo oder gebrochene Fadennudeln) und einer charakteristischen Würzung aus libyschem Gewürzmix (bharat), Kurkuma, etwas Schärfe und vor allem reichlich getrockneter Minze, die ihr das unverwechselbare Aroma gibt. Manche Varianten enthalten Kichererbsen. Sharba ist nahrhaft und wärmend und gilt als ideale Speise, um nach einem Fastentag schonend wieder zu Kräften zu kommen. Sie spiegelt die Verbindung der libyschen Küche mit der breiteren nordafrikanischen und mediterranen Tradition würziger Lammsuppen wider und wird auch außerhalb des Ramadan geschätzt. Als Lammsuppe ist Sharba libiya von Natur aus ohne Schweinefleisch und gehört zu den Gerichten, die Gastfreundschaft und Familienzusammenhalt verkörpern.", "persoenlich": "", "servier": "", "tags": ["Libyen", "Sharba libiya", "Lammsuppe", "Tomaten", "Minze", "bharat", "Ramadan", "Iftar", "Nudeln", "Maghreb", "würzig", "Hauptgericht"]}, {"id": "asida", "status": "published", "date": "", "cover": "", "name": "Asida", "land": "Libyen", "kontinent": "Afrika", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein glatter, fester Brei aus Weizenmehl, serviert mit einer Mulde aus Dattelsirup und Olivenöl oder Honig. Süße libysche Spezialität zu Festen.", "zutaten": ["300 g Weizenmehl", "600 ml Wasser", "1 Prise Salz", "150 g Dattelsirup (rub) oder Honig", "60 g Butter, zerlassen", "3 EL Olivenöl"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "Weizenmehl", "roh": "300 g Weizenmehl"}, {"menge": 600.0, "einheit": "ml", "item": "Wasser", "roh": "600 ml Wasser"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}, {"menge": 150.0, "einheit": "g", "item": "Dattelsirup (rub) oder Honig", "roh": "150 g Dattelsirup (rub) oder Honig"}, {"menge": 60.0, "einheit": "g", "item": "Butter, zerlassen", "roh": "60 g Butter, zerlassen"}, {"menge": 3.0, "einheit": "EL", "item": "Olivenöl", "roh": "3 EL Olivenöl"}], "zubereitung": ["Salzwasser zum Kochen bringen.", "Das Mehl nach und nach einrühren und dabei kräftig schlagen, um Klumpen zu vermeiden.", "Unter ständigem Rühren zu einem glatten, festen, klebrigen Brei kochen.", "Die Asida kuppelförmig in einer Schüssel anrichten.", "In die Mitte eine Mulde drücken und mit Dattelsirup, zerlassener Butter und Olivenöl füllen.", "Warm und gemeinschaftlich servieren, indem man Stücke in den Sirup tunkt."], "hinweise": "Kräftig und ohne Pause rühren, damit der Brei glatt wird.\n\nDattelsirup (rub) gibt das authentische Aroma.\n\nWarm servieren, solange die Asida geschmeidig ist.", "alternative": "", "geschichte": "Asida ist eine traditionelle Mehlspeise, die in Libyen und weiten Teilen Nordafrikas und der arabischen Welt verbreitet ist und besonders zu festlichen Anlässen zubereitet wird — in Libyen vor allem zum Geburtsfest des Propheten (Mawlid) sowie zu Familienfeiern und der Geburt eines Kindes. Es handelt sich um einen glatten, festen Brei aus Weizenmehl (manchmal Gerste oder Grieß), der in heißem Wasser unter kräftigem Rühren zu einer geschmeidigen, klebrigen Masse gekocht wird. Die Asida wird kuppelförmig in einer Schüssel angerichtet, und in die Mitte gibt man eine Mulde, die mit Dattelsirup (rub), Honig oder zerlassener Butter und Olivenöl gefüllt wird. Gegessen wird sie gemeinschaftlich, indem man Stücke des Breis abnimmt und in den Sirup tunkt. Süße Brei- und Teigspeisen dieser Art haben in der Region eine lange Geschichte als Festtags- und Trostessen. Asida ist als reine Mehl-Sirup-Speise von Natur aus vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Libyen", "Asida", "Mehlspeise", "Dattelsirup", "Honig", "süß", "Mawlid", "Festtag", "vegetarisch", "Maghreb", "gemeinschaftlich", "Dessert"]}, {"id": "couscous-aux-sept-l-gumes", "status": "published", "date": "", "cover": "", "name": "Couscous aux sept légumes", "land": "Marokko", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 20, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Gedämpfter Couscous mit sieben Gemüsesorten und Lamm in würziger Brühe. Das Freitagsgericht der marokkanischen Küche.", "zutaten": ["500 g Couscous (Hartweizengrieß)", "600 g Lammfleisch, in Stücken", "3 Möhren, 2 Zucchini, 1 Stück Kürbis", "0.25 Weißkohl, 1 Steckrübe", "200 g Kichererbsen", "2 Zwiebeln", "1 Prise Safran, 1 TL Ingwer, 1 TL Ras el-Hanout", "Olivenöl, Butter, Salz, Pfeffer"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Couscous (Hartweizengrieß)", "roh": "500 g Couscous (Hartweizengrieß)"}, {"menge": 600.0, "einheit": "g", "item": "Lammfleisch, in Stücken", "roh": "600 g Lammfleisch, in Stücken"}, {"menge": 3.0, "einheit": "", "item": "Möhren, 2 Zucchini, 1 Stück Kürbis", "roh": "3 Möhren, 2 Zucchini, 1 Stück Kürbis"}, {"menge": 0.25, "einheit": "", "item": "Weißkohl, 1 Steckrübe", "roh": "0.25 Weißkohl, 1 Steckrübe"}, {"menge": 200.0, "einheit": "g", "item": "Kichererbsen", "roh": "200 g Kichererbsen"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 1.0, "einheit": "Prise", "item": "Safran, 1 TL Ingwer, 1 TL Ras el-Hanout", "roh": "1 Prise Safran, 1 TL Ingwer, 1 TL Ras el-Hanout"}, {"menge": null, "einheit": "", "item": "Olivenöl, Butter, Salz, Pfeffer", "roh": "Olivenöl, Butter, Salz, Pfeffer"}], "zubereitung": ["Zwiebeln und Lamm im unteren Teil des Couscoussiers in Öl anbraten, mit Gewürzen würzen.", "Mit Wasser auffüllen, Kichererbsen zugeben und das Fleisch ansetzen.", "Den Couscous befeuchten, lockern und im Dampfaufsatz über der Brühe garen; mehrmals wiederholen und mit Butter auflockern.", "Das Gemüse nach Garzeit gestaffelt in die Brühe geben (festes zuerst, zartes später).", "Den fertigen Couscous auf einer großen Platte anhäufen.", "Fleisch und Gemüse darauf anrichten und mit etwas Brühe übergießen; restliche Brühe separat reichen."], "hinweise": "Den Couscous mehrfach dämpfen und auflockern — das macht ihn fluffig.\n\nDas Gemüse gestaffelt zugeben, damit nichts zerfällt.\n\nDie würzige Brühe separat zum Nachgießen reichen.", "alternative": "", "geschichte": "Couscous ist das Herzstück der marokkanischen und der gesamten maghrebinischen Küche und hat berberische Wurzeln, die viele Jahrhunderte zurückreichen. In Marokko ist der Couscous mit sieben Gemüsesorten besonders verbreitet und traditionell das Freitagsgericht, das nach dem Mittagsgebet im Kreis der Familie gegessen wird. Die Zahl Sieben gilt als glückbringend. Der eigentliche Couscous — feiner Hartweizengrieß — wird mehrfach von Hand befeuchtet, gerollt und über dem Dampf der köchelnden Brühe in einem speziellen Topf (couscoussier) gegart, was ihn locker und fluffig macht. Darüber kommen Lamm und ein Bett aus Gemüse wie Möhren, Zucchini, Kürbis, Kohl, Steckrübe, Kichererbsen und Zwiebeln, die in einer mit Safran, Ingwer und Ras el-Hanout gewürzten Brühe geschmort werden. Couscous verkörpert Gastfreundschaft und Gemeinschaft und wird oft aus einer großen, geteilten Platte gegessen. Als Lamm-Gemüse-Gericht ist es von Natur aus ohne Schweinefleisch und gilt als kulinarisches Wahrzeichen Marokkos.", "persoenlich": "", "servier": "", "tags": ["Marokko", "Couscous", "sieben Gemüse", "Lamm", "Hartweizengrieß", "Freitagsgericht", "Ras el-Hanout", "Safran", "berberisch", "Maghreb", "gedämpft", "Hauptgericht"]}, {"id": "tajine-de-poulet-aux-citrons-confits", "status": "published", "date": "", "cover": "", "name": "Tajine de poulet aux citrons confits", "land": "Marokko", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Geflügel"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Hähnchen, langsam geschmort mit eingelegten Salzzitronen, grünen Oliven und Safran im Tontopf. Klassiker der marokkanischen Tajine-Küche.", "zutaten": ["1 Hähnchen, in Teilen", "2 eingelegte Salzzitronen", "150 g grüne Oliven", "2 Zwiebeln", "3 Zehen Knoblauch", "1 Prise Safran, 1 TL Ingwer, 1 TL Kurkuma", "1 Bund Koriander und Petersilie", "Olivenöl, Salz, Pfeffer"], "zutatenS": [{"menge": 1.0, "einheit": "", "item": "Hähnchen, in Teilen", "roh": "1 Hähnchen, in Teilen"}, {"menge": 2.0, "einheit": "", "item": "eingelegte Salzzitronen", "roh": "2 eingelegte Salzzitronen"}, {"menge": 150.0, "einheit": "g", "item": "grüne Oliven", "roh": "150 g grüne Oliven"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 3.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "3 Zehen Knoblauch"}, {"menge": 1.0, "einheit": "Prise", "item": "Safran, 1 TL Ingwer, 1 TL Kurkuma", "roh": "1 Prise Safran, 1 TL Ingwer, 1 TL Kurkuma"}, {"menge": 1.0, "einheit": "Bund", "item": "Koriander und Petersilie", "roh": "1 Bund Koriander und Petersilie"}, {"menge": null, "einheit": "", "item": "Olivenöl, Salz, Pfeffer", "roh": "Olivenöl, Salz, Pfeffer"}], "zubereitung": ["Hähnchenteile mit Knoblauch, Safran, Ingwer, Kurkuma, Öl und gehackten Kräutern marinieren.", "Zwiebeln in Ringe schneiden und auf den Boden der Tajine oder eines Schmortopfs legen.", "Das marinierte Hähnchen darauf betten und mit etwas Wasser angießen.", "Zugedeckt bei kleiner Hitze 45–60 Minuten schmoren, bis das Hähnchen zart ist.", "Die in Streifen geschnittenen Salzzitronen und die Oliven zugeben und kurz mitschmoren.", "Mit frischen Kräutern bestreuen und mit Brot servieren."], "hinweise": "Eingelegte Salzzitronen sind unverzichtbar für das typische Aroma.\n\nBei kleiner Hitze schmoren, damit das Hähnchen saftig bleibt.\n\nMit Brot servieren, um die Sauce aufzunehmen.", "alternative": "", "geschichte": "Die Tajine ist sowohl ein Gericht als auch der namensgebende, kegelförmige Tontopf, in dem es zubereitet wird, und gehört zum Kern der marokkanischen Küche. Die charakteristische Form des Deckels lässt aufsteigenden Dampf kondensieren und zurück in das Gericht tropfen, sodass die Zutaten in wenig Flüssigkeit besonders schonend und aromatisch schmoren. Die Variante mit Hähnchen, eingelegten Salzzitronen (citrons confits) und grünen Oliven gehört zu den berühmtesten und spiegelt die für Marokko typische Kombination von herzhaften, salzigen und säuerlichen Aromen wider. Eingelegte Salzzitronen sind eine charakteristische Zutat der marokkanischen Küche und geben dem Gericht seine unverwechselbare, zugleich fruchtige und salzige Note. Gewürzt wird mit Safran, Ingwer, Kurkuma und frischem Koriander. Die Tajine wird traditionell im Topf serviert und mit Brot gegessen, das die Sauce aufnimmt. Als Geflügelgericht ist sie von Natur aus ohne Schweinefleisch und verkörpert die geduldige, gewürzbetonte Schmorkunst Marokkos.", "persoenlich": "", "servier": "", "tags": ["Marokko", "Tajine", "Hähnchen", "Salzzitronen", "Oliven", "Safran", "Geflügel", "Schmorgericht", "Maghreb", "Tontopf", "gewürzbetont", "Hauptgericht"]}, {"id": "kaab-el-ghzal", "status": "published", "date": "", "cover": "", "name": "Kaab el ghzal", "land": "Marokko", "kontinent": "Afrika", "gang": "Dessert", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Zarte, hörnchenförmige Gebäckstücke aus dünnem Teig mit einer Füllung aus Mandelpaste und Orangenblütenwasser. Marokkanisches Festtagsgebäck.", "zutaten": ["300 g Mehl", "50 g Butter (Teig)", "2 EL Orangenblütenwasser (Teig)", "300 g gemahlene Mandeln (Füllung)", "150 g Puderzucker (Füllung)", "1 TL Zimt", "3 EL Orangenblütenwasser (Füllung)"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "Mehl", "roh": "300 g Mehl"}, {"menge": 50.0, "einheit": "g", "item": "Butter (Teig)", "roh": "50 g Butter (Teig)"}, {"menge": 2.0, "einheit": "EL", "item": "Orangenblütenwasser (Teig)", "roh": "2 EL Orangenblütenwasser (Teig)"}, {"menge": 300.0, "einheit": "g", "item": "gemahlene Mandeln (Füllung)", "roh": "300 g gemahlene Mandeln (Füllung)"}, {"menge": 150.0, "einheit": "g", "item": "Puderzucker (Füllung)", "roh": "150 g Puderzucker (Füllung)"}, {"menge": 1.0, "einheit": "TL", "item": "Zimt", "roh": "1 TL Zimt"}, {"menge": 3.0, "einheit": "EL", "item": "Orangenblütenwasser (Füllung)", "roh": "3 EL Orangenblütenwasser (Füllung)"}], "zubereitung": ["Für die Füllung gemahlene Mandeln, Puderzucker, Zimt und Orangenblütenwasser zu einer formbaren Paste verkneten.", "Aus der Mandelpaste schlanke, an den Enden spitz zulaufende Röllchen formen.", "Mehl, Butter, Salz und Orangenblütenwasser mit etwas Wasser zu einem sehr geschmeidigen Teig kneten.", "Den Teig hauchdünn ausrollen, die Mandelröllchen einlegen und den Teig eng darum schließen.", "Zu Halbmonden (Hörnchen) biegen, die Ränder andrücken und überstehenden Teig abschneiden.", "Bei 170 °C hell backen, sodass sie zart bleiben; auskühlen lassen und zum Minztee servieren."], "hinweise": "Den Teig möglichst dünn ausrollen — das ist die Kunst dieses Gebäcks.\n\nHell backen, damit die Hörnchen zart und nicht hart werden.\n\nMit marokkanischem Minztee servieren.", "alternative": "", "geschichte": "Kaab el ghzal — „Gazellenhörner“ (französisch cornes de gazelle) — gehören zu den edelsten und bekanntesten Süßgebäcken Marokkos und sind ein fester Bestandteil von Festen, Hochzeiten, religiösen Feiertagen und der Gästebewirtung. Ihren Namen verdanken sie der charakteristischen geschwungenen Hörnchenform. Ein sehr dünner, geschmeidiger Teig wird mit einer Füllung aus fein gemahlenen Mandeln, Zucker, Zimt und Orangenblütenwasser umhüllt, zu schlanken Halbmonden geformt und behutsam gebacken, sodass sie hell und zart bleiben. Mandeln, Zimt und Orangenblütenwasser sind charakteristische Aromen der marokkanischen Konditorei, die für ihre Feinheit und ihren Reichtum an Mandelgebäck bekannt ist. Die Herstellung gilt als Kunst und erfordert Geschick beim dünnen Ausrollen des Teigs und beim Formen. Kaab el ghzal werden zum Minztee gereicht, der untrennbar zur marokkanischen Gastfreundschaft gehört. Als reines Teig-Mandel-Gebäck sind sie von Natur aus vegetarisch und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Marokko", "Kaab el ghzal", "Gazellenhörner", "Mandeln", "Orangenblütenwasser", "süß", "Festtag", "vegetarisch", "Minztee", "Maghreb", "Konditorei", "Dessert"]}, {"id": "couscous-tunisien-au-poisson", "status": "published", "date": "", "cover": "", "name": "Couscous tunisien au poisson", "land": "Tunesien", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Gedämpfter Couscous mit Fisch und Gemüse in einer scharfen, tomaten- und harissabetonten Brühe. Spezialität der tunesischen Küstenstädte.", "zutaten": ["500 g Couscous (Hartweizengrieß)", "800 g fester Fisch (z. B. Zackenbarsch, Meerbrasse), in Stücken", "2 EL Harissa", "3 EL Tomatenmark", "3 Möhren, 1 Stück Kürbis, 2 Kartoffeln", "150 g Kichererbsen", "1 TL Tabil (Koriander-Kümmel-Mischung)", "Olivenöl, Knoblauch, Salz"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Couscous (Hartweizengrieß)", "roh": "500 g Couscous (Hartweizengrieß)"}, {"menge": 800.0, "einheit": "g", "item": "fester Fisch (z. B. Zackenbarsch, Meerbrasse), in Stücken", "roh": "800 g fester Fisch (z. B. Zackenbarsch, Meerbrasse), in Stücken"}, {"menge": 2.0, "einheit": "EL", "item": "Harissa", "roh": "2 EL Harissa"}, {"menge": 3.0, "einheit": "EL", "item": "Tomatenmark", "roh": "3 EL Tomatenmark"}, {"menge": 3.0, "einheit": "", "item": "Möhren, 1 Stück Kürbis, 2 Kartoffeln", "roh": "3 Möhren, 1 Stück Kürbis, 2 Kartoffeln"}, {"menge": 150.0, "einheit": "g", "item": "Kichererbsen", "roh": "150 g Kichererbsen"}, {"menge": 1.0, "einheit": "TL", "item": "Tabil (Koriander-Kümmel-Mischung)", "roh": "1 TL Tabil (Koriander-Kümmel-Mischung)"}, {"menge": null, "einheit": "", "item": "Olivenöl, Knoblauch, Salz", "roh": "Olivenöl, Knoblauch, Salz"}], "zubereitung": ["Im unteren Teil des Couscoussiers Knoblauch und Tomatenmark in Olivenöl anrösten, Harissa und Tabil einrühren.", "Mit Wasser auffüllen, Kichererbsen zugeben und eine würzige, rote Brühe ansetzen.", "Den Couscous befeuchten, lockern und im Dampfaufsatz garen; mehrmals wiederholen.", "Das Gemüse nach Garzeit gestaffelt in die Brühe geben.", "Die Fischstücke vorsichtig in der Brühe gar ziehen lassen, ohne dass sie zerfallen.", "Den Couscous auf einer Platte anhäufen, mit Fisch und Gemüse anrichten und mit der scharfen Brühe übergießen."], "hinweise": "Harissa und Tabil geben die typisch tunesische Schärfe und Würze.\n\nDen Fisch erst spät zugeben, damit er nicht zerfällt.\n\nDen Couscous mehrfach dämpfen für eine lockere Konsistenz.", "alternative": "", "geschichte": "Couscous ist auch in Tunesien das zentrale Gericht der Küche und hat berberische Wurzeln, die weit zurückreichen. Während im Binnenland Lamm verbreitet ist, prägt an den Küsten — etwa in Sfax und entlang des Mittelmeers — der Fischcouscous die Tradition. Charakteristisch für die tunesische Variante ist die deutlich schärfere und tomatenreichere Würzung im Vergleich zum marokkanischen Couscous: Harissa, die scharfe Chilipaste, und reichlich Tabil (eine tunesische Gewürzmischung) geben der Brühe ihre rote Farbe und Feurigkeit. Der Hartweizengrieß wird über dem Dampf der köchelnden Brühe gegart, bis er locker ist, und mit dem in der würzigen Tomatenbrühe geschmorten Fisch und Gemüse wie Möhren, Kürbis, Kartoffeln und Kichererbsen serviert. Fischcouscous spiegelt die maritime Seite der tunesischen Küche und die Bedeutung des Mittelmeers wider. Als Fisch-Gemüse-Gericht ist er von Natur aus ohne Schweinefleisch und gehört zu den geschätzten Festtags- und Sonntagsessen der Küstenregionen.", "persoenlich": "", "servier": "", "tags": ["Tunesien", "Couscous", "Fisch", "Harissa", "Tabil", "Hartweizengrieß", "scharf", "Küstenküche", "Maghreb", "Sfax", "gedämpft", "Hauptgericht"]}, {"id": "brik", "status": "published", "date": "", "cover": "", "name": "Brik", "land": "Tunesien", "kontinent": "Afrika", "gang": "Vorspeise", "art": ["Fisch"], "schwierigkeit": "", "vorbereitungMin": 20, "kochMin": 40, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine knusprig frittierte Teigtasche aus hauchdünnem Malsouka-Teig mit Ei, Thunfisch und Petersilie. Tunesischer Klassiker mit flüssigem Eigelb.", "zutaten": ["4 Malsouka- oder Filoteigblätter", "4 Eier", "1 Dose Thunfisch", "1 Bund Petersilie", "1 Zwiebel, 1 EL Kapern", "50 g geriebener Käse (optional)", "Öl zum Frittieren, Salz, Pfeffer; Zitrone"], "zutatenS": [{"menge": 4.0, "einheit": "", "item": "Malsouka- oder Filoteigblätter", "roh": "4 Malsouka- oder Filoteigblätter"}, {"menge": 4.0, "einheit": "", "item": "Eier", "roh": "4 Eier"}, {"menge": 1.0, "einheit": "Dose", "item": "Thunfisch", "roh": "1 Dose Thunfisch"}, {"menge": 1.0, "einheit": "Bund", "item": "Petersilie", "roh": "1 Bund Petersilie"}, {"menge": 1.0, "einheit": "", "item": "Zwiebel, 1 EL Kapern", "roh": "1 Zwiebel, 1 EL Kapern"}, {"menge": 50.0, "einheit": "g", "item": "geriebener Käse (optional)", "roh": "50 g geriebener Käse (optional)"}, {"menge": null, "einheit": "", "item": "Öl zum Frittieren, Salz, Pfeffer; Zitrone", "roh": "Öl zum Frittieren, Salz, Pfeffer; Zitrone"}], "zubereitung": ["Thunfisch mit gehackter Petersilie, Zwiebel, Kapern, Salz und Pfeffer mischen.", "Ein Teigblatt auf die Arbeitsfläche legen und etwas Füllung in die Mitte geben.", "Eine Mulde formen und ein Ei hineingleiten lassen.", "Das Teigblatt rasch zu einer Tasche schließen, sodass das Ei eingeschlossen ist.", "In heißem Öl kurz und zügig beidseitig knusprig ausbacken, sodass das Eigelb flüssig bleibt.", "Sofort mit einem Spritzer Zitrone servieren."], "hinweise": "Nur kurz frittieren, damit das Eigelb flüssig bleibt.\n\nDie Tasche zügig schließen, bevor das Ei ausläuft.\n\nHeiß und frisch essen — am besten direkt aus der Pfanne.", "alternative": "", "geschichte": "Brik (auch Brik à l'œuf) ist eine der bekanntesten Spezialitäten Tunesiens und ein fester Bestandteil der Alltags- und Festküche, besonders beliebt während des Ramadan. Es handelt sich um eine knusprig frittierte Teigtasche aus Malsouka — einem hauchdünnen, an Filo erinnernden Teigblatt, das für die tunesische Küche charakteristisch ist. Die klassische Füllung besteht aus einem ganzen, rohen Ei, Thunfisch, Petersilie, Zwiebel und Kapern; das Besondere ist, dass das Ei beim kurzen Frittieren nur leicht stockt, sodass das Eigelb beim Hineinbeißen flüssig bleibt — was beim Essen Geschick erfordert. Brik spiegelt den Einfluss der mediterranen und osmanischen Teigtraditionen auf die tunesische Küche wider. Es wird heiß und frisch als Vorspeise oder Snack gegessen, oft mit einem Spritzer Zitrone. Als Teigtasche mit Ei und Fisch ist Brik von Natur aus ohne Schweinefleisch und gehört zu den Gerichten, die Tunesiens Vorliebe für knusprige, herzhafte Spezialitäten verkörpern.", "persoenlich": "", "servier": "", "tags": ["Tunesien", "Brik", "Malsouka", "Ei", "Thunfisch", "frittiert", "Teigtasche", "Ramadan", "Vorspeise", "Maghreb", "knusprig", "Snack"]}, {"id": "lablabi", "status": "published", "date": "", "cover": "", "name": "Lablabi", "land": "Tunesien", "kontinent": "Afrika", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 25, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Eine herzhafte Kichererbsensuppe über zerrupftem Brot, gewürzt mit Knoblauch, Kreuzkümmel und Harissa, gekrönt von einem Ei. Tunesisches Winterfrühstück.", "zutaten": ["300 g getrocknete Kichererbsen, über Nacht eingeweicht", "4 Zehen Knoblauch", "1 EL gemahlener Kreuzkümmel", "2 EL Harissa", "4 Scheiben altbackenes Brot", "4 Eier", "5 EL Olivenöl", "Zitrone, Kapern, Salz"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "getrocknete Kichererbsen, über Nacht eingeweicht", "roh": "300 g getrocknete Kichererbsen, über Nacht eingeweicht"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "4 Zehen Knoblauch"}, {"menge": 1.0, "einheit": "EL", "item": "gemahlener Kreuzkümmel", "roh": "1 EL gemahlener Kreuzkümmel"}, {"menge": 2.0, "einheit": "EL", "item": "Harissa", "roh": "2 EL Harissa"}, {"menge": 4.0, "einheit": "Scheiben", "item": "altbackenes Brot", "roh": "4 Scheiben altbackenes Brot"}, {"menge": 4.0, "einheit": "", "item": "Eier", "roh": "4 Eier"}, {"menge": 5.0, "einheit": "EL", "item": "Olivenöl", "roh": "5 EL Olivenöl"}, {"menge": null, "einheit": "", "item": "Zitrone, Kapern, Salz", "roh": "Zitrone, Kapern, Salz"}], "zubereitung": ["Kichererbsen mit Knoblauch in reichlich Wasser sehr weich kochen.", "Die Brühe mit Kreuzkümmel und Salz kräftig würzen.", "Das zerrupfte Brot in tiefe Schüsseln geben.", "Mit den heißen Kichererbsen und der Brühe übergießen, sodass das Brot durchweicht.", "Je ein weich gekochtes oder pochiertes Ei daraufsetzen.", "Mit Harissa, Olivenöl, Zitrone und Kapern nach Geschmack vollenden und heiß servieren."], "hinweise": "Reichlich Kreuzkümmel und Knoblauch geben den typischen Geschmack.\n\nAltbackenes Brot saugt die Brühe am besten auf.\n\nJeder würzt sein Lablabi mit Harissa selbst am Tisch.", "alternative": "", "geschichte": "Lablabi ist ein traditionelles tunesisches Gericht und ein beliebtes, günstiges Straßenessen, das besonders in den kühleren Monaten und gern zum Frühstück gegessen wird. Im Kern besteht es aus weich gekochten Kichererbsen in einer würzigen Knoblauch-Kreuzkümmel-Brühe, die über zerrupftes, oft altbackenes Brot gegeben wird, das die Brühe aufsaugt. Darüber kommen typische Beigaben: Harissa für die Schärfe, Olivenöl, ein Spritzer Zitrone oder Essig, Kapern, und häufig ein pochiertes oder weich gekochtes Ei. Jeder würzt sein Lablabi am Tisch nach eigenem Geschmack. Das Gericht ist ein Paradebeispiel für die Kunst, aus sehr einfachen, günstigen Zutaten — Kichererbsen, Brot, Knoblauch, Gewürze — eine sättigende, wärmende Mahlzeit zu schaffen, und spiegelt die volksnahe Seite der tunesischen Küche wider. Als Kichererbsengericht ist es von Natur aus vegetarisch und ohne Schweinefleisch und gehört zu den Speisen, die Tunesiens Liebe zu Harissa und Kreuzkümmel verkörpern.", "persoenlich": "", "servier": "", "tags": ["Tunesien", "Lablabi", "Kichererbsen", "Suppe", "Harissa", "Kreuzkümmel", "Brot", "vegetarisch", "Frühstück", "Straßenessen", "Maghreb", "winterlich"]}, {"id": "mechoui", "status": "published", "date": "", "cover": "", "name": "Mechoui", "land": "Mauretanien", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 25, "kochMin": 90, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ganzes oder großes Stück Lamm, über Stunden langsam geröstet, bis es zart vom Knochen fällt. Festmahl der saharanischen Nomadentradition.", "zutaten": ["2 kg Lammschulter oder -keule (mit Knochen)", "80 g Butter oder Schmalz vom Lamm", "1 EL gemahlener Kreuzkümmel", "1 EL Salz", "1 TL Paprika (optional)", "4 Zehen Knoblauch"], "zutatenS": [{"menge": 2.0, "einheit": "kg", "item": "Lammschulter oder -keule (mit Knochen)", "roh": "2 kg Lammschulter oder -keule (mit Knochen)"}, {"menge": 80.0, "einheit": "g", "item": "Butter oder Schmalz vom Lamm", "roh": "80 g Butter oder Schmalz vom Lamm"}, {"menge": 1.0, "einheit": "EL", "item": "gemahlener Kreuzkümmel", "roh": "1 EL gemahlener Kreuzkümmel"}, {"menge": 1.0, "einheit": "EL", "item": "Salz", "roh": "1 EL Salz"}, {"menge": 1.0, "einheit": "TL", "item": "Paprika (optional)", "roh": "1 TL Paprika (optional)"}, {"menge": 4.0, "einheit": "Zehen", "item": "Knoblauch", "roh": "4 Zehen Knoblauch"}], "zubereitung": ["Das Lamm rundum mit einer Paste aus Butter, zerdrücktem Knoblauch, Salz, Kreuzkümmel und Paprika einreiben.", "Einige Stunden, am besten über Nacht, durchziehen lassen.", "Das Fleisch bei niedriger Temperatur (etwa 150 °C) sehr langsam mehrere Stunden garen.", "Während des Garens immer wieder mit dem austretenden Fett und etwas Butter bestreichen.", "Gegen Ende die Hitze kurz erhöhen, damit die Außenseite knusprig wird.", "Zart vom Knochen fallend auf einer großen Platte anrichten und mit Kreuzkümmel-Salz servieren."], "hinweise": "Sehr langsam und lange garen — das macht das Fleisch butterzart.\n\nRegelmäßiges Bestreichen hält das Lamm saftig.\n\nKreuzkümmel-Salz zum Dippen separat reichen.", "alternative": "", "geschichte": "Mechoui — das langsam geröstete Lamm — ist tief in der nomadischen Tradition der Sahara und des Maghreb verwurzelt und in Mauretanien ein zentrales Festessen. Bei den Beduinen- und Nomadengemeinschaften, deren Reichtum und Lebensgrundlage über Jahrhunderte das Vieh war, gilt das Schlachten und gemeinschaftliche Verspeisen eines ganzen Lamms als höchster Ausdruck von Gastfreundschaft und wird zu Hochzeiten, religiösen Festen und der Bewirtung von Gästen zelebriert. Das Tier oder ein großes Stück wird, oft nur mit Salz, Kreuzkümmel und etwas Butter gewürzt, über vielen Stunden über Glut oder in einer Erdgrube langsam gegart, bis das Fleisch außen knusprig und innen butterzart vom Knochen fällt. Die schlichte Würzung stellt den reinen Fleischgeschmack in den Mittelpunkt. Mechoui wird gemeinschaftlich von einer großen Platte gegessen, traditionell mit der Hand. Es verkörpert die Verbindung der mauretanischen Küche mit der Wüsten- und Hirtenkultur und ist als Lammgericht von Natur aus ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Mauretanien", "Mechoui", "Lamm", "geröstet", "Sahara", "Nomadenküche", "Festtag", "Gastfreundschaft", "Kreuzkümmel", "Hirtenkultur", "gemeinschaftlich", "Hauptgericht"]}, {"id": "couscous-mauritanien", "status": "published", "date": "", "cover": "", "name": "Couscous mauritanien", "land": "Mauretanien", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Gedämpfter Couscous mit Lamm und Wüstengemüse in einer würzigen Brühe. Saharanische Fassung des maghrebinischen Grundgerichts.", "zutaten": ["500 g Couscous (Hartweizengrieß)", "700 g Lammfleisch, in Stücken", "3 Möhren, 1 Stück Kürbis", "0.25 Weißkohl, 2 Zwiebeln", "200 g Kichererbsen", "1 TL Kreuzkümmel, 1 TL Paprika", "Öl, Salz, Pfeffer"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Couscous (Hartweizengrieß)", "roh": "500 g Couscous (Hartweizengrieß)"}, {"menge": 700.0, "einheit": "g", "item": "Lammfleisch, in Stücken", "roh": "700 g Lammfleisch, in Stücken"}, {"menge": 3.0, "einheit": "", "item": "Möhren, 1 Stück Kürbis", "roh": "3 Möhren, 1 Stück Kürbis"}, {"menge": 0.25, "einheit": "", "item": "Weißkohl, 2 Zwiebeln", "roh": "0.25 Weißkohl, 2 Zwiebeln"}, {"menge": 200.0, "einheit": "g", "item": "Kichererbsen", "roh": "200 g Kichererbsen"}, {"menge": 1.0, "einheit": "TL", "item": "Kreuzkümmel, 1 TL Paprika", "roh": "1 TL Kreuzkümmel, 1 TL Paprika"}, {"menge": null, "einheit": "", "item": "Öl, Salz, Pfeffer", "roh": "Öl, Salz, Pfeffer"}], "zubereitung": ["Zwiebeln und Lamm im unteren Teil des Couscoussiers anbraten, mit Kreuzkümmel und Paprika würzen.", "Mit Wasser auffüllen, Kichererbsen zugeben und das Fleisch ansetzen.", "Den Couscous befeuchten, lockern und im Dampfaufsatz garen; mehrmals wiederholen und auflockern.", "Das Gemüse gestaffelt in die Brühe geben und weich schmoren.", "Den Couscous auf einer großen Platte anhäufen.", "Lamm und Gemüse darauf anrichten und mit Brühe übergießen; gemeinschaftlich servieren."], "hinweise": "Den Couscous mehrfach dämpfen für eine lockere Konsistenz.\n\nDas Gemüse je nach Garzeit gestaffelt zugeben.\n\nTraditionell von einer geteilten Platte essen.", "alternative": "", "geschichte": "Couscous gehört auch in Mauretanien zu den wichtigsten Gerichten und verbindet das Land mit der berberisch-maghrebinischen Tradition, die im gesamten Nordwesten Afrikas verbreitet ist. Als Bindeglied zwischen dem arabisch-berberischen Maghreb und Westafrika vereint die mauretanische Küche Einflüsse beider Welten. Der Hartweizengrieß wird, wie in der gesamten Region, über dem Dampf einer köchelnden Brühe gegart, bis er locker und fluffig ist, und mit Lamm sowie dem verfügbaren Gemüse — Möhren, Kürbis, Zwiebeln, Kohl und Kichererbsen — serviert, die in einer mit Kreuzkümmel und weiteren Gewürzen abgeschmeckten Brühe geschmort werden. In der kargen Sahara-Umgebung war Couscous ein nahrhaftes, sättigendes Gericht, das sich gut für die gemeinschaftliche Mahlzeit eignete. Es wird traditionell von einer großen, geteilten Platte gegessen und verkörpert Gastfreundschaft. Als Lamm-Gemüse-Gericht ist der mauretanische Couscous von Natur aus ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Mauretanien", "Couscous", "Lamm", "Hartweizengrieß", "Wüstengemüse", "Sahara", "Maghreb", "berberisch", "Kreuzkümmel", "gedämpft", "gemeinschaftlich", "Hauptgericht"]}, {"id": "lakh", "status": "published", "date": "", "cover": "", "name": "Lakh", "land": "Mauretanien", "kontinent": "Afrika", "gang": "Frühstück", "art": ["Vegetarisch"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Feiner Hirse-Couscous, serviert mit gesüßter, leicht säuerlicher Milch oder Joghurt. Süße Sahel-Spezialität Mauretaniens.", "zutaten": ["300 g feiner Hirse-Couscous (oder Hirsegrieß)", "500 ml Milch oder Joghurt", "100 ml leicht gesäuerte Milch (oder etwas Buttermilch)", "60 g Zucker", "4 Datteln, zerdrückt (optional)", "1 EL Orangenblütenwasser (optional)", "1 Prise Salz"], "zutatenS": [{"menge": 300.0, "einheit": "g", "item": "feiner Hirse-Couscous (oder Hirsegrieß)", "roh": "300 g feiner Hirse-Couscous (oder Hirsegrieß)"}, {"menge": 500.0, "einheit": "ml", "item": "Milch oder Joghurt", "roh": "500 ml Milch oder Joghurt"}, {"menge": 100.0, "einheit": "ml", "item": "leicht gesäuerte Milch (oder etwas Buttermilch)", "roh": "100 ml leicht gesäuerte Milch (oder etwas Buttermilch)"}, {"menge": 60.0, "einheit": "g", "item": "Zucker", "roh": "60 g Zucker"}, {"menge": 4.0, "einheit": "", "item": "Datteln, zerdrückt (optional)", "roh": "4 Datteln, zerdrückt (optional)"}, {"menge": 1.0, "einheit": "EL", "item": "Orangenblütenwasser (optional)", "roh": "1 EL Orangenblütenwasser (optional)"}, {"menge": 1.0, "einheit": "Prise", "item": "Salz", "roh": "1 Prise Salz"}], "zubereitung": ["Den Hirse-Couscous nach Packungsangabe befeuchten und über Dampf garen, bis er locker ist; auflockern und auskühlen lassen.", "Milch und gesäuerte Milch mit Zucker und nach Wunsch Orangenblütenwasser verrühren.", "Die zerdrückten Datteln unterrühren.", "Den Hirse-Couscous in Schalen geben.", "Mit der gesüßten Milch übergießen, sodass er gut durchtränkt ist.", "Gut gekühlt servieren."], "hinweise": "Den Hirse-Couscous gut auflockern, damit er die Milch aufnimmt.\n\nDie Süße und Säure der Milch nach Geschmack ausbalancieren.\n\nGekühlt ist Lakh besonders erfrischend.", "alternative": "", "geschichte": "Lakh ist eine traditionelle süße Speise, die in Mauretanien und der angrenzenden Sahel-Region, etwa im Senegal, verbreitet ist und die Verbindung der mauretanischen Küche zu Westafrika widerspiegelt. Grundlage ist feiner Couscous aus Hirse — Hirse ist eines der wichtigsten und ältesten Getreide der Sahelzone und übersteht das trockene Klima besser als Weizen. Der gedämpfte Hirse-Couscous wird mit gesüßter, oft leicht angesäuerter Milch oder Joghurt übergossen, manchmal verfeinert mit etwas Vanille, Orangenblütenwasser oder zerdrückten Datteln. Das Ergebnis ist eine erfrischende, sättigende Speise, die als süßes Frühstück, als Dessert oder zum Fastenbrechen gegessen wird. Lakh verbindet die getreidebasierte Grundernährung der Region mit der Bedeutung von Milch in der von Viehzucht geprägten Kultur. Als Gericht aus Hirse und Milch ist es von Natur aus vegetarisch und ohne Schweinefleisch und steht für die Sahel-Seite der mauretanischen Küche zwischen Wüste und Fluss.", "persoenlich": "", "servier": "", "tags": ["Mauretanien", "Lakh", "Hirse", "Couscous", "Milch", "süß", "Sahel", "vegetarisch", "Frühstück", "Datteln", "Westafrika", "Dessert"]}, {"id": "khobz-dafun", "status": "published", "date": "", "cover": "", "name": "Khobz dafun", "land": "Westsahara", "kontinent": "Afrika", "gang": "Beilage", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 15, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Ein ungesäuertes Fladenbrot, das traditionell in heißem Sand und unter Glut gebacken wird. Brot der saharanischen Nomaden.", "zutaten": ["500 g Mehl", "300 ml Wasser", "1 TL Salz", "1 Prise Trockenhefe (optional, für eine weichere Krume)"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Mehl", "roh": "500 g Mehl"}, {"menge": 300.0, "einheit": "ml", "item": "Wasser", "roh": "300 ml Wasser"}, {"menge": 1.0, "einheit": "TL", "item": "Salz", "roh": "1 TL Salz"}, {"menge": 1.0, "einheit": "Prise", "item": "Trockenhefe (optional, für eine weichere Krume)", "roh": "1 Prise Trockenhefe (optional, für eine weichere Krume)"}], "zubereitung": ["Mehl, Wasser und Salz (sowie optional etwas Hefe) zu einem festen, glatten Teig kneten.", "Kurz ruhen lassen und zu einem dicken, runden Fladen formen.", "Traditionell den Fladen in heißen Sand unter Glut betten und langsam garen.", "In der heimischen Küche stattdessen in einer schweren, trockenen Pfanne bei mittlerer Hitze beidseitig backen.", "Den Fladen wenden, bis er außen fest und durchgebacken ist.", "Etwas abkühlen lassen, aufbrechen und zu Fleisch-, Couscousgerichten oder Tee servieren."], "hinweise": "Ohne Sandgrube gelingt das Brot gut in einer Gusspfanne oder im Ofen.\n\nDen Teig fest halten, damit der Fladen seine Form behält.\n\nAls Beilage zu herzhaften Wüstengerichten reichen.", "alternative": "", "geschichte": "Khobz dafun — „vergrabenes Brot“ — ist ein traditionelles Fladenbrot der saharanischen Nomaden und gehört zur sahrauischen Esskultur der Westsahara, einem völkerrechtlich umstrittenen Gebiet. Die Zubereitung ist eine geniale Anpassung an das Leben in der Wüste, wo es weder Öfen noch viel Brennholz gibt: Ein einfacher Teig aus Mehl, Wasser und Salz wird zu einem dicken Fladen geformt und direkt in den heißen Sand unter einer zuvor entfachten Glut gebettet, wo er langsam gart. Nach dem Backen wird der Sand abgeklopft und die Kruste gereinigt. Das Brot ist außen fest und innen weich und begleitet die Mahlzeiten der Nomaden, etwa Fleisch- und Couscousgerichte oder Tee. Es spiegelt die Genügsamkeit und Erfindungsgabe der Wüstenbewohner wider, die mit minimalen Mitteln eine Grundnahrung herstellen. Khobz dafun ist als reines Mehl-Wasser-Brot von Natur aus vegan und ohne Schweinefleisch. In der heimischen Küche lässt es sich ersatzweise in einer Pfanne oder im Ofen backen.", "persoenlich": "", "servier": "", "tags": ["Westsahara", "Khobz dafun", "Sandbrot", "Fladenbrot", "Nomadenküche", "Sahara", "vegan", "vegetarisch", "sahrauisch", "ungesäuert", "Wüstenküche", "Beilage"]}, {"id": "couscous-sahraoui", "status": "published", "date": "", "cover": "", "name": "Couscous sahraoui", "land": "Westsahara", "kontinent": "Afrika", "gang": "Hauptgericht", "art": ["Fleisch", "Lamm"], "schwierigkeit": "", "vorbereitungMin": 30, "kochMin": 75, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Gedämpfter Couscous mit Lamm oder Kamelfleisch und wenig Gemüse, schlicht gewürzt. Festgericht der sahrauischen Wüstenküche.", "zutaten": ["500 g Couscous (Hartweizengrieß)", "700 g Lammfleisch (ersatzweise; traditionell auch Kamel)", "2 Zwiebeln", "3 Möhren, 1 Stück Kürbis", "150 g Kichererbsen", "1 TL Kreuzkümmel, Salz, Pfeffer", "Öl, Butter"], "zutatenS": [{"menge": 500.0, "einheit": "g", "item": "Couscous (Hartweizengrieß)", "roh": "500 g Couscous (Hartweizengrieß)"}, {"menge": 700.0, "einheit": "g", "item": "Lammfleisch (ersatzweise; traditionell auch Kamel)", "roh": "700 g Lammfleisch (ersatzweise; traditionell auch Kamel)"}, {"menge": 2.0, "einheit": "", "item": "Zwiebeln", "roh": "2 Zwiebeln"}, {"menge": 3.0, "einheit": "", "item": "Möhren, 1 Stück Kürbis", "roh": "3 Möhren, 1 Stück Kürbis"}, {"menge": 150.0, "einheit": "g", "item": "Kichererbsen", "roh": "150 g Kichererbsen"}, {"menge": 1.0, "einheit": "TL", "item": "Kreuzkümmel, Salz, Pfeffer", "roh": "1 TL Kreuzkümmel, Salz, Pfeffer"}, {"menge": null, "einheit": "", "item": "Öl, Butter", "roh": "Öl, Butter"}], "zubereitung": ["Zwiebeln und Fleisch im unteren Teil des Couscoussiers anbraten und würzen.", "Mit Wasser auffüllen, Kichererbsen zugeben und das Fleisch weich schmoren.", "Den Couscous befeuchten, lockern und über dem Dampf garen; mehrmals wiederholen und mit Butter auflockern.", "Das Gemüse gestaffelt in die Brühe geben.", "Den Couscous auf einer großen Platte anhäufen und Fleisch sowie Gemüse darauf anrichten.", "Mit etwas Brühe übergießen und gemeinschaftlich servieren."], "hinweise": "Den Couscous mehrfach dämpfen und mit Butter auflockern.\n\nDie Würzung schlicht halten — das Fleisch steht im Mittelpunkt.\n\nIm Anschluss die dreifache sahrauische Teezeremonie reichen.", "alternative": "", "geschichte": "Couscous ist auch in der Westsahara, einem völkerrechtlich umstrittenen Gebiet, das zentrale Festgericht und verbindet die sahrauische Küche mit der berberisch-maghrebinischen Tradition des gesamten Nordwestafrikas. In der kargen Wüstenumgebung, in der die sahrauischen Nomaden traditionell von Viehzucht lebten, ist Couscous ein nahrhaftes, sättigendes Gericht für Feste und die gemeinschaftliche Bewirtung von Gästen. Der Hartweizengrieß wird über dem Dampf einer köchelnden Brühe gegart und mit Lamm — bei festlichen Anlässen auch Kamelfleisch, das in der Region eine Rolle spielt — sowie dem verfügbaren Gemüse serviert. Die Würzung ist gegenüber den nördlichen Maghreb-Varianten oft schlichter und stellt das Fleisch in den Mittelpunkt, passend zur Verfügbarkeit von Zutaten in der Wüste. Gegessen wird traditionell von einer großen, geteilten Platte mit der Hand, oft gefolgt von der dreifachen Teezeremonie. Als Fleisch-Getreide-Gericht ist der sahrauische Couscous von Natur aus ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Westsahara", "Couscous", "Lamm", "Kamel", "Hartweizengrieß", "Sahara", "sahrauisch", "Nomadenküche", "Festtag", "berberisch", "gemeinschaftlich", "Hauptgericht"]}, {"id": "atay", "status": "published", "date": "", "cover": "", "name": "Atay", "land": "Westsahara", "kontinent": "Afrika", "gang": "Getränk", "art": ["Vegetarisch", "Vegan"], "schwierigkeit": "", "vorbereitungMin": 10, "kochMin": 30, "zeitGeschaetzt": true, "portionen": 4, "basisPortionen": 4, "kurzinfo": "Stark gebrühter grüner Minztee, in drei Aufgüssen und aus großer Höhe in kleine Gläser gegossen. Herzstück der sahrauischen Gastfreundschaft.", "zutaten": ["2 EL grüner Tee (Gunpowder)", "1 Bund frische Minze", "60 g Zucker (oder mehr nach Geschmack)", "500 ml Wasser"], "zutatenS": [{"menge": 2.0, "einheit": "EL", "item": "grüner Tee (Gunpowder)", "roh": "2 EL grüner Tee (Gunpowder)"}, {"menge": 1.0, "einheit": "Bund", "item": "frische Minze", "roh": "1 Bund frische Minze"}, {"menge": 60.0, "einheit": "g", "item": "Zucker (oder mehr nach Geschmack)", "roh": "60 g Zucker (oder mehr nach Geschmack)"}, {"menge": 500.0, "einheit": "ml", "item": "Wasser", "roh": "500 ml Wasser"}], "zubereitung": ["Den grünen Tee mit etwas heißem Wasser kurz überbrühen und das erste Wasser abgießen (Reinigung der Blätter).", "Frisches Wasser zugeben und den Tee stark aufkochen.", "Reichlich Minze und Zucker zugeben und kurz ziehen lassen.", "Den Tee aus großer Höhe in kleine Gläser gießen, um Schaum zu erzeugen, und mehrmals zurückgießen.", "Den ersten Aufguss servieren; anschließend Wasser, Minze und Zucker erneut aufgießen für den zweiten und dritten Aufguss.", "Die drei Gläser nacheinander und in Ruhe gemeinschaftlich genießen."], "hinweise": "Das Gießen aus der Höhe erzeugt die typische Schaumkrone.\n\nJeder der drei Aufgüsse schmeckt etwas anders — das ist Teil der Zeremonie.\n\nSich Zeit nehmen: Atay ist ein Ritual der Gastfreundschaft.", "alternative": "", "geschichte": "Atay — die dreifache Teezeremonie — ist weit mehr als ein Getränk und gehört zum kulturellen Kern der sahrauischen Gesellschaft in der Westsahara, einem völkerrechtlich umstrittenen Gebiet, sowie der gesamten saharanischen Nomadenwelt. Grüner Tee (oft Gunpowder), frische Minze und reichlich Zucker werden stark aufgebrüht und in drei aufeinanderfolgenden Aufgüssen aus demselben Tee zubereitet und serviert. Der Tee wird aus großer Höhe in kleine Gläser gegossen, sodass sich eine Schaumkrone bildet — eine Kunst, die Geschick verlangt. Die drei Gläser werden in der sahrauischen und maghrebinischen Tradition oft sinnbildlich gedeutet: das erste bitter „wie das Leben“, das zweite süß „wie die Liebe“, das dritte sanft „wie der Tod“. Die Zeremonie ist Ausdruck von Gastfreundschaft, Geselligkeit und sozialer Bindung und begleitet Begegnungen, Verhandlungen und Mahlzeiten. Sie nimmt Zeit in Anspruch und ist ein bewusstes, gemeinschaftliches Ritual. Der Tee ist als reines Pflanzengetränk selbstverständlich vegan und ohne Schweinefleisch.", "persoenlich": "", "servier": "", "tags": ["Westsahara", "Atay", "Minztee", "grüner Tee", "Teezeremonie", "Getränk", "vegan", "vegetarisch", "sahrauisch", "Sahara", "Gastfreundschaft", "Ritual"]}]};
